(1, 16, '6629', '2023', NULL, 'Actualiza la Ley 6 de Audiencias Públicas de la CABA: consagra las modalidades presencial, virtual o mixta, deroga la Ley 6306 y moderniza el procedimiento del instituto de participación ciudadana.', 'http://www2.cedom.gob.ar/es/legislacion/normas/leyes/ley6629.html', 1, 'Manual', NOW());
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, '41 y 43', 'Derecho a un ambiente sano. Obligacion de recomponer. Educacion ambiental. Proteccion de los recursos naturales', 'Identifica derechos y obligaciones en materia ambiental en forma general', 1, 'Informativa', 'No requiere. Es de carácter informativa', 'Es informativa', 8, NULL, NULL, 0, '{"custom_1783383400370": "Gral Ambiente", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Congreso Nacional", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "ambiente", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'todos en general y art. 22', 'Ley general del ambiente de cumplimiento en todo el pais. Aporta guias generales de accion en materia de evaluacion de impacto ambiental, educacion ambiental, ordenamiento territorial. Define el daño ambiental. Art. 22 establece la obligatoriedad de contratar seguro ambiental', 'Identifica derechos y obligaciones en materia ambiental en forma general. Obligacion de contratar seguro ambiental', 2, 'las acciones se establecen por normativa local. EL seguro ambiental a partir del art. 22 tiene variada normativa reglamentaria', 'No se tiene contratado el seguro ambiental. Al actualizar el NCA se definió que Cirion deberá contratar el seguro.', 'Se realizó el cálculo del NCA en diciembre 2024 dando un valor de 16. Se contratará un seguro ambiental, pero en caso de recertificar se encotrarían excentos porque bajaría el NCA a 12, sindo el límite 14,5', 5, 'Se encuantran en proceso de re-certificación ISO 14001', NULL, 1, '{"custom_1783383400370": "Ambiente General", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaría de Ambiente de la Nación", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Seguro ambiental", "custom_1784900000002": "EHS Argentina"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 28);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'Sustituye el artículo 2º de la Resolución del ex Ministerio de Ambiente y Desarrollo Sustentable Nº RESOL-388-2018-APN-MAD, de fecha 21 de junio de 2018, el que quedará redactado del siguiente modo:\n“Artículo 2°: Las entidades aseguradoras que obtengan la conformidad ambiental, deberán cubrir los riesgos que se correlacionen con la capacidad de remediación acreditada ante este Subsecretaaría de Ambiente de la Nación.\nLa UNIDAD DE EVALUACIÓN DE RIESGOS AMBIENTALES de la DIRECCIÓN DE MONITOREO Y PREVENCIÓN, podrá verificar la correlación entre las capacidades de remediación acreditadas y los riesgos cubiertos como asimismo los requisitos establecidos en la normativa ambiental’’.\nLos operadores y transportistas de residuos peligrosos que cumplimenten con los requisitos conforme el ANEXO I de la RESOL-388-2018-APN-MAD, podrán celebrar contratos con operadores y transportistas de jurisdicción provincial o nacional que careciere de operador local, cumplimentando estos, con los mismos requisitos que se advierten en el ANEXO I citado.\nLas Pólizas de Seguros de Caución de incidencia colectiva emitidas por las Entidades aseguradoras deberán ser extendidas indicando como beneficiarios tanto a la autoridad local que por derecho correspondiere como al Estado Nacional por conducto de este Ministerio y entes autárquicos y/o interjurisdiccionales de cualquier nivel gubernamental, hasta que se resuelva la situación fáctica extraordinaria descripta en los considerandos citados de la presente Resolución.\nLas pólizas que ya hubieren sido extendidas a la fecha, sin la totalidad de los beneficiarios antes descriptos, deberán ser regularizadas en el plazo de NOVENTA (90) días a partir del día siguiente de publicada la presente resolución.\nLas rescisiones de los contratos de reserva de capacidad instalada presentados por las entidades aseguradoras, cobrarán validez una vez que dicha entidad aseguradora presente nuevos contratos de capacidad instalada ante el Subsecretaaría de Ambiente de la Nación, conforme lo establecido en el ANEXO I de la RESOL-388-2018-APN-MAD, de fecha 21 de junio de 2018.', 'Si les corresponde tomar el seguo tener en cuenta que deberán tener como beneficiario además de la autoridad ambiental local , también a la autoridad de aplicación de la normativa ambiental nacional MAyDS y los entes autárquicos que pudieren corresponder dentro del plazo de 90 días contados desde el 04/08/2022.', 2, 'Cumplimiento', 'No se tiene contratado el seguro ambiental. Al actualizar el NCA se definió que Cirion deberá contratar el seguro en el caso de .', 'Se realizó el cálculo del NCA en diciembre 2024 dando un valor de 16. Se contratará un seguro ambiental, pero en caso de recertificar se encotrarían excentos porque bajaría el NCA a 13, sindo el límite 14,5', 5, 'Se encuantran en proceso de re-certificación ISO 14001', NULL, 2, '{"custom_1783383400370": "Ambiente General", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaría de Ambiente de la Nación", "custom_1783383763840": "Anual", "custom_1783383788609": "TODOS", "custom_1783383823178": "Seguro ambiental\\nNivel de complejidad ambiental", "custom_1784900000002": "EHS Argentina"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, NULL, 'Crea el “PROGRAMA SOLUCIONA VERDE” en la órbita de la SECRETARÍA DE INDUSTRIA, ECONOMÍA DEL CONOCIMIENTO Y GESTIÓN COMERCIAL EXTERNA del MINISTERIO DE DESARROLLO PRODUCTIVO, con el objetivo de brindar asistencia financiera a personas jurídicas para contribuir a la sostenibilidad ambiental de la producción mediante el desarrollo, la implementación y/o la adopción de soluciones, productos y/o servicios innovadores vinculados a la Economía del Conocimiento.', 'Tener en cuenta en el caso que requieran financiamiento para una innovación ambiental.', 1, 'Informativa', 'No requiere. Es de carácter informativa', 'Es informativa', 8, NULL, NULL, 3, '{"custom_1783383400370": "Ambiente General", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "MINISTERIO DE DESARROLLO PRODUCTIVO", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "ambiente", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 427);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Reglamentacion de la Ley 25675', 'Apruébese el documento “Guía para la elaboración de Estudios de Impacto Ambiental - Edición 2023”.\nEsta guía tiene como objetivo brindar lineamientos conceptuales y metodológicos generales para la elaboración de un estudio de impacto ambiental (EsIA), que integran a su vez criterios y recomendaciones para incorporar la variable del cambio climático. Se espera que constituya un aporte para la sistematización, ordenamiento y estandarización de conceptos, procesos, técnicas y metodologías aplicables en la materia. \nAsimismo, aprueba el documento “Guía sobre participación pública en la evaluación ambiental”.', 'Norma Indicativa que puede utilizarse por todas las jurisdicciones para completar sus procedimientos de Evaluación de Impacto Ambiental. Por  reglamentar la ley n° 25.675 de presupuestos mínimos, se usa subsidiariamente respecto de las normas que establecen el procedimiento de Evaluación de Impacto Ambiental debiendo tomar de éstas guías todo lo que no se encuentre normado por las provincias y la CABA', 1, 'Informativa', 'No requiere. Es de carácter informativa', 'Es informativa', 8, NULL, NULL, 4, '{"custom_1783383400370": "Evaluación de Impacto Ambiental", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaría de Ambiente de la Nación,", "custom_1783383763840": "Continuo y conforme el vencimiento establecido en a norma local sobre EIA", "custom_1783383788609": "Todos", "custom_1783383823178": "Estudio de Impacto Ambiental", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 338);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Reglamentacion de la Ley 25675', 'Se aprueba el Reglamento y el Glosario para la conformación de los PROGRAMAS DE RECONVERSION INDUSTRIAL (PRI) en el ámbito de la SECRETARÍA DE GOBIERNO DE AMBIENTE Y DESARROLLO SUSTENTABLE. Así por ser actividades que se desarrollan en jurisdicciones locales se aprueba el CONVENIO DE RECONVERSIÓN INDUSTRIAL ENTRE LA SECRETARÍA DE GOBIERNO DE AMBIENTE Y DESARROLLO SUSTENTABLE, LA AUTORIDAD LOCAL COMPETENTE DE LA PROVINCIA  donde se desarrolle la actividad que necesita firmar el plan y EL ESTABLECIMIENTO INDUSTRIAL Y/O DE SERVICIO que se encontrare incumpliendo con la normativa ambiental. Los Programas de Reconversión Industrial (PRI) prevén la posibilidad de implementar, en conjunto con las jurisdicciones locales involucradas, programas de adecuación tecnológica destinados a mejorar los procesos industriales y productivos, en cuanto a la reducción de la contaminación ambiental, eficiencia de uso de recursos, la cesación de emisiones riesgosas sobre los recursos naturales y la disminución de riesgos ambientales generados por los mismos. los PROGRAMAS DE RECONVERSIÓN INDUSTRIAL (PRI) se implementarán por ante la DIRECCIÓN NACIONAL DE EVALUACIÓN AMBIENTAL de esta SECRETARÍA DE CAMBIO CLIMÁTICO, DESARROLLO SOSTENIBLE E INNOVACIÓN, o a la que en el futuro la reemplace, actuando la misma en carácter de Unidad de Gestión', 'Voluntaria a los fines de Reconvertirse. Por  reglamentar la ley n° 25.675 de presupuestos mínimos puede ser utilizada por cualquier empresa de diferentes jurisdicciones locales a los fines de reconvertirse, se usa subsidiariamente respecto de las normas que establecen el procedimiento de Evaluación de Impacto Ambiental  y aplicación de sanciones.', 1, 'Informativa', 'No requiere, es voluntaria. Es de carácter informativa', 'Es informativa', 8, NULL, NULL, 5, '{"custom_1783383400370": "PROGRAMAS DE RECONVER SION INDUSTRIAL (PRI)", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaría de Ambiente de la Nación SECRETARÍA DE CAMBIO CLIMÁTICO, DESARROLLO SOSTENIBLE E INNOVACIÓN", "custom_1783383763840": "Si se aplica una infracción o deben hacer una mejora ambiental", "custom_1783383788609": "TODOS", "custom_1783383823178": "Programa de reconversión industrial", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 514);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 388);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Reglamentacion del articulo 22 de la Ley 25675', 'Toda persona física o jurídica, pública o privada, que realice actividades riesgosas para el ambiente, los ecosistemas y sus elementos constitutivos, deberá contratar un seguro de cobertura con entidad suficiente para garantizar el financiamiento de la recomposición del daño que en su tipo pudiere producir. La Resolucion 206/16 determina el Procedimiento para el Cumplimiento del Seguro Ambiental. Mediante la Resolucion 548/17 se establece como debe procederse ante un incidente ambiental.\nLa Resolucion 204/18 establece que las  actualizaciones del valor del Factor de Correlación se realizarán de manera anual y automática el 1° de marzo de cada año, tomando como variable de ajuste el promedio del Índice del Costo de la Construcción (ICC) y el Índice de Precios Internos al por Mayor (IPIM), ambos publicados por el Instituto Nacional de Estadísticas y Censos de la República Argentina (INDEC), correspondientes al año calendario anterior.', 'Establece la obligatoriedad de la contratacion del Seguro Ambiental', 2, 'Hay Resoluciones de la Secretaria de Ambiente de la Nación  que determinan modalidades de cumplimiento de la obligacion establecida en el artículo 22', 'No se tiene contratado el seguro ambiental. Al actualizar el NCA se definió que Cirion deberá contratar el seguro.', 'Se realizó el cálculo del NCA en diciembre 2024 dando un valor de 16. Se contratará un seguro ambiental, pero en caso de recertificar se encotrarían excentos porque bajaría el NCA a 12, sindo el límite 14,5', 5, 'Se encuantran en proceso de re-certificación ISO 14001', NULL, 6, '{"custom_1783383400370": "Seguro Ambiental", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaría de Ambiente de la Nación, Hoy MAyDS", "custom_1783383763840": "Anual", "custom_1783383788609": "TODOS", "custom_1783383823178": "Seguro ambiental", "custom_1784900000002": "EHS Argentina"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 28);
