INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 589);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Reglamentacion del articulo 22 de la Ley 25675', 'Decreto por el cual se podrá tomar no solo un seguro de caución o de transferencia de riesgo, sino que también se podrán auto asegurarse constituyendo un fondo de garantía, fideicomisos, o a través del instrumento financiero que ofrezcan a las autoridades de aplicación (Secretaría de Gobierno de Ambiente y Desarrollo Sustentable -SGAyDS- y la Superintendencia de Seguros de la Nación –SSN-) y estas lo acepten.\nEl monto deberá respetar el Monto Mínimo Asegurable calculado conforme las fórmulas ya existentes en las normas actualmente vigentes, como así también las garantías de cumplimiento de la recomposición ambiental que hoy cumplen las aseguradoras para la aprobación por la SGAyDS.\nTambién debe tenerse en cuenta que la norma hoy no podría entrar en vigencia ya que resulta necesario que la SGAyDS y la SSN dicten normas para poder establecer requisitos y procedimientos para poder aprobar los instrumentos financieros que no sean seguros.\nLa norma dice:\n Establécese que, a los fines de dar cumplimiento a la exigencia dispuesta en el artículo 22 de la Ley N° 25.675, aquellas personas humanas o jurídicas, públicas o privadas, que realicen actividades riesgosas para el ambiente, los ecosistemas y sus elementos constitutivos deberán contratar:\n1. Seguro de Caución por Daño Ambiental de Incidencia Colectiva,\n2. Pólizas de Seguro con Transferencia de Riesgo, u\n3. Otros instrumentos financieros o planes de seguro que sean aprobados por la Secretaría de Gobierno de Ambiente y Desarrollo Sustentable de la SECRETARÍA GENERAL de la PRESIDENCIA DE LA NACIÓN y la SUPERINTENDENCIA DE SEGUROS DE LA NACIÓN organismo descentralizado actuante bajo la órbita del MINISTERIO DE HACIENDA.\nLas coberturas existentes y los planes de seguro a ser aprobados en el marco del artículo 22 de la Ley N° 25.675, deberán garantizar la efectiva remediación del daño causado hasta el monto mínimo asegurable.', 'Se podrá tomar no solo un seguro de caución o de transferencia de riesgo, sino que también se podrán auto asegurarse constituyendo un fondo de garantía, fideicomisos, o a través del instrumento financiero que ofrezcan a las autoridades de aplicación. En cumplimiento de lo establecido en el art. 22 de la ley de presupuestos mínimos se puede tomar seguro de garantía con transferencia de riesgo, de caución u otros instrumentos financieros o planes de seguro que sean aprobados por la Secretaría de Gobierno de Ambiente y Desarrollo Sustentable de la SECRETARÍA GENERAL de la PRESIDENCIA DE LA NACIÓN y la SUPERINTENDENCIA DE SEGUROS DE LA NACIÓN organismo descentralizado actuante bajo la órbita del MINISTERIO DE HACIENDA', 2, NULL, 'No se tiene contratado el seguro ambiental. Al actualizar el NCA se definió que Cirion deberá contratar el seguro.', 'Se realizó el cálculo del NCA en diciembre 2024 dando un valor de 16. Se contratará un seguro ambiental, pero en caso de recertificar se encotrarían excentos porque bajaría el NCA a 12, sindo el límite 14,5', 5, 'Se encuantran en proceso de re-certificación ISO 14001', NULL, 7, '{"custom_1783383400370": "Seguro Ambiental", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Poder Ejecutivo Naciona, aplica el Ministerio de Ambiente y Desarrollo Sustentable", "custom_1783383763840": "Anual", "custom_1783383788609": "TODOS", "custom_1783383823178": "Seguro ambiental", "custom_1784900000002": "EHS Argentina"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 537);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Reglamentacion del articulo 22 de la Ley 25675', 'Se crea en el ámbito de la SECRETARÍA DE GOBIERNO DE AMBIENTE Y DESARROLLO SUSTENTABLE el Sistema Integral de Gestión de Garantías Ambientales (SIGGA), como herramienta obligatoria para las compañías de seguro que comercializan el seguro ambiental en el marco del artículo 22 de la Ley Nº 25.675, a los fines de lograr una correcta gestión, administración y control de las pólizas.\nEl Sistema Integral de Gestión de Garantías Ambientales (SIGGA), consistirá en un sistema unificado de información para el registro de las garantías ambientales que permitirá, entre otras funciones, concentrar información, administrar exenciones, contar con un registro de compañías aseguradoras y generar notificaciones predeterminadas en forma automática, siendo obligación de las compañías de seguro habilitadas a la comercialización del seguro ambiental, la adopción de este sistema.', 'Se informatiza la carga de datos a la cual podrá ingresar a consultar cualquier usuario,  de los seguros otorgados u otros instrumentos financieros o planes de seguro que sean aprobados por la Secretaría de Gobierno de Ambiente y Desarrollo Sustentable de la SECRETARÍA GENERAL de la PRESIDENCIA DE LA NACIÓN y la SUPERINTENDENCIA DE SEGUROS DE LA NACIÓN.\nSe trata de una norma informativa, pero debe estar porque aclara cosas sobre la obligación que surge de la norma principal.', 1, 'Procedimiental- acceso a la información.\nSe trata de una norma informativa, pero debe estar porque aclara cosas sobre la obligación que surge de la norma principal.', 'Es informativa', 'Es informativa', 8, NULL, NULL, 8, '{"custom_1783383400370": "Seguro Ambiental", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "SECRETARÍA GENERAL-SECRETARÍA DE GOBIERNO DE AMBIENTE Y DESARROLLO SUSTENTABLE", "custom_1783383763840": "Anual", "custom_1783383788609": "TODOS", "custom_1783383823178": "Seguro ambiental\\nNivel de complejidad ambiental", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 536);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo su articulado', 'El Congreso de la Nación Argentina ratificó el Acuerdo Regional de Escazú sobre el Acceso a la Información, la Participación Pública y el Acceso a la Justicia en Asuntos Ambientales en América Latina y el Caribe. Tiene como objetivo garantizar la implementación plena y efectiva en los Estados parte de tres (3) derechos fundamentales:\na) amplio acceso sin restricciones a la información ambiental,\nb) participación pública en los procesos de toma de decisiones ambientales y\nc) acceso a la justicia en asuntos ambientales asegurando mecanismos adecuados para el acceso a los procedimientos administrativos y judiciales vinculados a tales derechos. Además contiene disposiciones específicas para garantizar un entorno seguro, sin restricciones o amenazas para los defensores de derechos humanos en asuntos ambientales.\nEl acuerdo establece estándares regionales que deberán ser regulados a nivel nacional, promueve la creación de capacidades, sienta las bases de una estructura institucional de apoyo y ofrece mecanismos para mejorar la formulación de políticas y la toma de decisiones. Su característica vinculante, implica la obligatoriedad de su aplicación para los países que lo ratifiquen, como así también el reconocimiento a principios fundamentales para el derecho ambiental, como los principios “precautorio”, de “prevención”, “transparencia y rendición de cuentas”, “no discriminación”, “principio pro persona ”  y el de “no regresión” que impide a los países derogar las garantías y derechos ya reconocidos.\nEn definitiva el tratado Escazú recepta derechos y garantías a los fines de proteger a quienes luchan contra la desigualdad y la discriminación, y garantizar los derechos de todas las personas a un ambiente sano y al desarrollo sustentable, dedicando especial atención a las personas y grupos en situación de vulnerabilidad.', 'Tener presente que toda la información ambiental presentada o que debería ser presentada al Estado, es pública y cualquier habitante puede solicitarla. En el mismo sentido cualquier información ambiental con que cuente el Estado puede ser solicitada por la empresa cuando fuera necesario', 2, 'Brindar información ambiental a los organismos públicos que lo requieran', 'No requiere. Es de carácter informativa', 'Es informativa', 8, NULL, NULL, 9, '{"custom_1783383400370": "Gral Ambiente", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Congreso Nacional", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "ambiente", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 31);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo su articulado', 'Establece a la Subsecretaría de Ambiente, dependiente de la Vicejefatura de Gobierno, como Autoridad de Aplicación de las Leyes 3.246, 4.308, 5.346, 5.822 y 6.403.\nFaculta a la Autoridad de Aplicación de las Leyes 3.246, 4.308, 5.346, 5.822 y 6.403, a dictar las normas aclaratorias, complementarias y operativas que resulten necesarias para la implementación de dichas leyes.\nSustituye el texto del artículo 1° del Decreto 457/22 por el siguiente:\n“Artículo 1°.- Establecer a la Subsecretaría de Ambiente, dependiente de la Vicejefatura de Gobierno, como Autoridad de Aplicación de la Ordenanza 45.676/91.”\nSustituye el texto del artículo 7° del Anexo I del Decreto 1.325/06 por el siguiente:\n“Artículo 7°. - Establecer a la Subsecretaría de Ambiente, dependiente de la Vicejefatura de Gobierno, como Autoridad de Aplicación de la Ley 303.\nLa Autoridad de Aplicación podrá dictar las normas aclaratorias, complementarias y operativas que resulten necesarias para la implementación de la Ley 303 de acceso a la información, y su reglamentación.”\nSustituye el texto del artículo 8° del Anexo I del Decreto 1.325/06 por el siguiente:\n“Artículo 8°. - La Autoridad de Aplicación podrá celebrar convenios con organismos de otras jurisdicciones, con el objeto de dar cumplimiento a lo dispuesto en el artículo 8° de la Ley 303.”\nDeroga el Decreto 138/08.', 'Tener en cuenta la autoridad de aplicación Subsecretaría de Ambiente si deben informar alguna anomalía al GCBA', 2, NULL, NULL, NULL, 8, NULL, NULL, 10, '{"custom_1783383400370": "Gral Ambiente", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "JEFE DE GOBIERNO DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 441);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, @nc1);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo su articulado', 'Modifica las Normas (N.T. 2013 y mod.) mediante una reforma integral del régimen informativo periódico, con el objetivo de modernizar, simplificar y hacer más eficiente el marco regulatorio del mercado de capitales, fortaleciendo la transparencia y la protección del inversor.\nLa norma redefine las obligaciones de información de las emisoras con oferta pública, estableciendo un esquema más claro y unificado de presentación de información anual y trimestral, con plazos precisos, incorporación de reportes de gobierno corporativo y mayor énfasis en la calidad y comparabilidad de los estados financieros. Asimismo, en la memoria a presentar, deberán informar acerca de su política ambiental o de sustentabilidad, incluyendo, si tuvieran, los principales indicadores de desempeño de la Emisora en la materia, o, en caso de no contar con tales políticas o indicadores, deberán explicar los motivos por los que sus administradores consideran que no son pertinentes para su negocio.\nQuedan excluidas de la obligación indicada en el párrafo precedente las sociedades, cooperativas, y asociaciones que califiquen como PyME CNV conforme lo establece el Capítulo VI del Título II de estas Normas; aquellas que emitan únicamente bajo el Régimen de Oferta Pública con Autorización Automática por su Bajo o Mediano Impacto; y aquellas inscriptas o que soliciten su inscripción en el Registro especial para constituir programas globales de emisión de valores representativos de deuda con plazos de amortización de hasta TRESCIENTOS SESENTA Y CINCO (365) días corridos, los CEDEAR y CEVA\n\nComo se desprende de lo antes señalado, introduce un enfoque de simplificación regulatoria, eliminando exigencias consideradas redundantes o desactualizadas, y reduciendo cargas administrativas, especialmente para PyMEs y emisoras de menor impacto, a las que se les otorgan regímenes informativos más flexibles o incluso excepciones.\nAsimismo, armoniza criterios contables y de presentación, alineándolos con estándares nacionales e internacionales (NIIF), e incorpora pautas más estrictas sobre la responsabilidad del directorio en la elaboración, valuación y aprobación de los estados financieros, reforzando la necesidad de respaldo técnico y control interno.\nLa resolución también contempla particularidades para distintos tipos de entidades (financieras, aseguradoras, asociaciones, cooperativas), permitiendo la aplicación de normas específicas de sus organismos de control, e integra obligaciones para emisoras con actividad en mercados internacionales.', 'Si cotizan en Bolsa deben informar acerca de su política ambiental o de sustentabilidad, incluyendo, si tuvieran, los principales indicadores de desempeño de la Emisora en la materia, o, en caso de no contar con tales políticas o indicadores, deberán explicar los motivos por los que sus administradores consideran que no son pertinentes para su negocio.', 2, NULL, NULL, NULL, 5, NULL, NULL, 11, '{"custom_1783383400370": "Gral Ambiente", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "COMISIÓN NACIONAL DE VALORES"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, NULL, 'Crea, en la órbita del Subsecretaaría de Ambiente de la Nación, el CENTRO DE INFORMACIÓN AMBIENTAL (CIAM), sistema integrado de libre acceso que tendrá por objeto, a través de la implementación de tecnologías de monitoreo y procesamiento, generar, centralizar y sistematizar datos, estadísticas y proyecciones relativos al estado, evolución y tendencias del ambiente, sus ecosistemas y los recursos naturales, para su posterior análisis y divulgación.\n\nLa Resolución 202/2021:\nCrea el “PROGRAMA NACIONAL DE PREVENCIÓN DEL RIESGO AMBIENTAL” que tiene objetivos generales el potenciar las capacidades técnico administrativas de la autoridad ambiental de aplicación local, en relación al control del cumplimiento del Seguro Ambiental Obligatorio e identificar las distintas problemáticas que se presentan tanto en el ámbito interjurisdiccional, como a nivel provincial.\nTambién tendrá como objetivos particulares el fortalecimiento e integración de información del Seguro Ambiental Obligatorio que permita disponer de un registro permanente y actualizado de industrias que se encuentren obligadas a su cumplimiento (cfr. Art. 22, Ley 25.675) y la implementación de un plan de capacitaciones a los organismos provinciales y autoridades de aplicación local.\nPara la ejecución del Programa, se desarrollará una plataforma en el Centro de Información Ambiental (CIAM) donde se sistematice los datos de los expedientes de la DIRECCIÓN  DE MONITOREO Y PREVENCIÓN  junto con la creación de un Mapa del Riesgo Ambiental a nivel nacional utilizando los datos de la UNIDAD DE EVALUACIÓN DE RIESGOS AMBIENTALES, de la DIRECCIÓN DE MONITOREO Y PREVENCIÓN y el Sistema Integral de Gestión de Garantías Ambientales (SIGGA), donde las aseguradoras tienen la obligación de informar los seguros que emiten.', 'Tener en cuenta en el caso de necesitar información sobre los recursos naturales.\n\n\nEl CIAM tendrá información del Seguro Ambiental Obligatorio que permita disponer de un registro permanente y actualizado de industrias que se encuentren obligadas a su cumplimiento (cfr. Art. 22, Ley 25.675) y la implementación de un plan de capacitaciones a los organismos provinciales y autoridades de aplicación local.', 2, NULL, 'No requiere. Es de carácter informativa', 'Es informativa', 8, NULL, NULL, 12, '{"custom_1783383400370": "Gral Ambiente", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "MAyDS", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Riesgo Ambiental", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 481);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 434);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo su articulado', 'Aprueba el “PLAN NACIONAL DE ACCIÓN SOBRE EMPRESAS Y DERECHOS HUMANOS 2023-2026”, elaborado en el marco de las acciones promovidas por el MINISTERIO DE RELACIONES EXTERIORES, COMERCIO INTERNACIONAL Y CULTO.\n\nEstablece como objetivos del “PLAN NACIONAL DE ACCIÓN SOBRE EMPRESAS Y DERECHOS HUMANOS 2023-2026” los siguientes:\na) Objetivo 1: Fortalecer políticas públicas y promover acciones para respetar, proteger y cumplir los Derechos Humanos en el marco de actividades empresariales, dotando de mayor coherencia a las políticas públicas con incidencia en dicho marco;\nb) Objetivo 2: Profundizar la capacidad de los agentes del Estado y fomentar un entendimiento común sobre los estándares internacionales de empresas y Derechos Humanos;\nc) Objetivo 3: Incentivar un mayor diálogo entre áreas de gobierno que abordan la temática de Empresas y Derechos Humanos para facilitar un mayor involucramiento y participación en el diseño e implementación de políticas públicas.', 'Norma Institucional informativa que en razón de mencionar a los ODS. El Estado debe iniciar diálogo con las empresas', 1, 'Informativa', 'No requiere. Es de carácter informativa', 'Es informativa', 8, NULL, NULL, 13, '{"custom_1783383400370": "Gral Ambiente", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "SSAN", "custom_1783383763840": "TODOS", "custom_1783383788609": "No aplicable", "custom_1783383823178": "Empresas y Derechos Humanos", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 339);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', '1. Obtención de factibilidad de vuelco de efluentes 2. Presentación de DDJJ annual                                                                                    3. Observar los límites permisibles de descarga. \nResolución 113/2020: Subsecretaaría de Ambiente de la Nación (14/04/2020)\nFija una multa de PESOS VEINTICINCO MIL ($ 25.000) a los establecimientos industriales y/o especiales que omitieren presentar en término la Declaración Jurada Anual de Efluentes Líquidos Industriales, a la que hace referencia el Decreto N° 674/89, modificado por el Decreto N° 776/92.', 'Régimen aplicable a los establecimientos industriales y/o especiales, que produzcan en forma continua o discontinua vertidos residuales o barros originados por la depuración de aquéllos a conductos cloacales, pluviales o a un curso de agua, de modo que directa o indirectamente, en el radio de Capital  Federal y los partidos de la provincia de Buenos Aires acogidos al régimen de la empresa  AySA (ex Obras Sanitarias de la Nación.)\n\nSe exige la obtención de factibilidad de vuelco de efluentes líquidos y la presentación de la Declaración Jurada Anual de los efluentes volcados. Tener en cuenta que las multas se aplican en forma automática', 2, 'Factibilidad de Vuelco                                                     Requerir a AYSA                                                  Declaración Jurada                                                      Anual. \nDebe asimismo obtener permiso de vuelco de la prestadora AYSA.', 'No aplica por no producir vuelcos industriales. No debe realizar declaracion jurada ni obtener la factibilidad de vuelco de la prestadora. Solo vuelcan efluentes cloacales- Tampoco la normativa ACUMAR', 'No aplicable', 6, NULL, NULL, 14, '{"custom_1783383400370": "Agua", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaría de Ambiente de la Nación", "custom_1783383763840": "Vencimiento todos los meses de abril", "custom_1783383788609": "No aplicable", "custom_1783383823178": "Contaminacion de aguas", "custom_1784900000002": "No aplicable", "custom_1783384038540": "NO APLICABLE"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1370);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 888);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 492);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'Créase una UNIDAD FIJA (UF) como unidad de medida para la determinación de las infracciones que se cometan con relación a lo previsto en los artículos 31 y 34 de la Ley Nº 13.577, modificada por la Ley Nº 20.324, sus normas reglamentarias y complementarias, cuyo valor será equivalente al valor de la Unidad Retributiva fijada en virtud de lo establecido en el Convenio Colectivo de Trabajo Sectorial del Personal del Sistema Nacional de Empleo Público (SINEP), homologado por el Decreto N° 2098/08, sus modificatorias y\ncomplementarias.', 'Sustitúyese el artículo 15 del Decreto N° 674/89 y su modificatorio por el siguiente:\n“ARTÍCULO 15.- Las infracciones especificadas en el artículo 14 del presente decreto y Sustitúyese el inciso c) del artículo 1º del Decreto N° 776/92', 2, 'Factibilidad de Vuelco                                                     Requerir a AYSA                                                  Declaración Jurada                                                      Anual. \nDebe asimismo obtener permiso de vuelco de la prestadora AYSA.', 'No aplica por no producir vuelcos industriales. No debe realizar declaracion jurada ni obtener la factibilidad de vuelco de la prestadora. Solo vuelcan efluentes cloacales- Tampoco la normativa ACUMAR', 'No aplicable', 6, NULL, NULL, 15, '{"custom_1783383400370": "Agua", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaría de Ambiente de la Nación", "custom_1783383763840": "Vencimiento todos los meses de abril", "custom_1783383788609": "No aplicable", "custom_1783383823178": "Contaminacion de aguas", "custom_1784900000002": "No aplicable", "custom_1783384038540": "NO APLICABLE"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 415);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Abroga las Resoluciones N° 85 de fecha 22 de junio de 2000 del ex Instituto Nacional del Agua y del Ambiente, N° 607 de fecha 14 de marzo de 2012 y N° 555 de fecha 8 de marzo de 2012 de la ex Secretaría de Ambiente y Desarrollo Sustentable de la JEFATURA DE GABINETE DE MINISTROS y la Resolución N° 113 de fecha 11 de abril de 2020 del Subsecretaaría de Ambiente de la Nación, las cuales mantendrán sus efectos respecto a procedimientos o infracciones anteriores a la vigencia de la presente norma, de acuerdo a lo expuesto en los considerandos de la presente resolución.\n\nActualiza la multa por no presentar en término la Documentación Técnica Obligatoria y/o que no den cumplimiento en tiempo y forma a las observaciones y requerimientos del Subsecretaaría de Ambiente de la Nación en MIL UNIDADES FIJAS (1.000 UF) a aplicarse a los establecimientos industriales y/o especiales alcanzados por el régimen del Decreto N° 674 de fecha 24 de mayo de 1989, modificado por los Decretos Nº 776 de fecha 12 de mayo de 1992 y N° 241 de fecha 5 de mayo de 2022.\n\nFija un plazo máximo de SESENTA (60) días hábiles a otorgar para la presentación de la Documentación Técnica Obligatoria. Vencido el plazo otorgado y ante la no presentación de la Documentación Técnica Obligatoria se procederá a aplicar la sanción que fija el párrafo anterior.', 'Tener en cuenta por procedimiento de aplicación de multas, planos de CTM, plazo para realizar presentaciones.', 2, 'CTM conforme a norma         Factibilidad de Vuelco                                                     Requerir a AYSA                                                  Declaración Jurada                                                      Anual. \nDebe asimismo obtener permiso de vuelco de la prestadora AYSA.', 'No aplica por no producir vuelcos industriales. No debe realizar declaracion jurada ni obtener la factibilidad de vuelco de la prestadora. Solo vuelcan efluentes cloacales- Tampoco la normativa ACUMAR', 'No aplicable', 6, NULL, NULL, 16, '{"custom_1783383400370": "Agua", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Vencimiento todos los meses de abril", "custom_1783383788609": "No aplicable", "custom_1783383823178": "Contaminacion de aguas", "custom_1784900000002": "No aplicable", "custom_1783384038540": "NO APLICABLE"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'toda', 'Se modifica en su totalidad el marco regulatorio de prestación de servicio de aguas y cloacas, en a ex zona servida por OSN, hoy AySA - Ley Nacional N.º 26.221-, su ámbito de aplicación es CIUDAD AUTÓNOMA DE BUENOS AIRES y al comprendido por el territorio de los siguientes partidos de la Provincia de Buenos Aires, Almirante Brown, Avellaneda, Esteban Echeverría, Ezeiza, La Matanza, Lanús, Lomas de Zamora, Morón, Quilmes, San Fernando, San Isidro, General San Martín, Tres de Febrero, Tigre y Vicente López, respecto a los servicios de agua potable y desagües cloacales; Hurlingham e Ituzaingó respecto del servicio de agua potable; y los servicios de recepción de efluentes cloacales en bloque de los partidos de Berazategui y Florencio Varela,  posteriormente, mediante las Resoluciones Nros. 425/16 y 682/16 del ex-MINISTERIO DEL INTERIOR, OBRAS PÚBLICAS Y VIVIENDA se incorporaron al ámbito de aplicación los municipios de José C. Paz, Moreno, Merlo, Malvinas Argentinas, Florencio Varela, San Miguel, Presidente Perón, Escobar y Pilar. La modificación se realiza teniendo en cuenta la emergencia pública en materia económica, financiera, fiscal, administrativa, previsional, tarifaria, sanitaria y social declarada por el artículo 1° del Decreto N° 70/23 hasta el 31 de diciembre de 2025, y la necesidad de asegurar la continuidad en la prestación del servicio de agua potable en condiciones óptimas, se considera indispensable avanzar en la adopción de medidas inmediatas y eficaces para hacer frente a esta coyuntura. Entre las medidas que se incorporan se encuentra la posibilidad del corte de suministro ante la falta de pago. \n \nEn lo relativo a los efluentes industriales, establece un sistema de toma de muestras para el control de calidad, el cual estará a cargo de la Concesionaria. En este marco, los establecimientos industriales deberán someterse a una determinada cantidad de muestreos de rutina, según el rubro al que pertenezcan, de acuerdo con lo dispuesto en el Anexo 2 C del Decreto. Dicho Anexo especifica los distintos rubros industriales, la frecuencia de las inspecciones, los tipos de muestras a tomar y los parámetros a analizar. \n \nAsimismo, se establece un mecanismo de control indirecto de efluentes, que consiste en la realización de monitoreos en los puntos de descarga de las micro y macro cuencas. En caso de detectarse resultados que superen los límites establecidos por el marco regulatorio, se activará un control directo no programado en los establecimientos industriales involucrados.\n \nPor último, la norma prohíbe expresamente el vertido de residuos peligrosos, especiales y/o patogénicos, así como de barros u otros residuos contaminantes, en el sistema de desagües cloacales operado por la Concesionaria como método de disposición. En caso de detectarse vertidos fuera de los parámetros establecidos o que revistan peligrosidad, la Concesionaria deberá intimar al responsable para que adecúe la calidad de los efluentes dentro del plazo que se le fije. Asimismo, podrá facturar a los usuarios industriales el costo diferencial del tratamiento que requieran aquellos efluentes que superen los límites permitidos. En caso de reincidencia, la Concesionaria estará facultada a proceder al corte de la conexión cloacal.', 'Si en algún momento se vuelca a colectora, la concesionaria controlará todos los parámetros  que deriven del proceso', 2, 'Complir con los limites establecidos en la norma paa vuelcos cloacales. CTM conforme a norma         Factibilidad de Vuelco                                                     Requerir a AYSA                                                  Declaración Jurada                                                      Anual. \nDebe asimismo obtener permiso de vuelco de la prestadora AYSA.', 'Controlar los efluentes', 'No aplicable', 6, NULL, NULL, 17, '{"custom_1783383400370": "Agua", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "AySA", "custom_1783383763840": "Vencimiento todos los meses de abril para presentar DDJJ", "custom_1783383788609": "No aplicable", "custom_1783383823178": "Contaminacion de aguas", "custom_1784900000002": "No aplicable"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Se aprueban los lineamientos establecidos bajo el Anexo I (IF-2019-89573199-APN-DSYPQ#SGP), tendientes a lograr el manejo ambientalmente racional de los plásticos en todo su ciclo de vida, a fin de mitigar el avance de la contaminación de los cuerpos de agua a causa de los residuos plásticos y microplásticos y su consecuente impacto en el ambiente', 'Informativa y por ahora vountaria a los fines de gestionar los plásticos- economía circular', 1, 'Informativa', 'No requiere. Es de carácter informativa', 'Es informativa', 8, NULL, NULL, 18, '{"custom_1783383400370": "Residuos- Plastico", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaría de Ambiente de la Nación hoy Ministerio de Ambiente y Desarrollo Sustentable", "custom_1783383763840": "TODOS", "custom_1783383788609": "No aplicable", "custom_1783383823178": "Residuos Plásticos", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 63);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'El Estándar Nacional de Seguridad para la exposición a radiofrecuencias comprendidas entre 100 KHz y 300 GHz será de aplicación obligatoria a todos los sistemas de Telecomunicaciones que irradian, en frecuencias comprendidas entre 100 KHz y 300 GHz, situados en el territorio nacional.', 'Los titulares de autorizaciones de estaciones radioeléctricas de radiocomunicaciones y los licenciatarios de estaciones de radiodifusión, deberán demostrar que las radiaciones generadas por las antenas de sus estaciones no afectan a la población en el espacio circundante a las mismas, mediante una evaluación. Los titulares de licencias de radioaficionados deberán presentar el formulario técnico específico y la declaración jurada relativa al cumplimiento de la Resolución No 530 SC/2000, para cada una de sus estaciones fijas', 2, 'Presentacion de Formulario Tecnico Específico. Declaracion Jurada de cumplimiento de Estandares de Resolucion 530/2000', 'Cumple. Se miden radiaciones no ionizantes y se cuenta con las autorizaciones de ENACOM', 'Informe de medición de radiaciones no ionizantes realizado en diciembre 2019 en Artigas', 1, NULL, NULL, 19, '{"custom_1783383400370": "Antenas y Radiaciones No Ionizantes", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "CNC/MSyAS ahora ENACOM", "custom_1783383763840": "Continuo", "custom_1783383788609": "Field Operations", "custom_1783383823178": "Radiación no ionizante", "custom_1784900000002": "Field Operations\\nEHS"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Esta Ley genera las siguientes obligaciones: 1) Clasificar los residuos;\n2) Inscribirse como generador, transportista y/u operador;\n3) Obtener el CAA; \n4) Renovarlo anualmente, previa presentación de DDJJ; \n5) Gestionar adecuadamente los residuos; \n6) Abonar la tasa ambiental\n7) Registrarse en SIMEL\nAsimismo la Resolucion 177/17 establece condiciones y requisitos para sectores destinados al almacenamiento transitorio de residuos peligrosos. Asi en el Anexo I de la Resolucion para los Generadores se establece: \nA-1 Condiciones y Requisitos mínimos para sectores de acopio de residuos peligrosos generados\na) El sector destinado al acopio de residuos peligrosos, deberá encontrarse claramente delimitado, identificado y con acceso restringido utilizando cartelería con la leyenda “ACCESO RESTRINGIDO- ALMACENAMIENTO DE RESIDUOS PELIGROSOS”;\nb) Deberá hallarse separado de otras áreas de usos diferentes, con distancias adecuadas según el riesgo que presenten, impidiendo el contacto y/o la mezcla con residuos no peligrosos, insumos o materias primas;\nc) Deberá contar con piso o base impermeable y estar techado o poseer medios para resguardar los residuos peligrosos acopiados de las condiciones meteorológicas;\nd) Deberá contar con un sistema de colección, captación y contención de posibles derrames, que no permita vinculación alguna con desagües pluviales o cloacales. Los sistemas deberán poseer tapa o rejilla;\ne) Deberá poseer dimensiones acordes a la tasa de generación de residuos peligrosos y la periodicidad de los retiros;\nf) El acopio de los residuos peligrosos, deberá efectuarse en recipientes estancos, de materiales quimicamente compatibles, debidamente tapados o cerrados, impidiendo el contacto y/ o la mezcla con residuos no peligrosos, insumos o materias primas;\ng) Los recipientes deberán poseer rótulo indeleble e inalterable, identificando el/los residuos peligrosos contenidos incluyendo la siguiente información: descripción, categorización (Y), característica de peligrosidad (H) y nombre del Generador, a efectos de propender a su correcta gestión integral;\nh) Los residuos peligrosos deberán disponerse con un ordenamiento que permita su sencilla contabilización, dejando a su vez pasajes de UN (1) metro de ancho como mínimo, para acceder a verificar su estado.\nA-2 Condiciones y Requisitos mínimos para el almacenamiento transitorio en puntos de generación.\nEn los puntos de generación de residuos peligrosos, sector o puesto de trabajo, cada recipiente de acopio, deberá encontrarse identificado con rótulo indeleble e inalterable indicando la/s categoría/s sometida/s a control y la descripción del/los residuo/s contenidos dentro de éstos.\n\nFinalmente la Resolucion 232/18 estabelce que los Generadores, Transportistas u Operadores de residuos peligrosos que tramiten la renovación del Certificado Ambiental Anual, deberán dar inicio a dicho trámite mediante un nuevo Expediente Electrónico. Declaración Jurada.', 'La Ley Nacional 24051, establece la obligacion de gestionar de correcta manera los Residuos Peligrosos. Para ello impone obligaciones en todas las etapas de gestion de los mismos, esto es : Generador, Transportista y Operador. Establece un sistema de Responsabilidad por los incumplimientos a lo establecido en la Ley en el ambito Administrativo, Civil y Penal.', 2, 'Generador de Residuos: Obtener el CAA (Certificado Ambiental Anual) con renovacion anual y estar inscripto en SIMEL. Para Transportista Interjurisdiccional poseer el Permiso correspondiente', 'Se encuentra inscripto debe reinscribirse y tener el pago de la tasa al dia', 'La empresa se encuentra inscripta en Simel.  Aun no se ha emitido el CAA. Se verifica que los operadores esten habilitados.\nTasa de residuos peligrosos fue pagada el 31/12/2024 correspondiente al período 2023.', 3, 'Nación: Presentamos el expediente en el 2023 tanto para Nación como para Ciudad. Aún no se obtiene respuesta por parte del Organismo.\nRevisar si estamos inscritos en SIMEL.', NULL, 20, '{"custom_1783383400370": "Residuos Peligrosos", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaría de Ambiente de la Nación", "custom_1783383763840": "Renovacion Anual", "custom_1783383823178": "proteccion de recursos natturales", "custom_1784900000002": "Data Center Critical Facilities"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1707);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 583);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Aprueba los lineamientos para la gestión ambientalmente racional de la operación de incineración (categorizada D10 conforme Anexo III Sección A de la Ley Nº 24.051), y los requisitos mínimos complementarios a la Ley Nº 24.051 y su Decreto Reglamentario Nº 831/93.\nA los efectos de la presente resolución entiéndase por:\nIncineración: proceso de tratamiento térmico que ocurre a temperaturas de entre OCHOCIENTOS (800) y MIL TRESCIENTOS (1300) grados centígrados en presencia de exceso de oxígeno (λ > 1), y que tiene por finalidad la oxidación completa de todos los compuestos orgánicos contenidos en los residuos (denominada “combustión”) convirtiéndolos en una fase gaseosa (denominado “afluente gaseoso”) y otra sólida incombustible (denominado “cenizas de fondo”); esta definición es complementada con lo dispuesto en artículo 34 de la Ley N° 24.051 y artículo 33 del Decreto Reglamentario N° 831/93.\nAfluente gaseoso: masa de gases y material particulado procedente de la descomposición térmica de residuos peligrosos que es destinada a un sistema de obtención de energía (conversión energética) o a un sistema de tratamiento previo a su descarga a la atmósfera para cumplir con el límite de descarga o emisión correspondiente.\nEn tales casos luego de su utilización o tratamiento, se denomina “emisión gaseosa”.\nSistema de tratamiento de afluentes gaseosos: equipamiento que consta de operaciones unitarias y consecutivas por las cuales son conducidos los afluentes gaseosos de la combustión de un horno de incineración, cuya finalidad es su acondicionamiento para alcanzar el nivel de calidad de los parámetros establecidos en el límite de descarga y emisión correspondiente.\nHorno de incineración: equipamiento donde sucede la incineración y que consta de un sistema de carga de residuos, cámara de combustión primaria, cámara de combustión secundaria (integradas o separadas), y un sistema de descarga de cenizas de fondo.\nSistema de control: equipamiento conectado al horno y su sistema de tratamiento de afluentes gaseosos, con interfaz a un sistema computarizado donde se visualizan los parámetros operativos de proceso y calidad de la emisión.\nParámetros de proceso: temperatura, presión, caudal, valores límites permitidos de emisión.\nPrueba de eficiencia de incineración (PEI): actividad en la que, aplicando un protocolo aprobado, se verifican los parámetros de funcionamiento del horno, los límites de emisión y se calcula la eficiencia de la destrucción de una o más sustancia/s particular/es que compone/n los residuos peligrosos incinerados.', 'Tener en cuenta que puede realizarse tratamiento por incineración y por lo tanto se deben contratar sólo a plantas que puedan cumplir con esta normativa.', 1, 'Informativa', 'Certificado de tratamiento/destrucción', 'Responsable de residuos', 5, '09/10/2024: NACIÓN: Posee número de expediente EX-2021-02895705- -APN-DNSYPQ#MAD a nombre de CENTURYLINK ARGENTINA S.A. y formulario de solicitud de inscripción según IF-2021-02895656-APN-DTD#JGM.\nPosee aprobación de informe técnico final con fecha 14-08-2023 y habilitación de usuario SIMEL 30626747171/1\nEstudio legal ingresará la Solicitud de pronto despacho para obtener el Certificado Ambiental Anual', NULL, 21, '{"custom_1783383400370": "Residuos Peligrosos", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaria de Ambiente de la Nación", "custom_1783383763840": "Continua", "custom_1783383788609": "Tratamianto de residuos", "custom_1783383823178": "residuos", "custom_1784900000002": "responsable de residuos"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, NULL, 'Aprueba el Listado Operativo de Residuos Peligrosos abarcados por las Categorías Sometidas a Control previstas en el Anexo I de la Ley N° 24.051, de acuerdo al Anexo Único de la presente medida.\nEl Listado Operativo de Residuos Peligrosos deberá ser revisado en forma periódica y mantenerse actualizado por la Coordinación de Residuos Peligrosos de la Dirección Nacional de Sustancias y Productos Químicos de la Secretaría de Control y Monitorio Ambiental. Esta Resolución entrará en vigencia a partir del día siguiente a su publicación.', 'Tener presente la ampliación que se realizó de residuos peligrosos que deben ser gestionados y tratados como tales.\nSe trata de una norma informativa, pero debe estar porque aclara cosas sobre la obligación que surge de la norma principal.', 1, 'Informativa', 'Informativa', 'Es informativa', 8, NULL, NULL, 22, '{"custom_1783383400370": "Residuos Peligrosos", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Informativa", "custom_1783383788609": "Infraestructura\\nReal Estate\\nEHS", "custom_1783383823178": "Residuos Peligrosos", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 64);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, NULL, 'Sustituye el artículo 3º del Anexo I a la Resolución del ex Ministerio de Ambiente y Desarrollo Sustentable Nº RESOL-206-2016-APN-MAD, que fija el procedimiento para la verificación del cumplimiento de la obligación establecida en el artículo 22 de la Ley N.º 25.675 (seguro ambiental), el que quedará redactado del siguiente modo: “Artículo 3°: Los administrados que cuenten con el Certificado Ambiental Anual (C.A.A.) conforme lo dispuesto por Ley N.° 24.051, deberán dar estricto acatamiento a lo establecido en los artículos 1° y 2° del presente, en un plazo perentorio de 20 días hábiles administrativos, a partir de la notificación de la Resolución que lo otorga. En el caso que los administrados intimados justifiquen fehacientemente que existen causas que no les son imputables y les impiden dar cumplimiento al requerimiento; la UNIDAD DE EVALUACION DE RIESGOS AMBIENTALES tendrá la facultad de conceder una prórroga de 10 días hábiles administrativos a los mismos.\nVencido el plazo perentorio de la intimación, sin haber acreditado la documentación pertinente, los infractores serán pasibles de las sanciones previstas en el régimen establecido en el artículo 49 y subsiguientes de la Ley N.° 24.051.”', 'Tener en cuenta que los sujetos que deban obtener CAA deben presentar la documentación correspondiente al seguro ambiental colectivo obligatorio.', 2, 'Acción', 'No se tiene contratado el seguro ambiental. Al actualizar el NCA se definió que Cirion deberá contratar el seguro.', 'Se realizó el cálculo del NCA en diciembre 2024 dando un valor de 16. Se contratará un seguro ambiental, pero en caso de recertificar se encotrarían excentos porque bajaría el NCA a 12, sindo el límite 14,5', 5, 'Se encuantran en proceso de re-certificación ISO 14001', NULL, 23, '{"custom_1783383400370": "Residuos Peigrosos", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Continua", "custom_1783383788609": "EHS", "custom_1783383823178": "Seguro Ambiental", "custom_1784900000002": "EHS"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 429);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'Se crea el procedimiento de RÉGIMEN SIMPLIFICADO (RS) para GENERADORES MENORES de residuos en los términos de la Ley Nº 24.051, artículo 14 del Decreto 831/93, cuyas actividades de manipulación, transporte, tratamiento y/o disposición final se desarrollen conforme el PLAN DE GESTION previsto en el Anexo I (IF-2019-22475406-APN-DR#SGP).\nSon alcanzados por el REGIMEN SIMPLIFICADO aquellos generadores que se hallan comprendidos dentro de los rubros listados en el Anexo II (IF-2019-22512405-APN-DR#SGP) y generan de manera exclusiva los residuos allí detallados.\nLa solicitud del Certificado Ambiental Anual debe realizarse mediante Declaración Jurada a través de la plataforma TAD conforme el contenido previsto en el Anexo III (IF-2019-36635667-APN-DR#SGP). Se emitirá el Certificado Ambiental Anual una vez acreditados los pagos exigidos por las normas correspondientes y caratulado el expediente.\nLa renovación del certificado se realizará mediante Declaración Jurada a través de la plataforma TAD, cuyo contenido deberá ajustarse al Anexo IV (IF-2019-22516922-APN-DR#SGP). En aquellos supuestos en los que el Certificado Ambiental Anual se encontrare vigente y la actividad, residuos peligros y cantidades declaradas no hubieren sufrido modificaciones, se emitirá uno nuevo. En caso contrario, deberá tramitarse el que corresponda. El plazo dentro del cual deberá iniciarse la Renovación del Certificado Ambiental Anual deberá encontrarse comprendido dentro de los 30 (treinta) días previos al vencimiento del mismo.\nEn caso de comprobarse inexactitud en las manifestaciones de la Declaración Jurada, o faltare el pago de las tasas exigidas por ley, se procederá a intimar al administrado a la subsanación y/o cumplimiento, dando asimismo inicio a las actuaciones correspondientes, conforme lo establecido por el Artículo 9 de la Ley Nº 24.051; sin perjuicio de la aplicación de lo dispuesto en los Artículos 49, 50 y 51 de la citada ley; y pudiendo ser penado según los artículos 138, 173 inc. 8), 74 inc. 5), 255, 292, 293, 296, 297 y 298 del Código Penal de la Nación.\nEl Certificado Ambiental Anual que se otorgue a Generadores Menores por Régimen Simplificado, se ajustará al contenido previsto en el anexo V (IF-2019-22520114-APN-DR#SGP).\nLa presente Resolución entrará en vigencia a los 90 días de publicada. Los Anexos I a V forman parte de la presente.', 'Si son pequeños generadores pueden utlizar este procedimiento para inscribirse y renovar el CAA', 1, 'Informativa', 'CAA, manifiestos y certificados de tratamiento de los residuos', NULL, 4, 'De acuerdo a la cantidad de residuos peligrosos generada en el 2023 en Artigas, se considera a Cirion pequeños generadores de residuos?', NULL, 24, '{"custom_1783383400370": "REGIMEN SIMPLIFICADO PARA PEQUEÑOS GENERADORE DE RESIDUOS PELIGROSOS", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "SECRETARÍA GENERAL-SECRETARÍA DE GOBIERNO DE AMBIENTE Y DESARROLLO SUSTENTABLE \\nHOY MINISTERIO DE AMBIENTE Y DESARROLLO SUSTENTABLE", "custom_1783383763840": "anual", "custom_1783383788609": "Area generadora de residuos peligrosos", "custom_1783383823178": "Contaminación del Ambiente en general", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 540);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Se crea el SISTEMA DE GESTION INTEGRAL DE RESIDUOS Y OTROS (GIRO), cuya implementación será llevada a cabo por la DIRECCIÓN DE RESIDUOS de la SECRETARÍA DE CONTROL Y MONITOREO AMBIENTAL dependiente de la SECRETARÍA DE GOBIERNO DE AMBIENTE Y DESARROLLO SUSTENTABLE DE LA SECRETARÍA GENERAL DE LA PRESIDENCIA DE LA NACIÓN.\nSe otorga un plazo de 60 días corridos, una vez productivo el sistema GIRO, para que todos los generadores, transportistas y operadores que desarrollan su actividad en interjurisdicción, procedan a registrarse y dar de alta los establecimientos que suscribirán manifiestos a través del mismo.\nSe otorga un plazo de 240 días corridos una vez productivo el sistema para derogar las Resoluciones N° 827/2015, y su modificatoria E 213/2017 a fin de migrar en forma definitiva la trazabilidad en materia de gestión integral de residuos al sistema GIRO.', 'SISTEMA DE GESTION INTEGRAL DE RESIDUOS Y OTROS (GIRO),', 1, 'Informativa', 'No requiere. Es de carácter informativa', 'Es informativa', 8, NULL, NULL, 25, '{"custom_1783383400370": "Residuos Peligrosos", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaría de Ambiente de la Nación hoy Ministerio de Ambiente y Desarrollo Sustentable", "custom_1783383763840": "Continuo", "custom_1783383823178": "Generadores de residuos peligrosos", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 511);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Artículo 1 y 2 de la Ley y corrientes establecidas en el Anexo I de la Ley', 'El artículo 1 de la Ley 24051 dispone que la generación, manipulación, transporte, tratamiento y disposición final de residuos peligrosos quedarán sujetos a las disposiciones de la presente ley, cuando se tratare de residuos generados o ubicados en lugares sometidos a jurisdicción nacional o, aunque ubicados en territorio de una provincia estuvieren destinados al transporte fuera de ella, o cuando, a criterio de la autoridad de aplicación, dichos residuos pudieren afectar a las personas o el ambiente más allá de la frontera de la provincia en que se hubiesen generado, o cuando las medidas higiénicas o de seguridad que a su respecto fuere conveniente disponer, tuvieren una repercusión económica sensible tal, que tornare aconsejable uniformarlas en todo el territorio de la Nación, a fin de garantizar la efectiva competencia de las empresas que debieran soportar la carga de dichas medidas:\nPor su lado el artículo 2 determina que Será considerado peligroso, a los efectos de esta ley, todo residuo que pueda causar daño, directa o indirectamente, a seres vivos o contaminar el suelo, el agua, la atmósfera o el ambiente en general.\nEn particular serán considerados peligrosos los residuos indicados en el Anexo I o que posean alguna de las características enumeradas en el Anexo II de esta ley.\nLas disposiciones de la presente serán también de aplicación a aquellos residuos peligrosos que pudieren constituirse en insumos para otros procesos industriales.\nQuedan excluidos de los alcances de esta ley los residuos domiciliarios, los radiactivos y los derivados de las operaciones normales de los buques, los que se regirán por leyes especiales y convenios internacionales vigentes en la materia.', 'La Ley Nacional 24051, establece la obligacion de gestionar de correcta manera los Residuos Peligrosos. Para ello impone obligaciones en todas las etapas de gestion de los mismos, esto es : Generador, Transportista y Operador. Establece un sistema de Responsabilidad por los incumplimientos a lo establecido en la Ley en el ambito Administrativo, Civil y Penal.', 2, 'Generador de Residuos: Obtener el CAA con renovacion anual y estar inscripto en SIMEL.\n Para Transportista Interjurisdiccional poseer el Permiso orrespondiente', 'La enfermeria no genera residuos patogenicos', 'No aplica ya que no somos generadores de residuos patogenicos', 6, NULL, NULL, 26, '{"custom_1783383400370": "Residuos Peligrosos", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaría de Ambiente de la Nación", "custom_1783383763840": "\\"Renovacion Anual\\nDe acuerdo a lo dispuesto en la Resolucion 238/18, Los generadores, operadores y transportistas de residuos peligrosos que tuvieran certificado ambiental anual vigente, podrán solicitar la renovación anual automática, hasta 60 (sesenta) días previo a su vencimiento, siempre que la gestión de sus residuos peligrosos no hubiera sufrido modificaciones:\\nSe entenderá renovado el Certificado Ambiental Anual, cuando generador operador o transportista, declare bajo juramento que no ha sufrido modificaciones en los procesos de tratamiento, operaciones de eliminación o disposición final; en el manejo de los residuos peligrosos o en las Categorías Sometidas a Control (CSC), o en la capacidad máxima de almacenamiento o en los sectores de acopio, o en el proceso y/o actividad realizada; altas y/o bajas de las unidades de la flota automotor/embarcaciones, respecto del certificado que se pretende renovar\\"", "custom_1783383823178": "proteccion de recursos naturales", "custom_1784900000002": "No aplicable", "custom_1783384038540": "NO APLICABLE"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1707);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Toda persona física o jurídica que genere, transporte o de tratamiento a Residuos Peligrosos, deberá realizar dichas actividades de acuerdo a lo establecido por la presente Ley. Ademas para desarrollar las actividades descriptas debe estar inscripto en cada uno de los Registros establecidos por la Secretaría de Ambiente de la Nación', 'Inscripto en Nacion 2017-01792081 e inscripto en Simel debe presentar tasa abonada correspondiente al período 2023 para completar DDJJ que le otorgue el Certificado de Habilitacion como operador. Ciudad: debe instar el tramite', 2, 'Todo Residuos Peligroso debe gestionarse con su correspondiente Manifiesto', 'Las baterías se acopian en el deposito de residuos peligrosos', 'Manifiestos de residuos peligrosos', 1, 'Con fecha 31/12/2024 se abonó la tasa de retiros de residuos peligrosos por el período 2023', NULL, 27, '{"custom_1783383400370": "Residuos. Pilas y Baterias", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Congreso Nacional", "custom_1783383763840": "Renovacion Anual a través de la tasa", "custom_1783383788609": "Infraestructura\\nReal Estate", "custom_1783383823178": "contaminacion de recursos naturales / Residuos peligrosos", "custom_1784900000002": "Infraestructura", "custom_1783384038540": "#REF!"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1707);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Esta resolución tiene por objeto implementar la Estrategia Nacional de Gestión Sustentable de Residuos Especiales de Generación Universal (REGU) establecida por la resolución N° 522/2016, mediante la creación de Sistemas de Gestión. Quedan comprendidos en la presente los Sistemas de Gestión Sustentable de REGU presentados por productores, organizaciones, instituciones, municipios y jurisdicciones, siempre que prevean interjurisdiccionalidad o el eventual movimiento transfronterizo en alguna de las etapas de gestión.\nLos Sistemas de Gestión Sustentable de REGU deberán cumplir, como mínimo, con\nlos siguientes requisitos:\na. Descripción detallada de la gestión por etapas, contemplando la logística entre el consumidor, punto de recolección, centro de acopio cuando correspondiera y destino final teniendo en cuenta características de peligrosidad, cantidad involucrada y riesgo ambiental. A tal efecto, la propuesta deberá cumplimentar lo dispuesto por el artículo 5° de la Resolución N° 522/2016.\nb. Identificación de las jurisdicciones en las que se procura implementar el Sistema de Gestión clasificándolas específicamente en las siguientes categorías: Jurisdicción / Jurisdicciones de Recolección – entendida como el territorio en el cual se establecerán únicamente puntos de recolección diferenciada de los residuos alcanzados por el Sistema. Jurisdicción / Jurisdicciones de Almacenamiento Transitorio – entendida como el territorio en el cual se establecerán CATs - (Centros de Almacenamiento Transitorio: aquellos lugares específicamente habilitados para la recepción de REGU desde distintas jurisdicciones para su acopio y/o acondicionamiento con el objetivo de su posterior derivación para su valorización, tratamiento o disposición final. Jurisdicción / Jurisdicciones de Tratamiento / Valorización: entendida como el territorio en el cual se llevarán a cabo tareas de tratamiento y/o valorización. Jurisdicción / Jurisdicciones de Destino Final: entendida como el territorio en el cual se llevarán a cabo las tareas de disposición final adecuada o exportación. Jurisdicción / Jurisdicciones de Tránsito: entendida como el territorio por el cual los residuos únicamente serán transportados sin que dicho traslado conlleve ninguna de las actividades indicadas anteriormente. Todas las jurisdicciones incluidas en el Sistema de Gestión propuesto deberán identificarse en una de las categorías indicadas, pudiendo una jurisdicción corresponder a más de una categoría.\nc. Procedimientos específicos que para el caso de incluir incentivos que aseguren la devolución de REGU por parte del consumidor.\nd. Identificación precisa de los REGU a gestionar, indicando aquellas características que permitan verificar la trazabilidad y justifiquen la gestión propuesta.\ne. Alcance territorial del programa, identificando las diversas jurisdicciones involucradas y especificando el lugar de generación de los REGU. En caso de proponerse una implementación gradual y progresiva, informar el cronograma propuesto.\nf. Definición de los sistemas de recolección propuestos, indicando los mecanismos previstos para la logística diferenciada y las medidas de seguridad aplicables al transporte a fin resguardar las condiciones materiales del residuo.\ng. Flujo del REGU y sus materiales recuperados, en cada etapa de la gestión desde la recolección hasta su valorización o tratamiento y disposición final si correspondiere incluyendo domicilios de consolidación en caso de exportación.\nh. Régimen de información periódica propuesto, según corresponda.', 'Por esta norma deben tener una gestión sustentable de este tipo de residuos, siendo a mayoría tratados como residuos peligrosos, hasta que se estabelzca una obligación especidfica de diferenciarlos en los planes de gestión de residuos locales.', 1, 'Informativa', 'Es informativa', 'Es informativa', 8, NULL, NULL, 28, '{"custom_1783383400370": "Residuos Especiales de Generación Universal (REGU)", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "SECRETARÍA GENERAL-SECRETARÍA DE GOBIERNO DE AMBIENTE Y DESARROLLO SUSTENTABLE hoy Ministerio de Medio Ambiente", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Si gestión de los residuos contamnación del ambiente", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 541);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Aprueba el MANUAL DE BUENAS PRÁCTICAS Y RECOMENDACIONES PARA LA GESTIÓN SOSTENIBLE DE LOS APARATOS ELÉCTRICOS Y ELECTRÓNICOS EN CONDICIÓN DE REZAGO DE LA ADMINISTRACIÓN PÚBLICA NACIONAL.', 'RESIDUOS DE APARATOS ELÉCTRICOS Y ELECTRÓNICOS- GESTIÓN', 1, 'Informativa', 'Protección del ambiente', 'Es informativa', 8, NULL, NULL, 29, '{"custom_1783383400370": "RESIDUOS DE APARATOS ELÉCTRICOS Y ELECTRÓNICOS", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaría de Ambiente de la Nación", "custom_1783383763840": "Continuo", "custom_1783383788609": "Todos", "custom_1783383823178": "Informativa", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 68);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Se aprueba la GUÍA DE BUENAS PRÁCTICAS AMBIENTALES: RECOMENDACIONES PARA LA CORRECTA GESTIÓN DE RESIDUOS EN OFICINAS, como Anexo I (IF-2019-85375186-APN-DR#SGP)\n\nEn todas largas y cortas. Largas solapa residuos y cortas luego de las dos resoluciones de REGUS (Res 522/2016 y mod) . En obligaciones Voluntarias, tener en cuenta para los planes de gestión. Color Blanco', 'GESTIÓN DE RESIDUOS EN OFICINAS', 1, 'Es potestativa', 'Protección del ambiente', 'Es informativa', 8, NULL, NULL, 30, '{"custom_1783383400370": "Residuos de Oficinas", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "SECRETARÍA GENERAL-SECRETARÍA DE GOBIERNO DE AMBIENTE Y DESARROLLO SUSTENTABLE hoy Ministerio de Medio Ambiente", "custom_1783383763840": "Continuo", "custom_1783383788609": "Todos", "custom_1783383823178": "Informativa", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 519);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Crea el Plan de Compostaje Institucional (PCI) en el ámbito del Subsecretaaría de Ambiente de la Nación (PCI-MAyDS), como estrategia de gestión de valorización de residuos orgánicos. El PCI-MAyDS establece las bases para la planificación e implementación de una buena práctica que tienda a la valorización in situ de residuos orgánicos que se generan y optimice las acciones y decisiones que cotidianamente se toman respecto a los residuos orgánicos en el ámbito institucional.\n\nEl PCI-MAyDS se desarrollará en el ámbito de la Subsecretaría de Fiscalización y Recomposición perteneciente a la Secretaría de Control y Monitoreo Ambiental del Ministerio de Ambiente y la coordinación técnica y operativa estará a cargo de la Dirección de Calidad Ambiental y Recomposición, perteneciente a dicha Subsecretaría.\nSe invita a las provincias y municipios, instituciones, asociaciones y organizaciones y toda otra entidad pública y/o privada, a adherir al Plan de Compostaje Institucional (PCI). La adhesión será realizada mediante la presentación de la Carta de adhesión firmada por la autoridad correspondiente.', 'Si bien no aplica directamnte puede tomarse ya que insta a compostar residuos de oficinas públicas', 1, 'Voluntaria/Institucional', 'Poseer composteras si se cumple con la legislacion', 'Es informativa', 8, NULL, NULL, 31, '{"custom_1783383400370": "Compostaje Institucional", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "ambiente", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Crea  el PROGRAMA EDIFICIOS PÚBLICOS SOSTENIBLES PARA LOS ORGANISMOS DEL SECTOR PÚBLICO NACIONAL, en la órbita de la Unidad Gabinete de Asesores del  Subsecretaaría de Ambiente de la Nación (MAyDS), cuyo objetivo general es promover el manejo y gestión sostenible de recursos mediante buenas prácticas sostenibles de consumo y habitabilidad de acuerdo con lo establecido en el Decreto Nº 31/23. \nAprueba también la Guía de Implementación de Edificios Públicos Sostenibles, que como el Anexo I.', 'Si bien no aplica directamnte puede tomarse ya que insta a compostar residuos de oficinas públicas', 1, 'Voluntaria/Institucional', 'Poseer composteras si se cumple con la legislacion', 'Es informativa', 8, NULL, NULL, 32, '{"custom_1783383400370": "Compostaje Institucional", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "ambiente", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Se crea la categoría “Biopreparado” en materia de autorización y comercialización de insumos (productos) de uso agrícola, en el marco de las competencias del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA (SENASA).\nA los fines de la presente norma, se entiende por “biopreparado” a todo insumo elaborado en base a la combinación o mezcla de sustancias de origen vegetal, animal o mineral presentes en la naturaleza, que tienen propiedades nutritivas para las plantas y/o controladoras, repelentes o atrayentes de plagas y enfermedades, o son utilizadas como enmienda o sustrato, que se hayan obtenido mediante un procedimiento de tipo y escala artesanal accesible a todo usuario final, a partir de recursos mayoritariamente de obtención local.', 'Tener en cuenta en el caso de que decidan comercializar los biopreparados que surgen de la planta de compostaje', 1, 'Voluntaria/Institucional', 'Aplicable solo en caso de realizar compostaje', 'Es informativa', 8, NULL, NULL, 33, '{"custom_1783383400370": "Biopreparados", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA", "custom_1783383763840": "Si deciden producir biopreparados por compostar", "custom_1783383788609": "TODOS", "custom_1783383823178": "Compostaje", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Se implementa el Sistema de Gestión de Actas de Constatación e Inspección del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA (SENASA), en adelante SIG-ACTAS, como el sistema informático principal e interoperable para la gestión de las actas electrónicas del Organismo.\n\nEl SIG-ACTAS será de uso obligatorio para el SENASA, quedando vedada la emisión de actas papel por fuera del referido sistema.\nLos sistemas informáticos actuales de este Servicio Nacional que permitan la emisión de actas de inspección y constatación deberán implementar un servicio web que interaccione con el Sistema SIG-ACTAS. Dichos sistemas deberán adecuarse a fin de cumplir con las características consignadas en el Artículo 1° de la presente medida.\n\nEl SENASA notificará las actas que emita el SIG-ACTAS a través de la plataforma Trámites a Distancia (TAD) o por otro medio electrónico oficial que la reemplace o complemente, encontrándose las personas humanas o jurídicas habilitadas a realizar descargo respecto de lo actuado por el mismo medio electrónico.\nSin perjuicio de los medios consignados en el párrafo que antecede, serán de plena validez las formas de notificación y descargos establecidos por el Reglamento de Procedimientos Administrativos, aprobado por el Decreto N° 1.759/72 T.O. 2017, y por la Resolución N° 38 del 3 de febrero de 2012 del entonces MINISTERIO DE AGRICULTURA, GANADERÍA Y PESCA.', 'Tener en cuenta en caso de que tengan composteras', 1, 'Voluntaria/Institucional', 'Aplicable solo en caso de realizar compostaje', 'Es informativa', 8, NULL, NULL, 34, '{"custom_1783383400370": "SENASA", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA", "custom_1783383763840": "Si deciden producir biopreparados por compostar", "custom_1783383788609": "TODOS", "custom_1783383823178": "Compostaje", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Se aprueba el procedimiento para la importación de aquellas sustancias u objetos obtenidos a partir de la valorización de residuos, en los términos del artículo 2° del Decreto N° 181/92 y su modificatorio como Anexo I (IF-2019-95103372-APN-DSYPQ#SGP)\nSe aprueba las normas y requerimientos técnicos aplicables a los siguientes insumos (Anexo III (IF-2019-95106711-APN-DSYPQ#SGP): \na. Chatarra ferrosa\nb. Chatarra no ferrosa\nc. Rezagos de papel y cartón\nd. Vidrio roto, casco, cascote\ne. Rezagos plásticos', 'Si se necesita importar residuos realizarlo siguiendo este procedmiento', 1, 'Es potestativa', 'Certificado de importación', 'Cirion Technologies no importa sustancias u objetos obtenidos a partir de la valorización de residuos', 6, NULL, NULL, 35, '{"custom_1783383400370": "Valorización de residuos", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "SECRETARÍA GENERAL-SECRETARÍA DE GOBIERNO DE AMBIENTE Y DESARROLLO SUSTENTABLE hoy Ministerio de Medio Ambiente", "custom_1783383763840": "Constante", "custom_1783383788609": "No aplicable", "custom_1783383823178": "Importación de sustancias /Valorización de residuos", "custom_1784900000002": "NO APLICABLE", "custom_1783384038540": "NO APLICABLE"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 554);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Declara de interés del Subsecretaría de Ambiente de la Nación y del MINISTERIO DE TRANSPORTE DE LA NACIÓN, aquellos procesos productivos desarrollados en la República Argentina, que, a partir de la valorización de residuos generados en el país, permitan obtener durmientes y productos análogos para su empleo en la infraestructura del transporte ferroviario nacional, en el marco de los presupuestos de la economía circular y el desarrollo sostenible.', 'Comercializar residuos para hacer durmientes', 1, 'Es potestativa', 'Contancia de venta y re-uso', 'Cirion Technologies no comercializa sus residuos', 6, NULL, NULL, 36, '{"custom_1783383400370": "Valorización de residuos", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación Y MINISTERIO DE TRANSPORTE", "custom_1783383763840": "Constante", "custom_1783383788609": "No aplicable", "custom_1783383823178": "Valorización de residuos", "custom_1784900000002": "NO APLICABLE", "custom_1783384038540": "NO APLICABLE"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 489);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Aprueba el régimen transitorio de trazabilidad de los envases vacíos de fitosanitarios Tipo B el cual mantendrá su vigencia hasta la puesta en marcha del Sistema Único de Trazabilidad creado por el artículo 24 de la ley N° 27.279, estableciéndose como fecha tope al efecto el 30 de septiembre de 2023.\n\nA los efectos de lo dispuesto en el párrafo anterior el transporte de envases vacíos de fitosanitarios Tipo B, desde el CAT al operador, deberá cumplir con los requisitos definidos para el transporte de mercancías peligrosas de acuerdo a lo establecido en la Ley N° 24.449 y modificatorias, siendo el documento válido para ello, la carta de porte establecida en el artículo 9 de la Ley Nº 24.653, instrumento en el que deberá precisarse la cantidad de envases transportados expresada en unidades.\n\nLos operadores habilitados para el tratamiento de envases vacíos de fitosanitarios o similares, así como los que se habiliten en el futuro, deberán exigir el documento definido en el segundo párrafo, como único documento necesario para acreditar el transporte de carga de los envases vacíos tipo B.\n\nPodrán constituirse como Operadores de los envases Tipo B descriptos en el Artículo 4° de la Ley  N° 27.279 los operadores que se encuentren actualmente habilitados a tratar envases vacíos de fitosanitarios o similares, así como los que se habiliten en el futuro, para lo cual deberán acreditar el cumplimiento de los dispuesto por la Ley N° 27.279 y su normativa complementaria.', 'Si tiene contratado un aplicador debe constar en la receta domisanitaria de aplicación de venenos que fueron retirados para su gestión integral, En caso contrario deberán gestionarlos como residuos peligrosos conforme su Y o bien por el reégimen de envases de fitosanitarios.', 2, 'obligatoria', 'receta donde conste su gestión o manifiesto correspondiente', NULL, 4, 'Como Cirion no los va a aplicar directamente, deben controlar que quien los aplica, estén inscriptos en los registros correspondientes y emitan los certificados legales. Certificados provinciales o municipales -como en muchas Pcias del interior) o recetas domisanitarias como en Buenos Aires, Santa Fe y Córdoba, entre otras.', NULL, 37, '{"custom_1783383400370": "Envases de Fitosanitarios/Domisanitarios", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "cuando apliquen domisanitarios para prevenir plagas", "custom_1783383788609": "TODOS", "custom_1783383823178": "prevenir intoxicación y contaminación de aguas, suelo y aire"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 395);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1640);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo', 'Se sustituye el Sistema Federal de Fiscalización de Agroquímicos y Biológicos creado por Resolución SENASA 500/2003 y modificado por Disposición 119/2007 obrante como Anexo de la Disposición N° 119 del 19 de julio de 2007. Se aprueba el nuevo Sistema Federal de Fiscalización de Agroquímicos y Biológicos (SIFFAB)\nObjetivos: El SIFFAB tiene los objetivos siguientes:\nInciso a) Verificar que los productos que se comercialicen se correspondan con los registrados en el SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA conforme las normas vigentes.\nInciso b) Verificar la trazabilidad de los agroquímicos mediante la implementación y aplicación de los sistemas desarrollados a tal fin.\nInciso c) Retirar y hacer retirar del circuito comercial los productos que no cuenten con el registro en el SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA.\nInciso d) Proponer las sanciones a ser aplicadas sobre los infractores a las normas vigentes.\nInciso e) Verificar que se expendan únicamente productos registrados en el SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA bajo las condiciones en los que fueron aprobados y autorizada su venta y verificar el cumplimiento de documentación obligatoria requerida, trazabilidad y rastreo, identificación, composición y demás requisitos establecidos por las normas vigentes aplicables a los productos fitosanitarios, fertilizantes, enmiendas, sustratos, acondicionadores y protectores.\nInciso g) Colaborar con la capacitación de los distintos agentes que forman parte del sistema.\nInciso h) Fomentar y colaborar con la adopción de las Buenas Prácticas en el manejo y uso responsable de fitosanitarios.\nInciso i) Colaborar con programas y sistemas que requieran la participación en actividades propias de los mismos.', 'SOLO PODRÁN SER UTILIZADOS AGROQUÍMICOS Y DOMISANITARIOS REGISTRADOS EN EL SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA', 2, NULL, NULL, NULL, 4, NULL, NULL, 38, '{"custom_1783383400370": "RESIDUOS", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA- DIRECCIÓN NACIONAL DE INOCUIDAD Y CALIDAD AGROALIMENTARIA", "custom_1783383763840": "Los aplica profesional competente y entregan receta domisanitaria"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 570);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo', 'Se aprueba el nuevo Manual de Procedimientos, Criterios y Alcances para la autorización de establecimientos y/o de las personas humanas o jurídicas que intervengan en la cadena de elaboración en el mercado local, importación y/o exportación de productos fitosanitarios.\nTodos los establecimientos elaboradores de productos fitosanitarios, dentro del ámbito nacional, deben presentar una Declaración Jurada y contar con Director Técnico de Establecimiento, conforme se detalla en el Anexo I (IF-2025-68647583-APN-DNPV#SENASA), que forma parte integrante de la presente resolución.\nLa presentación de la Declaración Jurada otorgará automáticamente a las personas humanas o jurídicas y a los establecimientos la autorización para iniciar sus actividades, quedando sujetos a la fiscalización posterior del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA (SENASA).\nPor la modificación se suprime al director técnico.', 'Tener en cuenta la obligatoriedad de poseer un Director Técnico.', 2, NULL, NULL, NULL, 4, NULL, NULL, 39, '{"custom_1783383400370": "RESIDUOS", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 58);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo', 'Aprueba el Protocolo para la comercialización de sustancias activas y productos fitosanitarios en todo el Territorio Nacional, conforme lo establecido en esta resolución.', 'Informativa', 2, NULL, NULL, NULL, 4, NULL, NULL, 40, '{"custom_1783383400370": "RESIDUOS", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo', 'Sustituye el Artículo 5° de la citada Resolución N° 245/21, el que quedará redactado de la siguiente manera:\n“ARTÍCULO 5 ° .- Procedimiento de declaración de envases y embalajes. En el momento de la inscripción de las sustancias activas y los productos fitosanitarios formulados de uso agrícola y línea jardín, la empresa registrante debe adjuntar una Declaración Jurada al expediente de registro, declarando tipo, material y capacidad de los envases y los embalajes con los que planifica comercializar o transportar dichas sustancias y productos en el Territorio Nacional.”.\nSustituye el inciso g) del Artículo 7° de la mencionada Resolución N° 245/21, el que quedará redactado de la siguiente manera:\n“Inciso g) vida útil: esta debe ser establecida por el titular del producto. Al finalizar la vida útil de cada envase para su reutilización, la empresa registrante del producto es la responsable de ejecutar las opciones de Gestión Integral de Envases Vacíos de Fitosanitarios contempladas en el Artículo 6° de la Ley N° 27.279 y su procedimiento, teniendo en cuenta las Mejores Prácticas de Gestión Disponibles (MPGD).”.', 'Tener en cuenta la gestión de los envases y embalajes de fitosanitarios. Enviarlos a tratar y conservar la documentación necesaria o dejar constancia en la receta domisanitaria que los retira el aplicador para realizar su gestión integral.', 2, NULL, NULL, NULL, 4, NULL, NULL, 41, '{"custom_1783383400370": "RESIDUOS", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Modifica el Artículo 1°, de la Resolución N° 439 del 10 de octubre de 2022, el que quedará redactado de la siguiente manera: Apruébase el régimen transitorio de trazabilidad de los envases vacíos de fitosanitarios Tipo A y Tipo B el cual mantendrá su vigencia hasta la puesta en marcha del Sistema Único de Trazabilidad creado por el artículo 24 de la ley N° 27.279\n\nAmplíael régimen transitorio de trazabilidad de los envases vacíos de fitosanitarios establecido por la resolución MADS N°439/2022 a los envases Tipo A, el cual mantendrá su vigencia hasta la puesta en marcha del Sistema Único de Trazabilidad creado por el artículo 24 de la ley N° 27.279.\n\nA los efectos de lo dispuesto en el párrafo anterior, el transporte de envases vacíos de fitosanitarios Tipo A y Tipo B, desde el CAT al operador, así como desde el CAT a la industria en el caso de los envases Tipo A, deberá acreditarse mediante carta de porte, cumplimentando los requisitos establecidos al efecto del transporte del tipo de mercancías de que se trate en cada caso conforme lo establecido en la Resolución MADS N°439/22.\nSin perjuicio de lo indicado precedentemente, para el caso de los envases Tipo B, se deberá cumplir con lo indicado en el Artículo 2° de la Resolución MADS N° 439/2022\n\nLos envases Tipo B serán tratados por los  operadores que las jurisdicciones hayan habilitado independientemente de la provincia donde se ubiquen los CAT. \nDeja establecido que, tratándose de envases vacíos de fitosanitarios conforme el Inc. b del artículo 5 de la Ley 27279, no les caben ninguna de las restricciones de ingreso a territorios provinciales sin perjuicio de las reglamentaciones provinciales que pudieran establecerse.\n\nLos titulares de los CAT deberán informar mensualmente al Subsecretaaría de Ambiente de la Nación todos los movimientos hacia los operadores de Envases Vacíos de Fitosanitarios Tipo A y Tipo B respectivamente. Dicha información deberá contener como mínimo: Identificación del CAT (nombre/razón social, CUIT, domicilio, habilitación, responsable técnico); cantidad de envases de cada tipo que se gestiona en el mes correspondiente, Identificación del Operador (nombre/razón social, CUIT, domicilio, habilitación, responsable técnico), tipo de operación a la que será sometido el envase, identificación del destino posterior y su información asociada.\nEsta comunicación podrá ser entregada mediante un correo electrónico dirigido a controlymonitoreo@ambiente.gob.ar', 'Tener en cuenta el procedimiento a seguir para descartar fitosanitarios o domisanitarios si no son retirados por el aplicador.', 2, 'obligatoria', 'receta donde conte su gestión o manifiesto correspondiente', NULL, 4, NULL, NULL, 42, '{"custom_1783383400370": "Envases de Fitosanitarios/Domisanitarios", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "cuando apliquen domisanitarios para prevenir plagas", "custom_1783383788609": "todos", "custom_1783383823178": "prevenir intoxicación y contaminación de aguas, suelo y aire"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Aprueba la nueva norma para el etiquetado de productos fitosanitarios mediante la adopción del Sistema Globalmente Armonizado de Clasificación y Etiquetado de Productos Químicos (SGA), estableciendo su aplicación obligatoria para todos los titulares de registros de dichos productos en el territorio nacional.\nEstablece las condiciones y requisitos para el etiquetado, incluyendo la obligatoriedad de etiquetas completas o elementales según el envase, la organización de la información en secciones específicas, y la incorporación de pictogramas, advertencias, banda toxicológica y recomendaciones de uso conforme a criterios técnicos armonizados.\nDetermina los lineamientos para la clasificación de peligros para la salud humana y el ambiente, la identificación de sustancias, condiciones de presentación, idioma, tipografía y características físicas de las etiquetas, así como requisitos específicos para distintos tipos de productos (muestras, semillas, preservadores, línea jardín, exportación, entre otros).\nAprueba el “Modelo de Etiqueta Completa” como Anexo I (IF-2026-37429380-APN-DNPV#SENASA) y el “Modelo de Etiqueta Elemental” como Anexo II (IF-2026-37429757-APN-DNPV#SENASA), que establecen la estructura y contenido obligatorio del etiquetado.\nAprueba la Tabla de “Toxicidad Aguda en Mamíferos” como Anexo III (IF-2026-37430140-APN-DNPV#SENASA), las Tablas de “Sensibilización e Irritación Dermal y Ocular” como Anexo IV (IF-2026-37430796-APN-DNPV#SENASA) y las “Tablas de Peligros Ambientales” como Anexo V (IF-2026-37431136-APN-DNPV#SENASA), que complementan los criterios de clasificación y advertencias obligatorias en las etiquetas.\nEstablece que el incumplimiento de la norma será sancionado conforme a la Ley N° 27.233, abroga la Resolución N° 367/2014 del SENASA y dispone su entrada en vigor a partir del día siguiente a su publicación en el Boletín Oficial.', 'Tener en cuenta que el etiquetado de los envases debe poseer la simbología SGA.', 2, NULL, NULL, NULL, 4, NULL, NULL, 43, '{"custom_1783383400370": "Envases de fitosanitarios y agroquímicos", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Se aprueban los montos arancelarios que por retribución percibe el SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA, organismo descentralizado en la órbita de la SECRETARÍA DE AGRICULTURA, GANADERÍA Y PESCA del MINISTERIO DE ECONOMÍA, correspondientes a servicios prestados a terceros por las distintas unidades organizativas del citado Servicio Nacional, que se consignan en el Anexo I (IF-2026-40597599-APN-DSAYF#SENASA), que forma parte integrante de la presente resolución, a partir de la entrada en vigencia del presente acto.\nSe eximen del pago de aranceles a las personas jurídicas detalladas en el Anexo II (IF-2026-37447466-APN-DSAYF#SENASA), que forma parte integrante del presente acto.\nSe establece que los aranceles por Tasas por Servicio de Inspección Sanitaria que se detallan en el Anexo III (IF-2026-37447910-APN-DSAYF#SENASA), que forma parte integrante del presente acto, entrarán en vigor el primer día del mes siguiente al de su publicación en el Boletín Oficial, atento lo dispuesto en el Capítulo II del Decreto Nº 4.238 del 19 de julio de 1968.', 'Tener en cuenta que los servicios que presta el SENASA se deben retribuír conforme los aranceles fijados en esta norma', 2, NULL, NULL, NULL, 4, NULL, NULL, 44, '{"custom_1783383400370": "Pagos por servicios a terceros prestados por SENASA", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "MINISTERIO DE ECONOMÍA - SECRETARÍA DE AGRICULTURA, GANADERÍA Y PESCA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Se sustituye, a partir del 13 de mayo de 2026, el Anexo (IF-2024-42118621-APN-DSAYF#SENASA) de la Resolución N° RESOL-2019-923-APN-PRES#SENASA del 2 de agosto de 2019 del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA, por el Anexo (IF-2026-46345469-APN-DSAYF#SENASA) que se aprueba y forma parte integrante de la presente resolución.\nAbroga la Resolución N° RESOL-2024-453-APN-PRES#SENASA del 29 de abril de 2024 del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA.\nactualiza los montos y criterios de cobro por los servicios extraordinarios, urgentes y fuera de horario administrativo que brinda el organismo.', 'Pagar los servicios conforme aranceles contenidos en las normas', 2, NULL, NULL, NULL, 4, NULL, NULL, 45, '{"custom_1783383400370": "Actualiza los montos y criterios de cobro por los servicios extraordinarios, urgentes y fuera de horario administrativo que brinda el organismo", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Se aprueba la nómina de aranceles y trámites que se realicen ante la Administración Nacional de Medicamentos, Alimentos y Tecnología Médica (ANMAT) correspondientes a Especialidades Medicinales, Productos Médicos, Productos Cosméticos, de Higiene Personal y Perfumes, Productos de Higiene Oral de Uso Odontológico y Productos de Uso Doméstico (Domisanitarios) y Alimentos, conforme el detalle que como Anexo I (IF-2026-49531619-APN-DGA#ANMAT), Anexo II (IF-2026-49532501-APN-DGA#ANMAT), Anexo III (IF-2026-49533631-APN-DGA#ANMAT) y Anexo IV (IF-2026-49536835-APN-DGA#ANMAT) forman parte integrante de la presente Disposición, y son aprobados por la misma.\nDeroga las Disposiciones ANMAT N° DI-2025-4053-APN-ANMAT#MS, DI-2025-4054-APN-ANMAT#MS, DI-2025-4055-APN-ANMAT#MS, DI-2025-4058-APN-ANMAT#MS y DI-2025-4538-APN-ANMAT#MS.', 'Pagar los servicios conforme aranceles contenidos en las normas', 2, NULL, NULL, NULL, 4, NULL, NULL, 46, '{"custom_1783383400370": "Actualiza los montos y criterios de cobro por los servicios extraordinarios, urgentes y fuera de horario administrativo que brinda el organismo", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "ADMINISTRACIÓN NACIONAL DE MEDICAMENTOS, ALIMENTOS Y TECNOLOGÍA MÉDICA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Prohibición de producción y comercialización de las sustancias denominadas PCBs y de los aparatos que la contengan.\nDefinición de PCBs\nObligación de reemplazar los productos, equipos, instalaciones o sistemas actualmente en uso que contengan PCBs en cualquiera de sus formas o combinaciones para el año 2010.\nObligaciones para los generadores o poseedores de PCBs.\nCreación del Registro de Generadores o poseedores de PCBs', 'Los generadores de Energía y los Transformadores deberían estar libres de PCBs para el año 2010.\nSi se posee algún aparato que contenga  PCBs,  se deberá observar  las obligaciones fijadas en este régimen.', 2, 'Colocar carteleria que asi lo acredite. Libre de PCB es menos de 50ppm.', 'Los transformadores no contienen PCB ya que son secos sin embargo deben contar con la carteleria obligatoria ¨Libre de PCB"', 'Se verificó que cuentan con la carteleria obligatoria ¨Libre de PCB"', 1, NULL, NULL, 47, '{"custom_1783383400370": "Sustancias Controladas: PCBs", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Congreso Nacional", "custom_1783383763840": "Continuo", "custom_1783383823178": "contaminacion de recursos naturales", "custom_1784900000002": "Infraestructura\\nEHS"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 785);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 831);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Deroga las Resoluciones No 313/2005 y su modificatoria N° 1677/2005 del entonces MINISTERIO DE SALUD Y AMBIENTE (sobre el Registro Nacional Integrado de Poseedores de PCB)\nAprueba el procedimiento de inscripción, modificación, renovación anual y baja en el RENIPP, así como los requisitos para la presentación de Programas de Eliminación o Descontaminación.\nDispone el reempadronamiento de aquellos poseedores de PCB (bifenilos policlorados) que ya se encuentren inscriptos en el RENIPP, los que deberán ajustarse a los procedimientos y requisitos referidos en el párrafo anterior.', 'Los generadores de Energía y los Transformadores deberían estar libres de PCBs (bifenilos policlorados) para el año 2010.\nSi se posee algún aparato que contenga  PCBs,  se deberá inscribirse en el registro de CABA para que estos informen a nación', 2, 'Encontrarse inscriptos', 'Los transformadores no contienen PCB ya que son secos sin embargo deben contar con la carteleria obligatoria ¨Libre de PCB"', 'Se verificó que cuentan con la carteleria obligatoria ¨Libre de PCB"', 1, NULL, NULL, 48, '{"custom_1783383400370": "Sustancias Controladas: PCBs", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Mientras los posean almacenados sin tratamianto", "custom_1783383788609": "Infraestructura", "custom_1783383823178": "contaminacion de recursos naturales", "custom_1784900000002": "Infraestructura\\nEHS"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 474);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Deroga la Resolución RESOL-2019-192-APN-SECCYMA#SGP de fecha 4 de julio de 2019.\nCrea el LISTADO NACIONAL DE SUSTANCIAS Y PRODUCTOS QUÍMICOS EXISTENTES, CONTROLADOS, RESTRINGIDOS Y PROHIBIDOS, cuyo objeto es consolidar una base de información sobre las sustancias reguladas y los productos químicos producidos, comercializados y utilizados en el territorio argentino con el fin de facilitar la aplicación de la normativa nacional y el cumplimiento de los compromisos ambientales internacionales asumidos.\nEl LISTADO NACIONAL DE SUSTANCIAS Y PRODUCTOS QUÍMICOS EXISTENTES, CONTROLADOS, RESTRINGIDOS Y PROHIBIDOS es integrado, entre otras, por las siguientes \na. Normativa Nacional publicada en el Boletín Oficial;\nb. Registros Nacionales existentes en materia de sustancias y productos químicos;\nc. Otras fuentes oficiales relevadas por la Autoridad de Aplicación o aportadas por las Autoridades Competentes; \nd. Información complementaria presentada por los productores, importadores, comercializadores y usuarios de productos químicos y sus asociaciones.', 'Pueden consultar del mismo las sustancias prohibidas y permitidas, como así también las de uso restringido por las cuales se necesite autorización especial', 1, 'Informativa', 'Informativa', 'Informativa', 8, NULL, NULL, 49, '{"custom_1783383400370": "SUSTANCIAS QUÍMICAS EXISTENTES, RESTRINGIDAS Y PROHIBIDAS", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Continuo", "custom_1783383788609": "Todos", "custom_1783383823178": "contaminacion de recursos naturales", "custom_1784900000002": "Informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 67);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Establece un nuevo listado de Productos químicos prohibidos en el marco del Convenio de Estocolmo.\nProrroga el plazo establecido en la Resolución N° 451/19 para la entrada en vigencia de las prohibiciones, exclusivamente para el ácido perfluorooctanoico (PFOA), sus isómeros, sus sales y cualquier sustancia que se degrade en PFOA a regir a partir del 3 de diciembre de 2020.\nProhibe la producción e importación de los artículos y mercancías que podrían contener los productos químicos restringidos en el marco del Convenio de Estocolmo.', 'Controlar si poseen estas sustancias', 1, 'Informativa', 'Informativa', 'Informativa', 8, NULL, NULL, 50, '{"custom_1783383400370": "SUSTANCIAS QUÍMICAS EXISTENTES, RESTRINGIDAS Y PROHIBIDAS", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Continuo", "custom_1783383788609": "Todos", "custom_1783383823178": "contaminacion de recursos naturales", "custom_1784900000002": "Informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 477);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Establece el procedimiento de importación y exportación de los productos químicos detallados en el listado del Anexo I, los que se encuentran sujetos al Consentimiento Fundamentado Previo (CFP) conforme a la Ley Nº 25.278 que aprueba el Convenio de Rotterdam sobre el Procedimiento de Consentimiento Fundamentado Previo Aplicable a Ciertos Plaguicidas y Productos Químicos Peligrosos Objeto de Comercio Internacional.\nSe aprueba el procedimiento a los fines de tramitar el Consentimiento Fundamentado Previo y obtener la autorización para la importación y exportación de los productos químicos listados.', 'Aplica sólo si importan este tipo de sustancias', 1, 'Informativa', 'No es aplicable', 'No es aplicable al no importar ni exportar productos químicos', 6, NULL, NULL, 51, '{"custom_1783383400370": "SUSTANCIAS QUÍMICAS EXISTENTES, RESTRINGIDAS Y PROHIBIDAS", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Solo si importan sustancias", "custom_1783383788609": "Todos", "custom_1783383823178": "contaminacion de recursos naturales", "custom_1784900000002": "No es aplicable", "custom_1783384038540": "NO APLICABLE"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 445);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Crea la BRIGADA DE CONTROL AMBIENTAL (BCA), dependiente de la DIRECCIÓN DE INSPECCIONES, del Subsecretaaría de Ambiente de la Nación.\nFunciones:\na) Observar y hacer cumplir los principios de la política ambiental en concordancia con lo estipulado por la Ley General del Ambiente.\nb) Proteger el ambiente y los recursos naturales, dentro del ámbito legal de sus competencias territoriales, tanto en lo referido a suelo, subsuelo, agua, aire, biodiversidad, bosques nativos, flora y fauna silvestre;\nc) Participar en la formulación de las políticas ambientales, específicamente en lo referido a control y fiscalización ambiental;\nd) Implementar las políticas de fiscalización y control que se determinen, juntamente con las diversas áreas del Subsecretaaría de Ambiente de la Nación;\ne) Ejercer el control efectivo y permanente de los establecimientos y actividades que puedan ocasionar algún riesgo o daño para el ambiente, con amplias facultades de fiscalización, pudiendo realizar tareas investigativas, procedimientos de toma de muestras, monitoreos periódicos y permanentes, inspecciones, elaborar informes técnicos, patrullajes, control de vertido de efluentes, y cualquier otra medida que la BCA considere pertinente;\nf) Detectar infracciones a la normativa ambiental vigente y labrar actas a fin de sustanciar sumarios administrativos como también dar intervención a las diferentes jurisdicciones;\ng) Aplicar medidas preventivas, en el marco de las consideraciones generales de fiscalización indicado en el Anexo I (IF-2020-56535371-APN-DIN#MAD) que forma parte integrante de la presente resolución.\nh) Asistir a las distintas jurisdicciones, organismos provinciales, locales, y regionales en todo lo referente a control ambiental, capacitación, monitoreo y soporte en materia de inspecciones ambientales; y brindar apoyo cuando estos así lo soliciten;\ni) Perseguir, en conjunto con los distintos organismos nacionales, provinciales, locales y regionales, todas las actividades referidas al incumplimiento de la normativa ambiental vigente.\nj) Investigar las denuncias que reciba, de las cuales pueda detectarse la supuesta comisión de alguna infracción administrativa, y dando intervención, a través de la DIRECCIÓN DE INSPECCIONES, al Ministerio Público Fiscal, cuando se trate de la supuesta comisión de un ilícito;\nk) Realizar estudios de riesgo y relevamientos en caso de eventos de contaminación ambiental a cuyo conocimiento haya llegado por su pública repercusión o por denuncias de particulares;\nl) Prestar asistencia y apoyo ante requerimientos de organismos provinciales, locales y/o regionales, y al Sistema Nacional de Gestión Integral del Riesgo (SINAGIR), en los casos en que hubiere una emergencia ambiental;\nm) Comunicar al Poder Judicial cualquier actividad ilícita detectada, contraria al medio ambiente, para su posterior intervención y seguimiento;\nn) Asesorar y apoyar a las jurisdicciones locales en los programas de monitoreo, fiscalización y protección de glaciares;\nñ) Llevar los registros permanentes de las inspecciones, actas, informes y medidas preventivas efectuadas, como así también de las denuncias recibidas, investigaciones, intervenciones solicitadas al Ministerio Público Fiscal y al Poder Judicial, y de los bienes secuestrados y/o decomisados;\no) Entender en toda otra competencia que le otorgue cualquier normativa específica relacionada con la fiscalización y control ambiental.', 'Indicativa crea una unidad de control y fiscalización', 1, 'Informativa', 'Es informativa', 'Es informativa', 8, NULL, NULL, 52, '{"custom_1783383400370": "Control por parte del MAyDS de normas de su competencia", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Resolución Nacional 306/2020: Subsecretaaría de Ambiente de la Nación (08/09/2020)", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "contaminacion de recursos naturales", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 61);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'A tales efectos, cada sujeto obligado deberá alcanzar la incorporación mínima del ocho por ciento (8%) del total del consumo propio de energía eléctrica, con energía proveniente de las fuentes renovables, al 31 de diciembre de 2017, y del veinte por ciento (20%) al 31 de diciembre de 2025. El cumplimiento de estas obligaciones deberá hacerse en forma gradual, de acuerdo con el siguiente cronograma:\n1. Al 31 de diciembre de 2017, deberán alcanzar como mínimo el ocho por ciento (8%) del total del consumo propio de energía eléctrica.\n2. Al 31 de diciembre de 2019, deberán alcanzar como mínimo el doce por ciento (12%) del total del consumo propio de energía eléctrica.\n3. Al 31 de diciembre de 2021, deberán alcanzar como mínimo el dieciséis por ciento (16%) del total del consumo propio de energía eléctrica.\n4. Al 31 de diciembre de 2023, deberán alcanzar como mínimo el dieciocho por ciento (18%) del total del consumo propio de energía eléctrica.\n5. Al 31 de diciembre de 2025, deberán alcanzar como mínimo el veinte por ciento (20%) del total del consumo propio de energía eléctrica.\nEl consumo mínimo fijado para la fecha de corte de cada período no podrá ser disminuido en el período siguiente.\n Los Grandes Usuarios del Mercado Eléctrico Mayorista y las Grandes Demandas que sean Clientes de los Prestadores del Servicio Público de Distribución o de los Agentes Distribuidores, con demandas de potencia iguales o mayores a trescientos kilovatios (300 kW) deberán cumplir efectiva e individualmente con los objetivos indicados en el artículo precedente. A tales efectos, podrán autogenerar o contratar la compra de energía proveniente de diferentes fuentes renovables de generación a fin de cumplir con lo prescripto en este artículo. La compra podrá efectuarse al propio generador, a través de una distribuidora que la adquiera en su nombre a un generador, de un comercializador o comprarla directamente a CAMMESA bajo las estipulaciones que, para ello, establezca la Autoridad de Aplicación.\nLos contratos suscriptos por los sujetos indicados en el párrafo anterior no podrán fijar un precio promedio mayor a ciento trece dólares estadounidenses o su equivalente en moneda nacional, por cada megavatio-hora comercializado entre las partes (U$S 113/MWh). Cumplidos dos (2) años desde la entrada en vigencia de la reglamentación de la presente ley y hasta la finalización de la Segunda Etapa del “Régimen de Fomento Nacional para el Uso de Fuentes Renovables de Energía Destinada a la Producción de Energía Eléctrica”, la Autoridad de Aplicación podrá modificar el precio máximo establecido precedentemente si las condiciones de mercado lo justifican, aplicable para los nuevos contratos que se celebren', 'Si son grandes consumidores por consumir más de 300 KW Deberán alcanzar como mínimo el dieciseis por ciento (16%) del total del consumo propio de energía eléctrica, compran a través de CAMMESA', 2, 'Obligatoria', 'Cto con empresa que suministre el porcentaje necesario de energía\nCertificados de energía renovable', 'Para la Energia en Argentina consumida en el año 2024 vamos a mirar la compra hasta el 1Q de 2025 ya que la emisión es por año vencido', 5, NULL, NULL, 53, '{"custom_1783383400370": "USO DE ENERGÍA RENOVABLE/GRANDES GENERADORES", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Congreso Nacional", "custom_1783383763840": "Constante", "custom_1783383788609": "Todos", "custom_1783383823178": "Contaminación atmosferica", "custom_1784900000002": "Planning Infraestructure"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Aprueba los “Lineamientos para un Plan de Transición Energética al 2030”. La Resolución incorpora como Anexo el Programa de Transición Energética, por el que se establecen una serie de objetivos generales y lineamientos estratégicos para el 2030:\n Objetivos: inclusión; estabilidad y desarrollo; soberanía energética; dinamismo; federalismo y sostenibilidad.\n Lineamientos: eficiencia energética; energía limpia en emisiones de gases efecto invernadero (GEI); gasificación; desarrollo de capacidades tecnológicas nacionales; resiliencia del sistema energético; federalización del desarrollo energético; estrategia nacional para el desarrollo del hidrógeno.\n Particularmente respecto de la oferta de energía eléctrica, establece que en miras a cumplimentar los objetivos climáticos, la expansión del sistema eléctrico durante la próxima década deberá realizarse sobre la base de tecnologías bajas en emisiones de carbono. Esto buscará revertir la predominancia de las fuentes fósiles en la generación de electricidad.\n Se consideran 2 escenarios de oferta:\n REN 20: escenario de transición energética con capacidades nacionales, que alcanza un 20% de generación renovable al 2030 mediante un escalamiento de la participación de las energías renovables en la matriz eléctrica, lo que implicaría una incorporación de nueva potencia instalada por 8.700 MW.\nREN 30: escenario de transición acelerado incorporando potencia renovable que alcanzaría el 30% de participación en la generación eléctrica para el 2030. Esto requeriría la adición de 11.875 MW.\nMientras REN 20 demanda requerimientos de petróleo y gas natural, REN 30 supone mayor requerimiento de gas natural y menor requerimiento de petróleo.', 'Tener en cuenta y reducir uso de combustibles fósiles.', 1, 'Voluntaria/Institucional', 'Usar energía renovable', 'Para la Energia en Argentina consumida en el año 2024 vamos a mirar la compra hasta el 1Q de 2025 ya que la emisión es por año vencido', 5, NULL, NULL, 54, '{"custom_1783383400370": "TRANSICIÓN ENERGÉTICA/USO DE ENERGÍA SUSTENTABLE", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "MINISTERIO DE ECONOMÍA-SECRETARÍA DE ENERGÍA", "custom_1783383763840": "Constante", "custom_1783383788609": "Todos", "custom_1783383823178": "Contaminación atmosférica"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todas', 'Aprueban los lineamientos sobre transición energética trazados por la Secretaría de Energía de la Nación, en dos documentos llamados: “Plan Nacional de Transición Energética al 2030” (“PTE 2030”) y los “Lineamientos y Escenarios para la Transición Energética a 2050” (“LT 2050”). El PTE 2030 y LT 2050 fueron aprobados mediante Resolución Nº 517/2023 y Resolución Nº 518/2023 de la Secretaría de Energía de la Nación. En este documento se abordan los puntos más relevantes.', 'Tener en cuenta por las normas que se aprobarán sobre emisiones gaseosa, calidad de aire y/o uso de combustibles.', 1, 'Informativa', 'Usar energía renovable', 'Es informativa', 8, NULL, NULL, 55, '{"custom_1783383400370": "TRANSICIÓN ENERGÉTICA/USO DE ENERGÍA SUSTENTABLE", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "MINISTERIO DE ECONOMÍA-SECRETARÍA DE ENERGÍA", "custom_1783383763840": "Constante", "custom_1783383788609": "Todos", "custom_1783383823178": "Contaminación atmosférica", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Crea el REGISTRO NACIONAL DE PROYECTOS DE MITIGACIÓN DEL CAMBIO CLIMÁTICO, en el ámbito de la SECRETARIA DE CAMBIO CLIMÁTICO, DESARROLLO SOSTENIBLE E INNOVACIÓN o en la que en un futuro la reemplace.\nEstablece que el REGISTRO NACIONAL tendrá como objetivos registrar y sistematizar los proyectos que reduzcan las emisiones antropogénicas o aumenten las capturas de gases de efecto invernadero en el territorio nacional.\nDetermina que el REGISTRO NACIONAL deberá articular la información obtenida con el SISTEMA NACIONAL DE INFORMACIÓN SOBRE CAMBIO CLIMÁTICO.', 'Institucional/Tener en cuanta en cuanto a uso de energía renovable', 1, 'Indicativa', 'Usar energía renovable', NULL, 4, NULL, NULL, 56, '{"custom_1783383400370": "CAMBIO CLIMÁTICO/TRANSICIÓN ENERGÉTICA/USO DE ENERGÍA SUSTENTABLE", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Constante", "custom_1783383788609": "Todos", "custom_1783383823178": "Contaminación atmosférica", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'toda la norma', 'Aprueba el segundo PLAN NACIONAL DE ADAPTACIÓN Y MITIGACIÓN AL CAMBIO CLIMÁTICO como Anexo I y sus Fichas de Medidas de Adaptación, Mitigación o Pérdidas y Daños como Anexo II.', 'Institucional/Tener en cuanta en cuanto a uso de energía renovable', 1, 'Indicativa', 'Usar energía renovable', NULL, 4, NULL, NULL, 57, '{"custom_1783383400370": "CAMBIO CLIMÁTICO/TRANSICIÓN ENERGÉTICA/USO DE ENERGÍA SUSTENTABLE", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Constante", "custom_1783383788609": "Todos", "custom_1783383823178": "Contaminación atmosférica", "custom_1783384038540": "INFORMATVA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'TODA LA NORMA', 'Aprueba la ESTRATEGIA DE DESARROLLO RESILIENTE CON BAJAS EMISIONES A LARGO PLAZO AL 2050 como ANEXO I (IF-2023-69365985-APN-DNCC#MAD)\nCrea el “PROGRAMA NACIONAL DE ESCENARIOS DE LARGO PLAZO” bajo la órbita de la SECRETARIA DE CAMBIO CLIMÁTICO, DESARROLLO SOSTENIBLE E INNOVACIÓN del Subsecretaaría de Ambiente de la Nación, cuyo contenido se encuentra detallado en el ANEXO II.\nLos compromisos asumidos por Argentina pueden sintetizarse en los siguientes puntos:\n \n•	hacer esfuerzos en pos de alcanzar la neutralidad en emisiones de Gases de Efecto Invernadero (GEI) para el año 2050.\n•	disminuir las vulnerabilidades mediante la mejora de las capacidades institucionales y el fortalecimiento de las infraestructuras y servicios, y aumentar la capacidad de adaptación de los sistemas productivos.\n•	fortalecer la resiliencia de los diferentes sectores sociales, económicos y ambientales, a través de medidas que integren y prioricen las comunidades y grupos sociales en situación de vulnerabilidad e incorporen el enfoque de género y la equidad intergeneracional.\n•	generar las condiciones necesarias para aumentar el conocimiento y mejorar la percepción de los argentinos frente a los impactos del cambio climático, promoviendo el cambio cultural hacia una ciudadanía responsable, participativa e involucrada que permita responder solidariamente al desafío urgente de proteger el planeta.\nEl marco para la acción de la Estrategia se correlaciona con el propuesto para el Plan Nacional de Adaptación y Mitigación al Cambio Climático (PNAyMCC). Ambos instrumentos continúan el sendero de la visión plasmada en la Segunda NDC. Así, la Estrategia se estructura en torno a los siguientes ejes:\n \n1. Enfoques transversales: Género y diversidad, Gestión integral del riesgo, Salud, Transición laboral justa\n2. Líneas instrumentales: Economía para la transición, Fortalecimiento institucional, Investigación, desarrollo e innovación, Acción para el Empoderamiento Climático, Comunicación para la concientización y el cambio cultural\n3. Líneas estratégicas: Transformación del sistema energético; Transformación del sistema alimentario y forestal; Transformación del sistema de transporte, Transformación del sistema productivo industrial, Transformación del sistema urbano y territorial, Protección y restauración de los sistemas naturales\nA su vez, por medio de esta norma la autoridad creó el Programa Nacional de Escenarios de Largo Plazo bajo la órbita de la Secretaría de Cambio Climático, Desarrollo Sostenible e Innovación del Subsecretaaría de Ambiente de la Nación, cuyo objetivo general es diseñar y consolidar un espacio de articulación y unificado que nuclee a todos los actores involucrados en una actualización de la Estrategia de Desarrollo Resiliente con Bajas Emisiones a Largo Plazo a 2050 a partir de un proceso de participación ciudadana e institucional, involucrando diversos sectores productivos, económicos, sociales, gubernamentales, de investigación y ciencia, entre otros.\n \nTambién, prevé como objetivos específicos: elaborar modelos, escenarios y trayectorias visibles de largo plazo con enfoque sectorial estratégico asociado a diversas temáticas (energía, agricultura, silvicultura, otros usos de la tierra, industria, transporte, entre otros). Fortalecer técnicamente el análisis de sumideros para escenarios de largo plazo. Generar propuestas de fortalecimiento de la legislación y normativa asociadas a la acción climática de largo plazo, entre otros.\nFacultó a la Secretaría de Cambio Climático, Desarrollo Sostenible e Innovación en su carácter de Coordinación Técnica Administrativa del Gabinete Nacional de Cambio Climático, a dictar las normas complementarias y aclaratorias que resulten necesarias para la correcta implementación tanto de la Estrategia como del Programa.', 'Tener en cuenta por cambio que puedan realizarse en normas de emisiones e inmisiones gaseosas.', 1, 'Indicativa', 'PROTECCION DEL RECURSO AIRES- Usar energía renovable', NULL, 4, NULL, NULL, 58, '{"custom_1783383400370": "CAMBIO CLIMÁTICO/TRANSICIÓN ENERGÉTICA/USO DE ENERGÍA SUSTENTABLE", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Constante", "custom_1783383788609": "Todos", "custom_1783383823178": "Contaminación atmosférica", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'TODA', 'Aprueba la ESTRATEGIA NACIONAL DE SALUD Y CAMBIO CLIMÁTICO.', 'Tener en cuenta por cambio que puedan realizarse en normas de emisiones e inmisiones gaseosas.', 1, 'Indicativa', 'PROTECCION DEL RECURSO AIRES- Usar energía renovable', NULL, 4, NULL, NULL, 59, '{"custom_1783383400370": "CAMBIO CLIMÁTICO/TRANSICIÓN ENERGÉTICA/USO DE ENERGÍA SUSTENTABLE", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "MINISTERIO DE SALUD Y Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Constante", "custom_1783383788609": "Todos", "custom_1783383823178": "Contaminación atmosférica"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'TODA', 'Aprueba  el convenio de Viena para protección de la capa de ozono, adoptado en Viena el 22 de marzo de 1985 cuya copia certificada en idioma español, que consta de un preámbulo, veintiún (21) artículos y dos (2) anexos forman parte de la  ley.', 'Cumplir con las resoluciones que establcen que tipo de CFC´s pueden ser adquiridos en Argentina y cuáles resultan prohibidos', 2, 'Obligatorio', 'Compra de gases permitidos', NULL, 1, 'La empresa no importa CFCs. Todavía se poseen algunos equipos de aie acondicionado que usan gas refrigerante R22 (contaminante)  a importadores autorizados. A medida que se van reemplazando los nuevos equipos, estos ya usan gas R407 o 410 (ecológico).', NULL, 60, '{"custom_1783383400370": "CALIDAD DE AIRE/CAPA DE OZONO", "custom_1784900000001": "NACIONAL", "custom_1783383445340": ": Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Cuando se cambien gases refrierantes", "custom_1783383788609": "Todos", "custom_1783383823178": "Contaminación atmosférica"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'TODA', 'Ratifica el PROTOCOLO DE MONTREAL RELATIVO A LAS SUSTANCIAS QUE AGOTAN LA CAPA DE OZONO, suscripto en Montreal (CANADA) el 16 de setiembre de 1987, cuyo texto original en idioma español que consta de VEINTE (20) artículos,En el plazo de un año a contar de la entrada en vigor del presente Protocolo, cada Parte prohibirá la importación de sustancias controladas procedente de cualquier Estado que no sea Parte en él.\n\nA partir del 1º de enero de 1993, ninguna Parte que opere al amparo del párrafo 1 del artículo 5 podrá exportar sustancias controladas a los Estados que no sean Partes en el presente Protocolo.', 'Cumplir con las resoluciones que establcen que tipo de CFC´s pueden ser adquiridos en Argentina y cuáles resultan prohibidos', 2, 'Obligatorio', 'Compra de gases permitidos', NULL, 1, 'La empresa no importa CFCs. Todavía se poseen algunos equipos de aie acondicionado que usan gas refrigerante R22 (contaminante)  a importadores autorizados. A medida que se van reemplazando los nuevos equipos, estos ya usan gas R407 o 410 (ecológico).', NULL, 61, '{"custom_1783383400370": "CALIDAD DE AIRE/CAPA DE OZONO", "custom_1784900000001": "NACIONAL", "custom_1783383445340": ": Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Cuando se cambien gases refrierantes", "custom_1783383788609": "Todos", "custom_1783383823178": "Contaminación atmosférica"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'TODA', 'Aprueba Disposiciones a las que se ajustarán las sustancias controladas incluidas en el Anexo "A" del Protocolo de Montreal relativo a las Sustancias Agotadoras de la Capa de Ozono.Son denominadas sustancias controladas, los compuestos químicos incluidos en el Anexo "A" del Protocolo de Montreal, relativo a las Sustancias Agotadoras de la Capa de Ozono, ratificado por ley 23.778, y que se identifican como CFC 11, CFC 12, CFC 113, CFC 114, CFC 115, Halón 1211, Halón 1301 y Halón 2402.\n\nSu producción, utilización, comercialización, importación y exportación quedarán sometidas a las restricciones establecidas en el citado Protocolo y las disposiciones de la presente.', 'Cumplir con las resoluciones que establcen que tipo de CFC´s pueden ser adquiridos en Argentina y cuáles resultan prohibidos', 2, 'Obligatorio', 'Compra de gases permitidos', NULL, 1, 'La empresa no importa CFCs. Todavía se poseen algunos equipos de aie acondicionado que usan gas refrigerante R22 (contaminante)  a importadores autorizados. A medida que se van reemplazando los nuevos equipos, estos ya usan gas R407 o 410 (ecológico).', NULL, 62, '{"custom_1783383400370": "CALIDAD DE AIRE/CAPA DE OZONO", "custom_1784900000001": "NACIONAL", "custom_1783383445340": ": Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Cuando se cambien gases refrierantes", "custom_1783383788609": "Todos", "custom_1783383823178": "Contaminación atmosférica"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Adjudica las cuotas de importación de sustancias que agotan la capa de ozono, correspondientes al año 2023 y establece las cantidades máximas que podrán importar los importadores nuevos o eventuales durante el período 2023', 'Tener en cuenta en el caso que adquieran sustancias que agotan la capa de ozono.', 2, 'Obligatoria', 'Compra de gases permitidos', NULL, 1, 'La empresa no importa CFCs. Todavía se poseen algunos equipos de aie acondicionado que usan gas refrigerante R22 (contaminante)  a importadores autorizados. A medida que se van reemplazando los nuevos equipos, estos ya usan gas R407 o 410 (ecológico).', NULL, 63, '{"custom_1783383400370": "CALIDAD DE AIRE/CAPA DE OZONO", "custom_1784900000001": "NACIONAL", "custom_1783383445340": ": Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Cuando se cambien gases refrierantes", "custom_1783383788609": "Todos", "custom_1783383823178": "Contaminación atmosférica"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, NULL, 'Prorroga hasta el 31 de diciembre de 2022 el Régimen de Facilidades para el Pago de las Multas por Infracciones al Régimen de Contravenciones y Sanciones del Sector Combustibles Sólidos Líquidos, aplicadas por la Dirección Nacional de Refinación y Comercialización de esta Subsecretaría, que fuera aprobado por la Resolución Nº 987 de fecha 19 de octubre de 2021 de la SECRETARÍA DE ENERGÍA del MINISTERIO DE ECONOMÍA.', 'tener en cuenta la prórroga y en el caso de que les apliquen sanciones por obligaciones que surgen de regulación de combustibles fósiles. En vencimiento poner: 31/12/22', 2, 'Realizar auditoria  y prueba de hermeticidad de los tanques de almacenamiento de combustible, si se cometen infracciones se aplicarán multas por incumplimientos', 'Se encuentra presentada toda la documentacion en Secretaria de Energia a la espera de incoporar la nueva habilitacion', 'Se efectuó auditoría a los tanques de combustible en diciembre 2024. A la espera del informe', 5, NULL, NULL, 64, '{"custom_1783383400370": "Tanques Aéreos  Y subterraneos de Almacenamiento de Combustibles (TAAH) y SASH", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "MINISTERIO DE ECONOMÍA-SUBSECRETARÍA DE HIDROCARBUROS", "custom_1783383763840": "Anual", "custom_1783383788609": "Todos", "custom_1783383823178": "¨contaminacion del agua y suelo", "custom_1784900000002": "Infraestructura"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Crea el Registro Nacional de Infraestructura de Carga de Vehículos Eléctricos (VE) y Vehículos Híbridos Eléctricos (VHE), en el ámbito de la SUBSECRETARÍA DE ENERGÍA ELÉCTRICA de la SECRETARÍA DE ENERGÍA del MINISTERIO DE ECONOMÍA, con los objetivos de identificar, georeferenciar y difundir el uso de infraestructura de carga de VE y VHE, el relevamiento estadístico de los consumos eléctricos de dicha infraestructura y el fomento de la movilidad eléctrica en todo el territorio de la REPÚBLICA ARGENTINA. En el mismo deberán inscribirse las personas humanas o jurídicas que hayan contratado el servicio de suministro eléctrico, que abastece la infraestructura de carga de VE y VHE, con la correspondiente Distribuidora de energía eléctrica. Se encuentran alcanzados vehículos particulares livianos, flota liviana cautiva-taxis-, y motocicletas), comprendiendo además, la renovación del parque por tecnología BEV (Battery Electric Vehicles-Vehículos Eléctricos a Batería) a baterías de ion-litio, Híbridos Eléctricos y a Gas Natural Comprimido (GNC), en reemplazo de vehículos diesel y nafteros.', 'Inscribirse en el Registro Nacional de Infraestructura de Carga de Vehículos Eléctricos (VE) y Vehículos Híbridos Eléctricos (VHE), cuando cuenten con Infraestructura de Carga de Vehículos Eléctricos (VE) y Vehículos Híbridos Eléctricos (VHE) de cualquier tipo - instalación física todo aquel equipamiento relacionado a la carga de VE y VHE. Cada infraestructura de carga debe tener al menos un punto de carga y un cargador. Cada infraestructura de carga debe contar con sistema de protecciones, medidores, conductores, conectores, tomacorrientes y aquel otro dispositivo que se encuentre dentro de la instalación eléctrica dedicada a la carga del VE y VHE-, debiendo certificar dichas instalaciones', 2, 'Obligatoria', 'Constancia de inscripción en el registro', 'No aplicable', 6, NULL, NULL, 65, '{"custom_1783383400370": "Infraestructura de Carga de Vehículos Eléctricos (VE) y Vehículos Híbridos Eléctricos (VHE)", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "MINISTERIO DE ECONOMÍA-SECRETARÍA DE ENERGÍA", "custom_1783383763840": "inscribirse", "custom_1783383788609": "lugar de carga de baterías", "custom_1783383823178": "Energía"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Modificación de la reglamentación general de la ley N° 24.449 de tránsito y seguridad vial, DECRETO 779/1995. Se sustituyen los artículos 13, 14, 18, 19, 20, 21, 27, 28, 29 de la reglamentación general de la Ley N° 24.449 de tránsito y seguridad vial. Simplifica trámites. Por ser  una Ley Nacional, lo que requiere que tanto provincias como municipios deban decidir adherirse a esta normativa para que tenga validez dentro de sus respectivas jurisdicciones, aplicando en forma directa en rutas Nacionales.\nLa norma implementa  la licencia de conducir digital; elimina la Licencia Nacional de Transporte Interjurisdiccional (LiNTI); permitir peajes sin barreras en rutas nacionales; modifica las condiciones de seguridad de los vehículos; incorporar nuevas señales viales; modifica los plazos de vigencia de la Revisión Técnica Obligatoria (RTO); simplifica los trámites para obtener la licencia de conducir; modifica las condiciones a cumplir por los modelos nuevos de vehículos, elimina el Certificado de Homologación de Autopartes y/o Elementos de Seguridad (CHAS), establece que la  primera Revisión Técnica Obligatoria (RTO) para vehículos que no sean de uso particular debe realizarse dentro de los 12 meses de patentamiento; la RTO periódica para vehículos particulares tiene una vigencia de 24 meses si el vehículo tiene menos de 10 años de antigüedad, y de 12 meses si tiene más; para vehículos articulados destinados al transporte urbano, la autoridad jurisdiccional establece las condiciones especiales para su habilitación. \nLas importaciones en serie, que hasta ahora necesitaban la Licencia de Configuración de Modelo (LCM) y la Licencia de Configuración Ambiental (LCA), esa documentación ya no será necesaria siempre y cuando sean vehículos que provengan de los considerados “mercados de alta vigilancia”. En ese caso, con la sola presentación de las certificaciones internacionales reconocidas, las mismas Trans-WP29-343, esos vehículos quedarán automáticamente homologados para circular por el territorio argentino. \nLas importaciones de autopartes y cascos de motos. En ambos casos se establecen normas IRAM como estándares de calidad mínima en elementos de seguridad en general y en cascos de motocicletas en particular, promoviendo una circulación más segura en la vía pública.\nPara el caso de los autos que no se importarán en serie, sino como operaciones particulares e individuales, se podrá gestionar el Certificado de Seguridad Vehicular (CSV) creado también para importar trailers, remolques y casas rodantes. El CSV lo emite la Agencia Nacional de Seguridad Vial (ANSV). A partir de ahora, las licencias profesionales de conducir clases C, D y/o E, emitidas por las jurisdicciones que adhieran a las normas de la Agencia Nacional de Seguridad Vial (ANSV), tendrán validez para el transporte entre las distintas jurisdicciones\nEl objetivo de estas modificaciones fue agilizar trámites administrativos, reducir costos para los conductores y establecer criterios de seguridad.', 'Tener en cuenta en el caso de poseer vehículos particulares y de carga especialmente por el tema de licencias de conducir conforme la categoría.', 2, NULL, NULL, NULL, 4, NULL, NULL, 66, '{"custom_1783383400370": "Modificación de la reglamentación general de la ley N° 24.449 de tránsito y seguridad vial", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "PEN"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Se establece el Programa Nacional de Control de Pérdidas de Tanques Aéreos de Almacenamiento de Hidrocarburos y sus derivados.\nNormas técnicas para control de pérdidas y contaminación de sistemas de almacenamiento subterráneo de hidrocarburos.\nRégimen de Auditorias obligatorias para tanques de combustibles subterráneos.', 'Esta norma se aplica a los TAAH cuyo volumen de almacenaje individual supere los 2.500 litros y cuyo volumen por debajo de la superficie de la tierra sea inferior al 10% del volumen de almacenaje individual.', 2, 'Realizar auditoria  y prueba de hermeticidad de los tanques de almacenamiento de combustible', 'Informe de auditoría y prueba de hermeticidad de tanques de combustible', 'RES 1102: Al no haber renovado en tiempo y forma el permiso debió iniciarse nuevamente como una inscripción inicial.\nSe presentó solicitud de inscripción según expediente número EX-2024-110696990- -APN-DNEYR#MEC. Auditoría fue ejecutada el 30/12/24. Cantidad de tanques: 8 aéreos y 1 subterráneo.', 5, 'se realizó 30-12-2024 a la espera de emisión del certificado', NULL, 67, '{"custom_1783383400370": "Tanques Aéreos  Y subterraneos de Almacenamiento de Combustibles (TAAH) y SASH", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Secretaría de Energía de la Nación", "custom_1783383763840": "Anual", "custom_1783383788609": "Infraestructura Data Center", "custom_1783383823178": "Potencial derrame de combustible", "custom_1784900000002": "Infraestructura"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Se establece el Programa Nacional de Control de Pérdidas de Tanques Aéreos de Almacenamiento de Hidrocarburos y sus derivados.\nNormas técnicas para control de pérdidas y contaminación de sistemas de almacenamiento subterráneo de hidrocarburos.\nRégimen de Auditorias obligatorias para tanques de combustibles subterráneos.', 'Esta norma se aplica a los TAAH cuyo volumen de almacenaje individual supere los 2.500 litros y cuyo volumen por debajo de la superficie de la tierra sea inferior al 10% del volumen de almacenaje individual.', 2, 'Realizar auditoria de seguridad de los tanques de almacenamiento de combustible', 'Informe de auditoría de seguridad de tanques de combustible', 'RES 785: Se realizó la parte administrativa del trámite , Trámite N°811932, una vez que obtengamos el registro como operadores avanzamos con la auditoría. Planificada para el mes de enero.', 5, NULL, NULL, 68, '{"custom_1783383400370": "Tanques Aéreos  Y subterraneos de Almacenamiento de Combustibles (TAAH) y SASH", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "Secretaría de Energía de la Nación", "custom_1783383763840": "Determana el plazo SE, entre 10 y 15 años", "custom_1783383788609": "Infraestructura Data Center", "custom_1783383823178": "Potencial derrame de combustible", "custom_1784900000002": "Infraestructura"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo', 'Incorpora al Registro de Bocas de Expendio de Combustibles Líquidos, Consumo Propio, Almacenadores, Distribuidores y Comercializadores de Combustibles e Hidrocarburos a Granel y de Gas Natural Comprimido, creado por el Artículo 1° de la Resolución N° 1.102 de fecha 3 de noviembre de 2004 de la SECRETARÍA DE ENERGÍA del ex MINISTERIO DE PLANIFICACIÓN FEDERAL, INVERSIÓN PÚBLICA Y SERVICIOS y sus modificatorias, a todas las personas físicas o jurídicas habilitadas para el expendio de combustibles líquidos bajo la modalidad Estaciones de Servicio Móviles (venta por menor).\nAprueba el procedimiento y las condiciones técnicas y registrales para el expendio de combustibles líquidos bajo la modalidad ESTACIÓN MODULAR PORTÁTIL (Venta minorista), que como Anexo I (IF-2025-136587306-APN-SSCL#MEC) integra la presente medida.\nCrea un marco regulatorio integral para las estaciones de servicio móviles y modulares en Argentina, incorporándolas al registro oficial para expandir el suministro de combustibles a zonas sin bocas fijas, estableciendo requisitos técnicos (como UL-2085, NFPA 385, ADR) y un control reforzado para seguridad y trazabilidad, buscando modernizar la distribución y mejorar el acceso. \nAprueba el procedimiento y las condiciones técnicas y registrales para el expendio de combustibles líquidos bajo modalidad ESTACIÓN DE SERVICIO MÓVIL CISTERNA, que como Anexo II (IF-2025-136688716-APN-SSCL#MEC) integra la presente medida.\nAprueba los protocolos de seguridad “Anexo de Informe de Auditoría (Protocolo Estación Modular) y “Anexo de Informe de Auditoría (Protocolo Estación de Servicio Móvil Cisterna)” para certificar las condiciones técnicas y de seguridad de las categorías referidas en los Artículos 4° y 5° de la presente medida, que como Anexo III (IF-2025-136688977-APN-SSCL#MEC) integra la presente medida.', 'Tener en cuenta que está permitida la instalación de estaciones de servicio móviles y modulares.', 2, NULL, NULL, NULL, 4, NULL, NULL, 69, '{"custom_1783383400370": "ENERGÍA", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "MINISTERIO DE ECONOMÍA- SECRETARÍA DE ENERGÍA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo', 'Deroga el régimen creado en 2005 por la Resolución de la Secretaría de Energía 785/2005 y reemplaza el sistema de formularios y auditorías realizadas por auditores inscriptos en la misma autoridad que dicta la norma, por presentación en el nuevo registro de declaraciones juradas conteniendo un plan de inspección, mantenimiento, reparación y/o alteración conforme a los lineamientos establecidos en la norma API 653. Los mismos sólo podrán realizarlos profesionales, técnicos o inspectores certificados por norma API 653.\nLa norma crea el REGISTRO NACIONAL DE TANQUES AÉREOS DE ALMACENAMIENTO DE HIDROCARBUROS Y DERIVADOS DEL PETRÓLEO en el ámbito de la SECRETARÍA DE ENERGÍA del MINISTERIO DE ECONOMÍA.\nSujetos alcanzados: todas aquellas personas físicas y/o jurídicas que tengan localizados en el territorio nacional Tanques Aéreos de Almacenamiento de Combustibles Líquidos y sus Derivados (TAAH), de acuerdo con las definiciones y características consignadas en el Anexo I de la norma.\nCapacidad de los tanques y unidades de almacenamiento alcanzadas:\n1)  	Tanques aéreos individuales de 50m3 o más (50.000 litros).\n2)  	Operadores que posean la capacidad instalada total de almacenamiento de la sede sea igual o superior a los CIEN METROS CÚBICOS (100 m³, 100.000 litros), registrando todos aquellos TAAH cuya capacidad individual de almacenamiento sea igual o superior a CINCO METROS CÚBICOS (5m3 o 5000 litros), independientemente de su disposición horizontal o vertical.\nPara los tanques nuevos, la inscripción deberá realizarse dentro de los TREINTA (30) días hábiles desde su entrada en operación, de carácter automático y la realizará directamente el operador a través del sistema generador de alarmas de la SECRETARÍA DE ENERGÍA (SGDA) o el que en el futuro lo reemplace, conforme al formato establecido en el Formulario A1 que integra como Subanexo I el Anexo I de la norma.\nLos operadores de los tanques deberán inscribirse según las categorías aprobadas por la norma incluyendo a quienes almacenen: hidrocarburos líquidos, sus derivados y gaseosos, almacenaje de coque de petróleo, almacenaje de hidrocarburos e instalaciones de biocombustibles, bocas de expendio de GNL (Gas Natural Licuado), GNP (Gas Licuado de Petróleo) y GLPA (Gas Licuado de Petróleo Automotor)\nLa norma comienza a regir desde el 28 de junio de 2025, ya que se establece que comienza a regir desde su publicación que se realizó el 27 de junio de 2025.\nSujetos Inscriptos y con auditoría vigente:\na)   	Se incorporan al nuevo registro, los sujetos que actualmente se encuentren registrados por la Resolución 785/2005, conforme las nuevas definiciones.\nb)  	Los operadores que a la fecha de entrada en vigencia de la presente medida tengan inspecciones técnicas de sus tanques en curso o programadas, dispondrán de un plazo de SEIS (6) meses a fin de concluir la inspección y presentar el informe correspondiente ante la Autoridad de Aplicación. Transcurrido dicho plazo el operador deberá adecuar dichas instalaciones a lo dispuesto en la presente resolución.\nSe sugiere solicitar la baja a quienes quedarán fuera de la norma, debido a que antes se encontraban incluidos los sujetos con almacenamiento de más de 2.500 litros y actualmente el límite es mayor (50.000 litros).\nComo antes se expresó, para la confección de los planes y los controles se debe seguir la norma internacional (API 653), en declaraciones juradas técnicas certificadas, que serán responsabilidad del operador. El control externo lo realizará el Estado Nacional a través de la autoridad de aplicación.\nTodo lo que deriva de los controles ambientales de las normas serán realizados por las autoridades de aplicación local (de cada jurisdicción).\nLos profesionales que pueden realizar los planes deben encontrarse certificados por norma API 653.  La certificación API 653 válida en Argentina, como para cualquier otro lugar del mundo, sólo es emitida por el American Petroleum Institute (API). Esta certificación valida las competencias de los profesionales/inspectores de tanques de almacenamiento sobre el suelo según la norma API 653. \nLa norma también crea un sistema de aplicación de sanciones para los operadores, profesionales y técnicos contratados o propios de los operadores que incumplan con la misma y/o falseen información, estableciéndose que al plazo para la respuesta ante el labrado de actas de infracción es de 10 días, y la vía recursiva en el caso de imposición de sanciones es la establecido por la Ley Nacional N° 19549  de procedimientos Administrativos.  \n Aclaración: Los tanques de mensos de 50.000 litros o de instalaciones alcanzadas de menos de 500 litros, continúan debiendo ser controlados conforme lo establece la normativa de higiene y seguridad del trabajo (Decreto PEN. 351/1979, especialmente el capítulo 18 del Anexo I, que determina como debe estar contenidos, materiales constructivos, forma de almacenamiento, control de aspectos relacionados al control contra incendios, cartelería de seguridad, capacitaciones del personal que trabaja en el sitio, etc.).\nEn el caso de que las jurisdicciones locales -Municipios, Provincia o Ciudad Autónoma- los reglamenten, se deberá cumplir con todo lo que dispongan las autoridades de aplicación local.', 'Tener en cuenta solicitar la baja si los tanques son de menos de 50m3 o más, y si poseen más de 100 m³, 100.000 litros, registrar todos aquellos TAAH cuya capacidad individual de almacenamiento sea igual o superior a CINCO METROS CÚBICOS (5m3 o 5000 litros), independientemente de su disposición horizontal o vertical. Las auditorías y controles las realizarán profesionales que pueden realizar los planes deben encontrarse certificados por norma API 653.', 2, NULL, NULL, NULL, 5, NULL, NULL, 70, '{"custom_1783383400370": "ENERGÍA", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "MINISTERIO DE ECONOMÍA SECRETARÍA DE ENERGÍA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 295);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo', 'Aprueba la Norma NAG-501 (2018) “Norma Mínima de Seguridad para Plantas de Almacenamiento de Gas Natural Licuado en tierra”, que forma parte integrante de la presente Resolución como Anexo IF-2018-44024965-APN-GAL#ENARGAS.\nSustituye la Sección 12 de la NAG-100 (1993), la que quedará redactada de la siguiente manera:\n“SECCION 12 - SISTEMAS PARA GAS NATURAL LICUADO (GNL): a) Ningún operador puede almacenar, tratar, o  transferir gas natural licuado en sistema de cañería, a menos que satisfaga los requerimientos aplicables de esta Norma y de la Norma NAG-501; b) No se podrá almacenar, tratar o transferir gas natural licuado en un sistema de cañería en operación o en construcción, a menos que: 1) los sistemas sean operados de acuerdo con los requerimientos aplicables de operación de esta Norma y de la Norma NAG-501, y 2) toda modificación o reparación hecha a los sistemas existentes, sean realizados conforme a los requerimientos aplicables de esta Norma, y de la Norma NAG-501 en lo que sea aplicable”.\nAmplía el alcance del “Código argentino de gas - NAG”, puesto en vigencia a través del Artículo 1º de la Resolución ENARGAS N.º 2747/02, incorporando al Anexo 1 de dicho acto el siguiente texto: “Grupo V – Almacenamiento: Comprende todo lo referido a plantas de almacenamiento de Gas Natural Licuado (GNL) en tierra y off shore, almacenamientos subterráneos, plantas de licuefacción, transporte (Gasoductos Virtual) y diversas utilizaciones del GNL”.', 'Ningún operador puede almacenar, tratar, o  transferir gas natural licuado en sistema de cañería, a menos que satisfaga los requerimientos aplicables de esta Norma y de la Norma NAG-501', 2, NULL, NULL, NULL, 4, NULL, NULL, 71, '{"custom_1783383400370": "ENERGÍA", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "ENARGAS"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 564);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo', 'Sustituye el artículo 1° de la Ley N° 26.020 y sus modificatorias por el siguiente:\n“ARTÍCULO 1º.- Objeto. La presente ley establece el marco regulatorio para la industria y comercialización de gas licuado de petróleo. Se aplicarán supletoriamente las Leyes N° 24.076 y N° 17.319, y sus respectivas modificatorias, en todo lo que no esté expresamente establecido en la presente. Constituye un objetivo esencial del marco regulatorio establecido por la presente ley asegurar el suministro regular, confiable y económico de gas licuado de petróleo a sectores sociales residenciales de escasos recursos que no cuenten con servicio de gas natural por redes”.\nSustituye el artículo 8° de la Ley N° 26.020 y sus modificatorias por el siguiente:\n“ARTÍCULO 8º.- Autoridad de Aplicación y organismo de fiscalización. La Autoridad de Aplicación de la presente ley será la SECRETARÍA DE ENERGÍA del MINISTERIO DE ECONOMÍA, la cual podrá celebrar convenios para delegar sus funciones de fiscalización y control técnico en organismos públicos o privados que acrediten la competencia necesaria. Asimismo, podrá celebrar convenios específicos con las Provincias y la CIUDAD AUTÓNOMA DE BUENOS AIRES para delegar el ejercicio de sus facultades”.', 'Tener en cuenta.', 2, NULL, NULL, NULL, 4, NULL, NULL, 72, '{"custom_1783383400370": "ENERGÍA", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "PODER EJECUTIVO"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1969);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo', 'Aprobar la Adenda N° 1 Año 2025 de la norma NAG-132 (2024) “Accesorio de transición para sistemas de tuberías de polietileno para el suministro de combustibles gaseosos”, que como Anexo IF-2025-78837019-APN-GIYN#ENARGAS, forma parte del presente acto.\nDisponer que la Adenda N° 1 Año 2025 de la norma NAG-132 (2024) “Accesorio de transición para sistemas de tuberías de polietileno para el suministro de combustibles gaseosos”, entrará en vigencia al día siguiente de la publicación en el Boletín Oficial de la República Argentina, y será de aplicación para el inicio de trámites de nuevas certificaciones por parte de los Organismos de Certificación acreditados por el ENARGAS.', 'Tener en cuenta si poseen accesorios de transición para sistemas de tuberías de polietileno para el suministro de combustibles gaseosos.', 2, NULL, NULL, NULL, 4, NULL, NULL, 73, '{"custom_1783383400370": "ENERGÍA", "custom_1784900000001": "NACIONAL", "custom_1783383445340": "ENTE NACIONAL REGULADOR DEL GAS"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Arts. 14, y 26 a 30', 'El ambiente es patrimonio común. Toda persona tiene derecho a gozar de un ambiente sano, así como el deber de preservarlo y defenderlo en provecho de las generaciones presentes y futuras.\nToda actividad que suponga en forma actual o inminente un daño al ambiente debe cesar. El daño ambiental conlleva prioritariamente la obligación de recomponer.', 'Establece derechos y obligaciones que deben ser cumplidos por todas las personas en materia de proteccion ambiental', 1, 'Informativa', 'cumplimiento de la legislacion', 'Es informativa. Cumplimiento de la legislacion', 8, NULL, NULL, 74, '{"custom_1783383400370": "Ambiente General", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383763840": "Continuo", "custom_1783383788609": "todos", "custom_1783383823178": "proteccion del ambiente", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Toda obra debe contar con presentación de planos, visados ante colegio profesional correspondiente, suscriptos por profesional matriculado, encomienda profesional y pago de derechos de construcción. Los planos se registran ante la Dirección General de Registro de Obras y Construcciones en el Ministerio de Desarrollo Urbano de la Ciudad. (DGROC). Solo cuando hay modificaciones presentar nuevos planos.', 'Existen distintos tipos de habilitación según el rubro que encuadra la actividad comercial  que se pretende llevar a cabo, y la cantidad de metros que posea el establecimiento a habilitar. En principio, no vence la habilitación, salvo cambio de rubro , cambio de razón social, si se amplia o  el proyecto se ve modificado. Debe poseer Libro de Inspecciones.  Nomenclatura catastral D EZ Circ 15 Secc 49 Manzana 288 Paracela 1j Rubro:  "6.2.19 Centro de procesamiento de datos y tabulaciones"', 2, 'Planos de finalizacion de obra, sanitarios, electromecanicos y ventilacion.\nDeben poseer libro de Inspeccion \nHabilitacion según rubro', 'La habilitación de Artigas esta a nombre de Cirion Technologies.', 'La fecha de emisión de la certificación es del 13/12/2024', 1, NULL, '2030-12-31', 75, '{"custom_1783383400370": "Habilitación", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "No vence salvo modificaciones", "custom_1783383788609": "TODOS", "custom_1783383823178": "Habilitación", "custom_1783384038540": "#REF!"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Formulario de pago de ingresos no tributarios sellado', 'Se fija el valor de los aranceles que deberán abonarse por los diversos trámites ambientales a realizarse ante la Agencia de Protección Ambiental (APRA).', 1, 'Informativa', NULL, 'Se abonan tarifarias y aranceles varios en cada expedeinte', 4, NULL, NULL, 76, '{"custom_1783383400370": "Aranceles", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Agencia de Proteccion Ambiental", "custom_1783383763840": "Loa Aranceles se abonan con la tramitacion de los permisos", "custom_1783383788609": "TODOS"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, NULL, 'Sustituye varios textos del Anexo B de la Ordenanza N° 34.421 que reglamenta el CÓDIGO DE HABILITACIONES Y VERIFICACIONES para albergues, natatorios, transportes locales de alimentos, licencias para actividades y eventos transitorios, etc. . También sustituye y modifica la Ley 154  en cuanto a los transportista de residuos patogénicos inscriptos en el Registro de Residuos peligrosos de CABA en el APRA, obligando a quienes transporten residuos de generadores ubicados en CABA a tramitar su inscripción en el Registro de Generadores, Transportistas y Operadores de Residuos Patogénicos  y obtener el  Certificado de Aptitud Ambiental que es el instrumento que emite el Registro de Generadores, Transportistas y Operadores de Residuos Patogénicos y acredita, la aprobación del sistema de generación, transporte y tratamiento de residuos patogénicos. \nLos generadores, transportistas y operadores de residuos patogénicos, deben inscribirse en el Registro citado para obtener el Certificado de Aptitud Ambiental pertinente para el desarrollo de sus actividades, el que tendrá validez de dos (2) años tanto para los Operadores y Transportistas. Los transportistas que homologuen el Certificado Ambiental Anual nacional, deberán mantener actualizada la Declaración Jurada correspondiente. En el caso del Certificado para los Generadores, la vigencia será de tres (3) años. \n\nGeneradores de residuos patogénicos - Se consideran generadores de residuos patogénicos a todas las personas humanas o jurídicas, públicas o privadas que, como resultado de las actividades habituales que practiquen en cualquiera de los niveles de atención de la salud humana o animal, generen los desechos o elementos materiales definidos en el artículo 2° de la presente ley. Entre ellos, hospitales, sanatorios, clínicas, policlínicas, centros médicos, maternidades, salas de primeros auxilios, consultorios, servicios de ambulancias, laboratorios, centros de investigación y de elaboración de productos farmacológicos, gabinetes de enfermería, morgue y todo aquel establecimiento donde se practique cualquiera de los niveles de atención a la salud humano o animal con fines de prevención, diagnóstico, tratamiento, rehabilitación e investigación. Los Generadores de residuos patogénicos deberán adoptar medidas tendientes a su óptima separación en origen de los residuos patogénicos. \nEl Certificado de Gestión de Residuos Peligrosos es el instrumento que acredita, en forma exclusiva la aprobación de la gestión de los residuos peligrosos y deberá mantenerse actualizado y vigente, conforme lo establezca la reglamentación. \nTiene una validez de dos (2) años tanto para los Operadores y Transportistas, debiendo ser renovado a su vencimiento. Los transportistas que homologuen su inscripción nacional, deberán mantener actualizada la Declaración Jurada correspondiente. \nEn el caso del Certificado para los Generadores, la validez es de tres (3) años. \n\nResiduos Peligrosos. Establece que los datos incluidos en la declaración jurada para la inscripción en los registros creados por la ley serán actualizados según el plazo de vigencia establecido para cada caso, sin perjuicio que la autoridad de aplicación pueda solicitar en cualquier instancia información respecto a la generación, almacenamiento, transporte, tratamiento y disposición final de residuos peligrosos cuando así lo considere necesario. \n\nTambién modifica la gestión de aceites vegetales. “De Los Aceites Vegetales Y Grasas De Fritura Usados”, de la Ley 451, y establece respecto de la "Falta de inscripción en el Registro.- El titular de un establecimiento comprendido en los términos de la Ley de Regulación, Control y Gestión de Aceites Vegetales y Grasas de Fritura Usados que no se haya inscripto en el Registro, será sancionado con multa de setenta (70) a seis mil ochocientas (6.800) unidades fijas." \n\nTambién para “Actividades Lucrativas no Permitidas o Ejercidas en Infracción”, de la Ley 451 (texto consolidado por Ley 6347) y sus modificatorias, establece sanciones para quienes realicen "Pintada de cordón sin autorización de la Autoridad de Aplicación, será  sancionado con multa de quinientos (500) a tres mil (3.000) unidades fijas. \n\nTambién establece sanciones para no cumplan con las normas de instalación de carteles y estructuras publicitarias,  quienes no hagan la demarcación en la calzada de sector de ingreso y egreso de vehículos a la vía pública, estableciendo que los frentistas podrán pintar de amarillo el sector del cordón frente al ingreso y egreso de vehículos hacia y desde la vía pública, extendiendo esa demarcación medio metro a cada lado del ancho de la entrada. \nAdicionalmente, sólo cuando el tipo de calzada lo permita, se podrá delimitar el sector de ingreso y egreso de vehículos hacia y desde la vía pública mediante líneas en la calzada, ubicadas a medio metro de cada lado del ancho de la entrada y perpendiculares al cordón, de un largo de un metro y medio, y una línea paralela al cordón, uniendo las anteriormente mencionadas. Las líneas deben dibujarse en un trazo continuo en color amarillo y de un ancho de cero con diez metros. El estacionamiento en el espacio delimitado, se encuentra prohibido.  Los trabajos serán llevados a cabo por el frentista, a su costo.', 'Tener en cuenta que deben mantener la inscripción en el registro de residuos peligrosos y patogénicos de CABA. Y si el comedor realiza comida con frituras y genera aceite, deben requerir que se inscriba en el registro de aceites vegetales de CABA. También tener en cuenta que los transportistas de residuos patogénicos y peligrosos deben estar inscriptos en CABA. Otro tema a considerar es mantener la demarcación en la calzada de sector de ingreso y egreso de vehículos a la vía pública .', 2, 'Obligatoria', 'Hablitarse e inscribirse en los registros correspondientes', 'Registro de inscripción de residuos peligrosos\nEl registro como generadores de aceites vegetales NO ES APLICABLE porque en Artigas solo se entregan viandas de alimentos a los colaboradores.', 5, NULL, NULL, 77, '{"custom_1783383400370": "Habilitaciones/residuos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Legislatura Porteña", "custom_1783383763840": "Continuo", "custom_1783383788609": "Infraestructura\\nReal Estate", "custom_1783383823178": "Residuos Peligrosos\\nDemarcación", "custom_1784900000002": "Team Leader DC Critical Facilities"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'A la fecha de hoy la norma no se encuentra reglamentada, por lo que sus disposiciones no se encuentran operativas, salvo la prohibición de vuelco de efluentes a colector pluvial.Ciudad de Buenos Aires tiene cobertura de agua de red', 'Se regula la gestión ambiental del agua de dominio público de la Ciudad Autónoma de Buenos Aires.\nSe regulan los diversos permisos de uso de agua y de vuelco de efluentes líquidos.\nSe prohíbe el vertido de efluentes líquidos industriales y asimilables a los mismos, a la red pluvial, a los cursos y cuerpos de agua superficial, así como en la vía pública.', 2, 'La norma no esta reglamentada y por ahora no es aplicable', NULL, 'No es aplicable', 6, NULL, NULL, 78, '{"custom_1783383400370": "Agua: Uso de Aguas", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "N/A", "custom_1783383823178": "No esta operativa la norma", "custom_1783384038540": "NO APLICABLE"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, NULL, 'Se implementa mediante la presente resolución el Registro de Aguas creado por el artículo 21 de la Ley N° 3.295 (Texto consolidado por Ley N° 6.347) de Gestión Ambiental del Agua.\nSe incorporan  al Registro de Aguas, los permisos otorgados en el marco de la Ley N° 3.295 (texto consolidado por Ley N° 6.347), detallados en el Anexo I (IF-2021-23642904-GCABA-APRA) que forma parte integrante de la presente.  Los permisos que se otorgan son para:\n(i) extracción de agua subterránea; (ii) extracción de agua de cursos superficiales;\n(iii) vuelco de efluentes líquidos a conductos pluviales o curso de agua superficial; y\n(iv) labores transitorias y especiales.', NULL, 2, NULL, 'no se puso en practica', NULL, 4, '¿Aquí tenemos alguna obligación?', NULL, 79, '{"custom_1783383400370": "Agua: Uso de Aguas", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Legislatura de la Ciudad Autónoma de Buenos Aires"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', '1.Obtener la factibilidad de la localización de la estructura de la antena expedida por el Consejo de Plano Urbano Ambiental (COPUA), conforme lo establecido en el Acuerdo 328/CPUAM/09.                                                  \n2.Posteriormente, se deberá seguir el procedimiento administrativo regulado por la Resolución Conjunta APRA/SPLAN 1/08.', 'La Resolución Conjunta APRA/SPLAN 1/08 regula el procedimiento relacionado con la localización, impacto ambiental, instalación y registro de planos referentes al Rubro del Cuadro de Usos 5.2.1. a) - Agrupamiento Servicios Terciarios "Estación de radio y/o televisión, telefonía móvil celular, campo de antenas y equipos de transmisión", así como también, sus estructuras de soporte.\n\nEl Acuerdo 328/CPUAM/09 regula la localización de estructuras soporte de antenas del rubro estación de radio y/o televisión, telefonía móvil celular, radiocomunicaciones, campo de antenas, equipos de transmisión.\nEstablece el Estándar Nacional De Seguridad para la exposición a radiofrecuencias entre 100 kHz y 300 GHz.', 2, 'Debe realizarse el tramite de estudio de impacto ambiental con profesional habilitado y obtener la factibilidad de localizacion. No existen lugares predeterminados. No se verifico su cumplimiento ni hay requerimiento de autoridad', 'Se cumple con los estandares y paga canon por la instalacion de estructuras', 'Estudio de radiaciones no ionizantes realizado en diciembre 2019', 1, NULL, NULL, 80, '{"custom_1783383400370": "Antenas y Radiaciones No Ionizantes", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Agencia de Proteccion Ambiental", "custom_1783383763840": "vencimiento establecido por la resolucion que lo otorgue. No tiene vencimiento", "custom_1783383823178": "proteccion a la salud", "custom_1784900000002": "EHS"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', '1.Observar si la empresa posee fuentes fijas en los términos del Anexo II del Decreto 198/06. \n2.En ese caso, inscribirse en el Registro de Generadores de Contaminantes Atmosféricos Provenientes de Fuentes Fijas (R.E.F.) de acuerdo a los requisitos fijados en el art. 16 del decreto \n3.Observar los límites máximos de emisiones olorosas y los Estándares de Calidad de Aire y de Partículas Sedimentales \n4.Las determinaciones ambientales que se realicen con el fin de cumplimentar esta normativa, deberán ser efectuadas por laboratorios que se encuentren inscriptos en el RELADE.                                                                                                                                La Resolución CABA 68/APRA/21: Modifica el Anexo III “Estándares de Calidad de Aire” del Decreto N° 198/06.\nModifica el Anexo X “Métodos de medición de calidad de aire”, del Decreto N° 198/06.\nLos estándares de calidad de aire y sus métodos de medición, receptados en el Anexo I de la presente Resolución, se implementarán con carácter progresivo, a través de cinco (5) etapas:\na. Las primeras tres (3) etapas tendrán una duración de un (1) año calendario cada una y actuarán en forma concatenada, a contar a partir de la entrada en vigor del presente acto;\nb. Las etapas cuatro (4) y cinco (5), se implementarán conforme el cronograma que deberá establecer, antes de finalizar el año 2023, la Comisión Asesora de Expertos en Calidad de Aire, en conjunto con la Agencia de Protección Ambiental.', 'Atmosféricos Provenientes de Fuentes Fijas (R.E.F.)\nSe especifican las fuentes fijas que deben inscribirse en el REF (Anexo II, Decreto 198/06)\nPermiso de Emisión o Constancia de inscripción en el REF\nSe requiere la elaboración de Plan de Monitoreo\nSe fijan las características de los conductos de emisión\nLímites Máximos de Emisiones Olorosas (Anexo II, Ley 1.356)\nFijación de Estándares de Calidad del Aire y de Partículas Sedimentables (Anexo III, Decreto 198/06)\nCreación del Registro de Laboratorios de Determinaciones Ambientales (RELADE)', 2, 'Constancia de Inscripción en el Registro de Generadores de Contaminantes Atmosféricos Provenientes de Fuentes Fijas (R.E.F.) Verificar si hay ductos con emisiones.           Exp 2018-0303462.  Verificar la existencia de ductos al exterior o de emisiones difusas. Verificar si los HP denunciados en el plano electromecanico superan los 25 HP, de ser asi, deben registrarse como generadores. Controlar emisiones provenientes de equipos de generacion electrica de emergencia.', 'Se encuentran registrados. VENCIDO', 'Posee número de expediente 2018-03034623-MGEYA-APRA a nombre de LEVEL 3 ARGENTINA. sobre el cual se solicitó renovación de la inscripción y cambio de razón social, según número de tramite 1134, en el año 2020. El trámite se encuentra en estado “observado” donde solicitan se presente habilitación comercial y planos a nombre de CIRION TECHNOLOGIES, reflejando el cambio de razón social. El 20/12/24 se presenta la habilitación con el cambio de razón social y los planos actualizados, N° de carátula de EXP 2018-03034623-MGEYA-APRA. A la espera de respuesta de APRA. Las mediciones de efluentes gaseosos de los grupos electrógenos, se realizarán el 6/1/25.', 5, 'Se realizaron mediciones de monitoreo el 06/01/2025', NULL, 81, '{"custom_1783383400370": "Efluentes Gaseosos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires  PRESIDENTE DE LA AGENCIA DE PROTECCIÓN AMBIENTAL DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES", "custom_1783383763840": "Renovación cada 2 (dos) años.", "custom_1783383788609": "Infraestructura y EHS", "custom_1783383823178": "Proteccion del aire", "custom_1784900000002": "Data Center Critical Facilities"}');
