INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', '"Plan de Adaptación y Mitigación del Cambio Climático de la Ciudad Autónoma de Buenos Aires" .', 'Tener en cuanta por las modificaciones en cuanto a emisiones que pueden ocasionarse\nLa obligación en este caso es del estado, ya que esta norma \ninsta al Estado para que controle y regule los efluentes gaseosos que causan el cambio climático.', 1, 'Informativa', 'Cumplir con la normativa sobre transición energética y efluentes gaseosos', 'La obligación en este caso es del estado, ya que esta norma \ninsta al Estado para que controle y regule los efluentes gaseosos que causan el cambio climático.', 8, NULL, NULL, 82, '{"custom_1783383400370": "Efluentes Gaseosos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires  PRESIDENTE DE LA AGENCIA DE PROTECCIÓN AMBIENTAL DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES", "custom_1783383763840": "Continua", "custom_1783383788609": "Todos", "custom_1783383823178": "Aire", "custom_1784900000002": "Infraestructura", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 264);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', '1.Todo trámite de solicitud del Certificado de Aptitud Ambiental debe iniciarse exclusivamente vía internet, a través de la página web oficial del Gobierno de la Ciudad Autónoma de Buenos Aires. El trámite continuará y concluirá por esa vía para las actividades, proyectos, programas y/o emprendimientos categorizados como SRE y SRE c/C.  (SIN Relevante Efecto)  \n2.Observar el Cuadro de Usos agregado en las normas reglamantarias y verificar la categorización asignada al Rubro aplicable a la actividad de la empresa. En general, las actividades comerciales se encuentran categorizadas como de impacto ambiental Sin Relevante Efecto (SRE) y Sin Relevante Efecto c/Condiciones.                                                                          3.Observar el Procedimiento de Evaluación de Impacto Ambiental aprobado por Resolución N.º 67/APRA/21 Y Disposición 414/2021   aprueba  CRITERIOS OBJETIVOS - ANEXO II DE LA RESOLUCIÓN N° 67-APRA21 - SE APRUEBAN - CRITERIOS DE VALORACIÓN - RELEVANCIA AMBIENTAL DE UNA OBRA O USO - EVALUACIÓN DE IMPACTO AMBIENTAL - TABLA DE REFERENCIAS - CERTIFICADOS DE APTITUD AMBIENTAL - SE DEJA SIN EFECTO - DISPOSICIÓN N° 2.066-DGEVA/19 - AGENCIA DE PROTECCIÓN AMBIENTAL\n4.Obtener el Certificado de Aptitud Ambiental (CAA) expedido por la autoridad de aplicación', 'Procedimiento aplicable a todas las actividades que se desarrollan en el ámbito de la CABA\nCategorización de actividades en de impacto ambiental Sin Relevante Efecto (SRE); Sin Relevante Efecto c/Condiciones (SRE c/Condiciones); sujetas a Categorización (s/C); y Con Relevante Efecto (CRE)\nObtención de Certificado de Aptitud Ambiental (CAA)\nEl procedimiento de EIA dependerá de la categorización asignada al rubro de acuerdo al Cuadro de Usos del Código de Planeamiento Urbano incorporado al régimen.\nLas actividades categorizadas como CRE  se encuentran enumeradas en el art. 13 de la ley 123. \nLas actividades categorizadas como s/Categorización y SRE surgen, de acuerdo al Rubro, en el Cuadro de Usos Cuadro de Usos del Código de Planeamiento Urbano.\nLa Resolución 11/19 establece todo el procedimiento para la obtencion del CAA mediante el cual se determinan:\n-CUADRO DE CATEGORIZACIÓN \n-ACTIVIDADES, PROYECTOS, PROGRAMAS Y/O EMPRENDIMIENTOS CATEGORIZADOS COMO DE IMPACTO AMBIENTAL SIN RELEVANTE EFECTO (SRE) Y SIN RELEVANTE EFECTO CON CONDICIONES (SRE C/C) \n-ACTIVIDADES, PROYECTOS, PROGRAMAS Y/O EMPRENDIMIENTOS SUJETOS A CATEGORIZACION (s/C) \n-ACTIVIDADES, PROYECTOS, PROGRAMAS Y/O EMPRENDIMIENTOS CATEGORIZADOS COMO DE IMPACTO AMBIENTAL CON RELEVANTE EFECTO (CRE)\n-FORMULARIO DE CATEGORIZACION DE IMPACTO AMBIENTAL DE ACTIVIDADES, PROYECTOS, PROGRAMAS Y/O EMPRENDIMIENTOS SIN RELEVANTE EFECTO\n-FORMULARIOS DE CATEGORIZACIÓN DE IMPACTO AMBIENTAL Y CERTIFICADO DE APTITUD AMBIENTAL DE ACTIVIDADES, PROYECTOS, PROGRAMAS Y/O EMPRENDIMIENTOS SIN RELEVANTE EFECTO CON CONDICIONES \n-FORMULARIOS DE CATEGORIZACIÓN DE IMPACTO AMBIENTAL DE ACTIVIDADES, PROYECTOS, PROGRAMAS Y/O EMPRENDIMIENTOS SUJETOS A CATEGORIZACIÓN (S/C) O CON RELEVANTE EFECTO (CRE) \n-MODELO DE CERTIFICADO DE APTITUD AMBIENTAL DE ACTIVIDADES, PROYECTOS, PROGRAMAS Y/O EMPRENDIMIENTOS SIN RELEVANTE EFECTO (SRE) CON DISTRITO DE ZONIFICACIÓN (IF-2019- 03450415-APRA); MODELO DE CERTIFICADO DE APTITUD AMBIENTAL DE ACTIVIDADES, PROYECTOS, PROGRAMAS y/O EMPRENDIMIENTOS SIN RELEVANTE EFECTO (SRE) CON MIXTURAS\n-INDICADORES DE VALORACIÓN AMBIENTAL', 2, 'Certificado de Aptitud Ambiental', 'CAA Ciudad Autónoma de Buenos Aires,15 de febrero de 2019\nSe concede Certificado a CENTURY LINK S.A., titular de la/s actividad/es declarada/s en el anverso del\npresente, a desarrollarse en el inmueble sito en DEL CAMPO AV. 1301 / 1359 de esta Ciudad. Área según CUR 4,\ncon una superficie de 8311.99 m2, cuya categorización es SIN RELEVANTE EFECTO AMBIENTAL.', 'Exhibe Certificado de Aptitud Ambiental con vigencia indefinida.', 1, '26/12/2024: Se esperará realizar la auditoria de tanques de Artigas para renovar el CAA con nueva razón social.', NULL, 83, '{"custom_1783383400370": "Evaluacion de Impacto Ambiental", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Agencia de Proteccion Ambiental", "custom_1783383763840": "Certificado de Aptitud Ambiental Sin Relevante Efecto (SRE) otorgado en 2017", "custom_1783383788609": "EHS", "custom_1783383823178": "Proteccion de los recursos naturales y la calidad de vida", "custom_1784900000002": "EHS\\nData Center Critical Facilities"}');
