INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'La presente Ley tiene como objeto la actualización de la Ley 6 de Audiencias Públicas (texto consolidado por Ley 6588) de acuerdo a la práctica constitucional vigente de dicho instituto, la consagración definitiva de las nuevas modalidades de participación en las Audiencias Públicas realizadas en la Ciudad Autónoma de Buenos Aires, y la modernización de sus disposiciones.\nDroga la Ley 6306 que modificaba transitoriamente la Ley 6.', 'Regla las audiencias públicas en el caso de que debieran realizar un esdudio de impacto ambiental por una obra nueva', 1, 'Informativa', 'CAA', 'CAA', 8, NULL, NULL, 84, '{"custom_1783383400370": "Audiencias Públicas", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Legislatura Porteña", "custom_1783383763840": "Cuando se realice una obra nueva alcanzado por el porcedimiento de EIA", "custom_1783383788609": "Todos", "custom_1783383823178": "Daño al Ambiente", "custom_1784900000002": "La empresa", "custom_1783384038540": "INFORMATIVA"}');
