INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Apruébase el PROGRAMA NACIONAL DE ORDENAMIENTO AMBIENTAL DEL TERRITORIO\n(PNOAT) el que será implementado a través de la DIRECCIÓN NACIONAL DE PLANIFICACIÓN Y ORDENAMIENTO AMBIENTAL DEL TERRITORIO de la SECRETARIA DE POLITICA AMBIENTAL EN RECURSOS NATURALES.\n\nEl objetivo general es promover, desarrollar y consolidar el Ordenamiento Ambiental del Territorio (OAT), como política de Estado con perspectiva federal, respetando las competencias provinciales, acompañado y fomentando los procesos a través del Subsecretaría de Ambiente de la Nación.', 'Es una norma institucioanl que puede condicionar actividades, si se encuantran en zonas no aptas', 1, 'Informativa', 'Zonificación', 'Es informativa', 8, NULL, NULL, 85, '{"custom_1783383400370": "GENERAL- ORDENAMIENTO AMBIENTAL DEL TERRITORIO", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Subsecretaaría de Ambiente de la Nación", "custom_1783383763840": "Si se reglamenta el instituto OAT", "custom_1783383788609": "Todos", "custom_1783383823178": "Prevenir daño al ambiente", "custom_1784900000002": "Es informativa", "custom_1783384038540": "INFORMATIVA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Cualquier actividad que realice la empresa y que pudiera afectar al arbolado público urbano existente, deberá ser comunicada a la autoridad de aplicación a fin de obtener la autorización correspondiente.', 'Se entiende por arbolado público urbano a las especies arbóreas, las palmeras y las arbustivas manejadas como árboles, que conforman el arbolado de alineación y de los espacios verdes así como los implantados en bienes del dominio público del Gobierno de la Ciudad Autónoma de Buenos Aires.\nLa norma prohíbe:\na) Dañarlos en forma total o parcial lesionando su anatomía o fisiología, a través de heridas mecánicas, quemando sus tejidos con fuego, fijando elementos extraños, introduciendo o arrojando sustancias fitotóxicas en el suelo o en sus tejidos, o pintando los fustes o ramas con cal, barniz o pinturas.\nb) Plantar en la plantera otras especies vegetales junto al árbol.\nc) Instalar o disponer en la plantera cualquier tipo de elemento o equipamiento, eliminar o disminuir la superficie absorbente de la misma, alterar o destruir cualquier elemento protector.\nd) Podar, extraer, talar o plantar árboles, a excepción de los trabajos instruidos o autorizados por la Autoridad de Aplicación.', 2, 'En caso de necesidad de remocion de especies vegetales se debe informar a la autoridad de aplicación', 'La empresa no realiza podas en especies de la via publica', 'La empresa no realiza podas en especies de la via publica', 1, NULL, NULL, 86, '{"custom_1783383400370": "Flora: Arbolado Público", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Los permisos de poda se otorgan para cada caso especial", "custom_1783383788609": "Real Estate", "custom_1783383823178": "Proteccion de especies vegetales", "custom_1784900000002": "Real Estate"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, @nc3);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Tener presente el procedimiento de medición y evaluación de radiaciones no ionizantes, en caso que la autoridad de aplicación requiera la realización de mediciones.', 'Mediante esta norma se aprueba el Protocolo para la Evaluación de Radiaciones No Ionizantes de 100 kHz a 300 GHz, los Métodos de Medición y el Reporte de la Medición (Anexo I, II y III de la Resolución APRA 343/08)', 2, 'Se debe obtener con la Constancia de Radiacion No Ionizante realizada', 'La autoridad APRA no lo ha solicitado.\nCon la resolución del Ministerio de trabajo y de Salud se estaría cumpliendo con lo que solicita CABA, más la habilitación ENACOM', 'Estudio de radiaciones no ionizantes realizado en diciembre 2019 sin vencimiento, y sin riesgos', 1, NULL, NULL, 87, '{"custom_1783383400370": "Radiaciones Electromagnétcas", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Agencia de Proteccion Ambiental", "custom_1783383763840": "Es a requerimiento de la autoridad ambiental de CABA", "custom_1783383788609": "EHS", "custom_1783383823178": "proteccion de la salud", "custom_1784900000002": "EHS Argentina"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la Norma', 'Establecense presupuestos minimos de proteccion ambiental para la gestion integral de residuos domiciliarios. disposiciones generales. autoridades competentes. generacion y disposicion inicial. recoleccion y transporte. tratamiento, transferencia y disposicion final. coordinacion interjurisdiccional. autoridad de aplicacion. infracciones y sanciones. disposiciones complementarias. En el reglamento se estabelce que el Subsecretaaría de Ambiente de la Nación será la Autoridad de Aplicación de la Ley N° 25.916, el cual se encuentra facultado para dictar las normas complementarias que fueren necesarias para alcanzar los objetivos de dicha ley.\nAprueba el “Código unificado de colores para la clasificación e identificación de fracciones de residuos domiciliarios” como ANEXO II (IF-2022-116415878-APN-SCYMA#MAD) \n\nInvita a las provincias y a la Ciudad Autónoma de Buenos Aires a adherir al presente e incorporar sus disposiciones de manera progresiva, atendiendo a las condiciones técnicas, económicas y socio-culturales de cada jurisdicción.', 'Respecto de las actividades privadas y púbicas detemina por cantidad de residuos generados que los grandes generadores deben gestionar los residuos por sus propios medios aplicando el principio de economía circualar', 2, 'De cumplimiento obligatorio conforme normas locales', 'plan de gestión de residuos\nFacturas/Constancias por recojo de RSU', '26/12/24: Se disponen de las facturas de la empresa Veolia (retira residuos sólidos urbanos)', 4, NULL, NULL, 88, '{"custom_1783383400370": "Residuos: Residuos Sólidos Urbanos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Ley Naciona de Presupuestos Mínimos. Congreso de la Nación. Ver normas locales", "custom_1783383763840": "Continuo", "custom_1783383788609": "Todos", "custom_1783383823178": "contaminación", "custom_1784900000002": "Real Estate"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la Norma', 'Sustituye el inciso 56 del artículo 16 del Título V de la Ley de Ministerios Nº 22.520 (texto ordenado por Decreto Nº 438 del 12 de marzo de 1992) y sus modificatorias respecto de las funciones del MINISTERIO DE SEGURIDAD NACIONAL por el siguiente:\n“56. Colaborar con los entes nacionales, provinciales o privados, para proteger a la comunidad frente a desastres naturales o causados por el hombre y a ilícitos que por su naturaleza sean de su competencia”.\nSustituye el inciso 95 del artículo 16 del Título V de la Ley de Ministerios Nº 22.520 (texto ordenado por Decreto Nº 438 del 12 de marzo de 1992) y sus modificatorias por el siguiente:\n“95. Intervenir en lo relacionado a las acciones preventivas y ante las emergencias naturales y catástrofes climáticas”.', 'Institucional, tener en cuenta que en materia de desastres climáticos resulta competente el Ministerio de Seguridad Nacional.', 2, NULL, NULL, NULL, 4, NULL, NULL, 89, '{"custom_1783383400370": "Emergencias naturales y catástrofes climáticas", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "PODER EJECUTIVO NACIONAL"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 49);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Establece los lineamientos para la importación definitiva o temporaria al TERRITORIO NACIONAL, al Área Aduanera Especial y a las Zonas Francas, incluidos sus espacios aéreos y marítimos, y para la exportación, de residuos no peligrosos que hayan sido sometidos a una operación de valorización, a partir de la cual se obtengan materiales que serán utilizados como:\n1. insumo para un proceso productivo determinado, o\n2. un producto de uso directo.\nNo estará permitida la importación de aquellos residuos no peligrosos que, habiendo sido sometidos a una operación de valorización, pretendan tener como objetivo la valorización energética y/o su disposición final.\nLa exportación de residuos no peligrosos valorizados e insumos industriales valorizados no estará sujeta a prohibiciones y debe ajustarse al cumplimiento del Convenio de Basilea sobre el Control de los Movimientos Transfronterizos de los Desechos Peligrosos y su Eliminación.', 'Tener en cuenta en el caso de que importen residuos para su utilización en los procesos productivos.', 1, 'Es potestativa', 'Contancia de venta y re-uso', 'Cirion Technologies no comercializa sus residuos', 6, NULL, NULL, 90, '{"custom_1783383400370": "Residuos Valorizables: Residuos Sólidos Urbanos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "PEN", "custom_1783383763840": "Constante", "custom_1783383823178": "Valorización de residuos", "custom_1784900000002": "NO APLICABLE", "custom_1783384038540": "NO APLICABLE"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Aprueba el procedimiento para la importación de residuos no peligrosos valorizados, en los términos del artículo 6° del Decreto N° 1/25 que como Anexo I N° IF-2025-69178511-APN-SSAM#JGM forma parte integrante de la presente resolución. Los procedimientos, alcances de control y fiscalización de las mercaderías en trato, se regulan de esta forma para evitar obstruir el libre comercio, fundamentales para el desarrollo industrial nacional y la economía circular.\nAprueba el procedimiento para el tránsito por Territorio Nacional con destino a un tercer país, de los residuos alcanzados por el Decreto N° 1/25 que, como Anexo II N° IF-2025-69178160-APN-SSAM#JGM, forma parte integrante de la presente resolución.\nAprueba el procedimiento para la exportación de los residuos alcanzados por el Decreto N° 1/25, que como Anexo III N° IF-2025-69177856-APN-SSAM#JGM forma parte integrante de la presente resolución.\nAprueba el listado enunciativo de residuos no peligrosos que como Anexo IV N° IF-2025-65793694-APN-SSAM#JGM forma parte integrante de la presente resolución. El mismo podrá ser actualizado y/o modificado por la SUBSECRETARÍA DE AMBIENTE conforme a los antecedentes generados de autorizaciones emitidas y en base a la evidencia científica técnica o nuevas normas que se dicten en la materia.', 'Tener en cuenta si se necesita importar residuos como insumo, para transportar a un tercer país o bien exportarlos con autorización siempre de la autoridad ambiental de aplicación en materia de residuos.', 2, NULL, NULL, NULL, 4, NULL, NULL, 91, '{"custom_1783383400370": "Residuos Valorizables: Residuos Sólidos Urbanos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "JEFATURA DE GABINETE DE MINISTROS - SECRETARÍA DE TURISMO, AMBIENTE Y DEPORTES"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Establece el procedimiento para la solicitud y otorgamiento de la autorización para la importación de insumos industriales valorizados en origen, reglamentando el Decreto N° 1/2025, que regula la importación (definitiva o temporaria) y la exportación de residuos no peligrosos que, tras ser sometidos a una operación de valorización, pueden ser utilizados como insumos en procesos productivos o como productos de uso directo.\nSe regula un mecanismo para la solicitud y otorgamiento de autorizaciones de importación de insumos industriales valorizados en origen, que debe tramitarse antes del envío de las mercaderías. El plazo de vigencia de estas autorizaciones es de 365 días corridos y detallan las especificaciones técnicas de los materiales valorizados.\nPosee dos anexos en el primero se encuentra el procedimiento para solicitar y obtener autorizaciones de importación de insumos industriales valorizados y en el segundo anexo, fija las normas y requisitos técnicos aplicables a los insumos industriales valorizados en origen. Se especifican estándares nacionales e internacionales según el tipo de material como chatarra ferrosa; chatarra no ferrosa; rezagos de papel y cartón; vidrio roto, casco y cascote; y rezagos de plástico. También se detallan las posiciones arancelarias aplicables a cada categoría.', 'Tener en cuenta en el caso de que importen residuos para su utilización en los procesos productivos.', 1, 'Es potestativa', 'Contancia de venta y re-uso', 'Cirion Technologies no comercializa sus residuos', 6, NULL, NULL, 92, '{"custom_1783383400370": "Residuos Valorizables: Residuos Sólidos Urbanos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "PEN", "custom_1783383763840": "Constante", "custom_1783383823178": "Valorización de residuos", "custom_1784900000002": "NO APLICABLE", "custom_1783384038540": "NO APLICABLE"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Delega en la SUBSECRETARÍA DE AMBIENTE dependiente de la SECRETARÍA DE TURISMO, AMBIENTE Y DEPORTES de la VICEJEFATURA DE GABINETE DEL INTERIOR, las facultades que se detallan en el ANEXO I N° IF-2025-20820096-APN-SSAM#JGM, a saber: Designar Punto Focal Nacional para el Convenio de Rotterdam y para el Convenio de Estocolmo (Art. 4º Ley Nº 25.278), Otorgar el Consentimiento  Fundamentado Previo para los productos químicos conforme el Convenio de Rotterdam (Art. 11 Ley Nº 25.278 y art. 3  ANEXO II de la Resolución MAyDS Nº 110/21); otorgar el acuse de recibo a las notificaciones para los productos químicos conforme Art. 12 Ley Nº 25.278 del Convenio de Rotterdam; Otorgar autorización para la importación/exportación de los productos químicos detallados en el Anexo III del Convenio de Rotterdam (Art. 3º, Anexo II Resolución MAyDS Nº 110/21); realizar inspecciones, solicitar información y documentación necesaria a los fines de cumplir la Resolución MAyDS Nº 110/21 y el Convenio de Rotterdam (Ley Nº 25.278 - Art. 4º Resolución MAyDS Nº 110/21; Controlar la mercadería importada a fin de verificar el cumplimiento del Convenio de Rotterdam y de la Resolución MAyDS Nº 110/21, Ley Nº 25.278 - Art. 4º Resolución MAyDS Nº 110/21; Aprobar las exenciones de productos químicos y artículos comprendidos en el Convenio de Estocolmo (Ley Nº 26.011 - Art. 5º Resolución SGAyDS Nº 451/19); Otorgar el Consentimiento  Fundamentado Previo para los productos químicos y artículos que los contienen conforme el Convenio de Estocolmo (Ley Nº 26.011 - Art. 7º Resolución SGAyDS Nº 451/19); Otorgar autorización para la Importación/Exportación de productos químicos y artículos comprendidos en el Convenio de Estocolmo (Art. 7º Anexo V Resolución MAyDS Nº 291/20); Realizar inspecciones, solicitar información y/o documentación necesaria a los fines de cumplir con el Convenio de Estocolmo (Ley Nº 26.011 – Resolución SGAyDS Nº 451/19. Resolución MAyDS Nº 291/20), Controlar la mercadería importada a fin de verificar el cumplimiento del Convenio de Estocolmo y las Resoluciones SGAyDS N° 451/2019 y MAyDS N° 291/2020, Ley Nº 26.011 – Resolución SGAyDS Nº 451/19, Resolución MAyDS Nº 291/20; Prohibir el ingreso de sustancias reguladas por la Ley N° 24.040, cuando ello sea consecuente con los compromisos internacionales asumimos (Art. 1° Ley N° 24.040), Convalidar, en caso de corresponder, los Planes de Respuesta presentados por las provincias en el cumplimiento de las obligaciones establecidas en la Ley N° 27.520 (Art. 6° Ley N° 27.520).', 'Tener en cuanta las funciones otorgadas a la autoridad ambiental en cumplimiento de los Convenios de Estocolmo y Rotterdam.', 2, NULL, NULL, NULL, 4, NULL, NULL, 93, '{"custom_1783383400370": "Facultades delegadas a la Subsecretaría de Ambiente", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "JEFATURA DE GABINETE DE MINISTROS"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 292);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'La SECRETARÍA DE AGRICULTURA, GANADERÍA Y PESCA del MINISTERIO DE ECONOMÍA será la Autoridad de Aplicación de la Ley Nº 20.466.\nLos fertilizantes y enmiendas que se elaboren, fraccionen, vendan, importen o exporten estarán sujetos al registro a cargo del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA, organismo descentralizado en el ámbito de la SECRETARÍA DE AGRICULTURA, GANADERÍA Y PESCA del MINISTERIO DE ECONOMÍA, de conformidad con la normativa que este organismo dicte, con el fin de asegurar al usuario la bondad y calidad garantizada de estos.\nAsimismo, deberán inscribirse las personas humanas o jurídicas que fabriquen, importen, exporten, fraccionen o distribuyan fertilizantes o enmiendas. La Autoridad de Aplicación fijará las características que deberán presentar los productos a fin de dar cumplimiento al artículo 8º de la Ley Nº 20.466.', 'Tener en cuenta en el caso de que quieran inscribir una enmienda y/o fertilizante para su comercialización incluyendo a los que lo producen por compostaje.', 2, NULL, NULL, NULL, 8, NULL, NULL, 94, '{"custom_1783383400370": "Fertilizantes y Enmiendas", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "PODER EJECUTIVO NACIONAL", "custom_1783383763840": "Inscribir las enmiendas y/o fertilizantes."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Se aprueba el procedimiento simplificado de inscripción por autogestión y emisión inmediata de registro para personas humanas y jurídicas que intervengan en la elaboración, el fraccionamiento, la distribución, la importación o la exportación de productos fertilizantes, estimulantes, enmiendas, sustratos, inoculantes, acondicionadores, protectores y materias primas, así como de las plantas en las que se desarrollen dichas actividades, conforme a lo dispuesto en el Capítulo I del Manual Técnico obrante como Anexo de la presente resolución.\nInciso a) Las personas humanas y jurídicas deben completar, con carácter de Declaración Jurada, el formulario de inscripción a través de la plataforma de Trámites a Distancia (TAD) o la que se informe o la reemplace en el futuro.\nInciso b) La presentación de la Declaración Jurada habilitará automáticamente a las firmas registrantes a comercializar los productos registrados, quedando estas sujetas a fiscalización posterior por parte del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA (SENASA).\nInciso c) La detección de información falsa, incompleta o adulterada será motivo suficiente para suspender o cancelar automáticamente el registro otorgado, independientemente del resto de las medidas y sanciones administrativas que correspondan. Sin perjuicio de lo dispuesto precedentemente, el SENASA podrá formular los pedidos de subsanación que estime corresponder.', 'Tener en cuenta en el caso de que quieran inscribir una enmienda y/o fertilizante para su comercialización incluyendo a los que lo producen por compostaje.', 2, NULL, NULL, NULL, 8, NULL, NULL, 95, '{"custom_1783383400370": "Residuos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA", "custom_1783383763840": "Inscribir las enmiendas y/o fertilizantes."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Aprueba que el Sistema Integral de Gestión de Tratamientos para Embalajes de Madera (SIG-TEM) para aquellos tratamientos fitosanitarios sobre Embalajes de Madera, Maderas de Soporte y/o Acomodación utilizados en el comercio internacional de mercaderías. Resulta aplicable para todos los Centros de Aplicación de Tratamientos a Embalajes de Madera, Madera de Soporte y/o Acomodación (CATEM) habilitados por el SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA (SENASA).\nEsta norma comienza a regir dentro de noventa (90) días contados desde el 10/07/2024 (el 25/11/2024), y es un requisito para los embalajes de madera que deben cumplir los sujetos exportadores de productos.\n \nEs un certificado electrónico que deben tener los embalajes de productos a exportar que será solicitado en aduana, especialmente para la no trasmisión de plagas y asegurar el uso fitosanitarios registrados. Lo solicitan Centros de Aplicación de Tratamientos a Embalajes de Madera, Madera de Soporte y/o Acomodación (CATEM) habilitados por el SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA (SENASA) en conjunto con la empresa consumidora y solicitante del certificado también registrados en SENASA,\n \nLa Resolución N° 199/13 del SENASA regula los tratamientos fitosanitarios para los Embalajes de Madera, Maderas de Soporte y/o Acomodación utilizadas en el comercio internacional de mercaderías. En la misma se indica los tratamientos a los que deben someterse los Embalajes de Madera, Maderas de Soporte y/o Acomodación (Maderas de Estiba) que son eficaces contra la mayoría de las plagas, y la forma de identificarlos mediante marcas apropiadas reconocidas por las ORGANIZACIONES NACIONALES DE PROTECCIÓN FITOSANITARIA (ONPF) de los países importadores lo deben solicitar. Así, los tratamientos fitosanitarios y la aplicación de la marca deben ser realizados por Centros de Aplicación de Tratamiento o Armado, habilitados y fiscalizados por la ONPF del país de origen del embalaje. También la Resolución N° 199/13, reglamenta la inspección y fiscalización de dichos establecimientos por parte del SENASA, a fin de controlar el funcionamiento, el equipamiento, la trazabilidad y la correcta aplicación de los Tratamientos para Embalajes de Madera, Madera de Soporte y/o Acomodación de Mercaderías de Exportación.\nPor su parte la Resolución General Conjunta N° RESGC-2018-4297-E-AFIP-SENASA  del 24 de agosto de 2018 de la ADMINISTRACIÓN FEDERAL DE INGRESOS PÚBLICOS y SENASA aprueba el Documento de Tránsito Sanitario Vegetal Electrónico (DTV-e), sistema y manuales que serán utilizados por los sujetos alcanzados por esta norma como único documento válido para amparar el tránsito de productos, subproductos y derivados de origen vegetal, nacionales o importados, incluidos en el ámbito de aplicación de la mencionada norma. Por ello, todos los embalajes de madera tratados y certificados por la Res.  N° 15 deben ser acompañados por el correspondiente DTV-e.', 'Para exportar productos con embalajes de madera, maderas de soporte y acomodación se debe poseer un certificado electrónico de inocuidad por el tema de transparencia, evitar adulteración y corrupción crearon este sistema informático a efectos de contar con un procedimiento por el que se registran, identifican y se transmite la información de todos los tratamientos fitosanitarios realizados a los embalajes de madera en los Centros de Aplicación de Tratamientos a Embalajes de Madera, Madera de Soporte y/o Acomodación (CATEM). Este sistema permite que todos los Certificado de Tratamiento para Embalaje de Madera que antes eran manuales sean emitidos de forma digital.', 2, NULL, NULL, NULL, 4, NULL, NULL, 96, '{"custom_1783383400370": "Residuos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Se sustituye el Artículo 1° de la Resolución Nº 614 del 1 de diciembre de 2015 del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA, que quedará redactado de la siguiente manera:\n“ARTÍCULO 1°.- Embalajes de madera y maderas de soporte y acomodación, en adelante embalajes de madera. Regulación. Se reglamenta el arribo al territorio nacional de cualquier tipo de mercadería acondicionada en embalajes de madera, independientemente del tipo de madera con la que esté constituido el embalaje, con el objeto de prevenir el ingreso y dispersión de plagas. A los fines técnicos, será de aplicación la Norma Internacional para Medidas Fitosanitarias (NIMF) N° 15 en su versión vigente, junto con sus anexos.”.\nSe sustituye el Artículo 2° de la Resolución Nº 614 del 1 de diciembre de 2015 del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA, que quedará redactado de la siguiente manera:\n“ARTÍCULO 2°.- Objeto de la norma. Todo embalaje de madera que arribe o ingrese al país, debe encontrarse descortezado y libre de insectos y/o signos de actividad biológica. Dichos embalajes pueden provenir de cualquier país y contar con tratamiento y certificación - sello conforme la NIMF Nº 15.”.\nSe sustituye el artículo 4° de la Resolución Nº 614 del 1 de diciembre de 2015 del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA, que quedará redactado de la siguiente manera:\n“ARTÍCULO 4°.- Control oficial. Los inspectores del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA (SENASA), se encuentran facultados para inspeccionar y autorizar el ingreso de embalajes de madera y disponer las medidas fitosanitarias que resulten necesarias para verificar el cumplimiento de la presente resolución. El listado de inspectores autorizados estará disponible en el sitio oficial del Organismo.”.\nSe incorpora a la Resolución Nº 614 del 1 de diciembre de 2015 del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA el Anexo I (IF-2025-143717035-APN-DNPV#SENASA), Declaración Jurada de Embalajes de Madera, Madera Soporte y Acomodación, que se aprueba mediante la presente resolución.\nSe incorpora a la Resolución Nº 614 del 1 de diciembre de 2015 del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA el Anexo II (IF-2025-143718213-APN-DNPV#SENASA) - Matriz de Riesgo, que se aprueba mediante la presente resolución.\nSe incorpora a la Resolución Nº 614 del 1 de diciembre de 2015 del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA el Anexo III (IF-2025-143718517-APN-DNPV#SENASA), Declaración del depósito final de embalajes de madera para inspección posterior al ingreso, que se aprueba mediante la presente resolución.\nSe incorpora a la Resolución Nº 614 del 1 de diciembre de 2015 del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA el Anexo IV (IF-2025-143745959-APN-DNPV#SENASA), No conformidades y Medidas Aplicables.', 'Tener presente los controles que se deben realizar a los embalajes de madera que ingrese al país.', 2, NULL, NULL, NULL, 4, NULL, NULL, 97, '{"custom_1783383400370": "Residuos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Sustituye el Artículo 6° de la Resolución N° 199 del 8 de mayo de 2013 del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA (SENASA) por el siguiente:\n“ARTÍCULO 6°.- ARANCELES.\nInciso a) Autorización: el costo en concepto de la autorización para el inicio de actividad de los Centros de Aplicación de Tratamientos a Embalajes de Madera y Madera de Soporte y/o Acomodación (CATEM) y de las Fábricas de Embalajes de Maderas y Maderas de Soporte y/o Acomodación (FEM) serán abonados de acuerdo a la normativa vigente, por única vez.\nInciso b) Servicios de inspección: se abonará de acuerdo al volumen de madera certificada por el que se solicite el servicio de inspección correspondiente de acuerdo a la normativa vigente.”.', 'Tener presente cuando abonar la tasa.', 2, NULL, NULL, NULL, 4, NULL, NULL, 98, '{"custom_1783383400370": "Residuos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Aprueba el Reglamento Operativo del PROGRAMA DE GESTIÓN DE RESIDUOS SÓLIDOS URBANOS II (GIRSU II) actuante en jurisdicción de este Subsecretaaría de Ambiente de la Nación y financiado parcialmente con recursos provenientes del préstamo BID 5567/OC-AR, según figura en el Anexo.', 'Institucional y voluntaria para particulares', 2, 'De cumplimiento obligatorio conforme normas locales', 'plan de gestión de residuos en el que se deje constancia de la reduccion de residuos generados. Reciclar, reúsar o vender para su reúso', NULL, 4, 'La empresa  genera muy ppocos residuos, no ingresando en ninguna de las categorias especificados en las normas de Basura cero.', NULL, 99, '{"custom_1783383400370": "Residuos: Residuos Sólidos Urbanos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Resolución Nacional por Ley Naciona de Presupuestos Mínimos. Congreso de la Nación. Ver normas locales", "custom_1783383763840": "Constante", "custom_1783383788609": "Todos", "custom_1783383823178": "contaminación"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Aprueba la Norma Técnica de Alimentos para Animales de la REPÚBLICA ARGENTINA, como marco normativo consolidado e integral para toda la temática de alimentos destinados a la alimentación animal.\nSe mantiene el Registro de Productos destinados a la Alimentación Animal actualmente vigente, en el cual deben inscribirse todos los productos debidamente aprobados destinados a la alimentación animal que se elaboren, comercialicen, fraccionen, depositen, distribuyan, importen y/o exporten, los cuales deberán contar para ello con un establecimiento autorizado por el SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA (SENASA).', 'Cumplir con lo establecido por las Resolución n° 341/03 y modificatorias del SENASA. Resolución SENASA  Nº 594 del 26 de noviembre de 2015 a los fines de mantenerse inscriptos en el registro.', 2, NULL, NULL, NULL, 4, NULL, NULL, 100, '{"custom_1783383400370": "Norma Técnica de Alimentos para Animales", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Se aprueban las normas complementarias procedimentales para simplificar el trámite de  la Resolución RESOL-2024-1415-APNPRES#SENASA, Norma Técnica de Alimentos para Animales que establece el marco normativo consolidado e integral para toda la temática de productos destinados a la alimentación animal de la REPÚBLICA ARGENTINA, conforme lo dispuesto en la  Disposición.\nPara mejorar los controles, la nueva norma técnica aprobada contempla la aprobación y la autorización de uso y comercialización de productos destinados a la alimentación animal y, por ende, fija las condiciones, los requisitos y los procedimientos para la obtención de las autorizaciones por parte de los solicitantes.\nCertificados Vigentes: Para los productos aprobados con certificados vigentes respecto de los cuales no se haya solicitado su reinscripción con anterioridad al 03 de diciembre de 2024, se puede solicitar la reemisión del Certificado sin fecha de vencimiento cumplimentando los requisitos arancelarios vigentes al momento de requerirlo y las exigencias establecidas a dichos efectos por la Resolución SENASA N° 1415/24.', 'Tener presente que si se tiene el certificado con fecha de vencimiento se puede solicitar su reemisión abonando aranceles  cumpliendo con Resolución SENASA N° 1415/24 con los nuevos formularios.', 2, NULL, NULL, NULL, 4, NULL, NULL, 101, '{"custom_1783383400370": "Norma Técnica de Alimentos para Animales", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA - DIRECCIÓN NACIONAL DE INOCUIDAD Y CALIDAD AGROALIMENTARIA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Establece y se crea el listado de Servicios Informáticos y Sistemas de uso obligatorio en el ámbito del SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA (SENASA), para la realización de las distintas gestiones y/o trámites ante el SENASA por parte de los usuarios externos del Organismo, los cuales se detallan en el Anexo (IF-2024-132387051-APN-DTINF#SENASA), que forma parte integrante de la presente resolución.', 'Tener en cuenta los servicio informatizados para hacer los trámites.', 2, NULL, NULL, NULL, 4, NULL, NULL, 102, '{"custom_1783383400370": "Servicios Informáticos y Sistemas de uso", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "SERVICIO NACIONAL DE SANIDAD Y CALIDAD AGROALIMENTARIA"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', '1.El establecimiento  deberá separar los residuos domiciliarios reciclables (residuos secos).\nLos materiales reciclables deben estar limpios y secos. No es necesario separarlos en bolsas de diferentes colores.\n2.Coordinar con la Dirección General de Higiene Urbana dependiente del Ministerio de Ambiente, la forma en que se realizará la recolección diferencia de los residuos reciclables. Depende de la zona de ubicación del establecimiento y los volúmenes de desechos generados. Contactar cooperativas de la zona\n3.Los restantes Residuos Sólidos Urbanos deben disponerse mediante el recolector municipal. SI se entregan residuos en volquete, debera requerir a la empresa transportista un manifiesto; si se entregan a recicladores, una constancia de entrega/remito/factura.                                                                                                                                                                                                          4. Cumplir con los principios de la economía circular por Ley 6378 que crea en el ámbito de la Ciudad Autónoma de Buenos Aires el Sistema de Compensación Ecológico (SI.CO.ECO) que tiene por objeto concientizar sobre la importancia del reciclado, favorecer la separación en origen, reducir la cantidad de residuos sólidos urbanos, promover la economía circular y aminorar su impacto en el ambiente y la salud.', 'Mediante esta norma, los generadores están obligados a separar los residuos domiciliarios generados. La separación consiste en identificar los residuos pasibles de ser reciclados (residuos secos), reutilizados o reducidos a fin de que queden distribuidos en diferentes recipientes o contenedores, para su recolección diferenciada.\n\nLa recolección diferenciada se encuentra a cargo de la concesionaria del servicio de recolección.', 2, 'Contar con Plan de Gestion. SI se vendieran o donaran debe proveerse de remito/factura.Si la empresa contrata servicios de privados para la recoleccion, transporte y disposicion final debe requerirse al contratista los permisos correspondientes. Asimismo, Cirion Technologies debe tener permiso para disponer en relleno sanitario (CEAMSE).', 'La empresa separa los residuos y los gestiona con operadores autorizados. Los reciclables se entregan a…… cuentan con Plan de gestion de residuos', NULL, 4, NULL, NULL, 103, '{"custom_1783383400370": "Residuos: Residuos Sólidos Urbanos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires, LEGISLATURA DE CABA", "custom_1783383763840": "Continuo", "custom_1783383823178": "proteccion de los recursos naturales y la calidad de vida"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1501);
