INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Programa de Gestión de AVUs, Resoluciones de la Secretaría de Energía de la Nación N° 96/90 y N° 419/98 Gestión de Aceites vegetales usados Resolución 133/19 reglamenta Ley Sistema de Trazabilidad de AVUS', 'La ley establece que deben gestionarse los AVUs instando a su recuperación produciendo energía', 2, 'Obligatoria si poseen comedor y se genera aceite', 'No aplicable', '26/12/24: No es aplicable porque en el Comedor de Artigas solo se entregan  viandas de alimentos a los colaboradores', 6, NULL, NULL, 104, '{"custom_1783383400370": "Residuos de Aceites vegetales AVUs", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Continuo", "custom_1783383788609": "No aplicable", "custom_1783383823178": "Comedor", "custom_1784900000002": "No es aplicable", "custom_1783384038540": "NO APLICABLE"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, @nc2);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'Se crea el Programa de Gestión Integral de Bienes Voluminosos en Desuso (BVD), que estará a cargo de la Unidad de Coordinación General de Gestión Ambiental. \nQuedan comprendidos dentro de la definición "BVD": muebles, sanitarios, elementos de construcción, aberturas, aparatos eléctricos y electrónicos, entre otros. Los ciudadanos pueden adherirse voluntariamente comunicándose con el GCBA para el retiro de los residuos en sus domicilios.\n\na.- Si se trata de BVD a ser dispuestos por domicilios particulares, el vecino deberá comunicarse con el servicio de Atención Ciudadana del GCBA ya sea de manera telefónica a través de la línea 147, a través de su website o de otros medios habilitados a tal fin.\n\nb.- En el caso de aquellos BVD generados en comercios, oficinas, servicios, instituciones e industrias que puedan ser asimilables a los producidos en domicilios particulares, el titular o representante deberá completar el formulario que a tales efectos se disponga en la página web del GCBA u en otros canales habilitados a tal fin\nEl objeto del  Programa consiste en establecer un mecanismo que facilite una gestión diferenciada de los Bienes Voluminosos en Desuso, en adelante BVD, que sean generados en domicilios particulares o bien en comercios, oficinas, servicios o industrias, y que puedan asimilarse a los generados en los domicilios particulares, priorizando siempre que sea posible su recuperación, extensión de su vida útil y valorización.', 'Como generador en  oficinas/ servicios, que puedan ser asimilables a los producidos en domicilios particulares, el titular o representante deberá completar el formulario que a tales efectos se disponga en la página web del GCBA u en otros canales habilitados a tal fin para que los retire el GCBA y disponga, priorizando siempre que sea posible su recuperación, extensión de su vida útil y valorización.', 2, 'Solo si son generados', 'Manifiesto de transporte', 'Responsable de residuos', 4, 'Consultarlo con Real Estate', NULL, 105, '{"custom_1783383400370": "Residuos: Bienes Voluminosos en Desuso (BVD)", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "APRA del GCBA", "custom_1783383763840": "Cuando sean generados", "custom_1783383788609": "Todos", "custom_1783383823178": "ambiete", "custom_1784900000002": "responsable de residuos", "custom_1783384038540": "APLICA SOLO SI GENERAN ESCOMBROS"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1421);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Actualmente la norma no se encuentra operativa pero el  Decreto N°  705/2011 define a los RAEE como la corriente de residuos sólidos urbanos con características particulares de peligrosidad, nocividad o toxicidad, por lo cual la autoridad de aplicación de la Ley es la Agencia de Protección Ambiental (APRA), quien debe (i) publicar anualmente cifras y estadísticas sobre la recuperación y reutilización resultantes de la aplicación de la ley, y (ii) realizar tareas de capacitación y difusión acerca del uso racional y correcta gestión de los aparatos electrónicos en las dependencias del Poder Ejecutivo.', 'La norma establece que deben gestionarse los RAEE con Operador Habilitado', 2, 'Los RAEE se consideran Residuos Peligrosos y deben gestionarse como tal, con su correspondiente Manifiesto', 'Se gestionan con operador habilitado para RAEES: Silkers SA', '26/12/24: \nCertificado N° 1652 otorgado por empresa Silkers por SCRAP en Artigas realizado el 22/07/2024', 1, NULL, NULL, 106, '{"custom_1783383400370": "Residuos Eléctricos y Electrónicos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "El mismo plazo que la Inscripcion como Generador de Residuos Peligrosos: Anual", "custom_1783383788609": "Logistica\\nInfraestructura", "custom_1783383823178": "proteccion de los recursos naturales y la calidad de vida", "custom_1784900000002": "Logística"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, @nc4);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'De acuerdo a lo establecido en el articulo 6 de la ley son Sujetos Obligados los productores, importadores, distribuidores e intermediarios, por ser responsables de la puesta en el mercado de pilas de uso común dentro del ámbito de la Ciudad Autónoma de Buenos Aires.\nPara el caso de revestir alguna de las categorias mencionadas se debera:\n1 Presentar un Plan de Gestión Ambiental de Pilas en Desuso en forma individual o colectiva ante la Autoridad de Aplicación, respetando los lineamientos técnicos dispuestos por la misma Autoridad.\n2 Financiar e implementar el Plan de Gestión Ambiental de Pilas en Desuso aprobado por la Autoridad de Aplicación.\n3 Garantizar la trazabilidad de la gestión ambiental de las pilas en desuso y presentar la documentación requerida por la Autoridad de Aplicación.\n4 Implementar las mejores tecnologías disponibles para la gestión ambientalmente adecuada de las pilas en desuso.\n5 Brindar y difundir información a los consumidores, respecto de la implementación del Plan de Gestión Ambiental de Pilas en Desuso que será de acceso público.\n6 Gestionar y mantener los contenedores de disposición inicial previstos en el artículo 3°.\n7 Presentar anualmente ante la Autoridad de Aplicación un informe de gestión referido a la implementación del Plan de Gestión Ambiental de Pilas en Desuso.', 'El Articulo 1 de la Ley dispone que las pilas en desuso seran considerándolas como Residuos Sólidos Urbanos Sujetos a Manejo Especial, en concordancia con la Ley 1854 - (Texto consolidado por Ley 5666) de Gestión Integral de Residuos Sólidos Urbanos y sus normas complementarias.', 2, 'Se debera contar con la aprobacion del Plan de Gestion', 'Las pilas se disponen como residuos peligrosos con operador habilitado', 'Las pilas y/o baterías son dispuestas en el depósito de Residuos Peligrosos de Artigas', 1, '2018.07.18', NULL, 107, '{"custom_1783383400370": "Residuos. Pilas y Baterias", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Continuo", "custom_1783383823178": "proteccion de los recursos naturales"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, @nc8);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', '1.Verificar la existencia de residuos que puedan ser considerados patogénicos  en áreas de la empresa. Principalmente si existe alguna instalación que presta servicios de enfermería y/o laboratorio.\nTener presente que la reglamentación contempla la figura de “pequeño generador” (art. 20 del decreto).\n2.Si se generan residuos patogénicos, se deberá tramitar la inscripción en el Registro de Generadores, Transportistas y Operadores de Residuos Patogénicos (art. 12 y 13 de la ley).\n3.En el caso de encuadrarse como generador, observar los recaudos contemplados en el Título IV de la ley.\n4.Observar y cumplir las condiciones del almacenamiento transitorio en las instalaciones de la empresa. (art. 23 y ss. ley y decreto).\n5.ContratarTransportistas y Operadores habilitados inscriptos en el Registro.\n6.Exigir requisitos al servicio tercerizado externo, en lo que hace a las constancias de retiro y manifiestos de los residuos.', 'El régimen se aplica a la generación, manipulación, almacenamiento, recolección, transporte, tratamiento y disposición final de todos los residuos patogénicos provenientes de aquellas actividades que propendan a la atención de la salud humana y animal\nEl art. 2 del decreto enuncia una serie de desechos que se consideran residuos patogénicos\nCreación del Registro de Generadores, Transportistas y Operadores de Residuos Patogénicos.Solo encuadra la empresa si tiene un servicio medico interno. Se recomienda modifcar la categorización de la enfermería como tal', 2, 'Constancia de inscripción en el Registro de Generadores.', 'No son generadores', 'No son generadores de residuos patogénicos. No aplica', 6, NULL, NULL, 108, '{"custom_1783383400370": "Residuos. Residuos Patogénicos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Renovacion cada 2 años", "custom_1783383788609": "No aplicable", "custom_1783383823178": "proteccion de los recursos naturales", "custom_1784900000002": "No es aplicable", "custom_1783384038540": "NO APLICABLE"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 260);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, @nc7);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'De acuerdo a lo establecido en las normas aplicables, se debe verificar si se encuadra  en pequeños, medianos o grandes generadores de acuerdo a la formula polinómica prevista en el art. 21 del decreto.\nSi es generador, inscribirse en el Registro de Generadores, Operadores y Transportistas de Residuos Peligrosos mediante la presentación de la declaración jurada con los datos fijados en el art. 23 de la ley.\nObtener el Certificado de Gestión de Residuos Peligrosos mediante la inscripción al Registro.\nObservar y cumplir las condiciones de almacenamiento temporal previstas en el art. 26 del decreto. En este sentido se debe observar lo siguiente:\n1. De acuerdo a lo establecido en el inciso d) del articulo 26 de la Ley 2214,  los generadores de residuos peligrosos deberán almacenar los residuos peligrosos hasta su transporte y/o tratamiento dentro del plazo fijado por la autoridad de aplicación y en las condiciones apropiadas de seguridad que ésta establezca. \nAsimismo, la reglamentacion al articulo 26 de la Ley 2214, dada por el Decreto 2020/07 establece: Los pequeños generadores podrán almacenar los residuos peligrosos generados en su predio por el término máximo de dos (2) años. Los medianos y grandes generadores podrán almacenar los residuos peligrosos generados en su predio por el término máximo de un (1) año. Dicha autorización se concede para los dos casos, siempre y cuando el local de almacenamiento transitorio posea como mínimo una capacidad superior en un tercio (1/3) al volumen almacenado. La Autoridad de Aplicación podrá autorizar otras condiciones de almacenamiento y plazos para casos particulares.\nEl local de almacenamiento transitorio deberá contar con canaleta ciega de colección de líquidos o un sistema colector semejante aprobado por la Autoridad de Aplicación, zócalos y ángulos de tipo sanitario, pisos y paredes anticorrosivos, impermeables y fácilmente lavables, ventilación y extintores de incendio según riesgo.\nEl plan de contingencia por accidentes y derrames, para cada tipo de residuo deberá estar a disposición, y ser de fácil acceso. Los residuos de diferentes características no podrán ser mezclados. Los residuos de iguales características podrán mezclarse guardando un estricto control de las cantidades recibidas, almacenadas y despachadas, de modo que dicho extremo sea fácilmente comprobable por la autoridad competente. Los residuos que fueren almacenados para su posterior uso como insumos, serán tratados de la misma manera. La Autoridad de Aplicación podrá establecer condiciones diferenciales de almacenamiento transitorio para el pequeño generador.\nContratar  transportistas y Operadores habilitados inscriptos en el Registro..Conservar copia duplicada de todos los manifiestos de transporte.\nConservar el original de todos los certificados de tratamiento y disposición final.', 'El régimen regula la generación, manipulación, almacenamiento, transporte, tratamiento y disposición final de los residuos peligrosos en el ámbito de la CABA.\nClasificación de los generadores de residuos peligrosos en pequeños, medianos y grandes de acuerdo a la formula polinómica prevista en el art. 21 del decreto.\nCreación del Registro de Generadores, Operadores y Transportistas de Residuos Peligrosos\nObtención del Certificado de Gestión de Residuos Peligrosos\nObligación para el generador de presentar DDJJ de residuos en forma bianual.\nSe prevé la posibilidad de encuadrar a los residuos peligrosos como insumos.', 2, 'Certificado de Gestión de Residuos Peligrosos de CABA . Debe renovar inscripcion', 'Certificado de Generador de Residuos Peligrosos (Ciudad)', 'Posee número de expediente EX-2023-12856250-GCABA-APRA a nombre de CENTURY LINK S.A. y formulario de solicitud de inscripción según numero de tramite 8524.\nSe encuentra  en estado “observado”. La observación es del año 2023 según numero de informe IF-2023-16322650-GCABA-DGEVA. \nSe hizo el pedido del expediente a APRA (N° 02875241/24) de fecha 27/12/2024 para subsanar la observación', 5, NULL, NULL, 109, '{"custom_1783383400370": "Residuos. Residuos Peligrosos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Renovacion cada 2 años", "custom_1783383823178": "proteccion de los recursos naturales"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 259);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma, y especialmente lo estabelecido para pequeños generadores', 'Deroga y sustituye artículos de los decretos reglamentarios - 239-10 - 2020-07 - 1886-01 de las leyes N°3166 de regulación, control y gestión de aceites vegetales y grasas de fritura usados - AVUS - ley N° 2214 de residuos peligrosos de la Ciudad, define pequeños generadores, también artículos de la ley 154 de generación, manipulación, almacenamiento, recolección, transporte, tratamiento y disposición final de residuos patogénicos, Establece la Autoridad de Aplicación, establece una fórmula de categorización de  pequeños, medianos y grandes generadores, el certificado de gestión de residuos peligrosos, la forma de transporte de residuos peligrosos, plantas de tratamiento, registro de generadores, transportistas y operadores de AVUS. Se establecen sanciones, determinando que la constatación de inexactitudes o diferencias entre lo declarado y la cantidad o tipo de residuos peligrosos efectivamente generados y la incorrecta gestión de ellos, así como la falta de cumplimiento de lo establecido en el párrafo precedente, será causal suficiente para proceder a la clausura provisoria, total o parcial, de la actividad, hasta tanto se compruebe fehacientemente la adecuación de la gestión al presente régimen, ello sin perjuicio de las sanciones administrativas que pudieren corresponder según la infracción cometida.”. \nSe establecen modificaciones en el artículo 26 del Anexo I del Decreto Nº 2.020/07, por lo cual las bolsas deben ser color amarillas y los contenedores y rótulos de las bolsas identificados de acuerdo con el Anexo A y B de la Ley N° 2.214 (texto consolidado por Ley N° 6.588). También establece la necesidad de llevar un libro de control foliado donde conste:  Fecha de egreso de los residuos; Número de manifiesto con que se retira la carga; Empresa transportista; Empresa tratadora; Disposición final de los residuos; y, Número de constancia de tratamiento de los residuos. Para ello, deberá exigir el correspondiente Certificado de Tratamiento de los residuos según número de manifiesto. En el libro se deberá registrar también cualquier cambio en la actividad que involucre la generación de residuos peligrosos, el monitoreo de los cuerpos receptores (en caso de corresponder), inspecciones realizadas por el organismo de control, y toda otra novedad que a criterio de la autoridad de aplicación deba asentarse. \nSe establece el plazo permitido de almacenamiento de los residuos: \n* los pequeños generadores. por el término máximo de dos (2) años; y, \n* los medianos y grandes generadores, por el término máximo de un (1) año. \nLa autorización para el almacenamiento de los residuos se podrá conceder para los dos casos, siempre y cuando el local de almacenamiento transitorio posea como mínimo una capacidad superior en un tercio (1/3) al volumen almacenado. La autoridad de aplicación podrá autorizar otras condiciones de almacenamiento y plazos para casos particulares. \nEl local de almacenamiento transitorio deberá contar con canaleta ciega de colección de líquidos, o un sistema colector semejante aprobado por la autoridad de aplicación, zócalos y ángulos de tipo sanitario, pisos y paredes anticorrosivos, impermeables y fácilmente lavables, ventilación y extintores de incendio, según riesgo. El plan de contingencia por accidentes y derrames para cada tipo de residuo deberá estar a disposición, y ser de fácil acceso. \nLos residuos de diferentes características no podrán ser mezclados. Los residuos de iguales características podrán mezclarse guardando un estricto control de las cantidades recibidas, almacenadas y despachadas, de modo que dicho extremo sea fácilmente comprobable por la autoridad competente. \nLos residuos que fueran almacenados para su posterior uso como insumos, serán tratados de la misma manera. La Autoridad de aplicación podrá establecer condiciones diferenciales de almacenamiento transitorio para el pequeño generador.”. \nCualquier modificación ocurrida respecto de los datos aportados oportunamente ante "EL REGISTRO", deberá ser comunicada por medio fehaciente dentro de las cuarenta y ocho (48) horas de acaecida.”.', 'Tener en cuenta el plazo máximo a ser almacenado el residuo, las características de los depósitos, la necesidad de contar con manifiesto y certificado de tratamiento de CABA, libros de gestión a llevar, y la clasificación en pequeño, mediano y gran generador.', 2, 'Los mediano genradores pueden almacenar residuos  por dos años, mientras que los grandes solo un año', NULL, 'Se vienen gestionando los recojos de los residuos peligrosos', 1, NULL, NULL, 110, '{"custom_1783383400370": "Pequeños, medianos y grandes generadores de residuos peligrosos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Jefe de Gobierno CABA", "custom_1783383763840": "Cada dos años"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Establece que los pequeños generadores que generen residuos peligrosos correspondientes a todas las categorías de control, con excepción de Y10 e Y36, deberán realizar la inscripción a través de la Plataforma de Tramitación a Distancia (TAD) o la que en un futuro la reemplace y podrán obtener el Certificado de Gestión de Residuos Peligrosos de forma automática.\n\nLos medianos generadores que generen residuos peligrosos correspondientes a las categorías de control Y2, Y3, Y5, Y6, Y8, Y9, Y12, Y13, Y16, Y18, Y34, Y35, Y40, Y41 e Y42 y que generen menos de 100 kilogramos mensuales, deberán realizar la inscripción a través de la Plataforma de Tramitación a Distancia (TAD) o la que en un futuro la reemplace, y podrán obtener el Certificado de Gestión de Residuos Peligrosos de forma automática.\n\nAprueba el Formulario para la obtención y la renovación del Certificado de Gestión de Residuos Peligrosos en calidad de Generador, como Anexo I (IF2023-16188127-GCABA-DGEVA) y el Formulario para la renovación del Certificado de Gestión de Residuos Peligrosos en calidad de Operador, como Anexo II (IF-2023-16189002-GCABA-DGEVA).', 'Tener en cuenta la necesidad de inscribirse en el registro del GCBA y cumplir con la norma para poseer el Certificado de Gestión de Residuos Peligrosos en calidad de Generador.', 2, 'Certificado de Gestión de Residuos Peligrosos en calidad de Generador.', 'proteccion de los recursos naturales', NULL, 1, NULL, NULL, 111, '{"custom_1783383400370": "Pequeños generadores de residuos peligrosos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "SECRETARÍA DE AMBIENTE Y EL PRESIDENTE DE LA AGENCIA DE PROTECCIÓN AMBIENTAL DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES", "custom_1783383763840": "Cuando se enén a tratar", "custom_1784900000002": "No son generadores"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'Prorroga la vigencia de las inscripciones de los Transportistas inscriptos tanto en el Registro de Generadores, Operadores y Transportistas de Residuos Peligrosos conforme Ley N° 2.214, como en el Registro de Generadores, Transportistas y Operadores de Residuos Patogénicos conforme Ley N° 154, cuyo vencimiento acaeciera entre el 15 de marzo de 2023 y el 15 de mayo de 2023 al 20 de mayo de 2023 inclusive.\nLas medidas adoptadas mediante la presente, podrán ser prorrogadas, modificadas o ampliadas conforme se reglamente la Ley N° 6.616.', 'El régimen regula la generación, manipulación, almacenamiento, transporte, tratamiento y disposición final de los residuos peligrosos en el ámbito de la CABA.\nClasificación de los generadores de residuos peligrosos en pequeños, medianos y grandes de acuerdo a la formula polinómica prevista en el art. 21 del decreto.\nCreación del Registro de Generadores, Operadores y Transportistas de Residuos Peligrosos\nObtención del Certificado de Gestión de Residuos Peligrosos\nObligación para el generador de presentar DDJJ de residuos en forma bianual.\nSe prevé la posibilidad de encuadrar a los residuos peligrosos como insumos.', 2, 'Certificado de Gestión de Residuos Peligrosos de CABA . Debe renovar inscripcion', 'La empresa se encuentra inscripta en el registro de generadores de residuos peligrosos de CABA pero vencido', 'La empresa se encuentra inscripta en el registro de generadores de residuos peligrosos de CABA debe renovarlo.\n03/01/2025: Se pudo obtener a través de la plataforma de APRA la notificación que nos enviaran para subsanar las observaciones. \nF-2023-16322650-GCABA-DGEVA', 5, NULL, NULL, 112, '{"custom_1783383400370": "Residuos Peligrosos", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "DIRECTORA GENERAL DE EVALUACIÓN AMBIENTAL\\nDE LA AGENCIA DE PROTECCIÓN AMBIENTAL", "custom_1783383763840": "Renovacion cada 2 años", "custom_1783383823178": "proteccion de los recursos naturales y la calidad de vida"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', '1.Verificar si la actividad desarrollada por la empresa se debe inscribir en el RAC, de acuerdo al listado de actividades enumeradas en el Anexo IX del decreto.\n2.Para la inscripción en el RAC se debe presentar un informe de evaluación de impacto acústico (I.E.I.A.) con los lineamientos establecidos en el anexo X  y cumplimentar el trámite previsto en el art. 15 del decreto.\n3.Observar y respetar los límites máximos de emisión sonora al ambiente exterior e interior aplicables al establecimiento, de acuerdo a las correlaciones fijadas en el Anexo II (Áreas de sensibilidad acústica -art. 11 ley-  y  Distrito de Zonificación) y el Cuadro de Límites del Anexo III.   \n4. Si se realizan trabajos en la vía pública observar los recaudos previstos en el art. 27 de la ley.', 'La norma aplica a las fuentes fijas (aquellas diseñadas para operar en un lugar determinado)  o móviles (aquellas capaces de desplazarse entre distintos puntos, mediante un elemento propulsor y generan y emiten contaminantes)\nSe fijan los límites de emisión de ruidos y de vibraciones.\nLos límites de emisión acústica para fuentes fijas al ambiente exterior e interior fijados en el Anexo III del decreto, se determinan de acuerdo al distrito de zonificación aplicable al establecimiento según el Código de Planeamiento Urbano\nSe fijan los procedimientos de medición y evaluación de ruidos y vibraciones\nCreación del Registro de actividades catalogadas como potencialmente contaminantes por ruido y vibraciones (RAC)\nRequerimiento de Informe de Evaluación de Impacto Acústico\nFijación de medidas para el trabajo en la vía pública.', 2, 'Efectuar mediciones en forma anticipada a los efectos de determinar la necesidad de llevar a cabo un Informe de impacto acústico:\nEn caso de tener que llevar a cabo dicho Informe luego corresponderá la Inscripcion en el Registro creado por el articulo 17 de la Ley 1540', 'Informe de medición de Ruido Ambiental.', 'Se realizó la medición el día 6/1/25.', 5, 'El 6/01/2025 se realizaron las mediciones cuando se pusieron en funcionamianto los grupos electrógenos a los fines de dejar asentado que no resulta necesario registrarse en el Registro  creado por el articulo 17 de la Ley 1540', NULL, 113, '{"custom_1783383400370": "Ruido", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383788609": "Infraestructura Data Center\\nEHS", "custom_1783383823178": "Emisiones de ruido\\nRuido ambiental", "custom_1784900000002": "Data Center Critical Facilities\\nEHS"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 262);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, @nc10);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'Modificanse los términos del Artículo 1° de la Disposición Registro Ruidos RAC N° 7-GCABA-DEVA/22 el que quedará redactado de la siguiente manera: “Artículo 1°.- Se establecen las siguientes condiciones a cumplir, tanto por el titular del presente proyecto como por la/s contratista/s a cargo de las obras, para la Etapa de obra: 1) Cumplir con la Ley N° 1540, Decreto N° 740/07 y sus Límites Máximos Permisibles; 2) Según fuera declarado, las tareas asociadas a esta etapa deberán desarrollarse, exclusivamente, durante el periodo diurno, conforme artículo 12 del Decreto N° 740/07; 3) Contar con una programación de operaciones durante la obra que permita el trabajo con las fuentes de ruido y vibraciones, en horarios adecuados, a fin de minimizar el impacto en ambiente exterior; 4) Evitar la superposición temporal de actividades de obra potencialmente contaminantes por ruido y vibraciones; 5) Implementar jornadas de capacitación al personal de obra a fin de favorecer la concientización sobre la contaminación sonora y de vibraciones; 6) Proveer a los operarios de equipos de protección personal de acuerdo a lo estipulado por la legislación vigente; 7) Los camiones y transportes de carga deberán restringir su velocidad de circulación. Los mismos requerirán de una programación de llegada y salida en forma secuencial a fin de evitar la espera de vehículos en la vía pública, evitando situaciones de congestión vial que puedan derivar en focos de emisión de ruidos (motores y bocinas, entro otros); 8) Los camiones estacionados en el interior de la obra tendrán prohibido mantener encendido el motor mientras éstos se encuentren en espera; 9) Realizar un control periódico del estado de la maquinaria y equipos generadores de ruidos y vibraciones a los efectos de cumplir con las reglamentaciones vigentes; 10) Según fuera declarado en el Estudio de Impacto Ambiental, deberá evitarse el empleo de generadores; 11) Deberá ejecutarse una barrera modular compuesta por: Chapa galvanizada: 0,7 (mm) de espesor, Lana de Roca: 50 (mm) espesor, densidad volumétrica de 100 Kg/m 3 , Barrera acústica Auralex: 4 (mm) de espesor, densidad superficial de 5 Kg/m 2 , Placa acústica: 12 (mm) de espesor, densidad superficial de 11 Kg/m 2 , Velo acústico: 80 micrones; y para la Etapa operacional; 12) Controlar en forma continua el estado de conservación del pavimento e instrumentar acciones para su mantenimiento permanente; 13) Presentar dentro de los (60) días de haberse habilitado la totalidad de la obra, un Informe Técnico comprendiendo monitoreos de los niveles sonoros continuos equivalentes existentes en la región involucrada y en los 14 (catorce) puntos de referencia utilizados para la presentación de Informe de Evaluación de Impacto Acústico siguiendo lo establecido en el Anexo IV del Decreto N° 740/07; 14) En caso de que con la ejecución del proyecto se verificasen incrementos de significativa magnitud en el nivel de presión sonora respecto de la situación observada en la etapa preoperacional, deberán ejecutarse las medidas de mitigación pertinentes, de manera de minimizar las emisiones sonoras generadas por el flujo vehicular en la región comprometida.”', 'La norma aplica a las fuentes fijas (aquellas diseñadas para operar en un lugar determinado)  o móviles (aquellas capaces de desplazarse entre distintos puntos, mediante un elemento propulsor y generan y emiten contaminantes)\nSe fijan los límites de emisión de ruidos y de vibraciones.\nLos límites de emisión acústica para fuentes fijas al ambiente exterior e interior fijados en el Anexo III del decreto, se determinan de acuerdo al distrito de zonificación aplicable al establecimiento según el Código de Planeamiento Urbano\nSe fijan los procedimientos de medición y evaluación de ruidos y vibraciones\nCreación del Registro de actividades catalogadas como potencialmente contaminantes por ruido y vibraciones (RAC)\nRequerimiento de Informe de Evaluación de Impacto Acústico\nFijación de medidas para el trabajo en la vía pública.', 2, 'Efectuar mediciones en forma anticipada a los efectos de determinar la necesidad de llevar a cabo un Informe de impacto acústico:\nEn caso de tener que llevar a cabo dicho Informe luego correspondera la Inscripcion en el Registro creado por el articulo 17 de la Ley 1540', 'No se ha realizado estudio de ruido ambiental producido por generadores en funcionamiento', 'En proceso', 5, 'El 6/01/2025 se realizaron las mediciones cuando se pusieron en funcionamianto los grupos electrógenos a los fines de dejar asentado que no resulta necesario registrarse en el Registro  creado por el articulo 17 de la Ley 1540', NULL, 114, '{"custom_1783383400370": "Ruido", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Directora General de Evaluación Ambiental del APRA", "custom_1783383788609": "calidad de aire", "custom_1784900000002": "EHS"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'En el supuesto que la actividad desarrollada por la empresa, se encuentre categorizada como de impacto ambiental Con Relevante Efecto (Ley 123), se deberá contratar alguna de las pólizas de seguro ambiental habilitadas por la Superintendencia de Seguros de la Nación.Se realizo el Calculo de Nivel de complejidad ambiental y arroja el numero de 20 por lo que  contrataron seguro ambiental. Este calculo de NCA debe acompañar las presentaciones de renovacion o gestion de permisos. Se debe presentar ante Secretaria de Finanzas y APRA ante cada vencimiento', 'Estas Resoluciones disponen la obligatoriedad de acreditar la contratación del seguro ambiental previsto por el art. 22 de la Ley Nacional N° 25.675 para las actividades categorizadas como de impacto ambiental Con Relevante Efecto en los términos de la Ley 123 de EIA. Renovacion de tramites y permisos se requiere seguro.Establece que a efectos de obtener, modificar o renovar los respectivos permisos e inscripciones que otorga la AGENCIA DE PROTECCIÓN AMBIENTAL, los interesados deberán acompañar, previamente, con carácter de declaración jurada, el cálculo del Nivel de Complejidad Ambiental (NCA) de su establecimiento  suscripto por un profesional inscripto en el Registro de Evaluación Ambiental de la Ley N° 123. Se contrato seguro.', 2, 'Seguro Ambiental', 'El último NCA registrado es de diciembre 2024. El valor fue de 16, por tanto corresponde contratar seguro ambiental , pero con la certificación ISO 14001 se encontrarían exceptuados ya que quedarian en 12 puntos', 'En proceso', 5, 'Se procederá a enviar el formulario al broker para contratar el seguro ambiental EN EL CASO DE QUE NO SE RE-CERTIFIQUE.', NULL, 115, '{"custom_1783383400370": "Seguro Ambiental", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Agencia de Proteccion Ambiental", "custom_1783383763840": "Anual", "custom_1783383788609": "TODOS", "custom_1783383823178": "Seguro ambiental\\nNivel de complejidad ambiental", "custom_1784900000002": "EHS", "custom_1783384038540": "SE ENCUENTRAN EN PROCESO DE RECERTIFICACIÓN"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Prohibición de producción y comercialización de las sustancias denominadas PCBs y de los aparatos que la contengan.\nDefinición de PCBs\nObligación de reemplazar los productos, equipos, instalaciones o sistemas actualmente en uso que contengan PCBs en cualquiera de sus formas o combinaciones para el año 2010.\nObligaciones para los generadores o poseedores de PCBs.\nCreación del Registro de Generadores o poseedores de PCBs. Colocar carteleria que asi lo acredite. Libre de PCB es menos de 50ppm', 'De acuerdo a esta normativa, los generadores de Energía y los Transformadores deberían estar libres de PCBs para el año 2010.\nSi se posee algún aparato que contenga  PCBs, de acuerdo a la definición del Anexo I del Decreto 217/03, se deberá observar  las obligaciones fijadas en este régimen.', 2, 'No se otorga un permiso determinado sino que debem retirarse aquellos equipos que contengan PCB.', 'Los transformadores son libres de PCB, secos. Deben colocar carteleria que asi lo indique', 'Los transformadores cuentan con cartel "libre de PCB"', 1, NULL, NULL, 116, '{"custom_1783383400370": "Sustncias Controladas: PCBs", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Continuo", "custom_1783383788609": "evitar el daño ambiental", "custom_1783383823178": "PCB\\nTransformadores", "custom_1784900000002": "EHS"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 263);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, @nc9);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Obligaciones: \n1 Proveer agua apta de consumo humano (si se consume agua de bidon solicitar analisis de laboratorio al proveedor) \n2. Contratar laboratorio autorizado para realizar los monitoreos del agua de consumo', 'Esta norma establece la obligatoriedad del Certificado de Limpieza y Desinfeccion de Tanqes de Agua Potable', 2, 'Certificado de Limpieza y Desinfección de Tanques de Agua Potable (CLDTAP)', 'Estudio físico químico y microbiológico del agua para consumo humano', '26/12/24:\nSe exhibe Estudio físico y microbiológico del agua realizado en Artigas el 28/11/24.\nResultados satisfactorios', 1, 'Laboratorio industrial Borex', '2025-11-28', 117, '{"custom_1783383400370": "Control de Agua de Consumo", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Agencia de Proteccion Ambiental", "custom_1783383763840": "Semestral el Bactereologico y anual el fisicoquimico. La limpieza de tanques es semestral", "custom_1783383788609": "salud", "custom_1783383823178": "La empresa realiza la limpieza de los tanques de agua en tiempo y forma y analiza el agua de consumo tanto de bidones como la de red cada 6 meses", "custom_1784900000002": "Real Estate", "custom_1783384038540": "#REF!"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Deben llevarse a cabo desinfecciones y desratizaciones mediante empresas registradas y con Director Tecnico habilitado por APRA.\nLa Resolucion 452/18 ha derogado la Disposicion 710-14 que en su articulo 1 establecida: la obligatoriedad para consorcistas, representantes y/o administradores del Consorcio de Propiedad Horizontal, establecimientos públicos y privados, de contar con el Certificado de Desinfección y Desinfestación (CEDyT) en forma mensual,', 'Estas normas establecen la obligatoriedad de llevar a cabo Desinfecciones y Desratizaciones en todos los inmuebles donde se leven a cabo las actividades. Para tal fin se debe  contratar servicio externo que entregue certificado y oblea', 2, 'Contar con el Certificado de Desinfección y Desinfestación (CEDyT)', 'Certificado de Saneamiento y control de plagas', '26/12/24:\nSe cuentan con Certificados de desinfección y control de plagas de OSPE. \nEl último realizado en noviembre 2024', 1, 'Proveedor OSPE', '2024-12-31', 118, '{"custom_1783383400370": "Desinfección y Desratización: Control de Plagas", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Mensual.", "custom_1783383788609": "Real Estate\\nEHS", "custom_1783383823178": "Se contrata servicio externo que realiza mensualmente la desinfeccion", "custom_1784900000002": "Real Estate", "custom_1783384038540": "#REF!"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Se estabecen como obligaciones: 1 Contratar a una empresa habilitada a fin de realizar la limpieza de los tanques de agua, en forma trimestral. 2 Requerir la entrega del Certificado de Limpieza y Desinfección de Tanques de Agua Potable (CLDTAP)\nLa Resolucion 452/18 ha derogado la Disposicion 710-14 que en su articulo 1 establecida: la obligatoriedad para consorcistas, representantes y/o administradores del Consorcio de Propiedad Horizontal, establecimientos públicos y privados, de contar con el Certificado de Desinfección y Desinfestación (CEDyT) en forma mensual,', 'Estas normas definen la obligatoriedad de la limpieza semestral de los tanques de agua destinada al consumo humano, en aquellos inmuebles que consten de más de una unidad de vivienda.\nSe establece el uso obligatorio del Certificado de Limpieza y Desinfección de Tanques de Agua Potable (CLDTAP).\nFinalmente se establecen las multas por no cumplir con la Desinfeccion de Tanques de Agua y los Analisis Bacteriologicos Fisico Quimicos del Agua de Tanques. Finalmente establece los deberes del Consorcio o Administracion de los edificios de Propiedad Horizontal en relacion a los tanques de agua', 2, 'Certificado de Limpieza y Desinfección de Tanques de Agua Potable (CLDTAP)', 'Se realiza en forma semestral', '26/12/2024:\nSe exhibe CERTIFICADO\nLIMPIEZA Y DESINFECCION DE TANQUES DE AGUA de Artigas realizado el 08/11/2024.', 1, 'Proveedor OSPE', '2025-05-08', 119, '{"custom_1783383400370": "Limpieza de Tanques de Agua", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Semestral.", "custom_1783383788609": "salud", "custom_1783383823178": "Se realiza limpieza de tanques de agua", "custom_1784900000002": "Real Estate", "custom_1783384038540": "#REF!"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, @nc13);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo el articulado', 'Mediante estas normas se establece todo el sistema de Regulacion para Sistemas contra Incendios. Entre otras cosas se dispone:\n-Aprobación de la incorporación de códigos de respuesta rápida "QR" en las tarjetas identificatorias de extintores (matafuegos),  Verificar que los mismos poseen las tarjetas con su correspondiente codigo\n-Se establece  el procedimiento para el mantenimiento de las Instalaciones Fijas Contra Incendios, los lineamientos para el desarrollo de dichas tareas, y establecer la obligatoriedad del uso del Libro Digital de Inspección.\n- Se Establéce como plazo de vencimiento el 31 de Marzo de cada año, para el pago de la tasa referida en la Ley Tarifaria vigente, en relación al servicio de registro de mantenimiento de instalaciones fijas contra incendio.\n- Creación del Sistema de Autoprotección. Planes de Evacuación y Simulacro. Control de Riesgos. Creaci{on del Registro de Profesionales para la elaboración y puesta a prueba de los Sistemas de Autoprotección, en el que se inscribirán los sujetos que elaboren y presenten ante la Autoridad de Aplicación, dichos sistemas.\n-Clasificación de Edificios, Establecimientos y Predios según Criterios de Riesgo\n-Creacion del Registro de Fabricantes, Reparadores y Recargadores de Extintores (matafuegos) y equipos contra incendios.\n-Las instalaciones fijas contra incendio (IFCI) deben ser fabricadas, reparadas, instaladas y mantenidas por personas físicas y/o jurídicas inscriptas en el "Registro de Fabricantes, Reparadores e Instaladores de Instalaciones Fijas contra Incendios"\n-Establece que todas las actuaciones que se hayan iniciado solicitando la aprobación de un Plan de Evacuación y Simulacro en los términos de la Ley 1346, en el período comprendido entre los años 2007 y mediados de 2013, al  momento de su vencimiento anual, si estuvieses circulando en formato papel, deberá iniciarse nuevamente en formato digital, como expediente electrónico.', 'Este conjunto de normas establecen todo el sistema de Autoproteccion contra Incendio con que deben contar todos los edificios situados en la Ciudad Autónoma de Buenos Aires', 2, 'Aprobacion del Sistema de Autoproteccion en general por la Autoridad de Aplicación', 'Resolución CABA sobre Sistema de Autoprotección', 'Con fecha 23/12/2024 se aprobó el Sistema de Autoprotección de Artigas. \nLas nuevas fechas de simulacro:\n1° Simulacro: 09/04/2025, 10:00hs.\n2° Simulacro: 08/10/2025, 15:00hs.', 1, NULL, '2026-12-22', 120, '{"custom_1783383400370": "Control de Incendio", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Las Disposiciones de Aprobación de los Sistemas de Autoprotección según la Ley N° 5.920 tendrán una validez de dos (2) años a partir de la fecha de su aprobación, siempre que no existan modificaciones en el sistema presentado y cumplan con las exigencias anuales establecidas en la Disposición Reglamentaria 1358/18.\\nLa vigencia de la recarga de los extintores (matafuegos) es de un (1) año.\\nSeguidamente al procedimiento de recarga se debe realizar una única revisión y/o control completo del estado del matafuego, no pudiendo ser este último requerido por las empresas como servicio accesorio y/o condición de contratación del servicio principal.\\"", "custom_1783383788609": "EHS", "custom_1783383823178": "Sistema de Autoprotección\\nControl de Incendios\\nCódigo QR", "custom_1784900000002": "EHS Argentina\\nInfraestructura", "custom_1783384038540": "#REF!"}');
