INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Artículo 7', 'El artículo 7 de esta norma expresamente dispone: Deróganse los artículos 2°, 3°, 5°, 6° y 7° de la Resolución N°\n347/APRA/15 por los que se crearon el Registro de Auditores del Sistema de Almacenamiento Subterráneo de Hidrocarburos (SASH) y el Registro de Auditorías del Sistema de Almacenamiento Subterráneo de Hidrocarburos (SASH) y normativa complementaria y reglamentaria.                                                                                                                                                    Aprueba procedimientos y formularios - evaluación de sitios contaminados-hidrocarburos y recomposición ambiental - plan de tareas de manejo de contingencias - sistema de almacenamiento subterráneo de hidrocarburos-tanques cañerías y accesorios-SASH - almacenamiento aéreo - estudio de información ambiental - pautas adicionales de evaluación - plan de recomposición ambiental-PRA - recomposición ambiental - contaminación predio público o privado - constancia de recomposición ambiental emitida por DGET - faculta a dirección general de evaluación técnica - dirección general de control - constancia no necesidad de recomposición ambiental-CNNRA - Agencia de Protección Ambiental', 'En el caso de poseer tanques de combustibles se establecen pautas adicionales de evaluación - plan de recomposición ambiental-PRA - recomposición ambiental - contaminación predio público o privado - constancia de recomposición ambiental emitida por DGET - faculta a dirección general de evaluación técnica - dirección general de control - constancia no necesidad de recomposición ambiental-CNNRA - Agencia de Protección Ambiental', 2, 'Obligatoria', 'constancia de recomposición ambiental emitida por DGET - faculta a dirección general de evaluación técnica - dirección general de control - constancia no necesidad de recomposición ambiental-CNNRA - Agencia de Protección Ambiental', NULL, 4, 'Estudio de pasivo de suelo\nEstudio hidrogeológico', NULL, 121, '{"custom_1783383400370": "Tanques Aéreos  Y subterraneos de Almacenamiento de Combustibles (TAAH) y SASH", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Si existe contamianción", "custom_1783383788609": "proteccion de los recursos naturales", "custom_1783383823178": "Se realiza la auditoria de tanques con auditores habilitados", "custom_1784900000002": "Responsable de medio ambiente/residuos"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1984);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'TODA', 'Aprueba la baja del trámite “Registro de Tanques del Sistema de Almacenamiento Subterráneo de Hidrocarburos (SASH)” en el Inventario Único de Trámites (IUT).', 'tener en cuenta que los tanques subterráneos no se registran más en CABA', 2, 'Obligatoria', 'constancia de recomposición ambiental emitida por DGET - faculta a dirección general de evaluación técnica - dirección general de control - constancia no necesidad de recomposición ambiental-CNNRA - Agencia de Protección Ambiental', NULL, 4, 'Demostrar si cuando se extrae un tanque no se dejó contaminación.', NULL, 122, '{"custom_1783383400370": "Tanques Aéreos  Y subterraneos de Almacenamiento de Combustibles (TAAH) y SASH", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "SECRETARIA DE AMBIENTE, EL PRESIDENTE DE LA AGENCIA DE PROTECCIÓN AMBIENTAL Y EL SECRETARIO DE INNOVACIÓN Y TRANSFORMACIÓN DIGITAL", "custom_1783383763840": "Si existe contamianción", "custom_1783383788609": "proteccion de los recursos naturales", "custom_1783383823178": "Se realiza la auditoria de tanques con auditores habilitados", "custom_1784900000002": "Responsable de medio ambiente/residuos"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda', 'SITIOS CONTAMINADOS reemplaza y deroga las Resoluciones APRA 326/13, APRA 565/14 y APRA 566 APRA/15. La Res. APRA 227/23 aprueba: A) el “Procedimiento para la Evaluación de Sitios Potencialmente Contaminados y su Recomposición Ambiental”; B) el “Procedimiento para Extracción del Sistema de Almacenamiento Subterráneo de Hidrocarburos (Tanques, Cañerías y Accesorios) - SASH, o para la Extracción del Sistema de Almacenamiento Aéreo de Hidrocarburos (Tanques, Cañerías y Accesorios) - SAAH” y “Procedimiento para la excepción de extracción del Sistema de Almacenamiento Subterráneo de Hidrocarburos (Tanques, Cañerías y Accesorios) - SASH, o para la Extracción del Sistema de Almacenamiento Aéreo de Hidrocarburos (Tanques, Cañerías y Accesorios) - SAAH”; C) el “Alcance y Contenido del Estudio Hidrogeológico” y “Niveles Guía de Calidad Ambiental”; D) el “Procedimiento del Análisis de Riesgo a la Salud Humana (RBCA)”; E) el “Contenido del Plan de Recomposición Ambiental (PRA)”; F) el “Procedimiento de Inhabilitación Ambiental de Sitios Contaminados”; y G) el “Formulario de trámite de Sitio Potencialmente Contaminado” y el “Formulario de trámite de Recomposición Ambiental”.', 'Tener en cuenta en el caso de que sea necesario remover un tanque y remediar', 2, 'Obligatoria', 'constancia de recomposición ambiental emitida por DGET - faculta a dirección general de evaluación técnica - dirección general de control - constancia no necesidad de recomposición ambiental-CNNRA - Agencia de Protección Ambiental', NULL, 4, NULL, NULL, 123, '{"custom_1783383400370": "Tanques Aéreos  Y subterraneos de Almacenamiento de Combustibles (TAAH) y SASH", "custom_1784900000001": "CIUDAD AUTONOMA DE BUENOS AIRES (CABA)", "custom_1783383445340": "SECRETARIA DE AMBIENTE, EL PRESIDENTE DE LA AGENCIA DE PROTECCIÓN AMBIENTAL Y EL SECRETARIO DE INNOVACIÓN Y TRANSFORMACIÓN DIGITAL", "custom_1783383763840": "Si existe contamianción", "custom_1783383788609": "proteccion de los recursos naturales", "custom_1783383823178": "Se realiza la auditoria de tanques con auditores habilitados", "custom_1784900000002": "Responsable de medio ambiente/residuos"}');
