INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`obs_estado_cumplimiento`,`vencimiento_plazo`,`orden`,`datos_dinamicos`) VALUES
(@m, 'N/A', 'Cirion Corporativo exige cumplimiento del proyecto ESG que recoge las fuentes de emisiones de Carbono de las actividades operativas de Cirion', 'Cirion Technologies Argentina debe  recolectar todos los años los datos de emisines de efecto invernadero y que luego son enviadas a Inglaterra para su análisis:\n- Combustible usado por grupos electrógenos.\n- Vuelos de colaboradores de Cirion Technologies Argentina.\n- Pérdida de Gases refrigerantes de los equipos de aire acondicionado.', 2, 'Acción', 'Planillas de levantamiento de información', 'Se viene recolectando la data del período 2023', 5, NULL, NULL, 0, '{"custom_1783383400370": "BUENAS PRÁCTICAS AMBIENTALES", "custom_1783383445340": "Cirion Corporativo", "custom_1783383763840": "Todos los meses de marzo", "custom_1783383788609": "Field Operations/Administración", "custom_1783383823178": "Gases de efecto invernadero", "custom_1784900000002": "Manager Field Operatrions\\nManager Accountig"}');
