(3, 2, '2026-06-29', 1, 1, 1, '[{"id": "norma_nivel_jur", "label": "Nivel Jurisdiccional (Norma)", "custom": false}, {"id": "custom_1783383400370", "label": "Categoría", "custom": true}, {"id": "custom_1783383445340", "label": "AUTORIDAD DE APLICACIÓN", "custom": true}, {"id": "norma_emisor", "label": "Emisor Norma", "custom": false}, {"id": "normas", "label": "Normativas (Tipo, Nro, Año)", "custom": false}, {"id": "norma_sintesis", "label": "Síntesis y Categorías", "custom": false}, {"id": "articulos_aplicables", "label": "Artículos Aplicables", "custom": false}, {"id": "resumen_legal", "label": "Obligación / Resumen Legal", "custom": false}, {"id": "interpretacion_aplicacion", "label": "Interpretación Aplicación", "custom": false}, {"id": "id_tipo_modalidad", "label": "Modalidad", "custom": false}, {"id": "obs_modalidad", "label": "Modalidad (detalle)", "custom": false}, {"id": "custom_1783383763840", "label": "PERIODICIDAD / PLAZO", "custom": true}, {"id": "custom_1783383788609", "label": "PROCESO AL QUE APLICA", "custom": true}, {"id": "custom_1783383823178", "label": "PELIGRO / ASPECTO", "custom": true}, {"id": "evidencia_cumplimiento", "label": "Requerimiento Evidencia", "custom": false}, {"id": "custom_1784900000002", "label": "Responsable(s) de Cumplimiento", "custom": true}, {"id": "verificacion_cumplimiento", "label": "Notas de Verificación", "custom": false}, {"id": "estado", "label": "Estado Cumplimiento", "custom": false}]', 2, 1, 'normas', '[]');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Arts. 1, 2, 3, 4, 5, 8, 9, 10, 12', 'Establece las condiciones de higiene y seguridad en el trabajo a fines de proteger la vida, preservar y mantener la integridad psicofísica de los trabajadores, prevenir, reducir o eliminar los riesgos de los ambientes de trabajo y estimular y desarrollar una actitud positiva respecto de la prevención de los accidentes o enfermedades derivadas del trabajo.\nCuando el trabajo se ejecute por terceros en establecimientos o puestos de trabajo del dador principal y/o con maquinarias o elementos suministrados por éste, el dador será solidariamente responsable del cumplimiento de la ley. \nEmpleador debe adoptar y poner en práctica medidas de seguridad e higiene adecuadas, especialmente en lo relativo a: \na) la construcción, instalación y equipamiento de edificios y lugares de trabajo en condiciones ambientales y sanitarias adecuadas,  \nb) la colocación y mantenimiento de resguardos y protectores de máquinas e instalaciones, \nc) el suministro y mantenimiento de equipos de protección personal,\nd) las operaciones y procesos de trabajo.\ne) disponer el examen preocupacional y revisación periódica del personal,\nf) mantener maquinaria e instalaciones en buen estado de funcionamiento,\ng) instalar equipos necesarios para la renovación del aire y eliminación de gases, vapores y demás impurezas producidas en el curso del trabajo,\nh) mantener en buen estado de conservación, uso y funcionamiento las instalaciones eléctricas y de servicio de agua potable,\ni) evitar acumulación de desechos y residuos que constituyan un riesgo para la salud,\nj) eliminar o reducir los ruidos y vibraciones perjudiciales para la salud de los trabajadores,\nk) instalar equipos necesarios para afrontar riesgos en caso de incendio u otro siniestro,\nl) depositar las sustancias peligrosas de manera segura,\nm) disponer de medios adecuados para la inmediata prestación de servicios de emergencia y primeros auxilios,\nn) colocar en lugares visibles, avisos o carteles que indiquen medidas de higiene y seguridad y adviertan sobre la peligrosidad de maquinarias e instalaciones,\nñ) promover capacitación del personal en la materia, especialmente en lo relativo a prevención de riesgos según tareas encomendadas, y\no)  denunciar accidentes y enfermedades de trabajo.\nAsimismo, empleador debe cumplir con las condiciones de higiene en los ambientes laborales que establece el decreto reglamentario (carga térmica, contaminación ambiental, radiaciones, ventilación, iluminación, ruidos, vibraciones, etc). \nDeben observarse las normas sobre instalaciones eléctricas, maquinarias, herramientas, ascensores y montacargas, protección contra incendios, EPP, capacitación del personal, sustancias químicas y estrés térmico, entre otras.\nTrabajador debe:\na) Cumplir con las normas de higiene y seguridad y las recomendaciones que se les formulen sobre el uso y cuidado del equipo de protección personal (EPP) y de las maquinarias, operaciones y procesos de trabajo,\nb) Someterse a los exámenes médicos y cumplir con prescripciones e indicaciones que le formulen,\nc) Cuidar los carteles sobre higiene y seguridad y observar sus indicaciones,\nd) Colaborar en la organización de programas de formación y educación en la materia, y asistir a los cursos que se dictaren.', 'Trabajadores y empleador deberán cumplir con las obligaciones contenidas en la Ley, relativas a las condiciones de higiene y seguridad en el trabajo, a fin de evitar riesgos a la salud y la integridad psicofísica.', 2, 'Acción', 'Se observan cumplimientos, gestión y documentación, pero  también se observan  desvíos que se detallan en informe adjunto.', NULL, 4, 0, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Salud y Seguridad", "custom_1784900000002": "El empleador es responsable en virtud del art 3º del Dec 351/79 de la ley 19587, que establece que las firmas comerciales, sociedades, empresas o personas de existencia visible o ideal que adquieran, exploten o administren un establecimiento en funcionamiento  o en condiciones de funcionar, asumen todas las responsabilidades a la ley 19587 y sus reglamentos."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 24);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, NULL, 'La Res Conj. 22/2021:\nSustituye el Artículo 982 del Código Alimentario Argentino que quedará redactado de la siguiente manera: “Artículo 982: Con las denominaciones de Agua potable de suministro público y Agua potable de uso domiciliario, se entiende la que es apta para la alimentación y uso doméstico: no deberá contener substancias o cuerpos extraños de origen biológico, orgánico, inorgánico o radiactivo en tenores tales que la hagan peligrosa para la salud. \nDeberá presentar sabor agradable y ser prácticamente incolora, inodora, límpida y transparente. \nEl agua potable de uso domiciliario es el agua proveniente de un suministro público, de un pozo o de otra fuente, ubicada en los reservorios o depósitos domiciliarios.\nEstablece los límites que el agua potable deberá cumplir con las características físicas, químicas y criterios microbiológicos.\nLa autoridad sanitaria competente podrá admitir valores distintos si la composición normal del agua de la zona y la imposibilidad de aplicar tecnologías de corrección lo hicieran necesario.\nEn aquellas regiones del país con suelos de alto contenido de arsénico, la autoridad sanitaria competente podrá admitir valores mayores a 0,01 mg/l con un límite máximo de 0,05 mg/l cuando la composición normal del agua de la zona y la imposibilidad de aplicar tecnologías de corrección lo hicieran necesario; ello hasta contar con los resultados del estudio “Hidroarsenicismo y Saneamiento Básico en la República Argentina – Estudios básicos para el establecimiento de criterios y prioridades sanitarias en cobertura y calidad de aguas”, cuyos términos fueron elaborados por la Coordinación de Políticas Socioambientales de la entonces SECRETARÍA DE GOBIERNO DE SALUD del entonces MINISTERIO DE SALUD Y DESARROLLO SOCIAL y de la ex -SECRETARÍA DE INFRAESTRUCTURA Y POLÍTICA HÍDRICA del entonces MINISTERIO DEL INTERIOR, OBRAS PÚBLICAS Y VIVIENDA. La Comisión Nacional de Alimentos deberá recomendar el límite máximo admitido para dichas regiones del país en base a los estudios antes referidos.', 'Las que tienen realizar estudio bacteriológico semestral y fisicoquímico anual especialmente en baños (incluyendo duchas), cocina y dispensers.', 2, NULL, NULL, NULL, 4, 1, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "SECRETARÍA DE CALIDAD EN SALUD Y SECRETARÍA DE ALIMENTOS, BIOECONOMÍA Y DESARROLLO REGIONAL"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 450);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, NULL, 'Se rectifica el Artículo 1º de la Resolución Conjunta N° RESFC-2019-12-APN-SRYGS#MSYDS de\nfecha 10 de abril de 2019 de la SECRETARÍA DE REGULACIÓN Y GESTIÓN SANITARIA y la SECRETARÍA DE ALIMENTOS Y BIOECONOMÍA que quedará redactado de la siguiente forma: ARTÍCULO 1º.- Sustitúyese el Artículo 21 del Código Alimentario Argentino, el que quedará redactado de la siguiente manera: “Artículo 21:\n1. Toda persona que realice actividades por la cual esté o pudiera estar en contacto con alimentos, en\nestablecimientos donde se elaboren, fraccionen, almacenen, transporten, comercialicen y/o enajenen alimentos, o sus materias primas, debe estar provista de un CARNET DE MANIPULADOR DE ALIMENTOS, expedido por la autoridad sanitaria competente, con validez en todo el territorio nacional.\n2. Cada jurisdicción implementará el sistema de otorgamiento del CARNET DE MANIPULADOR de conformidad con lo prescrito en el presente artículo.\n3. Es responsabilidad del empleador garantizar las condiciones necesarias para que el manipulador de alimentos cumplimente en forma adecuada la obtención del CARNET.\nEl único requisito para la obtención del CARNET, será cursar y aprobar un Curso de Capacitación en Manipulación Segura de Alimentos, el cual tendrá las siguientes características:\n- Capacitadores: podrán pertenecer a instituciones públicas (de los niveles municipales, provinciales y nacionales) o al sector privado, y deberán contar con título terciario o universitario que acredite formación en manipulación de alimentos, o con experiencia comprobable en inocuidad alimentaria.\nEn todos los casos, deben ser reconocidos por la autoridad sanitaria jurisdiccional competente, quien podrá supervisar su actividad cuando lo considere necesario.\n- Modalidad: podrá cursarse de forma presencial o virtual.\n- Carga horaria: tendrá una duración mínima de 7 horas reloj.\n- Metodología y contenidos: serán implementados en forma teórico-práctica y deberán ajustarse a los contenidos mínimos incluidos en el Anexo I, que registrado con el Nº IF-2019-41457293-APN-DERA#ANMAT forma parte integrante del presente artículo. Cada jurisdicción podrá adaptar/complementar los contenidos mínimos en función de la necesidad local y el público destinatario.\n- Evaluación: se realizará en forma presencial y a cargo de un capacitador.\n- Exención: toda persona con título terciario o universitario que acredite formación en manipulación de alimentos podrá ser eximida de realizar el curso de capacitación, debiendo aprobar la evaluación.\nEl CARNET tendrá vigencia por el plazo de 3 años. Para su renovación será obligatorio rendir un examen de conocimientos, quedando a criterio de la autoridad sanitaria solicitar la realización de un curso de actualización de contenidos.\nSi el examen no es aprobado en dos oportunidades consecutivas, la persona deberá realizar nuevamente el Curso de Capacitación en Manipulación Segura de Alimentos.\n4. Las autoridades sanitarias llevarán en su jurisdicción el registro de capacitadores reconocidos y el registro de manipuladores de alimentos capacitados, que pondrán a disposición para su acceso público.\n5. El CARNET de Manipulador es personal e intransferible. El CARNET deberá tenerse en depósito en la administración del establecimiento para su exhibición a las autoridades sanitarias, cuando éstas así lo soliciten, con excepción de los manipuladores que deberán llevarlas consigo en caso de que trabajen en más de un establecimiento y/o realicen tareas fuera de éste.\nEn caso de robo, deterioro o pérdida del CARNET, se deberá solicitar un duplicado.\n6. El CARNET de Manipulador deberá contener los siguientes datos:\n- Lugar y fecha de emisión.\n- Datos filiatorios del titular: nombre, tipo y número de documento, domicilio actualizado.\n- Fotografía tamaño carnet actualizada. Fecha de vencimiento.\n- Firma y sello de la autoridad que lo expida.\n7. Las autoridades sanitarias provinciales podrán solicitar a los manipuladores de alimentos los análisis de salud que consideren necesarios.', 'Toda persona que realice actividades por la cual esté o pudiera estar en contacto con alimentos, en establecimientos donde se elaboren, fraccionen, almacenen, transporten, comercialicen y/o enajenen alimentos, o sus materias primas, debe estar provista de un CARNET DE MANIPULADOR DE ALIMENTOS, expedido por la autoridad sanitaria competente, con validez en todo el territorio nacional, debiendo obtener también la libreta sanitaria o acreditar análisis de salud conforme la jurisdicción local lo requiera. Validez tres años.', 2, NULL, NULL, NULL, 4, 2, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "SECRETARÍA DE REGULACIÓN Y GESTIÓN SANITARIA Y SECRETARÍA DE ALIMENTOS Y BIOECONOMÍA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 530);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, NULL, 'Sustitúyese el Artículo 16 del Código Alimentario Argentino, el que quedará redactado de la siguiente manera: “Artículo 16: El titular de la autorización del establecimiento debe garantizar:\n1. Que se mantengan las condiciones higiénico-sanitarias y legales determinadas por la normativa vigente y establecidas en la autorización sanitaria correspondiente en el establecimiento.\n2. Que los productos elaborados o puestos en circulación cumplan con las condiciones higiénico- sanitarias y legales determinadas por la normativa vigente y establecidas en la autorización sanitaria correspondiente.\n3. Los recursos para que se implementen las medidas necesarias en el establecimiento para la obtención de productos que se ajusten a la autorización sanitaria correspondiente.\n4. Que el establecimiento cuente con la documentación correspondiente que avale la trazabilidad de los productos autorizados, desde la recepción de las materias primas hasta la comercialización del producto final.\n5. Que, cuando así lo requiera la normativa vigente, el establecimiento cuente con la Dirección Técnica dispuesta en el Artículo 17 del Código y facilitarle a éste los recursos para el cumplimiento de sus funciones.\n6. Que se informe a las autoridades sanitarias competentes cuando exista evidencia que permita sospechar o confirmar que se encuentra comprometida la inocuidad de uno o varios productos en circulación. Se deben además reportar las medidas adoptadas y colaborar con las autoridades competentes en la adopción de las acciones necesarias para prevenir los riesgos derivados del consumo de dicho producto, de acuerdo con la normativa y los procedimientos vigentes.\nEl titular del establecimiento será responsable ante la autoridad sanitaria por el incumplimiento de toda otra obligación prevista en el presente Código; además, será solidariamente responsable con la dirección técnica del establecimiento ante la autoridad sanitaria, en el marco de lo establecido en el Artículo 17 del presente Capítulo.\nEn el caso de elaboración de productos por terceros, el titular del establecimiento y el titular del producto serán responsables por el cumplimiento de las obligaciones establecidas en el presente Artículo y además solidariamente responsables con la dirección técnica ante la autoridad sanitaria en el marco de lo establecido en el Artículo 17 del presente Código.\nEn el caso de los establecimientos comunitarios, definidos en el Artículo 152 tris del presente Código, el titular del establecimiento y el/los elaborador/es de el/los productos serán responsables por el cumplimiento de las obligaciones establecidas en el presente artículo, y además solidariamente responsables con la dirección técnica ante la autoridad sanitaria en el marco de lo establecido en el Artículo 17 del presente Código.”', 'Resulta obligatoria para los productores de alimentos y comedores donde se elabore comida o se brinden viandas a los trabajadores.', 2, NULL, NULL, NULL, 4, 3, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "SECRETARÍA DE GESTIÓN SANITARIA Y SECRETARÍA DE AGRICULTURA, GANADERÍA Y PESCA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 293);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, NULL, 'Se sustituye el Artículo 12 del Código Alimentario Argentino el que quedará redactado de la siguiente manera: “Artículo 12: A los efectos de este Código se establecen las siguientes definiciones:\n1. Con la denominación de Fábrica de alimentos o Establecimientos elaboradores /industrializadores de alimentos, se entiende el ámbito que comprende el local y el área hasta el cerco perimetral que lo rodea, en el cual se llevan a cabo un conjunto de operaciones y procesos con la finalidad de obtener un alimento elaborado hasta su expedición.\nQuedan incluidas las áreas adyacentes para la recepción de materias primas e insumos y su almacenamiento, así como también el almacenamiento y despacho de los alimentos elaborados.\n2. Con la denominación de Boca de expendio o Local de expendio o Comercio de alimentos o Local de venta minorista, se entiende el establecimiento donde se almacenan, elaboran, fraccionan y/o acondicionan alimentos destinados a la venta directa al consumidor, ya sea para ser retirados del local o para consumirlos en el mismo.\nPodrá contar con una sala de elaboración asociada de acuerdo con el rubro.”\nPor ser una ley nacional de adhesión, sólo es aplicable en las provincias que han adherido al mismo, como así también el texto al que adhirieron.  Muchas jurisdicciones locales que adhieren también lo hacen a sus modificatorias. Así, son exigibles sus disposiciones en tanto y en cuanto las provincias adhieran por norma, y sólo será válido en cada jurisdicción  la parte o disposiciones que decidan (versión de la norma a la que adhieran). \nEl tema sanitario de expendio de alimentos, en la mayoría de las provincias es Municipal. \nEn cuanto a todo lo atinente a productos que se comercializan en todo el país, y consecuentemente transitan Inter jurisdiccionalmente y son destinados a exportación, la Administración Nacional de Medicamentos, Alimentos y Tecnología Médica (en adelante ANMAT), fiscaliza que se cumpla con el CAliA. También la forma de producción de alimentos que se comercializan en todo el país. Por ello la Resolución Conjunta 12/2025 - RESFC-2025-12-APN-SGS#MS, que sólo cambia la definición de industrias y depósitos, se aplica a los establecimientos minoristas. \n Por ello, esta norma es que los comercios minoristas, o quienes preparan comida fresca (por ello se aplica también a los comedores y restaurantes que se encuentren dentro de industrias y depósitos de cualquier rubro) cumplirán con esta resolución si la jurisdicción local adhiere, de la misma forma que se realiza con el plazo de validez de los carnet de manipuladores de alimentos -que para la fabricación de productos destinados a ser comercializados en todo el país y/o exportados es obligatorio y tiene validez por tres años-, y la exigencia de la Libreta Sanitaria -que el CAliA la eliminó-,  depende de la reglamentación o creación de la obligación que posean las  jurisdicciones locales. \nAsí, para las provincias adheridas a las normas modificatorias y complementarias del código, en el caso de que las industrias que tengan algún lugar con venta minorista, o bien si quienes les elaboran comida para sus comedores se encuentren fuera de la provincia, debe cumplir con estas normas de seguridad e higiene por la nueva Resolución Conjunta 12/2025 - RESFC-2025-12-APN-SGS#MS: \n1. No se permitirá utilizar los locales con ningún otro destino que el autorizado por la Autoridad Sanitaria competente y se deberá excluir del establecimiento todo producto, artículo, elemento, etc. ajeno a la actividad a desarrollar. \n2. El local deberá contar con la amplitud suficiente en relación con la actividad que desarrolla, al equipamiento que posee y al personal que se desempeña en el mismo.\n3. El diseño y disposición de equipos y materiales en el local deberá ser tal que permita la implementación de un procedimiento de limpieza y desinfección adecuados. Las superficies y materiales deberán ser de material no tóxico para su uso previsto.\n4. Los techos o cielorrasos deberán ser de fácil limpieza y estar construidos de manera que se impida la acumulación de suciedad, se reduzca al mínimo la condensación y la formación de mohos.\n5. Las paredes deberán ser construidas o revestidas con materiales no absorbentes, de color claro, lisas, sin grietas, fáciles de limpiar y desinfectar.\n6. Los pisos deberán estar construidos o revestidos con materiales resistentes al tránsito, no absorbentes, lisos, sin grietas, fáciles de limpiar y desinfectar. Deberán tener una pendiente tal que permita que los líquidos escurran hacia las rejillas impidiendo su acumulación.\n7. La ventilación del local podrá ser natural o artificial, de manera que el aire no fluya de zonas sucias a zonas limpias o de zonas húmedas a zonas secas. Se deberá instalar un equipo de extracción de aire en aquellos locales donde se genere calor o polvo en exceso.\n8. La iluminación podrá ser natural y/o artificial siempre que posibilite la realización de las tareas y no altere los colores. Los artefactos de iluminación que estén ubicados sobre el área de manipulación de alimentos deberán estar protegidos contra roturas o construidos con materiales anti- estallidos.\n9. Las aberturas deberán contar con un método adecuado de protección anti plagas y permanecer en buenas condiciones de mantenimiento e higiene.\n10. El titular será responsable de todo producto a la venta con defectos de elaboración o deficiencias en el envase, por lo que los productos deben someterse a inspección, clasificación o selección según sea necesario, para eliminar las mercaderías inadecuadas.\n11. Los locales deberán poseer equipos de frío, de ser necesario, que garanticen las temperaturas adecuadas para la óptima conservación de los diferentes tipos de alimentos.\n12. Los locales deberán contar con agua potable en cantidad y temperatura adecuadas de acuerdo al uso. Se deberá proveer de todos los elementos necesarios para realizar una adecuada limpieza y desinfección de manos.\n13. Los productos alimenticios deberán estar ubicados sobre tarimas o estibas, separadas del piso y de las paredes a una distancia y en condiciones tales que permitan correcta inspección y limpieza.\n14. Los materiales para empaquetar o envasar alimentos deberán almacenarse y emplearse en condiciones higiénicas; no transmitirán al producto sustancias o elementos perjudiciales, proporcionándole una protección adecuada contra la contaminación.\n15. Los alimentos destinados a devoluciones deberán estar identificados y diferenciados de aquellos destinados a la comercialización.\n16. Los productos de limpieza deberán estar almacenados en un sector distinto al de los alimentos.\n17. Toda persona que realice actividades por las cuales esté o pudiera estar en contacto con alimentos debe estar provista de un CARNET DE MANIPULADOR DE ALIMENTOS, expedido por la autoridad sanitaria local competente, con validez en todo el territorio nacional.\n18. El fraccionamiento permitido de alimentos deberá realizarse en el acto de su expendio, directamente de su envase original y a la vista del comprador. \n19. Para realizar el fraccionamiento permitido de alimentos fuera de la vista del público, el establecimiento deberá estar autorizado por la autoridad sanitaria competente y cumplir con todos los recaudos de los Artículos 18, 19, 20 y 21 del presente Código en todo lo referente a locales, almacenamiento, personal, higiene y demás precauciones descriptas, y que sean de aplicación para el fraccionamiento permitido de alimentos. \n20. El material de envasado que se use para los alimentos fraccionados debe estar aprobado, y en cada envase deberá figurar el número de registro de producto alimenticio, el número del establecimiento fraccionador, su nombre y dirección, pudiendo figurar la marca del producto, previa autorización del propietario de la misma. Debe figurar además del nombre del producto, la fecha de fraccionamiento, día, mes y año, el peso neto y la leyenda: “Conservar refrigerado...” (indicando las condiciones específicas de conservación, cuando corresponda), con caracteres de buen realce y visibilidad.\n21. Para cada grupo de alimentos (cárneos, chacinados, embutidos, productos de la pesca, productos lácteos, productos farináceos, azucarados, café, etc.) se deberá cumplir con lo establecido respectivamente para cada caso en particular, en las normas de carácter especial.”', 'Resulta obligatoria para las industrias que realizan venta al minorista (ej. A empleados, proveedores o al público) y comedores donde se elabore comida o se brinden viandas a los trabajadores.', 2, NULL, NULL, NULL, 4, 4, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "SECRETARÍA DE GESTIÓN SANITARIA Y SECRETARÍA DE AGRICULTURA, GANADERÍA Y PESCA"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 305);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Artículos 20 y 21', 'Requiere la supresión de barreras físicas en los ámbitos urbanos arquitectónicos y del transporte que se realicen, o en los existentes que se remodelen en forma total y parcial, a fin de lograr la accesibilidad para personas con movilidad reducida. Ello, con el fin de lograr que personas con movilidad reducida gocen de las condiciones adecuadas de seguridad y autonomía, para su integración y la equiparación de oportunidades.  \nSe establecen anchos máximos de itinerarios peatonales, características de los pisos, desniveles, grado de inclinación, diseño de escaleras y rampas, pasamanos, características de espacios libres, baños públicos, estacionamientos, señales verticales y de tráfico, semáforos, etc. Requiere asimismo que las obras en la vía pública estén señalizadas y protegidas por vallas y luces, y con elementos que los no videntes puedan detectar a tiempo. Establece que los Códigos de Edificación locales deberán contemplar estas exigencias.', 'Se deberán tener en cuenta los requisitos constructivos y arquitectónicos contenidos en la norma, a fin de garantizar la accesibilidad de personas con movilidad reducida.', 2, 'Continuo', 'Rampas de acceso y ascensores para acceder a los pisos.', NULL, 4, 5, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Al momento de realizar modificaciones, ampliaciones, demoliciones o nuevas construcciones.", "custom_1783383788609": "TODOS particularmente a las personas discapacitadas para caminar.", "custom_1783383823178": "Accesos y circulación  a las personas discapacitadas.", "custom_1784900000002": "Empleador"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 901);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 887);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'Poseen horas para lactancia pero no lactario. Tampoco poseen baño para discapacitados. \n\nDeben habilitar un baño de discapacitados conforme Ley 10592 y modificarías , y un lactario ya que la Ley 26873 y Decreto n° 22/2015 instan a poseer lugares para poder extraer leche materna. \n\nDeben tener baño de discapacitados y Lactario siempre que les sea posible por requerimiento del personal, pero es obligación legal poseer baño de discapacitados', 'Es optativa, pero resulta importante poseer lactario', 2, 'optativa', 'Lactario', NULL, 4, 6, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Constante", "custom_1783383788609": "Trabajadoras", "custom_1783383823178": "Salud y Seguridad"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1636);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1960);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1961);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'art. 179 LCT', 'Se reglamenta el artículo 179 de la Ley de Contrato de Trabajo N° 20.744 y sus modificatorias, estableciendo que los establecimientos que posean más de 100 personas trabajando en el sitio (ya que no sólo toma a los trabajadores propios sino que cuenta a los que pertenecen a otras empresas contratistas que presten servicio en la empresa y concurran a la misma, como los de limpieza, comedor, seguridad, etc.) deben deberán ofrecer espacios de cuidado para niños y niñas de entre 45 días y 3 años de edad para quienes durante el tiempo de la jornada de trabajo los tengan a su cargo. La obligación será exigible a partir del 25 de marzo de 2023, con la posibilidad de aplicar sanciones si no se cumple. La norma a su vez brinda la posibilidad de que en el caso de no ser posible brindar un espacio en el mismo establecimiento, facilitar otro sitio que deberá encontrarse a menos de dos kilómetros, o bien abonar una suma dineraria no remunerativa, en concepto de reintegro de gastos de guardería o trabajo de cuidado de personas, debidamente documentados.', 'Si tiene más de 100 personas trabajando deberán poseer guardería.', 2, 'Obligatorio', 'guardería o pago de  guuardería', NULL, 4, 7, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "a partir del 25 de marzo de 2023", "custom_1783383788609": "Toda la planta", "custom_1783383823178": "Salud y Seguridad"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 847);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Anexo I', 'Características constructivas: toda modificación o ampliación de las instalaciones deberá cumplir con la normativa sobre higiene y seguridad, teniendo en cuenta el funcionalismo en la distribución y las características del lugar de trabajo y dependencias complementarias, tanto para situaciones de desarrollo normal de actividades como para casos de emergencia. Los equipos riesgosos deberán quedar aislados o adecuadamente protegidos.\nLas construcciones deberán utilizar materiales adecuados a sus usos y funciones, ajustando las formas y cálculos de las estructuras a las mejores técnicas que aseguren la máxima estabilidad y seguridad. Deberán utilizarse los coeficientes de resistencia requeridos por las normas constructivas aplicables (ver Códigos de Planeamiento Urbano y de Edificación de la Ciudad Autónoma de Buenos Aires) \nServicios sanitarios: se debe disponer de servicios sanitarios adecuados e independientes para cada sexo, en función de la cantidad de empleados. Los locales sanitarios deberán contar con: (i) lavabos y duchas con agua caliente y fría; (ii) retretes individuales con puerta que asegure el cierre del baño en no menos de 3/4 de su altura (2,10 m); y (iii) mingitorios. \nDeberán considerarse las condiciones mínimas constructivas y funcionales de los servicios sanitarios, establecidas en los artículos 48 a 51 del Anexo I, en cuanto se apliquen al establecimiento.\nComedor: de poseer, deberá ubicarse lo más aisladamente posible del resto del establecimiento. Los pisos, paredes y techos serán lisos y de fácil limpieza. Deberán contar con iluminación, ventilación y temperatura adecuada. \nCocina: debe poseer buen estado de conservación y contar con condiciones higiénicas adecuadas. Si fuera necesario, deberá contar con campanas de aspiración forzada para captación de vapores y humos. Los artefactos para que los empleados puedan calentar sus comidas deberán contar con las condiciones adecuadas de higiene y seguridad.  \nAgua potable: es obligatorio contar con provisión y reserva de agua potable para uso humano. Deben realizase análisis bacteriológicos (semestralmente), físicos y químicos (anualmente) de las aguas potables para uso de los empleados –tanto de red, como de los sistemas de purificación de aguas, o de aguas embotelladas (dispenser con bidón)-, en laboratorios oficiales o privados, y sus resultados archivarse y estar disponibles cuando la autoridad los requiera. Los parámetros deben cumplir con el art. 58 (Anexo I) del Decreto 351/79 y Capítulo XII del Código Alimentario Argentino (arts. 982 y ss). \nVentilación: El ambiente laboral debe estar ventilado, preferentemente en forma natural. Se debe cumplir con la ventilación mínima según cantidad de empleados (ver Anexo I, art. 66). \nSe deben evitar condiciones ambientales perjudiciales para la salud (carga térmica, vapores, gases, nieblas, polvos, etc.). Se debe mantener permanentemente ventilado el establecimiento, a fin de asegurar concentraciones adecuadas de oxígeno, evitando la existencia de zonas de estancamiento.\nLos sistemas de extracción de aire deberán cumplimentar con los requisitos de los arts. 69 y 70, Anexo I del Decreto 351/79.    \nIluminación y color: la iluminación debe ser adecuada a las tareas a realizar, teniendo en cuenta el mínimo tamaño a percibir, la reflexión de los elementos, el contraste y el movimiento, y de modo que permita observar y reproducir los colores en la medida en que sea necesario. Se debe evitar el efecto estroboscópico, así como el deslumbramiento directo o reflejado de las luminarias. La uniformidad, el contraste y las sombras deben ser adecuados. \nLas iluminancias, las relaciones de iluminancias y la uniformidad de la iluminación se establecen en el Anexo IV del Decreto 351/79. \nDeben contar con sistema de iluminación de emergencia, que suministre una iluminancia no menor de 40 luxes a 80 cm. del suelo, y que se active en casos de corte de energía, facilitando la evacuación del personal en caso necesario e iluminando los lugares de riesgo.\nSe deben utilizar los colores de seguridad del Anexo IV del Decreto 351/79 para identificar personas, lugares y objetos a fin de prevenir accidentes. \nSe deben señalizar salidas normales o de emergencia y caminos de evacuación en caso de peligro. \nInstalaciones eléctricas: deben cumplir con las prescripciones necesarias para evitar riesgos a personas o cosas. Las instalaciones y equipos eléctricos de más de 1000 voltios de tensión deberán estar aprobados por el responsable del servicio de higiene y seguridad en el trabajo del establecimiento. Las tareas de montaje, maniobra y mantenimiento con o sin tensión deberán cumplir con el Anexo VI del Decreto 351/79. Los trabajos de mantenimiento deben ser efectuados por personal capacitado, debidamente autorizado por la empresa. El mantenimiento de las instalaciones deberá respetar los respectivos programas –diseñados de acuerdo a normas de seguridad-, debiendo registrar los resultados. \nSe deben adoptar medidas para la eliminación de la electricidad estática en aquellas operaciones donde pueda producirse, cumpliendo con Anexo VI del Decreto 351/79. Los establecimientos expuestos a descargas atmosféricas deberán contar con una instalación que evite las sobretensiones, con tomas a tierra independientes de cualquier otra.\nAscensores y montacargas: Deberán respetarse las cargas máximas admisibles establecidas por el fabricante, y cumplir con las exigencias mínimas de seguridad establecidas por el artículo 137 del Anexo I del Decreto 351/79. \nAparatos con presión interna: de existir, los mismos deberán cumplir con las normas de seguridad detalladas en los artículos 138 a 144 inclusive del Anexo I, Decreto 351/79, debiendo ser manipulados por personal debidamente capacitado. \nProtección contra incendios: El edificio deberá contar con las protecciones contra incendio que correspondan, según sus usos. Deberán observarse las normas sobre calidad de materiales a utilizar, características técnicas de las protecciones, dimensionamiento, métodos de cálculo y procedimientos para ensayos de laboratorio de la Superintendencia de Bomberos de la Policía Federal (SBPF). Las estructuras portantes y muros en general deberán emplear materiales incombustibles (Ver tablas Anexo VII y Capitulo 5 del Decreto 351/79), teniendo asimismo en cuenta la carga de fuego. La resistencia al fuego de un elemento estructural incluye la resistencia del revestimiento y del sistema constructivo del que forma parte. Los materiales resistentes al fuego deberán soportar sin derrumbarse la combustión de los elementos que contengan, de forma de permitir la evacuación de las personas. \nSi una estructura experimenta un incendio, debe ser objeto de pericia técnica antes de su rehabilitación, a fin de comprobar sus condiciones de resistencia y estabilidad. Las conclusiones de dicha pericia serán informadas a la autoridad competente, previa aprobación del organismo oficial correspondiente. \nEl Anexo VII del Decreto 351/79 contiene las definiciones de los términos técnicos en materia de protección contra incendios.\nLos equipos que consuman combustibles líquidos y gaseosos (calderas, termotanques, etc.), tendrán dispositivos automáticos que aseguren la interrupción del suministro de fluido cuando se produzca alguna anomalía.\nLas instalaciones eléctricas deberán contar con protección contra incendios según lo establecido en el Anexo VI del Decreto 351/79.\nLos sectores de incendio (excepto en garajes) podrán abarcar como máximo una planta del establecimiento, y deberán contar con control de propagación vertical y horizontal, según características y requisitos del Artículo 171 del Anexo I del Decreto 351/79. Los sectores de incendio se separaran entre sí por pisos, techos y paredes resistentes al fuego. En los muros exteriores de edificios provistos de ventanas se asegurará la eficacia del control de propagación vertical. \nTodo sector de incendio debe comunicarse directamente con un medio de escape, prohibiéndose la evacuación de un sector de incendio a través de otro sector de incendio. Los medios de escape deberán cumplimentar con los requisitos del artículo 172 del Anexo I del Decreto 351/79. \nLas condiciones de situación (requerimientos específicos de emplazamiento y acceso de edificio), de construcción, de extinción, y las condiciones generales y específicas relacionadas con los usos de los establecimientos, riesgo, situación, construcción y extinción se encuentran detalladas en el Anexo VII del Decreto 351/79. \nMatafuegos: la cantidad se determinará en función del riesgo, carga de fuego, clases de fuegos y distancia a recorrer para alcanzarlos. Las clases de fuegos se designan con las letras A, B, C y D, según detalle del artículo 176, Anexo I del Decreto 351/79. Deberá instalarse como mínimo un matafuego cada 200 m2 de superficie a ser protegida. La máxima distancia a recorrer hasta el matafuego será de 20 m. para fuegos clase A y 15 m para fuegos clase B. Ver asimismo especificaciones de los artículos 176 a 180 del Anexo I, y Anexo VII del Decreto 351/79. \nEl empleador deberá incrementar la dotación de equipos manuales si la magnitud del riesgo lo requiere, y/o adoptar un sistema fijo contra incendios, según la clase de fuego involucrada en función del riesgo a proteger.\nEl empleador deberá contar con certificaciones de cumplimiento de las normas, emitidas por entidades reconocidas. La autoridad podrá exigir una demostración práctica sobre el estado y funcionamiento de los elementos de protección contra incendio. El establecimiento deberá tener indicado en forma bien visible, la carga de fuego de cada sector de incendio. \nEl empleador que controle por sí las recargas y reparación de quipos contra incendios deberá llevar un registro de inspecciones y las tarjetas individuales por equipos que permitan verificar el mantenimiento y condiciones de los mismos. Si los equipos son controlados por terceros, dichos equipos deben estar certificados por los organismos competentes y los terceros encontrarse inscriptos en el Registro correspondiente (ver también normativa de la CABA). \nEl empleador deberá capacitar al personal en el manejo correcto de los equipos contra incendio y planificar las medidas necesarias para el control de emergencias y evacuaciones. Deberá llevar un registro en el que consten las acciones proyectadas y la nómina del personal afectado a las mismas. \nElementos de protección personal (EPP): los fabricantes y proveedores de EPP deberán encontrarse inscriptos en los registros correspondientes (ver también normativa de CABA). \nEl responsable del Servicio de Higiene y Seguridad, con la participación del Servicio de Medicina Laboral, deberá determinar la necesidad de uso de equipos y elementos de protección personal, las condiciones de utilización y su vida útil. \nLos medios de protección ocular serán seleccionados en función de los riesgos como ser: radiaciones nocivas y/o sustancias sólidas, líquidas o gaseosas. La protección de la vista se efectuará mediante el empleo de anteojos, pantallas transparentes u otros elementos adecuados, los que reunirán las especificaciones fijadas por los artículos 194 y 195 del Anexo I del Decreto 351/79. \nEn todo trabajo en altura se requiere el uso de cinturones de seguridad provistos de anillas por las que pasará la cuerda salvavidas. Estos cinturones cumplirán con las especificaciones técnicas correspondientes (art. 200, Anexo I del Decreto 351/79 y normativa complementaria)\nSelección de personal: El servicio de medicina laboral extenderá un certificado de aptitud en relación con la tarea a desempeñar, previo al ingreso del trabajador. Las modificaciones de las exigencias y técnicas laborales requieren un nuevo examen médico del trabajador. El postulante/trabajador está obligado a someterse a los exámenes preocupacionales y ocupacionales periódicos que disponga el servicio médico.\nCapacitación: Se deberá capacitar al personal en materia de higiene y seguridad, prevención de enfermedades profesionales y accidentes de trabajo. La capacitación deberá complementarse con material educativo, avisos y carteles que indiquen las medidas de higiene y seguridad. Se deberá planificar en forma anual los programas de capacitación para los distintos niveles, y estarán a disposición de la autoridad de aplicación, a su solicitud. Los planes serán programados y desarrollados por los servicios de medicina, higiene y seguridad en el trabajo. Se deberá entregar por escrito al personal, las medidas tendientes a evitar enfermedades profesionales y accidentes de trabajo. \nEl empleador deberá ordenar, a requerimiento de la autoridad, la suspensión de las tareas que se realicen implicando riesgos graves inmediatos para la salud o la vida de los trabajadores, o para terceros.', 'Ante cualquier modificación o ampliación de las instalaciones, deberá cumplirse con la normativa establecida en cuanto a materiales, instalaciones, servicios, provisión de agua potable, etc. Ello deberá interpretarse en concordancia con el Código de Edificación  municipal, el Cödigo de Planeamiento Urbano  y otras normas complementarias.', 1, 'Informativo', 'Se cumple con los requisitos en la obra nueva al momento de la auditoria.', 'Se pudo verificar que la obra de ampliación de Artigas cumplía con los requisitos.', 4, 8, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Contratistas/ Subcontratistas", "custom_1784900000002": "Contratista/subcontratista, empleador, responsable de H&S"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 50);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1672);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Anexo IV', 'Iluminación y color: las tablas 1,2 y 4 del Anexo IV se basan en la Norma IRAM-AADL J 20-06. La tabla 1 establece la intensidad mínima de iluminación medida sobre el plano de trabajo según la dificultad de la tarea visual y la tabla 2 de acuerdo con el destino del local. Se deberán mantener las relaciones máximas de iluminancia de la tabla 3 a fin de evitar incomodidad visual o deslumbramiento. La tabla 4 establece la iluminación general mínima en función de la iluminancia localizada.\nEn cuanto al color, se establece que los valores a utilizar para la identificación de lugares y objetos serán los establecidos por las normas IRAM 10.005; 2507 e IRAM DEF D 10-54.', 'Se deberán tener en cuenta los estándares del Anexo IV y lo establecido por las Normas IRAM-AADL J20-06, IRAM 10.005, 2507 e IRAM DEF D 10-54.', 2, 'Acción', 'Registros de monitoreos de iluminación', NULL, 4, 9, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Cada vez que se actualice el Reglamento", "custom_1783383788609": "TODOS", "custom_1783383823178": "Reglamento", "custom_1784900000002": "Responsable de H&S."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 50);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1672);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Anexo V', 'Acústica: se establecen los límites a exposiciones de sonido a los que pueden estar expuestos repetidamente casi todos los trabajadores sin efectos adversos para la audición.', 'Cumplir con los límites de exposiciones de sonido a los que pueden estar expuestos los trabajadores.', 2, 'Acción', 'Señalización de uso de  protección auditiva en lugares donde puede ser requerido.', NULL, 4, 10, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Cada vez que se actualice el Reglamento", "custom_1783383788609": "TODOS", "custom_1783383823178": "Reglamento", "custom_1784900000002": "La  responsabilidad de identificar la necesidad de protección es del responsable de EH&S. De la colocación y mantenimiento de la señalización: infraestructura. De su uso, el jefe de cada sector y el operador que realiza tareas en lugares ruidosos."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 50);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1672);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Anexo VI', 'Instalaciones eléctricas: el artículo 1 del Anexo VI enumera las definiciones y terminología, que incluyen los siguientes términos: niveles de tensión; tensión de seguridad; bloqueo de un aparato de corte o de seccionamiento; consignación de una instalación, línea o aparato; distancias de seguridad; y trabajos con tensión.\nEl personal que efectúe mantenimiento de instalaciones eléctricas deberá estar debidamente capacitado. Los trabajos con tensión deben ser ejecutados por personal especialmente habilitado.  La habilitación será visada por el jefe del servicio de higiene y seguridad de la empresa, según los requisitos del artículo 1.2.2. del Anexo VI del Decreto 351/79. \nSe establecen las normas para trabajos y maniobras en instalaciones eléctricas, tanto de baja, como media y alta tensión; disposiciones respecto de canalizaciones eléctricas, tanto aéreas como subterráneas; normas para trabajos y maniobras en dispositivos y locales eléctricos; condiciones de seguridad en instalaciones eléctricas; y procedimientos en locales con riesgos eléctricos especiales; entre otras.', 'El personal que efectúe mantenimiento de instalaciones eléctricas deberá encontrarse capacitado y habilitado para dichas tareas, y deberá cumplir con las normas del Anexo VI y normativa complementaria.', 2, 'Acción', 'Registros de capacitación en seguridad eléctrica', NULL, 4, 11, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Riesgo eléctrico", "custom_1784900000002": "La responsabilidad es del empleador. Y de la persona a cargo de infraestructura."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 50);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1672);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Anexo VII', 'Protección contra incendios: Establece las condiciones mínimas constructivas y de equipamiento, según los usos, que deberán encontrarse presentes a fin de prevenir y contener incendios.\nEl anexo contiene definiciones y especificaciones sobre caja de escaleras, carga de fuego, coeficiente de salida, factor de ocupación, inflamables, combustibles, incombustibles, refractarias, medios de escape, presurización, punto de inflamación momentánea, resistencia al fuego, sector de incendio, superficie de piso, unidad de ancho de salida, velocidad de combustión, y resistencia al fuego de los elementos constitutivos de los edificios, entre otras. \nLa tabla 2.1. detalla los niveles de riesgo en función de los materiales constructivos según su combustión y la actividad llevada a cabo en el establecimiento. \nLas tablas 2.2.1 y 2.2.2. enumeran los niveles de riesgo según el cálculo de la carga de fuego. \nEl artículo 3. regula los medios de escape, incluyendo los anchos mínimos, el factor de ocupación, situación de los medios de escape (números de salidas, distancia máxima a una caja de escalera, independencia de la salida, etc.), caja de escaleras, escaleras auxiliares exteriores, escaleras verticales, escaleras mecánicas, escaleras principales, escaleras secundarias, escaleras fijas de servicio, escaleras de mano, plataforma de trabajo, rampas y puertas giratorias. \nEl artículo 4. se ocupa del potencial extintor del establecimiento. Las tablas 4.1. y 4.2. establecen el tipo y cantidad de matafuegos que deberán instalarse según la carga de fuego.\nEl artículo 5. establece las condiciones generales y específicas de situación. \nEl artículo 6. regula las condiciones generales y específicas de construcción según las características del riesgo. \nEl artículo 7. regula las condiciones generales y específicas de extinción, junto con el cuadro de protección contra incendios.', 'El servicio de Higiene y Seguridad laboral deberá constatar el cumplimiento con los requisitos constructivos y de equipamiento contra incendios del Anexo VII.', 2, 'Acción', 'Estudio de carga de fuego de la instalación', NULL, 4, 12, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Riesgo de incendio.", "custom_1784900000002": "La responsabilidad es del empleador. Y de la persona a cargo de infraestructura."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 50);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1672);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Anexo VIII (sustituido por Resolución Min. Trabajo 2665/80)', 'Requiere la confección del "Informe Anual Estadístico" y aprueba formulario a presentar por empleador.', 'Confeccionar el Informe Anual Estadístico según los formularios aprobados por la Autoridad de Aplicación', 2, 'Acción', 'Informe Anual estadístico', NULL, 4, 13, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "De acuerdo al Programa Anual de Mantenimiento", "custom_1783383788609": "Field Operativos/Servicios Generales", "custom_1783383823178": "Registros de mantenimiento", "custom_1784900000002": "ART"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 50);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1672);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, NULL, 'Aprueba el Reglamento de Higiene y Seguridad para la industria de la Construcción. Establece que el Decreto 351/79 y la Resolución 1069/91 no se aplicarán a la industria de la construcción. \nEl Reglamento se aplica a trabajadores que desarrollen su actividad en empresas constructoras, tanto en el área física de las obras como en los sectores, funciones y dependencias conexas (obradores, depósitos, talleres, servicios auxiliares y oficinas técnicas y administrativas). \nEl comitente será solidariamente responsable, junto con el contratista, del cumplimiento de las normas del Decreto. \nEl contratista deberá acreditar, antes de la iniciación de la obra, la contratación del seguro que cubra los riesgos de trabajo del personal afectado a la misma según ley 24557, o la existencia de autoseguro y el comitente deberá notificar a la SRT el eventual incumplimiento de dicho requisito.  \nEl empleador es el principal y directo responsable del cumplimiento de los requisitos del Decreto, que incluyen la creación y mantenimiento de las condiciones y medio ambiente de trabajo que aseguren protección física y mental a los trabajadores y la reducción de la siniestralidad laboral. Deberán asimismo adecuar las instalaciones de las obras y los restantes ámbitos de trabajo a las normas vigentes. Deberán también Capacitar a sus trabajadores en materia de Higiene, Seguridad y Prevención de enfermedades y accidentes de trabajo. Los programas de Capacitación deberán incluir a todos los sectores de la empresa en los distintos niveles, y en su preparación deberán intervenir los Servicios de Higiene y Seguridad y de Medicina del Trabajo.\nEl trabajador debe someterse a los exámenes periódicos de salud requeridos, someterse a los procesos terapéuticos prescriptos para el tratamiento de enfermedades y lesiones; cumplir con las normas de prevención establecidas legalmente y en los Planes y Programas; asistir a los cursos de capacitación; usar los equipos de protección personal o colectiva y observar las medidas de prevención; utilizar en forma correcta materiales, máquinas, herramientas, dispositivos y todo elemento con que desarrolle su trabajo; observar las indicaciones de los carteles y avisos; colaborar en la organización de Programas de Formación y Educación; e informar al empleador de todo hecho o situación riesgosa en sus puestos de trabajo.\nEl trabajador tiene derecho a gozar de condiciones y medio ambiente de trabajo saludables; y a recibir información completa y fehaciente sobre los resultados de sus exámenes de salud.      \nEstablece que las prestaciones en materia de Medicina y de Higiene y Seguridad en el Trabajo serán prestadas por graduados universitarios, siendo el objetivo fundamental la prevención de todo daño a la vida y la salud de los trabajadores en sus ámbitos de trabajo. El capítulo 3 se aboca a las prestaciones en Higiene y Seguridad en el Trabajo, y el capítulo 4 al legajo técnico de Higiene y Seguridad, que es la documentación generada por la prestación de Higiene y Seguridad. \nEl capítulo 5 se ocupa de los Servicios de Infraestructura de Obra, que incluye los servicios de transporte de personal, viviendas para el personal (de corresponder), instalaciones sanitarias, vestuarios, comedor, cocina, evacuación de desechos cloacales y orgánicos, y provisión de agua de uso y consumo humano.\nEl capítulo 6 regula las condiciones generales en el ámbito donde se desarrollen las tareas constructivas, la manipulación y almacenamiento de materiales, el orden y limpieza en la obra, la circulación peatonal y vehicular, la iluminación, calefacción y ventilación, la protección contra la caída de objetos y materiales o de personas, trabajos en la vía pública (los que deberán señalizarse, vallarse y cercarse), y señalización. Asimismo, se regula lo atinente a instalaciones eléctricas y las distancias de seguridad según el nivel de tensión para prevenir descargas (ver Tabla 1). Requiere que el personal que realice trabajos en instalaciones eléctricas sea adecuadamente capacitado por la empresa sobre los riesgos a los que estará expuesto y en el uso del material, herramientas y equipos de seguridad. También recibirá instrucciones sobre cómo socorrer a un accidentado de descarga eléctrica, primeros auxilios, lucha contra el fuego y evacuación de locales incendiados.   \nLa norma define tres métodos de trabajo con tensión: a contacto; a distancia y a potencial. Asimismo establece procedimientos para trabajos con distintas tensiones y sin tensión, tanto en líneas aéreas como subterráneas. Además establece normas para el mantenimiento de las instalaciones eléctricas. \nPor su parte, regula la prevención y protección contra incendios en obras en construcción, el rol del responsable de Higiene y Seguridad, y las características de los equipos e instalaciones de extinción de incendios. Además establece normas de seguridad para depósitos de inflamables, y regula el uso de elementos de protección personal. \nEl capítulo 7 se aboca a las normas higiénico-ambientales en obra, incluyendo normas sobre contaminación ambiental, ventilación, radiaciones, ruidos y vibraciones, iluminación, y carga térmica.     \nEl capítulo 8 establece las normas de prevención en las distintas etapas de la obra: demolición, excavaciones, trabajos subterráneos, trabajos con explosivos, túneles y galerías subterráneas, submuración, trabajos con pilotes y tablestacas, trabajos con hormigón y trabajos con pinturas.\nEl capítulo 9 comprende las normas de prevención en las instalaciones y equipos de obra, incluyendo silos y tolvas, máquinas para trabajar la madera, herramientas de accionamiento manual y mecánicas, herramientas eléctricas, escaleras de mano, de dos hojas, estructurales temporarias y telescópicas mecánicas, andamios, silletas, caballetes, pasarelas y rampas, vehículos y maquinaria automotriz, camiones, hormigoneras, elevadores, autoelevadores, montacargas, ganchos, eslingas, etc.\nAdemás establece normas sobre uso de sopletes, generadores de vapor, compresores, cilindros de gases a presión, almacenamiento y utilización de gases comprimidos, máquinas y equipos de transformación de energía, motores de combustión interna, etc.', 'Los trabajadores (en relación de dependencia y contratados) que realicen tareas de construcción, sea en la vía pública o en las instalaciones de la empresa, no se encuentran alcanzados por el Decreto 351/79, reglamentario de la Ley 18.587 y Resolución 1069/91, sino que deberán cumplir con el Reglamento de Higiene y Seguridad en la Construcción aprobado por el Decreto 911/96 y normas complementarias. Es importante cumplir con las normas del Reglamento, relativas al ambiente laboral, seguridad e higiene en obras en construcción.\nEs crucial contar con seguro que cubra los riesgos de trabajo previo al inicio de las obras. Además, se deberá capacitar al personal en materia de higiene, seguridad y prevención de enfermedades y accidentes, debiendo intervenir los Servicios de Higiene y Seguridad y de Medicina del Trabajo.  \nAsimismo, los trabajadores deberán realizarse los exámenes periódicos de salud, y deberán usar los elementos de protección personal de manera obligatoria.', 2, 'Acción', 'Actas de entrega de EPP\nRegistro de incidentes\nRegistros de inducción a la contratista\nRegistros de capacitación', 'La contratista Raposeiras cumple con los registros necesarios para dar cumplimiento a este artículo', 4, 14, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. Dirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Al momento de realizar modificaciones, ampliaciones, demoliciones o nuevas construcciones.", "custom_1783383788609": "Obras de construcción", "custom_1783383823178": "Riesgo de accidentes durante la construcción de las obras", "custom_1784900000002": "Empresa constructora"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 872);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'Aprueba el “PROCEDIMIENTO DE CONTROL DE LOS PROGRAMAS DE SEGURIDAD PARA LAS OBRAS EN CONSTRUCCIÓN PRESENTADOS EN FORMA REMOTA”.', 'tener en cuenta en el caso de poseer obras de construcción en la planta o bien contratar nuevas.', 2, 'Acción', 'Programa presentado a la  ART', 'LA CONTRATIITA', 4, 15, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. Dirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Al momento de realizar modificaciones, ampliaciones, demoliciones o nuevas construcciones.", "custom_1783383788609": "Obras de construcción", "custom_1783383823178": "Riesgo de accidentes durante la construcción de las obras", "custom_1784900000002": "Empresa constructora"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 375);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'Aprueba las “MEDIDAS DE SEGURIDAD EN ALTURA” que como Anexo I IF-2023-144412295-APN-GP#SRT forma parte de la presente resolución.\nAprueba el Anexo II IF-2023-144412578-APN-GP#SRT “GLOSARIO Y DEFINICIONES RELACIONADAS A LOS TRABAJOS EN ALTURA”, que como tal forma parte integrante de la presente resolución.\nAprueba el Anexo III IF-2023-144412806-APN-GP#SRT - ”PLANILLAS DE LISTAS DE VERIFICACIÓN DE EQUIPOS OPERATIVOS”: SILLETAS, ANDAMIOS FIJOS/MÓVILES, ANDAMIOS COLGANTES, PLATAFORMAS ELEVADORAS MÓVILES DE PERSONAS (PEMP), EQUIPOS DE TRABAJO EN ALTURA -SISTEMAS DE ARRESTO DE CAÍDAS PERSONALES-, y TRABAJOS EN POSTES”, que como tal forman parte integrante de la presente resolución. \nÉsta resolución reglamenta el  Decreto Nacional 911/96 y  Resolución Nacional N° 231/96 Estatuto para la Construcción”, pero puede utilizarse en subsidio.', 'Tener en cuenta para usar como modelo para permisos y reglas de seguridad para realizar trabajos en altura.', 2, 'ACCIÓN', 'Permisos de trabajao y capacitaciones. Cartelería', 'contratistas', 5, 16, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. Dirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Al momento de realizar trabajos en altura", "custom_1783383788609": "Obras de construcción", "custom_1783383823178": "Caídas", "custom_1784900000002": "empresa constructora, contratista e iindicativamente la empresa"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1678);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establecen que el servicio de medicina laboral podrá ser interno o externo según voluntad del empleador, debiendo estar a cargo de médicos con especialización en medicina del trabajo. \nLas horas médico semanales deberán ser asignadas por el empleador en función de la cantidad de trabajadores equivalentes. El número de trabajadores equivalentes se calcula sumando al número total de trabajadores dedicados a tareas de producción, el 50% de los trabajadores asignados a tareas administrativas. \nSegún el artículo 7° del Decreto 1338, en plantas con hasta 150 trabajadores equivalentes, la asignación de horas médico en planta será voluntaria. En cambio, para plantas con un número de entre 151 y 300 trabajadores equivalentes, corresponderá un total de 5 horas médico semanales; entre 301 y 500 trabajadores equivalentes, las horas médico semanales serán 10; entre 501 y 700 trabajadores equivalentes serán 15 horas médico semanales; entre 701 y 1000 trabajadores equivalentes tendrán 20 horas médico semanales, y entre 1001 y 1500 trabajadores equivalentes, corresponderán 25 horas médico semanales en planta. Cuando el número de trabajadores equivalentes supere los 1500, se deberán agregar a las 25 horas médico semanales previstas, 1 hora médico por cada 100 trabajadores adicionales.\nPor su parte, el artículo 8° del Decreto 1338 requiere que cuando existan en planta más de 200 trabajadores dedicados a tareas productivas, o más de 400 trabajadores equivalentes en cada turno de trabajo, se asigne un enfermero/a con título habilitante que asista al médico.', 'Cumplir con las horas médico semanales exigidas por la norma, y de contar con consultorio o enfermería, la misma deberá encontrarse habilitada según las normas locales.', 2, 'Acción', 'Contrato del servicio de medicina del trabajo', 'Deberá consultarse a la  ART para determinar si el servicio es requerido o no, teniendo en cuenta el trabajo en la vía pública realizado por contratistas. La ley no habla de cantidad mínima de trabajadores, y tiene en cuenta los trabajadores que realizan tareas administrativas.\nSe viene cotizando el servicio de medicina laboral', 4, 17, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo         Medicina Laboral.", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. Ministerio de Salud de la Provincia de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "Todos", "custom_1783383823178": "Contar con un servicio de medicina laboral", "custom_1784900000002": "Recursos Humanos"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1676);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 628);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'Se establecen los lineamientos para una respuesta integral a las enfermedades de transmisión sexual con incidencias en materia laboral como:\n“Artículo 8º- Prueba diagnóstica en el ámbito laboral. Se prohíbe la oferta y la realización de la prueba diagnóstica de VIH, hepatitis virales y otras ITS en los exámenes médicos preocupacionales, como así también durante el transcurso y como parte de la relación laboral. Las ofertas de empleo no podrán contener restricciones por estos motivos. En el caso de accidentes de trabajo podrá requerirse la prueba diagnóstica de VIH, hepatitis virales y otras ITS, al sólo efecto de proteger la salud de la persona afectada. No podrá condicionarse la permanencia o promoción en los puestos de trabajo a la realización o al resultado de esta prueba.\nArtículo 9°- Derechos laborales. Las personas con VIH, hepatitis virales, otras ITS y/o TBC tienen los siguientes derechos laborales:\na) El derecho al trabajo y a la permanencia en el mismo, sin discriminación, despidos, suspensiones, hostigamientos, reducciones salariales, violencia, violación de la confidencialidad, para la población referida en la presente ley.\nSe presume, salvo prueba en contrario, que el despido de personas con VIH, hepatitis virales, otras ITS y/o TBC obedece a razones de discriminación;\nb) El derecho a que no sea condicionado el ingreso a fuentes laborales o a la promoción de puestos de trabajo por la realización de pruebas diagnósticas;\nc) El derecho a no ser objeto de pruebas diagnósticas de modo compulsivo;\nd) El derecho a ser beneficiarios de políticas de empleabilidad para personas con VIH, hepatitis virales, otras ITS y/o TBC, impulsando el acceso universal, asistencia integral y no discriminación, conforme a la “Recomendación sobre el VIH/SIDA y el mundo del trabajo” de la OIT;\ne) El derecho a la inclusión de las personas con VIH, hepatitis virales, otras ITS y/o TBC en los programas de formación y capacitación del Ministerio de Trabajo, Empleo y Seguridad Social o el organismo que en un futuro lo reemplace;\nf) El derecho a ser beneficiarios de políticas de acciones afirmativas que fomenten la inclusión laboral, tanto en el ámbito público como en el privado, para la población contemplada en esta ley, garantizando la confidencialidad del diagnóstico.', 'Tener en cuenta para las capacitaciones de Medicina Laboral. El reglamento Aprueba la Reglamentación del Capítulo VII de la Ley N° 27.675 - “LEY NACIONAL DE RESPUESTA INTEGRAL AL VIH, HEPATITIS VIRALES, OTRAS INFECCIONES DE TRANSMISIÓN SEXUAL ITYS- Y TUBERCULOSIS –TBC- respecto la Seguridad Social. Prueba diagnóstica en el ámbito laboral. El MINISTERIO DE TRABAJO, EMPLEO Y SEGURIDAD SOCIAL dictará las normas aclaratorias y complementarias y todo acto administrativo que resulte necesario para dar cumplimiento a lo establecido en el artículo de la ley que se reglamenta.\nAsimismo, todas las instituciones públicas o privadas que sean responsables de la realización de exámenes de salud para el ámbito laboral deberán disponer en lugares visibles para todas las personas usuarias un letrero de un tamaño mínimo de OCHENTA CENTÍMETROS (80 cm) por CINCUENTA CENTÍMETROS (50 cm) con el siguiente texto: “Se prohíbe la oferta y la realización de la prueba diagnóstica de VIH, hepatitis virales y otras ITS en los exámenes médicos preocupacionales, como así también durante el transcurso y como parte de la relación laboral. Las ofertas de empleo no podrán contener restricciones por estos motivos. Usted puede informarse del texto legal y denunciar su incumplimiento llamando a la línea gratuita de la SRT.\nEntre los exámenes de salud para el ámbito laboral se incluyen los exámenes preocupacionales o de ingreso, periódicos, previos a una transferencia de actividad, posteriores a una ausencia prolongada, previos a la extinción del contrato laboral, como también toda otra prueba diagnóstica de VIH, hepatitis virales y otras ITS durante la vigencia de la relación laboral.', 2, 'Obligatorio, recordar que es un agente cancerígeno declarable poseer personas con hepatitis', 'Planilla de capacitación firmada', NULL, 4, 18, '{"custom_1783383400370": "Salud Ocupacional/Enfermedades/capactación /Estudios médicos", "custom_1783383445340": "SRT y Ministerio de Salud", "custom_1783383763840": "Cuando se capacite en medicina laboral", "custom_1783383788609": "Todos", "custom_1783383823178": "contagio de enefermedad", "custom_1784900000002": "Servicio médico"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 408);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 363);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Requiere que los empleadores de la construcción comuniquen a su ART, al menos con 5 días hábiles de anticipación. el inicio de todo tipo de obra que emprendan. Además, deberán confeccionar un Programa de Seguridad que integra el Legajo Técnico (conf. Resolución SRT 231/1996, Anexo I, art. 3) para cada obra que inicien. \nEstablece que los Servicios de Higiene y Seguridad de los empleadores de la construcción redacten el Programa de Seguridad conforme los lineamientos del Anexo I. Asimismo, prevé que los Servicios de Prevención de las ART controlen el contenido de tales Programas y su cumplimiento, según los mecanismos de verificación del Anexo I.', 'Deberá cumplirse con la norma previo al inicio de cualquier obra constructiva. Asimismo, los trabajadores deberán realizase los exámenes periódicos de salud, y deberán usar los elementos de protección personal de manera obligatoria.', 2, 'Acción', 'Programa de seguridad aprobado por ART', NULL, 4, 19, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Al momento de realizar modificaciones, ampliaciones, demoliciones o nuevas construcciones.", "custom_1783383788609": "Empresas constructoras", "custom_1783383823178": "Contar con el personal cubierto por ART en caso de accidente.", "custom_1784900000002": "EH&S / Planning Infraestructura"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece que a fin de cumplir con lo normado por la Resolución SRT 51/97, el empleador de la construcción que actúe en carácter de contratista principal o comitente coordinará un Programa de Seguridad Único para toda la obra, que contemplará todas las tareas a realizar, tanto por parte de su personal como de las empresas subcontratistas. Ello no exime a los empleadores de las empresas subcontratistas, a notificar el inicio de obra conforme el artículo 1 de la Resolución SRT 51/97, ni de la confección y presentación ante su Aseguradora, del Programa de Seguridad del artículo 2 de la norma citada, debiendo dicho programa adaptarse al Programa de Seguridad Único del contratista. \nLa norma mantiene vigentes las obligaciones para los Servicios de Prevención de las ART. A los efectos del cumplimiento del mecanismo de verificación del Anexo I de la Resolución SRT 51/97, el Servicio de Prevención de la ART del contratista principal será responsable de controlar el cumplimiento del Programa de Seguridad Único de la obra. El Servicio de Prevención de la ART de cada subcontratista será responsable de controlar el cumplimiento del Programa de Seguridad en lo atinente al personal cubierto por esa ART, debiendo elevar un informe de visita a obra al Director de o el contratista principal o comitente, y al responsable de Higiene y Seguridad de éstos.', 'Deberá cumplirse con la norma previo al inicio de cualquier obra constructiva.', 2, 'Acción', 'Programa de Seguridad', NULL, 4, 20, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Al momento de realizar modificaciones, ampliaciones, demoliciones o nuevas construcciones.", "custom_1783383788609": "Obra en construcción.", "custom_1783383823178": "Accidente por falta de coordinación en la coordinación de la obra.", "custom_1784900000002": "EH&S"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece que los requisitos de seguridad para tareas ejecutadas en espacios confinados serán satisfechos en tanto se cumpla con las exigencias de la norma IRAM N° 3625 del 12 de agosto de 2003. En caso de verificarse discrepancia entre los valores de la Tabla 1 de la Norma IRAM citada (concentraciones máximas permitidas de contaminantes) y los valores del Anexo IV de la Resolución MTEySS 295/2003, deberán aplicarse las normas más estrictas.  \nLas infracciones a esta normas serán sancionadas conforme lo establecido en las Leyes 24557, 25212 y concordantes.', 'En trabajos en espacios confinados, cumplir con los estándares de la Norma IRAM N° 3625/2003 y del Anexo IV de la Resolución MTEySS 295/2003 (en caso de discrepancia, aplicar el estándar más estricto).', 2, 'Acción', NULL, NULL, 4, 21, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Trabajos en espacios confinados", "custom_1783383788609": "TODOS", "custom_1783383823178": "Riesgo de accidentes por ingresar a un espacio confinado sin autorizado y según procedimiento seguro.", "custom_1784900000002": "Mantenimiento e Infraestructura de su implementación. S&H de identificar los espacios confinados, capacitar al personal que ingresa. Verificar el procedimiento. e"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece que cuando se ejecuten trabajos de movimiento de suelos, excavaciones manuales o mecánicas a cielo abierto superiores a 1,20 mts de profundidad, para la ejecución de zanjas y pozos y todo otro tipo de excavación no incluida en la Resolución SRT 550/2011, el empleador debe adoptar las medidas de prevención detalladas en el Anexo de la Resolución.', 'Cumplir con las medidas de prevención del Anexo de la Resolución al momento de ejecutar trabajos de movimiento de suelos, excavaciones manuales o mecánicas a cielo abierto para la ejecución de zanjas y pozos', 2, 'Acción', NULL, NULL, 4, 22, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Al momento de realizar trabajos de movimiento de suelos y excavaciones manuales o mecánicas a cielo abierto para la ejecución de zanjas y pozos.", "custom_1783383788609": "Obras de construcción", "custom_1783383823178": "Accidente por colapso de la excavación.", "custom_1784900000002": "En caso las hubiera en el futuro  será responsabilidad del constructor, del comitente principal, de cumplimentarlo. Infraestructura deberá verificarlo. S&H  deberá verificarlo."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Regula el uso de autoelevadores. Son considerados autoelevadores los vehículos autopropulsados, con conductor sentado, utilizados para la elevación y transporte de cargas menores o iguales a 3.500 kg., provistos de contrapesos integrados a la estructura, mástil/torre y cilindro de elevación, a los cuales se adicionan accesorios especialmente diseñados según las tareas que se deban realizar.\nRequiere que al utilizar autoelevadores se adopten las condiciones de seguridad para autoelevadores contenidas en la Resolución. \nSólo se permitirá la operación del autoelevador a conductores autorizados por el empleador, luego de una capacitación teórico-práctica no menor a 10 horas con evaluación final. El examen deberá revalidarse cada 2 años. Se establecen los contenidos mínimos del curso de capacitación. \nEl operador del autoelevador debe realizar un control diario del equipo en el inicio del turno de trabajo, mediante un listado de verificación o chequeo que deberá contener al menos los puntos listados por la norma. El operador deberá informar al supervisor o encargado, de las irregularidades detectadas en el chequeo previo. \nEl empleador es responsable del correcto mantenimiento de los autoelevadores. Los mismos deberán ser revisados trimestralmente por un profesional con incumbencia.', 'Los autoelevadores sólo podrán ser operados por conductores autorizados por el empleador, luego de una capacitación teórico-práctica según los requisitos de la norma. El operador deberá controlar el equipo diariamente e informar al supervisor o encargado de cualquier irregularidad detectada.Asimismo, el autoelevador deberá ser revisado trimestralmente por un profesional con incumbencia. El operador deberá cumplir con las condiciones de seguridad para autoelevadores de la norma.', 1, 'Informativo', NULL, NULL, 4, 23, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Operación de autoelevadores.", "custom_1783383788609": "No aplica."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba el “Protocolo para la Medición de Contaminantes Químicos en el Aire en un Ambiente de Trabajo”, de uso obligatorio para quienes deban medir el nivel de contaminantes químicos conforme la Ley 19587.\nLos valores de medición de contaminantes químicos en el ambiente de trabajo tendrán una validez de 12 meses.', 'De corresponder la medición de contaminantes químicos en el aire en el ambiente laboral, se deberá cumplir con el protocolo de medición que aprueba la norma.', 2, 'Acción', NULL, NULL, 4, 24, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Anual", "custom_1783383788609": "No aplica."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba el “Protocolo para la medición del valor de puesta a tierra y la verificación de la continuidad de las masas en el ambiente laboral”. El Protocolo es de uso obligatorio para todos los que deban medir el valor de la puesta a tierra y verificar la continuidad de las masas según Ley 19587. \nLos valores de medición de la puesta a tierra, la verificación de la continuidad del cortocircuito de tierra de las masas en el ambiente laboral, tendrán una validez de 12 meses.', 'Se deberá medir el valor de puesta a tierra de forma anual, por un profesional con incumbencias. El informe deberá encontrarse firmado por el profesional, y la firma visada por el Colegio Profesional respectivo.', 2, 'Acción', 'Certificado de Medición de Puesta a Tierra con firma de profesional calificado', NULL, 4, 25, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Anual", "custom_1783383788609": "TODOS", "custom_1783383823178": "Riesgo eléctrico.", "custom_1784900000002": "Field Operations-Infraestructura"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece las funciones de los Servicios de Higiene y Seguridad en el Trabajo y de Medicina del Trabajo según Decreto 1338/1996. Aprueba las funciones conjuntas de ambos Servicios (Anexo I), las funciones del Servicio de Higiene y Seguridad en el Trabajo (Anexo II), y las funciones del Servicio de Medicina del Trabajo (Anexo III). \nCrea el “Registro Digital Único de Legajos de Salud” que se integrará con información suministrada por los Servicios de Medicina del Trabajo y las ART. \nAmbos Servicios deberán registrar ante la SRT las acciones ejecutadas en cumplimiento de las funciones por medio de las herramientas informáticas diseñadas por la SRT. \nEl Anexo I establece, entra las funciones conjuntas de ambos Servicios, las de asesorar al empleador en la definición de la Política en materia de Seguridad y Salud en el Trabajo; relevar y confeccionar el Mapa de Riesgos; la evaluación de los accidentes y de agentes causantes de enfermedades profesionales y la propuesta de medidas correctivas y preventivas; fiscalizar el cumplimiento de la normativa en la materia; registrar el seguimiento de avances, adecuaciones y retrocesos del empleador en el Plan de Regularización de Incumplimientos; verificar las acciones de la ART o el EA por establecimiento (exámenes médicos periódicos, prestaciones médicas a trabajadores, visitas según programas o planes de focalización, etc.); visitar y relevar los puestos de trabajo; y elaborar y ejecutar el Programa Anual de Capacitación en Higiene y Seguridad y Medicina del Trabajo.\nEl Anexo II establece, entra las funciones del Servicio de Higiene y Seguridad en el Trabajo, las de elaborar el Programa de Higiene y Seguridad en el Trabajo como parte del Programa Anual de Prevención de Riesgos; confeccionar el Manual de Procedimientos del Servicio de Higiene y Seguridad que incluya un Plan de Contingencias, un Organigrama Operativo; la Capacitación del personal, un Plan de Evacuación y Simulacros, un Plan de Preparación ante Emergencias, la coordinación con entidades externas y el proceso de corte de servicios, entre otros; mantener actualizados el Diagrama de Procesos y Distribución, los Planos Generales y de Servicios de Prevención y Lucha contra Incendio y los Planos de Evacuación y Vías de Escape; verificar la ejecución del Programa Anual de Prevención de Riesgos; registrar mediciones de contaminantes; elaborar un Plan de Capacitación Anual de uso de elementos de protección personal, plan de evacuación ante emergencias, riesgo de incendio, riesgo eléctrico, etc.      \nEl Anexo III lista, entre las funciones del Servicio de Medicina del Trabajo, las de elaborar un Programa de Medicina del Trabajo como parte del Programa Anual de Prevención de Riesgos Laborales; confeccionar un Manual de Procedimientos Médicos; realizar visitas periódicas en los puestos de trabajo; elaborar un procedimiento para determinar requerimientos de exámenes médicos preocupacionales en función del puesto de trabajo; elaborar un procedimiento de Vigilancia Médica; informar al empleador sobre la aptitud física o psicofísica de cada trabajador; ejecutar acciones de asistencia y seguimiento al trabajador por enfermedad inculpable, accidente o enfermedad profesional; realizar estudios de ausentismo por morbilidad; ejecutar acciones de educación sanitaria; confeccionar un Registro de Enfermedades Profesionales y Accidentes de Trabajo; y realizar las acciones de atención primaria de la salud; entre otras.', 'Cumplir con los requisitos de funcionamiento de los Servicios de Higiene y Seguridad en el Trabajo y de Medicina Laboral en función de la cantidad de empleados. Entre los requisitos se incluye la confección de la Política sobre Seguridad y Salud en el Trabajo, el diseño del Mapa de Riesgos, la evaluación de accidentes y agentes causantes de enfermedades profesionales y la propuesta de medidas correctivas y preventivas, la confección del Plan de Regularización de Incumplimientos, y la elaboración y ejecución del Programa anual de capacitación del personal, entre muchos otros.', 2, 'Acción', 'Si bien existe la normativa sobre “Registro Digital Único de Legajos de Salud”, la autoridad no la ha puesto en vigencia.', 'No aplica', 4, 26, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "Todos.", "custom_1783383823178": "Coordinación entre EH&S y el servicio médico (este ultimo no existe).", "custom_1784900000002": "Empleador."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece los límites máximos para las tareas de traslado de objetos pesados (Anexo I, Tabla 1), y los límites máximos  para las tareas de empuje o tracción de objetos pesados (Anexo II, Tablas 1, 2, 3 y 4). El Anexo III aprueba las definiciones utilizadas en la Resolución y sus Anexos.', 'Se debe cumplir con las normas sobre traslado, empuje o tracción de objetos pesados.', 2, 'Acción', NULL, NULL, 4, 27, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "No aplica.", "custom_1783383823178": "No existe manipulación de materiales. El servicio de logistica es subcontratado"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Clarifica los conceptos sobre sistemas de higiene personal que regula el Decreto 351/79.\nEstablece que los elementos a utilizar en la higiene personal de los trabajadores debe quedar a consideración del servicio de medicina y de higiene y seguridad de la empresa, siempre teniendo en cuenta el tipo de tareas que se desarrollan y los elementos tóxicos a los que se expone el trabajador.', 'Requiere que el servicio de medicina y de higiene y seguridad en el trabajo de la empresa determinen los elementos a utilizar para la higiene personal de los trabajadores.', 2, 'Acción', NULL, NULL, 4, 28, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Se crea, en el ámbito de la SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) el PROGRAMA NACIONAL DE PREVENCION POR RAMA DE ACTIVIDAD, en adelante “EL PROGRAMA”, cuyo objetivo principal será el desarrollo y programación de políticas activas de prevención primaria, secundaria y terciaria, de manera conjunta o independiente con las Organizaciones Empresariales, las Organizaciones Sindicales, las Administradoras de Trabajo Locales y las Aseguradoras de Riesgo de Trabajo. Sustituye el artículo 2° de la Resolución de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 770 de fecha 24 de abril de 2013, el que quedará redactado de la siguiente forma: “EL PROGRAMA” comprenderá todas las ramas de producción y servicios existentes y las que en un futuro surjan de los siguientes criterios de apertura:\na) Índices de incidencia de Accidentes de Trabajo y Enfermedades Profesionales (AT/EP) anuales por encima del promedio nacional.\nb) Actividades de importancia o relevancia económica para el país y la región.\nc) Aquellas que la SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) considere relevantes.”.\nSustituye el artículo 4° de la Resolución S.R.T. N° 770/13, el que quedará redactado de la siguiente forma: A los fines de la participación activa de los diferentes actores sociales, en el cumplimiento de los objetivos detallados en la presente resolución, se propiciará la creación de Comisiones de Trabajo para cada actividad, cuya integración se conformará con representantes de cada una de las siguientes entidades: La SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) por el ESTADO NACIONAL; los GREMIOS relacionados a la actividad por las Organizaciones Sindicales; las CÁMARAS EMPRESARIAS que correspondan por las Organizaciones de Empleadores; y las Aseguradoras de Riegos del Trabajo (A.R.T.), Empleador Autoasegurado, A.R.T. MUTUAL o la UNIÓN DE ASEGURADORAS DE RIESGOS DEL TRABAJO (U.A.R.T.) en representación del Sector Asegurador.\nEn forma complementaria se podrá convocar, con carácter de invitado, a otras entidades: Organismos Públicos nacionales, provinciales y municipales, y/o Organizaciones Privadas (Organizaciones No Gubernamentales, Colegios de Profesionales, etc.), con alcance en la temática a desarrollar en las diferentes Comisiones de Trabajo”.\nSustituye  el artículo 5° de la Resolución S.R.T. N° 770/13, el que será remplazado por el Anexo IF-2022-81238880-APN-GP#SRT “Funciones de las Comisiones de Trabajo”, el que como tal forma parte integrante de la presente resolución.', 'Tener en cuenta la posibillidad de apyo y asesoramianto para prevenir enfermedades y accidentes, como así también intervenir en comsiones de trabajo', 1, 'voluntario/instititucional', 'participar de comisiones en SRT Y mejorar el Programa', NULL, 4, 29, '{"custom_1783383400370": "Seguridad Ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "constante", "custom_1783383788609": "Todos", "custom_1783383823178": "accidentes/enfermedades"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 648);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'Norma de metrología legal, aprueba, la ampliación del alcance operativo del Servicio Argentino de Calibración y Medición (SAC) a la Norma ISO 17034, para la producción de Materiales que sean de Referencia, ello debido a la creciente demanda actual de prestación de servicios del SAC, por la que surgen requerimientos de nuevas actividades como es la producción de Materiales de Referencia, necesaria en una primera etapa en materia de Seguridad Vial, como también para la actividad institucional.\nLos materiales de referencia (MR) se utilizan en todas las etapas del proceso de medición, incluyendo la validación del método, la calibración y el control de la calidad. También se utilizan en las comparaciones interlaboratorio para la validación del método y para la evaluación de la aptitud del laboratorio.\nLa demostración de la competencia científica y técnica de los productores de materiales de referencia (PMR) es un requisito básico para asegurar la calidad de los materiales de referencia. La demanda de nuevos MR de mayor calidad está aumentando como consecuencia tanto de la mejora de la precisión del equipo de medición como por la necesidad de datos más precisos y fiables en las disciplinas científicas y tecnológicas. Es, por lo tanto, no sólo necesario para los PMR proveer información acerca de sus materiales en la forma de documentos del MR, sino también demostrar su competencia en la pro¬ducción de materiales de referencia de calidad adecuada.', 'Tener en cuenta por calibración de aparatos de medición, para la constancia de calibración que debe adjuntarse a las mediciones y estudios obligatorios que debe registrar el servicio de higiene y seguridad del trabajo', 2, 'Controlar los aparatos de medición', 'certificados de calibración', NULL, 4, 30, '{"custom_1783383400370": "Higiene y Seguridad", "custom_1783383445340": "Superintendecia de Riesgo de trabajo y autoridad de aplicación en materia laboral local", "custom_1783383763840": "cada vez que se hacen mediciones controlar que la calibración esté vigente", "custom_1783383788609": "Todos", "custom_1783383823178": "riesgos en general", "custom_1784900000002": "EHS"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 402);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Artículos 1, 2, 3, 5 y 6', 'Crea el Registro de Fabricantes, Reparadores y Recargadores de Extintores (Matafuegos) y equipos contra incendios y el Registro de Fabricantes, Reparadores e Instaladores de Instalaciones Fijas. \nRequiere que los extintores, equipos e instalaciones fijas sean fabricados, reparados, recargados e instalados por empresas registradas cumpliendo las exigencias de las Normas IRAM o de las Normas ISO o similares. Cada matafuego debe contar con una tarjeta que certifique la vigencia del matafuego, clase, capacidad, fecha de carga, fecha de vencimiento y garantía de la empresa habilitada.', 'Los equipos extintores sólo pueden ser fabricados, reparados, recargados o instalados por empresas registradas ante la DGDyPC de la CABA', 1, 'Informativo', 'Registro de mantenimiento de extintores por proveedor habilitado.', NULL, 4, 31, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Defensa y Protección al Consumidor (DGDyPC) de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Protección contra incendio.", "custom_1784900000002": "Infraestructura/Mantenimiento.  S&H de verificarlo."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1129);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1155);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Artículos 1 y 2', 'Requiere que todos los edificios a construir a partir de la entrada en vigencia de la Ordenanza, cuenten con escaleras para salidas de emergencia, con acabados y revestimientos incombustibles, caja de escalera (para edificios de 2 o más pisos), antecámara con puerta de cierre automático para acceder a la caja de escalera (para edificios de 12 mts. de altura o más), y demás requisitos constructivos del art. 1. \nLos edificios construidos con anterioridad a 1992, deberán cumplir con los requisitos del artículo 2 respecto de los medios de salida de emergencia: reemplazar los elementos combustibles por incombustibles, acreditar resistencia al fuego de las puertas que separan los pasillos de las unidades, y poseer iluminación en los medios de escape horizontales y verticales, entre otros.\nDe no poder concretarse alguno de los requisitos, deberán presentarse alternativas para el caso particular ante la autoridad competente del Gobierno de la Ciudad de Buenos Aires.', 'Edificio deberá contar con escaleras para salidas de emergencia según las especificaciones de la norma, o en su defecto deberán presentarse alternativas para el caso particular ante la autoridad competente.', 1, 'Informativo', 'Escaleras de emergencia para evacuación.', NULL, 4, 32, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Defensa y Protección al Consumidor (DGDyPC) del Gobierno la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Evacuación.", "custom_1784900000002": "Infraestructura/Mantenimiento de su realización/construcción.  S&H de verificarlo."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1127);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'La norma refiere a la “Conservación de Ascensores, Montacargas, Escaleras Mecánicas, Guarda Mecanizada de Vehículos y Rampas Móviles”. Establece que el propietario de un inmueble que cuenta con estas máquinas deberá mantenerlas en perfectas condiciones de seguridad, contratar asimismo un seguro de responsabilidad civil por potenciales daños a terceros y contratar a un profesional o empresa habilitada que sea el “Conservador” de las instalaciones, y cuya función será el cumplimiento de las normas técnicas de conservación de la instalación que se establecen en la presente. Detalla cuáles son los datos y la documentación que debe figurar en el libro de Inspecciones tanto del propietario como del “Conservador”, a su vez también, determina como debe actuar el “Conservador” en el caso de registrar algún desperfecto. Establece que el propietario debe exhibir en un lugar visible una tarjeta en la cual conste el nombre y el domicilio de la empresa responsable de la conservación y mantenimiento, el nombre y número de matrícula del representante técnico y la fecha de cada uno de los servicios prestados por el “Conservador” a la instalación durante el año.', 'Es responsabilidad del propietario o del consorcio habilitar y mantener los ascensores, montacargas, escaleras mecánicas, guarda mecanizada de vehículos y/o rampas móviles, con su correspondiente Libro de Inspección. Contar con seguro de responsabilidad civil. Contar con un Conservador. Cada ocupante deberá tener acceso a dicha información, la que podrá ser requerida por la Municipalidad ante una inspección.', 1, 'Informativo', 'Registro de mantenimiento de ascensores', NULL, 4, 33, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Registro de Obras y Catastro (DGROyC) del Gobierno de la Ciudad de Buenos Aires", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Circulación de las personas.", "custom_1784900000002": "Infraestructura."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1201);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Adhiere a lo dispuesto por el artículo 21 de la Ley 22431, modificada por Ley 24314 y decreto reglamentario 914/1997, artículos 1, 2 y 3, en lo referido al acceso y traslado de personas con necesidades especiales en ascensores. Para ascensores a instalar a partir de la entrada en vigencia de la ley, será de aplicación la normativa del artículo 1. Los ascensores instalados con anterioridad a la entrada en vigencia de la ley, y que funcionan con puertas tijeras en cabinas, deberán proceder a su reemplazo por otras que se ajusten a lo dispuesto por el artículo 1, o a su recubrimiento hasta una altura de 1,20 mts. desde el nivel del solado con material de calidad, rígido o no rígido, de acuerdo con las normas técnicas dictadas al efecto. Se exceptúan de la norma los edificios históricos.', 'De corresponder, el propietario del edificio deberá adaptar los ascensores a las  exigencias de la norma para el acceso de personas con movilidad reducida.', 1, 'Informativo', 'Rampas de acceso para discapacitados.', NULL, 4, 34, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Registro de Obras y Catastro (DGROyC) del Gobierno de la Ciudad de Buenos Aires", "custom_1783383763840": "Una vez", "custom_1783383788609": "TODOS particularmente a las personas discapacitadas para caminar.", "custom_1783383823178": "Accesos y circulación  a las personas discapacitadas.", "custom_1784900000002": "Administración"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1340);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Otorga a la Dirección General de Protección del Trabajo (DGPT) las funciones de fiscalización, control y sanción por incumplimientos de las normas relativas a la salud, higiene y seguridad en el trabajo, la seguridad social y las cláusulas normativas de los convenios colectivos de trabajo, dentro del ámbito geográfico de la Ciudad Autónoma de Buenos Aires.', 'Establece que la Dirección General de Protección del Trabajo de la CABA será la autoridad de aplicación en materia de salud, higiene y seguridad en el trabajo, tanto de las normas nacionales como locales.', 1, 'Informativo', NULL, NULL, 4, 35, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "No requiere acción."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1153);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Deroga la Ley 1346 y normas complementarias sobre "Planes de Evacuación y Simulacro ante Incendio, Explosión o Advertencia de Explosión".\nEsta ley simplifica las presentaciones de los locales o establecimientos de menos de 200 metros cuadrados, liberándolos de la necesidad de efectuar presentaciones ante Defensa Civil y así prescindir de los servicios profesionales para la presentación del Plan de Evacuación. Simplemente se prepara una declaración jurada que deberá estar disponible en el local, en la cual se declaran las condiciones de evacuación en caso de emergencia. El formulario de declaración jurada fue aprobado por Disposición DGDCIV 1358/2018.\nPor el contrario, los locales que por sus características son considerados más peligrosos, deberán elaborar un “Sistema de Autoprotección”, elaborado por un profesional previamente inscripto en el Registro de Profesionales de Sistemas de Autoprotección creado por la Ley, quien deberá indicar la cantidad de personas necesarias para coordinar la evacuación o adoptar las primeras medidas de respuesta a la emergencia. Se deberán seguir las pautas de la Ley para la preparación del Sistema de Autoprotección.', 'Simplifica presentaciones de Planes de Evacuación y Simulacro ante incendio, de establecimientos de menos de 200 metros cuadrados.', 1, 'Informativo', 'Elaboración del sistema de autoprotección e inscripción ante la autoridad', NULL, 4, 36, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Defensa Civil (DGDCIV) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "De corresponder, según plazos de la ley.", "custom_1783383788609": "TODOS", "custom_1783383823178": "Protección contra incendio y evacuación.", "custom_1784900000002": "EH&S"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1143);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Deroga el Código de Planeamiento Urbano aprobado por Ley 449 (texto consolidado por Ley 6017) y normativa reglamentaria, y aprueba un nuevo Código Urbanístico. Sin embargo, los trámites de permisos y avisos de obra iniciados con anterioridad a la entrada en vigencia del nuevo Código (27/12/2018) deberán someterse al Código de Planeamiento Urbano anterior, vigente al momento de la presentación. Asimismo, los actos administrativos dictados con anterioridad a la entrada en vigencia del nuevo Código Urbanístico, conservarán su validez por el término en el que fueron otorgados.\nEl Plan Urbano Ambiental, aprobado por Ley 2930 constituye la Ley Marco del Código Urbanístico y normas complementarias. El Código Urbanístico ordena el tejido, los usos del suelo y las cargas públicas, incluyendo los espacios públicos y privados y las edificaciones que en éstos se desarrollen, considerando las condiciones ambientales, morfológicas y funcionales de la ciudad en su totalidad. Regula además aquellos asuntos relacionados con el uso del suelo y el subsuelo, las cesiones de espacio público, el parcelamiento y la apertura de vías públicas, el sistema de movilidad, el tejido urbano y la edificabilidad, lineamientos del hábitat, reurbanización e integración socio-urbana, protección patrimonial e identidad, instrumentos de desarrollo territorial y programas de actuación urbanística, y todos aquellos aspectos que tengan relación con el ordenamiento urbanístico del territorio de la ciudad.  \nEl Título 1 establece las generalidades, principios y definiciones, incluyendo los derechos y obligaciones en materia urbanística tipos de uso, conceptos de ciudad verde y compromiso ambiental, edificabilidad, y antenas, entre otros.\nEl Título 2 se ocupa de certificados y trámites, incluyendo el Certificado de Uso Conforme, y No Conforme y el Certificado Urbanístico.\nEl Título 3 establece las normas de uso del suelo, incluyendo la instalación de antenas.\nEl Título 4 regula las cesiones de espacio público, parcelamiento y apertura de vías públicas.\nEl Título 5 se ocupa de los sistemas de movilidad, incluyendo la red vial, sistemas y modos de transporte.   \nEl Título 6 establece las normas de edificabilidad. \nEl Título 7 norma los lineamientos del hábitat.\nEl Título 8 la reurbanización e integración socio-urbana.\nEl Título 9 la protección patrimonial e identidad. \nEl Título 10 los instrumentos de desarrollo territorial y programas de actuación urbanística.', 'Deberá aplicarse el Código de Planeamiento Urbano ante cualquier construcción, modificación, ampliación, demolición o reforma edilicia. Asimismo, en caso de cambio de rubro, ampliación o anexo de rubro, o cualquier otra modificación de la habilitación existente. Prestar atención a trámites iniciados bajo el Código anterior.', 1, 'Informativo', 'Las contratistas cargan la documentación en la plataforma EHS Latam.', NULL, 4, 37, '{"custom_1783383400370": "Edificación", "custom_1783383445340": "Dirección General de Interpretación Urbanística (DGIU) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Sólo ante cambios edilicios o cambios en la habilitación.", "custom_1783383788609": "TODOS", "custom_1783383823178": "Infraestructura.", "custom_1784900000002": "Infraestructura."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1142);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Deroga el Código de Edificación aprobado por Ordenanza 34421 (texto consolidado por Ley 6017) y normativa reglamentaria, y aprueba un nuevo Código de Edificación. Sin embargo, los trámites de permisos y avisos de obra iniciados con anterioridad a la entrada en vigencia del nuevo Código (01/01/2019) deberán someterse al Código de Edificación anterior, vigente al momento de la presentación. \nEstablece los requisitos y procedimientos básicos para las etapas que componen una obra en cualquiera de sus variantes, tanto para la presentación y elaboración de su proyecto, la ejecución y fiscalización de la misma, y obligaciones y controles que hacen a la conservación. Asimismo, define los estándares constructivos, de habitabilidad, seguridad, funcionalidad, accesibilidad y sustentabilidad (incluyendo iluminación, ventilación, dimensiones de entradas, pasillos, escaleras, cajas de escaleras, rampas, medios de salida y evacuación, señalización, coeficiente de ocupación, etc.), así como también las condiciones generales para la prevención y extinción en caso de incendio. \nEl Código conforma un conjunto de definiciones, conceptos, condiciones generales y requisitos básicos que deben cumplirse en etapa de Proyecto, en el proceso de comienzo, ejecución, y finalización de la obra y en todas las presentaciones de carácter obligatorio. Es complementado por Reglamentos Técnicos. Los interesados podrán proponer técnicas alternativas, las que deberán acreditar que la solución propuesta se encuentra avalada en otras jurisdicciones nacionales o internacionales de mayor rigor normativo, demostrando a la vez la eficacia mediante métodos de verificación.\nAquellas presentaciones de solicitud de permiso de obra que incluyan ejecución de instalaciones mecánicas, eléctricas, térmicas, inflamables, elevadores, prevención de incendio, antenas y sanitarias; o ampliaciones, refacciones o transformaciones de obras ya existentes, deben cumplir los requisitos básicos contenidos en los Reglamentos Técnicos. \nEl Título 1 del Código de Edificación se aboca a las generalidades, definiciones, principios y objetivos básicos. \nEl Título 2 se refiere a los avisos y permisos de obra. \nEl Título 3 establece normas sobre arquitectura y estética urbana, incluyendo pautas sobre veredas, ochavas, cercas, fachadas, toldos, ornamentos, etc. Incluye normas sobre iluminación y ventilación, medios de salida y accesibilidad, salubridad, seguridad en la utilización, instalaciones de prestaciones y suministros (instalaciones eléctricas, termomecánicas, térmicas, de gas, etc.), y sanitarias, sistemas de seguridad contra incendios, medios mecánicos de elevación (ascensores y montacargas), etc.\nEl Título 4 se ocupa de la ejecución de las obras, las medidas de seguridad para el personal y para terceros, demoliciones, excavaciones, obradores, etc.\nFinalmente, el Título 5 regula la conservación y mantenimiento de edificios, incluyendo mantenimiento y conservación de instalaciones eléctricas, termomecánicas, electromecánicas, instalaciones contra incendio, edificios en mal estado o en ruinas, etc. Establece la obligatoriedad de conservar y mantener los inmuebles en óptimas condiciones de higiene, salubridad y seguridad.\nRequiere que una vez finalizada la obra, el constructor o profesional responsable de la obra e instalaciones registre ante la Autoridad de Aplicación la documentación completa de las características técnicas del edificio y las indicaciones para su mantenimiento, lo cual conformará el “Manual de Mantenimiento del Edificio”.   \nTanto las instalaciones eléctricas como las termomecánicas deberán ser conservadas en perfecto estado de uso, funcionamiento, seguridad, higiene, salubridad y estética, debiendo realizar verificaciones periódicas según lo establecen los Reglamentos Técnicos.\nToda instalación de ascensores, montacargas, escaleras mecánicas, caminos rodantes, rampas móviles y guarda mecanizada de vehículos debe disponer de un servicio de mantenimiento y asistencia técnica por parte de un Conservador inscripto en el Registro correspondiente. Deberá impedirse su utilización cuando las instalaciones no ofrezcan garantías de seguridad. \nTodo edificio que cuente con instalaciones térmicas deberá inscribirse en el Registro correspondiente a efectos de su certificación, conservación y mantenimiento. \nLas instalaciones contra incendio deberán ser inscriptas en el Registro correspondiente a fin de su mantenimiento.', 'El Código de Edificación rige toda construcción, modificación, refacción, ampliación o demolición edilicia.', 1, 'Informativo', 'Memoria descriptiva del proyecto de construcción o ampliación debe cumplir con el Código de Edificaciones', NULL, 4, 38, '{"custom_1783383400370": "Edificación", "custom_1783383445340": "Dirección General de Registro de Obras y Catastro (DGROyC) del Gobierno de la Ciudad de Buenos Aires", "custom_1783383763840": "Ante cambios edilicios. También de aplicación continua como complementario de las leyes de higiene y seguridad.", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de construcción e infraestructura.", "custom_1784900000002": "Infraestructura."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1205);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Regula el procedimiento por el que se otorgan permiso para desempeñarse como Foguista de Calderas a Vapor de Agua. Requiere que las calderas a vapor de agua sean puestas y mantenidas en funcionamiento por personas matriculadas como Foguistas de Calderas. Establece 3 categorías de foguistas profesionales (1ª, 2ª y 3ª categoría) y una categoría de foguista no profesional. \nQuedan exceptuadas de la reglamentación: atención de generadores con capacidad menor a 25 lt y atención de generadores con presión no mayor de 300 g/cm2\nLa atención de calderas por foguistas no matriculados dará lugar al labrado de un Acta de Comprobación a ser remitida al Tribunal de Faltas, sin perjuicio de la clausura de la instalación hasta su regularización.', 'Las calderas a vapor de agua deben ser instaladas y mantenidas en funcionamiento por foguistas matriculados, salvo que se trate de generadores con capacidad menor a 25 lt y generadores con presión no mayor de 300 g/cm2.', 1, 'Informativo', NULL, NULL, 4, 39, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "División Inspecciones Térmicas e Inflamables de la Dirección General de Fiscalización de Obras de Terceros del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Continuo"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1175);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Reglamenta la Ordenanza 40473 de creación del Registro de Fabricantes, Reparadores y Recargadores de Equipos contra incendio (Matafuegos, Extintores). Establece las especificaciones técnicas para la fabricación, reparación y recarga de equipos contra incendio, y las facultades inspectivas de la autoridad de aplicación.', 'Los equipos extintores sólo pueden ser fabricados, reparados, recargados o Instalados por empresas registradas ante la DGDyPC de la CABA', 1, 'Informativo', 'Recarga hecha por empresa habilitada.', NULL, 4, 40, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Defensa y Protección al Consumidor (DGDyPC) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Según fecha de expiración de equipos.", "custom_1783383788609": "TODOS", "custom_1783383823178": "Protección contra incendio.", "custom_1784900000002": "Administración / Field Operations"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1181);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Reglamenta la Ordenanza 49308 de Conservación de Ascensores, Montacargas, Escaleras Mecánicas, Guarda Mecanizada de Vehículos y Rampas Móviles. \nEstablece que el mantenimiento de ascensores, montacargas, escaleras mecánicas y rampas móviles deberá realizarse por profesionales habilitados denominados “Conservadores”. El Libro de Inspección de “Conservación de Instalaciones” del Código de Edificación deberá contener las características y requisitos del Anexo II del Decreto. El expediente de conservación (uno por cada inmueble) servirá para el trámite inicial de presentación y para toda gestión a futuro. En casos de reformas, ampliaciones o modificaciones de los ascensores y montacargas, deberá iniciarse un nuevo expediente. \nA los efectos de su verificación, deberá presentarse copia del “Certificado de Habilitación” de las instalaciones para tramitar el “Permiso de Conservación”. En caso de instalaciones nuevas, el expediente de conservación deberá ser presentado dentro de los 30 días de obtenido el Certificado de Habilitación de las instalaciones. \nEn caso de cambio de Conservador, el responsable deberá efectuar la comunicación fehaciente a la Autoridad de Aplicación. A tal efecto, el Decreto crea el Registro de Conservadores en el ámbito de la Dirección General de Fiscalización de Obras y Catastro. \nLos Conservadores deberán presentar anualmente el listado de máquinas por ellos mantenidas, indicando si las mismas poseen libro de conservación, su número de expediente y su habilitación correspondiente. \nEn caso de urgencia o accidente, el responsable deberá informar al Conservador por escrito, y arbitrar los medios que permitan el acceso del Conservador, durante las 24 horas.\nLa Tarjeta de Control de Conservación (Anexo V) deberá exhibirse en lugar visible de la cabina del ascensor, receptáculo del montacargas, inmediatez de la escalera mecánica, guarda mecanizada de vehículo o rampa móvil.\nEs obligatorio el uso de la Tarjeta de Control de Seguridad con sus correspondientes Rótulos (indican el nivel de seguridad a través de su color), para identificar el estado de utilización de ascensores, montacargas, escaleras mecánicas, guarda mecanizada de vehículo y rampas móviles.  \nEl Anexo IV del Decreto establece las normas de seguridad e higiene que deberá aplicar el Conservador, incluyendo la sectorización del área de trabajo y la colocación de carteles de advertencia.', 'Es responsabilidad del propietario o del consorcio habilitar y mantener los ascensores, montacargas, escaleras mecánicas, guarda mecanizada de vehículos y/o rampas móviles, con su correspondiente Libro de Inspección. Contar con seguro de responsabilidad civil. Contar con un Conservador. Cada ocupante deberá tener acceso a dicha información, la que podrá ser requerida por la Municipalidad ante una inspección.', 1, 'Informativo', 'Registro de mantenimiento de ascensores', NULL, 4, 41, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Registro de Obras y Catastro (DGROyC) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Circulación del personal.", "custom_1784900000002": "Infraestructura."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1179);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Requiere que todas las instalaciones sanitarias internas nuevas, ampliaciones o modificaciones de las existentes sean registradas previo a su comienzo ante el Gobierno de la Ciudad Autónoma de Buenos Aires. Establece el procedimiento para su registro y aprobación.', 'Toda instalación sanitaria interna nueva debe ser registrada ante la autoridad del GCBA', 1, 'Informativo', NULL, NULL, 4, 42, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Registro de Obras y Catastro (DGROyC) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Ante la construcción de instalaciones sanitarias nuevas"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1178);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece que los cronogramas de los Planes de Evacuación y Simulacro deberán ser presentados para su aprobación ante la Autoridad de Aplicación, y efectuados dentro del año de su aprobación. Los establecimientos que la Autoridad indique, deberán prever en sus cronogramas la realización de 3 prácticas de simulacro dentro del año de su aprobación.\n Se definen los términos grave riesgo, emergencia, catástrofe, simulacro y simulación.', 'Presentar los Cronogramas de los Planes de Evacuación y Simulacro ante la Dirección General de Defensa Civil del GCBA. Realizar las prácticas de simulacros que la autoridad indique.', 2, 'Acción', 'Plan de Simulacros\nInforme de simulacros realizados', NULL, 4, 43, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Defensa Civil (DGDCIV) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Anual", "custom_1783383788609": "TODOS", "custom_1783383823178": "Evacuación.", "custom_1784900000002": "S&H"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1180);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Reglamenta la Ley 5920 de Sistemas de Autoprotección. Establece que el “Sistema de Autoprotección" se formule de acuerdo a parámetros de riesgo en función del destino o uso del establecimiento, superficie y características edilicias. Requiere que la práctica de los simulacros se realice al menos 4 veces al año, siendo coordinadas por la Autoridad de Aplicación.', 'Realizar prácticas de simulacros al menos 4 veces al año.', 2, 'Acción', 'Plan de Simulacros\nInforme de simulacros realizados', NULL, 4, 44, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Defensa Civil (DGDCIV) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Cuatrimestral", "custom_1783383788609": "TODOS", "custom_1783383823178": "Evacuación.", "custom_1784900000002": "S&H"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Artículos 1, 2 y 3', 'Presentación de Planos de Condiciones contra Incendio ante Nuevas Obras: Se deberán presentar dos copias heliográficas del Plano de Proyecto y el Certificado de Uso Conforme a fin de obtener un número de expediente y el “visado previo”. El plano visado se adjuntará a la documentación requerida para tramitar permisos de obra conforme el Código de Edificación (art. 4.12.1.3.). Dentro del plazo de 30 días, se deberá presentar el Plano de Condiciones contra Incendio para su registro ante la Autoridad Competente, bajo responsabilidad el profesional interviniente. \nEl incumplimiento implicará la paralización de las obras y la aplicación de sanciones al profesional actuante.', 'Ante nuevas obras, presentar los Planos de Condiciones contra Inendio', 1, 'Informativo', 'Planos del sistema contra incendios de las nuevas obras o proyectos', NULL, 4, 45, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Registro de Obras y Catastro (DGROyC) de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Ante nuevas obras.", "custom_1783383788609": "TODOS", "custom_1783383823178": "Evacuación.", "custom_1784900000002": "Planning Infraestructura"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Artículo 1', 'Requiere que los profesionales intervinientes en la elaboración del plan de evacuación y simulacro en caso de incendio, explosión o advertencia de explosión, presenten la encomienda profesional extendida por el colegio o consejo profesional correspondiente.', 'Profesionales que elaboren los Planes de Evacuación y Simulacro deben presentar encomienda profesional extendida por el Colegio o Consejo Profesional', 1, 'Informativo', 'No se pudo verificar.', NULL, 4, 46, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Fiscalización de Obras y Catastro (DGFOyC) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "A realizarlo por el profesional", "custom_1783383788609": "TODOS", "custom_1783383823178": "Evacuación.", "custom_1784900000002": "Infraestructura."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece que si el resultado de la auditoría del Conservador no fuera el esperado, deberá realizarse la denuncia correspondiente ante la Dirección General de Fiscalización de Obras y Catastro a fin de que ésta realice una inspección e intime al propietario para que, dentro de los 2 días contados desde la fecha de inspección, intime al Conservador que se presente ante el Departamento de Elevadores a fijar fecha y hora para una nueva inspección conjunta. \nUna vez recibida la intimación, el propietario deberá interrumpir el uso del artefacto hasta tanto se encuentre en condiciones. El incumplimiento con esta norma dará lugar a la clausura de la instalación.', 'En caso de que la auditoría de ascensores efectuada por el Conservador arroje un resultado negativo, deberá seguirse el procedimiento de denuncia ante la Dirección General de Fiscalización de Obras y Catastro del GCBA', 1, 'Informativo', 'Registro de habilitación de profesional que firma plan de evacuación', NULL, 4, 47, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Registro de Obras y Catastro (DGROyC) del Gobierno de la Ciudad de Buenos Aires", "custom_1783383763840": "Responsabilidad del propietario o consorcio", "custom_1783383788609": "TODOS", "custom_1783383823178": "Circulación del personal.", "custom_1784900000002": "EH&S"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Al inicio de todo tipo de obra, los empleadores de la construcción deberán presentar ante la Dirección General de Protección del trabajo, vía correo electrónico a unidadtecnica@buenosaires.gob.ar, constancia de presentación ante la ART del aviso de inicio de obra. Además, deberán exhibir junto al cartel de obra exigido por el Código de Edificación, un cartel de inspecciones (según modelos de los Anexos I y II de la Resolución) donde los inspectores de la Dirección General de Protección del Trabajo dejarán constancia del número de acta y fecha de cada inspección que se realice durante el transcurso de la obra, mediante el estampado de un sticker por cada inspección según modelo del Anexo III.', 'Al inicio de todo tipo de obra, presentar ante la Dirección General de Protección del Trabajo del GCBA la constancia de presentación ante la ART del inicio de obra. Exhibir los carteles reglamentarios de obras y de inspección.', 2, 'Acción', 'Constancia de presentación ante la ART del inicio de obra', NULL, 4, 48, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Al inicio de nuevas obras.", "custom_1783383788609": "Obras de construcción", "custom_1783383823178": "Condiciones de construcción e infraestructura.", "custom_1784900000002": "Infraestructura."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Los empleadores de la construcción deberán exhibir junto al cartel de obra exigido por el Código de Edificación, y junto al cartel de inspecciones (Resolución SSTR 6019/2012), un cartel de prevención conteniendo la obligatoriedad de uso de los elementos de protección personal y los riesgos a los que se encuentran expuestos los trabajadores de obra, según modelo del Anexo I de la Resolución.\nLa entrega de los carteles se efectuará a todas las obras registradas en el Sistema de Gestión de Riesgo de Trabajo “Matriz” de la Subsecretaría de Trabajo, Industria y Comercio de la Ciudad Autónoma de Buenos Aires.\nLos empleadores deberán ingresar en el sitio web  http://dgpdt.buenosaires.gob.ar el domicilio de la obra y retirar el cartel en las oficinas de la Dirección General de Protección del Trabajo, en el plazo de 48 hs. de registrada la obra.', 'Exhibir el cartel de prevención sobre obligatoriedad de uso de elementos de protección personal (EPP) y los riesgos del trabajo en obra. Gestionar el cartel online y retirarlo en la Dirección General de Protección del Trabajo', 2, 'Acción', 'Cuenta con cartelería.', NULL, 4, 49, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Subsecretaría de Trabajo, Industria y Comercio (SSTIyC) del gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Al inicio de nuevas obras.", "custom_1783383788609": "Obras de construcción", "custom_1783383823178": "Condiciones de EH&S  de construcciones.", "custom_1784900000002": "Infraestructura."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Artículos 1 y 2', 'Faculta a la Autoridad de Aplicación a evaluar y registrar los planos de prevenciones contra incendio en los que se proyecten instalaciones de presurización de cajas de escaleras como complemento solución alternativa a la disposición de antecámara para el acceso a las mismas. La instalación que se proyecte deberá cumplir con los requisitos del art. 2.', 'Establece normas para la registración de los Planos de Prevenciones contra Incendio en los que se proyecten instalaciones de presurización de cajas de escaleras.', 2, 'Acción', NULL, NULL, 4, 50, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Registro de Obras y Catastro (DGROyC) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Ante la registración de un Plano de Prevención de Incendio"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece el procedimiento administrativo para la obtención de rótulos para Tarjetas de Control de Seguridad de Ascensores, cuyo uso es obligatorio. El trámite será llevado a cabo por la Empresa Conservadora.', 'Establece el trámite para la obtención de rótulos para Tarjetas de Control de Seguridad de Ascensores, que son obligatorios.', 2, 'Acción', 'Oblea de control', NULL, 4, 51, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Registro de Obras y Catastro (DGROyC) de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Una vez", "custom_1783383788609": "TODOS", "custom_1783383823178": "Protección contra incendio", "custom_1784900000002": "Infraestructura."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece el procedimiento administrativo para solicitar las Tarjetas de Control de Seguridad y Control de Conservación de Ascensores, cuyo uso es obligatorio. El trámite deberá ser llevado a cabo por el Propietario del inmueble, su Apoderado o el Administrador del Consorcio.', 'Establece el trámite para la obtención de las Tarjetas de Control de Seguridad y Control de Conservación de Ascensores.', 2, 'Acción', 'Oblea de control', NULL, 4, 52, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Registro de Obras y Catastro (DGROyC) de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Una vez", "custom_1783383788609": "TODOS", "custom_1783383823178": "No aplica.", "custom_1784900000002": "Infraestructura."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Requiere que en las presentaciones donde se solicite permiso para efectuar instalaciones mecánicas, eléctricas, térmicas, inflamables, de ascensores, de prevenciones contra incendio, de antenas y sanitarias, y de ampliar, refaccionar o transformar las ya existentes, se presente el Certificado de Encomienda de Tareas Profesional, extendido por el Consejo Profesional respectivo.', 'Los ensayos, estudios y presentaciones efectuadas por profesionales deberán encontrarse visadas por el Colegio Profesional respectivo', 1, 'Informativo', 'No disponible.', NULL, 4, 53, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Registro de Obras y Catastro (DGROyC) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "A cumplir por el profesional", "custom_1783383788609": "TODOS", "custom_1783383823178": "Infraestructura.", "custom_1784900000002": "Infraestructura."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece que el área Laboratorio de Ensayos de Materiales, dependiente de la Dirección General de Defensa y Protección al Consumidor, es la autoridad responsable de la guarda, custodia y expendio de las tarjetas y etiquetas identificatorias de extintores (matafuegos).', 'Las tarjetas y etiquetas identificatorias de extintores serán expedidas por la Dirección General de Defensa y Protección del Consumidor', 1, 'Informativo', NULL, NULL, 4, 54, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Defensa y Protección al Consumidor (DGDyPC) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "No requiere acción"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Requiere la obtención de habilitación o permiso para el ejercicio de toda actividad comercial o industrial en la Ciudad de buenos Aires. Las actividades habilitadas deberán ajustarse a los Códigos de Planeamiento Urbano, de Edificación y de Habilitación, y demás reglamentaciones.\nRequiere que los Planes de Evacuación y Simulacro sean presentados por escrito ante la Dirección General de Defensa Civil, cumpliendo con los requisitos del artículo 1, los que incluyen la presentación de un Plano de Evacuación y un Cronograma de Prácticas de Simulacros, entre otros. \nEstablece los requisitos para las renovaciones de los planes de Evacuación y Simulacro. \nEstablece que los Planes presentados tendrán una validez de 2 años.', 'Requiere habilitación para el ejercicio de toda actividad comercial o industrial.', 1, 'Informativo', 'Registro de habilitación', NULL, 4, 55, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Defensa Civil (DGDCIV) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Protección contra incendio y evacuación.", "custom_1784900000002": "EH&S"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Requiere que todos los edificios de la Ciudad de Buenos Aires cuenten con elementos de protección personal contra incendios, específicamente con máscaras de escape y protección respiratoria, en número suficiente. Dichos elementos deberán contar con la homologación expedida por el Laboratorio de Ensayo de Materiales de la Dirección General de Defensa y Protección del Consumidor. \nLa fiscalización del cumplimiento de las obligaciones de la Disposición estará a cargo del área Fuego dependiente de la Coordinación de Inspecciones.', 'Contar en el edificio con los elementos de protección personal contra incendios, homologados por el Laboratorio de Ensayo de Materiales de la Dirección General de Defensa y Protección del Consumidor del GCBA.', 1, 'Informativo', 'Actas de entrega de Elementos de protección personal contra incendios', NULL, 4, 56, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Defensa y Protección al Consumidor (DGDyPC) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Protección contra incendio y evacuación.", "custom_1784900000002": "Infraestructura."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'art. 64 y siguientes del decreto 351/79', '.Los establecimientos en los que se realicen actividades laborales, deberán ventilarse preferentemente en forma natural. La ventilación mínima de los locales, determinado en función del número de personas, será la establecida en la siguiente tabla:\nVentilación mínima requerida en función del número de ocupantes.\nPara actividad sedentaria\na. Cantidad de personas: 1 \nb. Cubaje del local en metros cúbicos por persona: 3 / 6 / 9/12/15\nc. Caudal de aire necesario en metros cúbicos por hora y por persona : 43/ 29/ 21/15/12', 'Deben realizarlo y revisarlo anualmene,', 2, 'Acción', NULL, NULL, 4, 57, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "Todos los años", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo e infraestructura.", "custom_1784900000002": "Responsable de H&S"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 50);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1672);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Ley de Riesgos del Trabajo. Esta norma establece la obligación de encontrarse Autoasegurado o bien contar con una ART. Contiene obligaciones tanto para los empleadores como para las Aseguradoras.', 'Poseer contrato con ART O BIEN SER AUTOASEGURADA, y Realizar el relevamineto anual de agentes de riesgo RAR', 2, 'Acción', NULL, NULL, 4, 58, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo/Riesgo del Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1784900000002": "ART"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1693);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 2323);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba el “Procedimiento para la Comprobación y Juzgamiento de Infracciones y Ejecución de las Sanciones de Multa en el marco de la Ley N° 24.557 y sus normas complementarias y reglamentarias”, que como Anexo I IF-2026-45332397-APN-SRT#MCH forma parte integrante de la presente resolución.\nAprueba los modelos de “Certificado de Deuda con el Fondo de Garantía -artículo 46 de la Ley N° 24.557-”, que como Anexo II IF-2026-45335381-APN-SRT#MCH forman parte integrante de la presente resolución.', 'Cumplir con los establecido en las normas para no ser sancionados', 2, NULL, NULL, NULL, 4, 59, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo/Riesgo del Trabajo", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1427);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Extiende el ámbito de aplicación de la Ley de Riesgos del Trabajo N° 24.557, sus modificatorias y complementarias a los trabajadores asociados y las trabajadoras asociadas en Cooperativas de Trabajo previstas en la Ley de Cooperativas N° 20.337 y su modificatoria. Esta extensión quedará condicionada a que la propia cooperativa solicite su inclusión en dicho régimen respecto de sus asociados y asociadas.\nLa decisión de contratar la cobertura mediante un seguro de riesgos del trabajo será adoptada por la asamblea de socios y socias de la Cooperativa de Trabajo, conforme las formalidades y condiciones dispuestas por la Ley N° 20.337, sus normas complementarias y los estatutos cooperativos.', 'Tener en cuenta por contratistas para la exigencia de ART a las cooperativas', 2, 'obligatoria para cooperativas. Ver contratistas', 'Contratar ART.', NULL, 4, 60, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo/Riesgo del Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "constante", "custom_1783383788609": "todos", "custom_1783383823178": "Riesgos de trabajo"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1968);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'La presente ley tiene por objeto incorporar al Programa Médico Obligatorio (PMO) de las Obras Sociales Nacionales, un protocolo para el abordaje integral de personas víctimas de violencia de género a través de la cobertura total e integral de las prácticas preventivas y terapéuticas. Inclúyanse todas las terapias médicas, psicológicas, psiquiátricas, farmacológicas, quirúrgicas, y toda otra atención que resulte necesaria o pertinente.\nLas obras sociales, los prestadores de salud y todos aquellos organismos comprendidos en la presente ley, deberán articular con las instancias nacionales, provinciales y/o locales que provean programas para la atención de la violencia de género a los fines de garantizar que la atención integral de las víctimas se realice con los parámetros y las indicaciones adecuadas.', ': Tener en cuenta por las prestaciones médicas que debe prestar el servicio médico, incorporar temas de violencia de género y derivarlos a las mutuales', 2, 'Obligatoria', NULL, NULL, 4, 61, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo/Riesgo del Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "constante", "custom_1783383788609": "todos", "custom_1783383823178": "Violencia de género"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1705);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todps', 'Declara el día 13 de septiembre como el “Día de la implementación del Sistema de Riesgos del Trabajo en la REPÚBLICA ARGENTINA”, en conmemoración a la fecha de sanción de la Ley N° 24.557 y establece ese día como día no laborable para los empleados de la SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.).', '13 de septiembre de cada año  día no laborable para los empleados de la SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.)', 1, 'indicativa/institucional', NULL, NULL, 4, 62, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo/Riesgo del Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "anual", "custom_1783383788609": "Todos", "custom_1783383823178": "Tener en cuanta que es un día no laborable para la SRT"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1694);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Poseer servicio de higiene, seguridad y riesgo del trabajo. Establece las funciones que deberán desarrollar los Servicios de Higiene y Seguridad en el Trabajo y de Medicina del Trabajo en los plazos que determine oportunamente la S.R.T.,  considerando el riesgo propio de la actividad, el tamaño de la empresa y la inclusión en los planes de focalización de la S.R.T.\nSe aprueban por la misma: las “Funciones Conjuntas de Ambos Servicios” , las “Funciones del Servicio de Higiene y Seguridad en el Trabajo” y las “Funciones del Servicio de Medicina del Trabajo”.\nAsimismo se crea el “Registro Digital Único de Legajos de Salud” que se integrará con la información suministrada por los Servicios de Medicina del Trabajo de los establecimientos y las Aseguradoras de Riesgos del Trabajo (A.R.T.) de acuerdo a las pautas que determinará la S.R.T. Esta información será visualizada solamente por la S.R.T., y será suministrada al trabajador a su requerimiento.', 'Poseer servicio de higiene y segurdad, y medicina laboral. Deben tener tmabién un plan de capacitaciones anual en higienen y seguridad y medicina laboral, señalizaciones controlar,', 2, 'Acción', NULL, NULL, 4, 63, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "Todos los años", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo e infraestructura.", "custom_1784900000002": "Responsable de H&S"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 630);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Art. 159  Decreto N° 351/1979', 'Cuando el trabajador entre a un espacio confinado a través de un agujero de hombre u otra pequeña abertura, se lo proveerá de cinturón de seguridad y cable de vida, debiendo haber un observador en el exterior durante el lapso que dure la tarea. Cuando se interrumpan los trabajos se deberán retirar los sopletes del interior del lugar.', 'Control del cable de vida', 2, 'Acción', NULL, NULL, 4, 64, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "Todos los años", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo e infraestructura.", "custom_1784900000002": "Responsable de H&S"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 50);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1672);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Esta Resolución aprueba el Protocolo para medición del valor de puesta a tierra y verificación de la continuidad de las masas en el aire del ambiente de trabajo, con validez por 12 meses. Por ello anualmente debe realizarse esa medición en forma obligatoria.', 'Medir puesta a tierra y continuidad. Todos los tableros deben poseer cartelería reglmantaria', 2, 'Acción', NULL, NULL, 4, 65, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "Todos los años", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo e infraestructura.", "custom_1784900000002": "Responsable de H&S"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 631);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Se adopta el “Reglamento para la Ejecución de Trabajos con Tensión en Instalaciones Eléctricas con tensión menor o igual a UN KILOVOLTIO (1 kV)”, de acuerdo al documento Nº 95.705 —edición 01 de junio de 2013— elaborado por el Comité de Estudios Nº 53 de la ASOCIACION ELECTROTECNICA ARGENTINA (A.E.A). Se establece la obligatoriedad para los empleadores que desarrollen trabajos con tensión, de poner a disposición de las comisiones de higiene y seguridad, constituidas en los casos y con las modalidades que determine el Convenio Colectivo de Trabajo respectivo, los Planes de Capacitación en materia de trabajos con tensión que se desarrollen para la habilitación de los trabajadores que realicen dichas tareas.', 'Cumplir en caso de que se realicen trabajos con tensión. Chequeos médicos a personal que realice la tarea y entrega de crededenciales, según sea quien dirija y ejecute el trabajo conforme su capacitación. Capacitaciones periódicas', 2, 'Acción', NULL, NULL, 4, 66, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "Cada 2 años se entrega la credencial a quienes realizan el trabajo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Infraestructura.", "custom_1784900000002": "Infraestructura."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba el “Reglamento para la Ejecución de Trabajos con Tensión en Instalaciones Eléctricas Mayores a UN KILOVOLT (1 kV)”, elaborado por la Asociación Electrotécnica Argentina (A.E.A.) -Comisión Nº 21, edición 2020-, como Anexo IF-2022-18125137-APN-GP#SRT.\nEstablece la obligatoriedad para los empleadores que desarrollen trabajos con tensión, de poner a disposición de las comisiones de higiene y seguridad constituidas en los casos y con las modalidades que determine el convenio colectivo de trabajo respectivo, los Planes de Capacitación en materia de trabajos con tensión que se desarrollen para la habilitación de los trabajadores que realicen dichas tareas.\nDeroga la Resolución de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO Nº 592 de fecha 2 de julio de 2004.\nLa presente medida entrará en vigencia a partir de los NOVENTA (90) días corridos contados desde la fecha de publicación en el Boletín Oficial.', 'Cumplir con el reglamento si realizan trabajos con tensión mayor a 1kV.', 2, 'Acción', NULL, NULL, 4, 67, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "Cada 2 años se entrega la credencial a quienes realizan el trabajo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Infraestructura.", "custom_1784900000002": "Infraestructura."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 420);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'Ratifica la entrada en vigencia conforme al plazo estipulado en el Artículo 2° de la Resolución Nº 247 de fecha 22 de mayo de 2019 de la SECRETARÍA DE COMERCIO INTERIOR del ex MINISTERIO DE PRODUCCIÓN Y TRABAJO y su modificatoria (mediante la cual, entre otras cuestiones, se aprobó el “Reglamento Técnico y Metrológico para los Medidores de Energía Eléctrica en Corriente Alterna”), para aquellos instrumentos que cuentan con su respectivo Certificado de Aprobación de Modelo, a partir del día 31 de diciembre de 2021.\nEstablece un Régimen Transitorio de Aprobación de Modelo en Curso hasta el día 31 de diciembre de 2022, para aquellos instrumentos incluidos en el alcance de la Resolución N° 247/19 de la SECRETARÍA DE COMERCIO INTERIOR y su modificatoria, que se encuentran en cualquier instancia posterior a la apertura fehaciente de la Orden de Trabajo (OT) en el INSTITUTO NACIONAL DE TECNOLOGÍA INDUSTRIAL (INTI), organismo descentralizado en el ámbito del MINISTERIO DE DESARROLLO PRODUCTIVO, y no cuenten con certificado de aprobación de modelo a partir del día 1° de enero de 2022.\nSe entenderá por apertura fehaciente de Orden de Trabajo (OT), aquellos casos que se haya notificado por el INSTITUTO NACIONAL DE TECNOLOGÍA INDUSTRIAL (INTI), a la firma recurrente y a la Dirección de Inspecciones dependiente de la Dirección Nacional de Gestión Comercial Interna de la SUBSECRETARÍA DE ACCIONES PARA LA DEFENSA DE LAS Y LOS CONSUMIDORES de la SECRETARÍA DE COMERCIO INTERIOR del MINISTERIO DE DESARROLLO PRODUCTIVO, de dicha apertura, aplicable también a los casos en que la Orden de Trabajo (OT) fuera abierta con anterioridad a la publicación de la presente resolución.', 'Tener en cuenta los aparatos de medición y certificaciones para mediciones de energía eléctrica en corriente alterna', 2, 'obligatoria', NULL, NULL, 4, 68, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "Cada vez que se realicen mediciones", "custom_1783383788609": "Toda la planta", "custom_1783383823178": "elctricidad /mantenimiento"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 416);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'Se establece un nuevo programa de prevención específico para Pequeñas y Medianas Empresas (PyMES), el que se denominará “Programa de Prevención para Empleadores PyMES con Siniestralidad Elevada (P.E.S.E.-PyMES)”, mediante el cual se dirigirán acciones preventivas de los riesgos derivados del trabajo para el segmento de empleadores que cumpla con las condiciones de ingreso fijadas en la resolución, con la finalidad de disminuir la siniestralidad laboral y mejorar las condiciones de salud y seguridad en el ambiente de trabajo.', NULL, 2, NULL, NULL, NULL, 4, 69, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 592);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'Sustituye el último párrafo del artículo 5° del Anexo I de la Resolución de la SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 20 de fecha 09 de marzo de 2018, el que quedará redactado de la siguiente manera:\n“Se establece que la Gerencia de Prevención, conforme las facultades asignadas por el artículo 3° de la presente resolución, consignará el porcentaje de comparación establecido para considerar el ingreso de un empleador a la Muestra, dentro de un rango definido entre un mínimo de VEINTE POR CIENTO (20 %) y un máximo de TRESCIENTOS POR CIENTO (300 %).”.\nSustituye el punto 4, del inciso b) del artículo 6° del Anexo I de la referida Resolución S.R.T. N° 20/18, el que quedará redactado de la siguiente manera:\n“4) La suma de los valores correspondientes a los incisos 1 a 3 se ponderará considerando el lapso de cobertura respecto del período de evaluación anual establecido. A los fines del cómputo de dichos valores, la sumatoria de accidentes de trabajo con más de DIEZ (10) días de baja laboral, la totalidad de las enfermedades profesionales registradas y las secuelas incapacitantes por Accidentes de Trabajo no incluidas en el punto b) 1) -excluido el estrés postraumático-, se comenzará a considerar a partir del segundo evento registrado.”.', 'Se modifican los porcentajes de comparación establecido para considerar el ingreso de un empleador a la Muestra, por accidentes y enfermedades.', 2, NULL, NULL, NULL, 4, 70, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO - GERENCIA DE PREVENCIÓN"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 55);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'CAPÍTULO XV: \n\nMÁQUINAS Y HERRAMIENTAS', 'Controlar su estado', 'Registrar controles', 2, 'Acción', NULL, NULL, 4, 71, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "Todos los años", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo e infraestructura.", "custom_1784900000002": "Responsable de H&S"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 50);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1672);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Inscripción en el registro. Se crea en el ámbito de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) el Sistema de Vigilancia y Control de Sustancias y Agentes Cancerígenos, en adelante S.V.C.C..\nSe aprueba el “Listado de Sustancias y Agentes Cancerígenos” como Anexo I; el “Procedimiento para informar la presencia de Sustancias y Agentes Cancerígenos” como Anexo II; el “Listado de Códigos de Agentes de Riesgo” como Anexo III.\nSe establece la obligatoriedad de la inscripción en el S.V.C.C. de todos los empleadores que en sus establecimientos produzcan, importen, utilicen, obtengan en procesos intermedios, vendan y/o cedan a título gratuito las sustancias o agentes que se enumeran en el Anexo I IF-2019-87690501-APN-GP#SRT de la presente, así como todos aquellos que en función de sus procesos productivos, actividades económicas o con motivo de circunstancias medioambientales, estén alcanzados por las previsiones del Anexo II.', 'DDJJ Anual', 2, 'Acción', NULL, NULL, 4, 72, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "Todos los años", "custom_1783383788609": "sectores donde se poseen o manipulan", "custom_1784900000002": "Responsable de H&S"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Resolución 861/2015 mod por Res. 739/2017 SRT Se aprueba para Medición de Contaminantes Químicos en el Aire de un Ambiente de Trabajo, un protocolo con validez por 12 meses. Por ello anualmente debe realizarse esa medición en forma obligatoria.La Res, 739/17 aclara varios puntos para medir con el protocolo legal y volcar los datos en el mismo\n Medir cada 12 meses con protocolo legal', 'Medir con protocolo legal', 2, 'Acción', NULL, NULL, 4, 73, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "Todos los años", "custom_1783383788609": "sectores donde se generan (hidrógeno en sala de baterías)", "custom_1784900000002": "Responsable de H&S"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 632);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 603);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Anexo III, punto 20.3.3.', 'Botiquines. Lo básico que debe contener conforme página de la SRT, https://www.argentina.gob.ar/salud/primerosauxilios/botiquin: \n\nElementos básicos a poseer en el botiquín:\nGuantes descartables de látex para no contaminar heridas y para seguridad de la persona que asiste a la víctima.\nGasas y vendas limpias (de 7 y 10 cm. de ancho) para limpiar heridas y detener hemorragias.\nApósitos estériles para limpiar y cubrir heridas abiertas.\nCinta adhesiva para fijar gasas o vendajes.\nTijera para cortar gasas y vendas o la ropa de la víctima.\nAntisépticos, yodo povidona, agua oxigenada (de 10 volúmenes) o alcohol para prevenir infecciones.\nJabón neutro (blanco) para higienizar heridas.\nAlcohol en gel y líquido para higienizar las manos.\nEl botiquín no tiene que incluir medicamentos, para no favorecer la automedicación.\nLos botiquines están provistos de todos los elementos solicitados por el Ministerio de Salud en conjunto con la SRT, excepto el jabón neutro.', 'Deben controlar que los botiquines estén completos y poeer desfibrilador', 2, 'Accion', NULL, NULL, 4, 74, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo y Salud Ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "constante", "custom_1783383788609": "Todos los botiquines", "custom_1783383823178": "Condiciones de trabajo", "custom_1784900000002": "Responsable de H&Sy Medicina laboral"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 628);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos', 'Deroga la “GUÍA PARA LA SELECCIÓN DE MEDICAMENTOS PARA UN BOTIQUÍN TOXICOLÓGICO DE EMERGENCIA”, aprobada por Resolución Nº 99 del 29 de febrero de 1996 de la ex SECRETARÍA DE RECURSOS Y PROGRAMAS DE SALUD del MINISTERIO DE SALUD.\nY aprueba el documento titulado “BOTIQUÍN TOXICOLÓGICO” que como Anexo (IF-2023-95458889-APN-DNCSSYRS#MS) forma parte integrante de esta Resolución.', 'Deben controlar que los botiquines estén completos y poeer desfibrilador', 2, 'Accion', NULL, NULL, 4, 75, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo y Salud Ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "constante", "custom_1783383788609": "Todos los botiquines", "custom_1783383823178": "Condiciones de trabajo", "custom_1784900000002": "Responsable de H&Sy Medicina laboral"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 349);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'La norma establece la obligación de instalar Desfibriladores Externos Automáticos (DEA) y capacitar para su uso en los espacios públicos y privados de acceso público, como establecimientos deportivos y culturales, centros religiosos, casinos, bancos y lugares de trabajo con más de 1.000 empleados. La reglamentación de la Ley 27.159 a través del Decreto 402/2022 regula un sistema de prevención integral de eventos por muerte súbita y establece la obligación para los espacios públicos y privados de acceso público, como establecimientos deportivos y culturales, centros religiosos, casinos, bancos y lugares de trabajo con más de 1.000 empleados, de instalar Desfibriladores Externos Automáticos (DEA) así como la capacitación para el uso de este dispositivo.\nAsimismo, establece la creación de un "Registro de Desfibriladores Externos Automáticos", que funcionará en el ámbito del Programa Nacional de Prevención de las Enfermedades Cardiovasculares, que funciona desde junio de 2011. En cuanto a la responsabilidad la norma establece que ninguna persona interviniente que haya obrado de acuerdo con las disposiciones de la presente ley, está sujeta a responsabilidad civil, penal, ni administrativa, derivadas del cumplimiento de la misma. Así lo definido respecto de la responsabilidad, hayan adherido o no las Pcias. a la norma  resulta  aplicable el artículo 11 porque modifica los códigos de fondo (Civil y Penal) en cuanto a la eximición de responsabilidad por muertes súbitas cuando se usa el desfibrilador (DEA)\nEl objeto de la norma  es regular un sistema de prevención integral de eventos por muerte súbita en espacios públicos y privados de acceso público a fin de reducir la morbimortalidad súbita de origen cardiovascular.\n\n \n\nLa norma define espacios públicos y privados de acceso público: lugares públicos y sedes de lugares privados, cuyo volumen de tránsito y permanencia de personas se determinará de conformidad a lo que disponga la autoridad de aplicación en coordinación con las jurisdicciones', 'Poseer desfibrilador y capacitar anualmente para su uso.', 2, 'Acción', 'capacitaciónes y poseer el defibrilador', NULL, 5, 76, '{"custom_1783383400370": "SALUD OCUPACIONAL", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "Constante", "custom_1783383788609": "Todos", "custom_1783383823178": "Paro cardíaco"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprobación del Protocolo para la Medición del nivel de Ruido en el Ambiente Laboral, que como Anexo forma parte integrante de la presente resolución, y que será de uso obligatorio para todos aquellos que deban medir el nivel de ruido conforme con las previsiones de la Ley de Higiene y Seguridad en el Trabajo Nº 19.587 y sus normas reglamentarias.', 'Las mediciones de ruido deberán ser efectuadas siguiendo el protocolo. Los valores de las mediciones plasmadas en los formularios, poseerán una validez de 12 meses.', 2, 'Accion', 'Todo el sitios', NULL, 4, 77, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "Anual", "custom_1783383788609": "Todo el sitio", "custom_1783383823178": "Condiciones de trabajo", "custom_1784900000002": "Higiene y Seguridad"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprobación del Protocolo para la Medición de la Iluminación en el Ambiente Laboral, que como Anexo forma parte integrante de la presente resolución, y que será de uso obligatorio para todos aquellos que deban medir el nivel de iluminación conforme con las previsiones de la Ley N º 19.587 de Higiene y Seguridad en el Trabajo y normas reglamentarias.', NULL, 2, 'Accion', 'Todo el sitios', NULL, 4, 78, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación.", "custom_1783383763840": "Anual", "custom_1783383788609": "Todo el sitio", "custom_1783383823178": "Condiciones de trabajo", "custom_1784900000002": "Higiene y Seguridad"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'TODOS', 'Aprueba las “ESPECIFICACIONES TÉCNICAS SOBRE CARGA TÉRMICA – ESTRÉS POR CALOR” que como Anexo IF-2023-82368389-APN-GP#SRT forma parte integrante de la presente resolución, las que serán de aplicación a toda tarea que se realice en los establecimientos y explotaciones, persigan o no fines de lucro, cualesquiera sean la naturaleza económica de las actividades.\nSustitúyase el apartado “ESTRÉS TÉRMICO Y TENSIÓN TÉRMICA” del Anexo II “ESTRÉS TÉRMICO (Carga térmica)” del Decreto N° 351 de fecha 5 de febrero de 1979 – Texto sustituido por el artículo 3° de la Resolución del MINISTERIO DE TRABAJO EMPLEO Y SEGURIDAD SOCIAL N° 295 de fecha 10 de noviembre de 2003- por las “ESPECIFICACIONES TÉCNICAS SOBRE CARGA TÉRMICA – ESTRÉS POR CALOR” aprobadas por el artículo 1° de la presente Resolución.\nDeja sin efecto las disposiciones contenidas en el artículo 137, Capítulo 7, del Anexo del Decreto Reglamentario N° 911 de fecha 5 de agosto de 1996.\nDeja sin efecto las disposiciones contenidas en el apartado CARGA TÉRMICA del artículo 54, Capítulo 4, Título III, del Anexo I del Decreto Reglamentario N° 249 de fecha 20 de marzo de 2007.\nLa presente resolución entrará en vigencia a partir de los CIENTO OCHENTA (180) días corridos contados desde su publicación en el Boletín Oficial\n\nEn todas largas y cortas luego de la fila donde se encuentra la Carga térmica y en normas decreto 351/79. Obligaciones: Tener en cuenta cómo se debe medir el estrés por calor, aprueba límites y métodos de medición. Color: el mismo que tenga carga térmica', ': Tener en cuenta cómo se debe medir el estrés por calor, aprueba límites y métodos de medición. Prorroga por el término de CIENTO OCHENTA (180) días corridos el plazo establecido en el  artículo 5° de la Resolución de la SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 30 de fecha 26 de julio de 2023 por la que se aprobaron las “ESPECIFICACIONES TÉCNICAS SOBRE CARGA TÉRMICA– ESTRÉS POR CALOR” y conforme lo estipulado en su artículo 5º, dicha resolución entrará en vigencia a partir de los CIENTO OCHENTA (180) días corridos contados desde su publicación en el Boletín Oficial.', 2, 'Accion', 'Todo el sitios', 'Protocolo/estudio', 4, 79, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nMinisterio de Trabajo", "custom_1783383763840": "Anual . Comenzando a regir a los 180 días contados desde el 23 de enero de 2024.", "custom_1783383788609": "Todo el sitio", "custom_1783383823178": "Condiciones de trabajo", "custom_1784900000002": "Higiene y Seguridad"}');
