INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', '1.- Confeccionar Solicitud (con carácter de declaración jurada), adjuntar requisitos de\nacuerdo al tipo de Autorización solicitada.\nPresentación de la documentación en el 7mo. Piso, Oficina 3 (Radiofísica Sanitaria)\ndel Ministerio de Salud, en el horario de 11:00 a 13:00 y de 14:00 a 16:00.\nAllí se verifica que la documentación sea la correcta y esté completa.\nSi la documentación no fuese la adecuada, deberá presentarse nuevamente.\n2.-\nSe retira en la misma oficina y horarios a los 30 días.( consultar previamente via\ntelefónica o correo electrónico ,si el documento ha sido otorgado y firmado)', 'Trámite es necesario para hacerse responsable del uso de equipos Láser e IPL; es de validez Nacional conforme Resolución 1271/01 Y 1062/10,', 2, 'Accion', 'Sector donde se encuentre', NULL, 4, 80, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Ministerio de salud de la a Nación.", "custom_1783383763840": "Conforme habilitación", "custom_1783383788609": "Sector donde se encuentre", "custom_1783383823178": "Condiciones de trabajo", "custom_1784900000002": "Higiene y Seguridad"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 841);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Artículo 1', 'Exige la presentación del Certificado de Nomenclatura Parcelaria para los trámites sobre Condiciones contra Incendio, ya sean de obra nueva, ampliación o modificación.', 'Ante cualquier trámite sobre Condiciones contra Incendio, deberá presentarse el Certificado de Nomenclatura Parcelaria.', 1, 'Informativo', 'Certificado de Nomenclatura Parcelaria.', NULL, 4, 81, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Registro de Obras y Catastro (DGROyC) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Ante obra nueva.", "custom_1783383788609": "TODOS", "custom_1783383823178": "Protección contra incendio", "custom_1784900000002": "Infraestructura"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba la clasificación de los edificios según criterios de riesgo en función del destino, uso, superficie, características edilicias y nivel de afluencia de público. Aprueba el formulario modelo de Declaración Jurada y los requisitos para la presentación de Sistemas de Autoprotección. \nEstablece el procedimiento de trámite de inscripción, permanencia y funcionamiento del “Registro de Profesionales para la Elaboración y Puesta a Prueba de los Sistemas de Autoprotección”.', 'Establece requisitos para la presentación de la Declaración Jurada de Sistemas de Autoprotección.', 1, 'Informativo', 'Declaración Jurada de sistemas de autoprotección', NULL, 4, 82, '{"custom_1783383400370": "boti", "custom_1783383445340": "Dirección General de Defensa Civil (DGDCIV) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Según plazos fijados por la autoridad", "custom_1783383788609": "TODOS", "custom_1783383823178": "Protección contra incendio y evacuación.", "custom_1784900000002": "EH&S"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece que las Disposiciones de Aprobación de los Sistemas de Autoprotección de la Ley 5920 tendrán una validez de 2 años, siempre que no existan modificaciones y cumplan con las exigencias anuales de las Disposición DGDCIV 1358/2018. \nEstablece que las constancias de Evaluación Positiva de los Planes conforme la Ley 1346 tendrán una validez por dos años, siempre que los mismos se encuentren vigentes y mantengan las condiciones y su efectividad sea comprobada con al menos dos ejercicios de simulacro anuales.', 'Establece plazos de validez de los Sistemas de Autoportección', 2, 'Acción', 'Certificado de aprobación del sistema de autoprotección', NULL, 4, 83, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Dirección General de Defensa Civil (DGDCIV) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "Cada 2 años", "custom_1783383788609": "TODOS", "custom_1783383823178": "Protección contra incendio y evacuación.", "custom_1784900000002": "EH&S"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Arts. 7, 75, 176, 188, 208, 209, 210, 211, 212, 213 y concordantes', 'En ningún caso se pueden pactar en el contrato de trabajo, condiciones laborales inferiores a las dispuestas por las normas aplicables, convenciones colectivas y laudos. \nEmpleador debe adoptar las medidas adecuadas para tutelar la integridad psicofísica y la dignidad de los trabajadores. \nEmpleador está obligado a observar las normas sobre higiene y seguridad. El trabajador podrá rehusarse a cumplir tareas si el mismo le fuera exigido en transgresión a tales condiciones.\nProhíbe ocupar a mujeres en trabajos penosos, peligrosos o insalubres. \nLos trabajadores de entre 16 y 18 años deberán presentar un certificado de aptitud para el trabajo, y someterse a exámenes periódicos exigidos por las normas vigentes. Menores de 16 años no podrán ser contratados.\nLos artículos 208 a 213 inclusive establecen los derechos del trabajador a su remuneración y los plazos, así como la conservación del empleo, su reincorporación y despido ante accidentes o enfermedades inculpables.', 'Las normas contenidas en la Ley de Contrato de Trabajo son de orden público, y por ende, obligatorias (no pueden ser renunciadas por las partes).', 2, 'Acción', NULL, NULL, 4, 84, '{"custom_1783383400370": "Condiciones laborales", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "A TODOS LOS EMPLEADOS.", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "Empleador."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 905);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Toda la norma', 'Por esta norma se crea en el ministerio el Programa de Empleo Verde, que tiene por objeto impulsar el crecimiento del empleo verde, favorecer las actividades económicas más cuidadosas en el uso de los recursos naturales y el impacto ambiental, y acompañar a los trabajadores y a las unidades productivas en la transición hacia una sociedad más justa en términos sociales, económicos y ambientales.\nSe define “empleo verde” a todo aquel que cumple con los estándares de empleo decente o trabajo digno y que contribuye además a preservar y restaurar los recursos naturales, el ambiente y/o la biodiversidad tanto en sectores tradicionales como en sectores emergentes.\n \nObjetivos del programa: (i) impulsar la creación de empleos verdes; (ii) promover la formación profesional, certificación y mejora de las competencias laborales en perfiles ocupacionales que sean ambientalmente sustentables; (iii) acompañar a trabajadores en procesos de transición justa buscando reducir el impacto negativo que pueden generar los cambios en el mercado de trabajo; (iv) favorecer la movilidad de trabajadores y de empresas hacia sectores de actividad verdes en función del producto final o el proceso de trabajo; (v) identificar oportunidades estratégicas a nivel sectorial y territorial para la promoción y creación de empleos verdes; (vi) impulsar la formalización de trabajadores y unidades productivas que realizan actividades ambientalmente sostenibles; (vii) acompañar y sostener el empleo en la transición hacia una economía verde; (viii) desarrollar acciones positivas contra todas las formas de discriminación en el mundo del trabajo bajo un abordaje interseccional que considere las características de los trabajadores en situación de vulnerabilidad y riesgo de exclusión del mercado laboral, en particular por motivos de género, edad, discapacidad y étnico – raciales.', 'Aún no reglamentada, institucional, tiende a impulsar el crecimiento del empleo verde, favorecer las actividades económicas más cuidadosas en el uso de los recursos naturales y el impacto ambiental, y acompañar a los trabajadores y a las unidades productivas en la transición hacia una sociedad más justa en términos sociales, económicos y ambientales.', 2, 'Programática', 'Poseer trabajos verdes', NULL, 4, 85, '{"custom_1783383400370": "Condiciones laborales", "custom_1783383445340": "Ministerio de Trabajo, Empleo y Seguridad Social –", "custom_1783383763840": "No reglamentada", "custom_1783383788609": "Todos", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "Empleador/recursos  humanos"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 379);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Tiene por objetivo reducir la siniestralidad laboral a través de la prevención de los riesgos derivados del trabajo. \nLa ley define accidente de trabajo y enfermedad profesional, y regula las incapacidades laborales temporarias y permanentes. \nAsimismo, aborda las prestaciones dinerarias y en especie. \nAdemás, dedica un capítulo a la gestión de las prestaciones, y otro a los derechos, deberes y prohibiciones de la ART, el empleador y los trabajadores.\nEl empleador debe: \na) asegurar a empleados por eventuales accidentes laborales a través de contratación de ART de libre elección, y debe notificar a sus empleados sobre identidad de ART a la que los ha afiliado. \nb) informar a ART las altas y bajas de sus empleados.\nc) declarar y abonar la cuota mensual de la ART junto con los aportes y contribuciones que integran la CUSS.\nd) denunciar ante ART y SRT los accidentes y enfermedades profesionales que se produzcan.\ne) mantener un registro de siniestralidad.\nf) cumplir con preceptos de la Ley 19.587 de seguridad e higiene en el trabajo.\ng) permitir el ingreso de personal de ART, durante horas laborales y sin necesidad de previo aviso, y suministrar la información requerida por ésta.\nh) poner en conocimiento de los trabajadores el Plan de Mejoramiento de las condiciones de higiene y seguridad, y brindar capacitación en reducción de riesgos laborales. Se establecen 4 niveles de cumplimiento de las normas de prevención de riesgos de trabajo, siendo el nivel 1 de no cumplimiento, y constituyendo el nivel 4 la adopción de normas de prevención por encima de las obligaciones legales en materia de seguridad e higiene.  Todos los Planes de Mejoramiento deberán alcanzar al menos el tercer nivel.\nLa ART debe delinear un Plan de Acción para la empresa, que contemple: \na) la evaluación periódica de los riesgos existentes y su evolución. \nb) inspecciones periódicas de cumplimiento de las normas de prevención de riesgos de trabajo y del plan de acción. \nc) definición de medidas correctivas a ejecutar por la empresa para reducir los riesgos identificados y la siniestralidad registrada. \nd) una propuesta de capacitación de empleados sobre prevención de riesgos de trabajo. \nEl Plan de Acción es de ejecución obligatoria por parte del empleador. \nEmpleados y empleador deben adoptar las medidas legalmente previstas para evitar los riesgos laborales. Empleador y ART están obligados a informar a la SRT, o a las Autoridades del Trabajo provinciales, sobre el plan de acción delineado y su desarrollo, según lo establece la normativa complementaria. \nLa ART deberá fiscalizar el cumplimiento de la ley de riesgos de trabajo (incluyendo la fiscalización del cumplimiento de la ley 19.587 de seguridad e higiene en el trabajo) y del desarrollo del plan de acción, y deberá denunciar ante la SRT los incumplimientos por la empresa.\n Obligaciones del trabajador: Trabajadores deben asistir a los cursos de capacitación dentro del horario laboral, deben utilizar los elementos de protección personal y observar las medidas de seguridad impartidas en los cursos de capacitación. Trabajadores deben informar al empleador de toda situación riesgosa.', 'La ley de Riesgos de Trabajo complementa la Ley de Higiene y Seguridad N° 19587 en lo referente a la siniestralidad laboral y los riesgos del trabajo. Es una Ley de orden público, y por ende, no puede ser renunciada por las partes.', 2, 'Acción', 'Registros de capacitación en temas de EH&S\nActas de entrega de EPP\nDocumento Roles y Responsabilidades en EH&S', NULL, 4, 86, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Consultar con Andrés Boetsch la periodicidad", "custom_1783383788609": "Field Operations/Servicios Generales", "custom_1783383823178": "Instalaciones eléctricas", "custom_1784900000002": "EH&S"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1693);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Artículo 1 y Anexo', 'Ratifica el Pacto Federal del Trabajo. Establece en su Anexo II el “Régimen General de Sanciones por Infracciones Laborales”, el cual reemplaza al régimen de la Ley 18694.\nReconoce la competencia de las Administraciones del Trabajo provinciales y municipales en materia de fiscalización del medio ambiente laboral, respecto de los establecimientos radicados en sus territorios.', 'Es importante reconocer la autoridad de las administraciones provinciales y municipales, permitirles el ingreso a los establecimientos para realizar tareas de inspección y responder a sus requerimientos de información y documentación.', 1, 'Informativo', NULL, NULL, 4, 87, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "A TODOS LOS EMPLEADOS.", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "Empleador."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 851);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 2321);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Regula la estructura de los "Planes de Mejoramiento" del artículo 4, apartado 2 de la Ley 24557 y a tales fines clasifica a los empleadores en 4 categorías según el grado de cumplimiento de la normativa en higiene y seguridad. Establece los criterios para evaluar el cumplimiento del Plan de Mejoramiento. Excluye de esta obligación a los empleadores autoasegurados, y a los no asegurados. \nEl Plan de Mejoramiento deberá ser acordado entre la aseguradora y el empleador dentro de los 3 meses de firmado el contrato de afiliación. Mientras el Plan de Mejoramiento se encuentre en ejecución, el empleador no podrá ser sancionado por incumplimiento. Vencido el plazo máximo de ejecución del Plan, el empleador podrá ser sancionado por las autoridades competentes. \nLa ART deberá vigilar el cumplimiento del Plan de Mejoramiento, dejando constancia de sus visitas y de las observaciones efectuadas en el formulario correspondiente. Deberán asimismo brindar capacitación a los trabajadores en prevención de riesgos, informar sobre los derechos y deberes de las partes, instruir a trabajadores en sistemas de evaluación a aplicar para verificar el Plan de Mejoramiento, colaborar en acciones de promoción de la prevención que desarrolle la SRT, y cumplir con toda obligación que establezca la autoridad. \nLa ART deberá informar a las partes sobre la red de establecimientos para atención médica y hospitalaria, y los cambios en la reglamentación de la Ley sobre Riesgos del Trabajo. \nSe prohíbe la realización de exámenes psicofísicos a trabajadores, o exigir la exhibición de exámenes preexistentes, con carácter previo a la contratación. Una vez contratado, los exámenes preocupacionales estarán a cargo de la ART y serán sin cargo al empleador, a excepción de aquellos exámenes a trabajadores que no se incorporen a la empresa, o que habiéndose incorporado permanezcan bajo la dependencia del empleador por menos de 3 meses. \nEl empleador está obligado a: permitir el ingreso de la ART dentro de los horarios de trabajo y sin necesidad de notificación previa, y suministrar toda la información necesaria para desarrollar y evaluar el Plan de Mejoramiento. Debe asimismo cumplir con el Programa de Capacitación acordado con la ART, poner en conocimiento de los trabajadores el Plan de Mejoramiento, y proveer a la ART toda la información sobre accidentes de trabajo o enfermedades profesionales. \nEn caso de omisión o incumplimiento por parte de la ART, el empleador deberá intimarla fehacientemente dentro de los 30 días corridos del hecho. De no regularizarse la situación, el empleador deberá notificar a la SRT.\nSon obligaciones del trabajador: cumplir con las normas de prevención de las normas vigentes y de los planes de prevención, asistir a cursos de capacitación durante las horas de trabajo, utilizar equipos de protección personal o colectiva, utilizar en forma correcta y segura las máquinas, herramientas y dispositivos que desarrollen su actividad laboral, colaborar en la organización de programas de formación y educación en materia de salud y seguridad, e informar al empleador de todo hecho o circunstancia riesgosa inherente a sus puestos de trabajo y al establecimiento en general. \nLos trabajadores podrán denunciar ante la ART o la SRT los incumplimientos del Plan de Mejoramiento y las violaciones a las normas de higiene y seguridad (salvo que el empleador se encuentre cumpliendo el Plan de Mejoramiento).\nLos empleadores autoasegurados deberán: cumplir con las normas de higiene y seguridad en el trabajo, confeccionar el registro de siniestralidad por establecimiento, notificar a la SRT los accidentes y enfermedades profesionales que se produzcan, y cumplir con toda otra obligación que le imponga la SRT.', 'De corresponder, el establecimiento deberá contar con un Plan de Mejoramiento acordado entre la ART y el empleador. El cumplimiento del Plan de Mejoramiento será vigilado por la ART, dejando constancia de las visitas y las observaciones. Deberá brindarse capacitación a los empleados en materia de prevención de riesgos. Se debe permitir el ingreso de la ART en horarios de trabajo y suministrar toda la información necesaria para la evaluación del Plan de Mejoramiento.', 2, 'Acción', 'No aplica.', 'No aplica.', 4, 88, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "No aplica.", "custom_1783383823178": "No aplica.", "custom_1784900000002": "No aplica."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 2323);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Artículo 1', 'Establece que los empleadores autoasegurados y los que incumplan la obligación de asegurarse, serán responsables frente a los trabajadores y sus derechohabientes. La falta de seguro, así como la omisión de prestaciones en caso de accidente de trabajo o enfermedad profesional será considerada falta grave en los términos de la Ley 18694 (Nota: La Ley 18694 fue abrogada por el artículo 15 del Anexo II de la Ley 25212, que establece las sanciones por infracciones laborales).', 'Es obligatorio contar con seguro.', 2, 'Acción', 'No aplica por no ser autoasegurados', 'No aplica por no ser autoasegurados', 4, 89, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "No aplica por no ser autoasegurados", "custom_1783383823178": "No aplica por no ser autoasegurados", "custom_1784900000002": "No aplica por no ser autoasegurados"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 879);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba el “Procedimiento Complementario para la Denuncia de Accidentes de Trabajo” en el Registro Nacional de Accidentes Laborales (R.E.N.A.L.)\nAprueba también el “Procedimiento Complementario para la Denuncia de Enfermedades Profesionales” en el Registro de Enfermedades Profesionales (R.E.P.)\nLas Aseguradoras de Riesgos del Trabajo (A.R.T.) y Empleadores Autoasegurados (E.A.) deberán ajustarse a los procedimientos dispuestos en los Anexos de esta Disposición, para remitir la información de las contingencias ocurridas con posterioridad a la entrada en vigencia de la presente.', 'Tener en cuenta el procedimiento de denuncias de accidentes y  enfermedades profesionales.', 2, 'Obligatorio', 'Informativa.', 'Documentos genrados ante accidentes o enfermedades.', 4, 90, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "A TODOS LOS EMPLEADOS.", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "Informativa."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 419);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueban los listados de enfermedades profesionales previstas en el artículo 6°, apartado 2 de la Ley 24.557 de riesgos de trabajo. \nListan  los agentes que causan las enfermedades profesionales, así como las actividades laborales que pueden generar exposición a agentes de riesgo.', 'Century Link deberá minimizar la exposición de los trabajadores a los agentes listados según el tipo de actividad laboral, y prevenir la ocurrencia de enfermedades profesionales.', 2, 'Acción', 'Informativa.', 'Informativa.', 4, 91, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "A TODOS LOS EMPLEADOS.", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "Informativa."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Se determina que los elementos de protección personal suministrados por los empleadores a los trabajadores deberán contar, en los casos que la posea, con la certificación emitida por aquellos Organismos que hayan sido reconocidos para la emisión de certificaciones de producto, por marca de conformidad o lote, según la resolución de la entonces SECRETARIA DE INDUSTRIA, COMERCIO Y MINERIA (S.I.C. y M.) N° 896 de fecha 6 de diciembre de 1999. A su vez, se crea el formulario ““Constancia de Entrega de Ropa de Trabajo y Elementos de Protección Personal” de utilización obligatoria para los empleadores. La vigencia de esta norma comenzará a regir a los 180 días de su publicación.', 'Poseer planillas completas de entrega de EPP. Todos sus campos deben estar completos.', 2, 'de cumplimiento obligatorio', NULL, NULL, 4, 92, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "SRT y autoridad de aplicación laboral local", "custom_1783383763840": "Solo si deben entregar EPP", "custom_1783383788609": "TODOS", "custom_1783383823178": "Medidas de Higiene y seguridad", "custom_1784900000002": "Higiene y Seguridad"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1710);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Actualiza el Reglamento Técnico de Elementos de Protección Personal, con el objetivo de garantizar que los productos que llegan a los consumidores argentinos sean seguros y de alta calidad, alineados con los estándares internacionales. Los mismo se encuentra definidos en el Anexo I de la norma\nSe establece que los certificados nacionales y extranjeros de organismos de certificación acreditados son válidos para comercializar en el país, evitando así la duplicación de ensayos y procesos de control que las plantas internacionales ya verificadas. Esto aplica para elementos de prevención contra el ahogamiento por inmersión; de protección auditiva; la indumentaria de protección y equipos de protección contra caída en altura; de protección de la cabeza; respiratoria, total o parcial del rostro, protectores auditivos de diferentes niveles,  cobertores /orejeras, tapones auriculares, protección de extremidades superiores e inferiores, ocular de todos los niveles, indumentaria específica para diferentes riesgos, y de prevención contra el deslizamiento.\n\nEl procedimiento que deberán cumplir los fabricantes e importadores de los productos se encuentra en el Anexo III de la norma, como las normas nacionales de referencia en el Anexo II. Así, las exigencias establecidas en esta resolución que serán de aplicación a los productos, junto a las normas técnicas correspondientes a cada uno de ellos, se encuentran detallados en el Anexo II. Por su parte los distribuidores y los comercializadores, mayoristas y/o minoristas, de los productos detallados en el Anexo II, deben contar con una copia simple de la declaración jurada de conformidad, en formato papel o digital, para comercializar y/o distribuir los productos y ser exhibida cuando se lo requiera.\nLos productos listados en el Anexo II deberán dar cumplimiento a las normas técnicas de los organismos de normalización establecidos en el cuadro contenido en la resolución, o las que en el futuro las reemplacen. Las mismas deberán ser adecuadas para cumplir los requisitos esenciales de seguridad. En el caso de que se requiera la aplicación de más de una norma contemplada para un producto específico, deberán aplicarse todas ellas. A su vez, en el caso de que alguno de los productos listados requiera complementar la evaluación de los requisitos específicos con la norma técnica de requisitos generales -si la hubiera-, las mismas deberán complementarse.\nA partir de la medida, se eliminan trámites redundantes que obstaculizan el libre comercio. Esta norma debe tenerse en cuenta al momento de adquirir los EPP, ya que aplica directamente a los fabricantes e importadores, distribuidores y los comercializadores, mayoristas y/o minoristas, de los productos detallados en el Anexo II de la norma.', '. . Esta norma debe tenerse en cuenta al momento de adquirir los EPP, ya que aplica directamente a los fabricantes e importadores, distribuidores y los comercializadores, mayoristas y/o minoristas, de los productos detallados en el Anexo II de la norma.          Aplica para elementos de prevención contra el ahogamiento por inmersión; de protección auditiva; la indumentaria de protección y equipos de protección contra caída en altura; de protección de la cabeza; respiratoria, total o parcial del rostro, protectores auditivos de diferentes niveles,  cobertores /orejeras, tapones auriculares, protección de extremidades superiores e inferiores, ocular de todos los niveles, indumentaria específica para diferentes riesgos, y de prevención contra el deslizamiento.', 2, 'Acción AL TIEMPO DE ADQUIRIRLOS', 'Planilla de registro de entrega de EPP', 'Cuentan con EPP: Protectores auditivos, zapatos de seguridad, cascos, arneses. Ropa esporadicamente. Verificar firma de planilla.', 4, 93, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "SECRETARÍA DE INDUSTRIA Y COMERCIO DE LA NACIÓN", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo", "custom_1784900000002": "RRHH con protoclo según res 299/11 SRT"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece que los empleadores podrán utilizar aplicaciones informáticas para ingresar y completar, con carácter de declaración jurada, la información solicitada en el formulario “Constancia de Entrega de Ropa de Trabajo y Elementos de Protección Personal” creado por la Resolución de la SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) Nº 299 de fecha 18 de marzo de 2011.\nLas aplicaciones informáticas deberán permitir la posibilidad de que el/la trabajador/a no firme, en el caso de no haber recibido alguno de los ítems referidos, y/o de firmar con observaciones en el supuesto de haberlos recibido en forma insuficiente o deficiente.\nEstablece también que los empleadores podrán utilizar aplicaciones informáticas para registrar, con carácter de declaración jurada, las constancias de capacitación a sus trabajadores/as dependientes conforme las previsiones del artículo 9º, inciso k de la Ley N° 19.587.\nLas aplicaciones informáticas referidas deberán contar con la posibilidad de detallar la fecha y temáticas abordadas en cada oportunidad, nombre del capacitador y modalidad de la capacitación. Debe habilitarse la posibilidad de que los/as trabajadores/as manifiesten observaciones y comentarios sobre la capacitación recibida reservando debidamente su identidad.\nPodrán acreditarse constancias de capacitación realizadas con anterioridad a la entrada en vigencia de esta norma en la medida que cumplan con las exigencias prevista.', 'Tener en cuenta la posibilidad de utilizar sistemas informáticos en los que el trabajador pueda firmar y realizar observaciones para registrar entrega de EPP y capacitaciones.', 2, 'de cumplimiento obligatorio', NULL, NULL, 4, 94, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Ministerio de Trabajo de la Provincia de Buenos Aires", "custom_1783383763840": "Solo si deben entregar EPP", "custom_1783383788609": "TODOS", "custom_1783383823178": "Medidas de Higiene y seguridad", "custom_1784900000002": "Higiene y Seguridad"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 504);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Dispone que el MINISTERIO DE DESARROLLO SOCIAL y el MINISTERIO DE TRABAJO, EMPLEO Y SEGURIDAD SOCIAL efectuarán las modificaciones necesarias en sus programas de formación, empleo e intermediación laboral, con el objetivo de convertir las diferentes prestaciones de asistencia a personas desempleadas o con trabajos precarizados en incentivos para la contratación de sus beneficiarios y beneficiarias bajo la forma de empleo asalariado registrado en el sector privado.\nPodrán acceder a estos programas las empleadoras y los empleadores a quienes les resulten de aplicación las disposiciones del Capítulo 3 del Título IV de la Ley N° 27.541 y sus modificaciones, regidas bajo la Ley de Contrato de Trabajo N° 20.744 (t.o. 1976) y sus modificatorias y los regímenes previstos en las Leyes Nros. 22.250 y 26.727 y sus respectivas modificatorias.', 'Cumplir con lo establecido en el decreto, y tener en cuenta las modificaciones que puedan surgir respecto de los trabajadores precarizados tomados durante la pandemia', 2, NULL, NULL, NULL, 4, 95, '{"custom_1783383400370": "Laboral", "custom_1783383445340": "PEN"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'La presente ley tiene por objeto establecer los presupuestos legales mínimos para la regulación de la modalidad de Teletrabajo en aquellas actividades, que por su naturaleza y particulares características, lo permitan.\nRegula e incorpora a la LCT la modalidad del teletrabajo.\nEn tal sentido, se garantiza el derecho a la desconexión digital, a la intimidad y a las tareas de cuidado.\nAsimismo, se establece que la modalidad será voluntaria, que los gastos estarán a cargo del empleador y se contemplan cuestiones referidas a la capacitación; la protección de la información laboral; la representación digital; y el goce de todos los derechos colectivos.\nDerecho a la desconexión digital. El empleado tendrá derecho a no ser contactado y a desconectarse de los dispositivos, fuera de su jornada laboral y durante los períodos de licencias. Tareas de cuidados. Quienes tengan a su cargo, de manera única o compartida, el cuidado de personas menores de trece años, personas con discapacidad o adultas mayores que convivan con la persona trabajadora y que requieran asistencia específica, tendrán derecho a horarios compatibles con las tareas de cuidado a su cargo y/o a interrumpir la jornada. Reversibilidad. El consentimiento prestado por la persona que trabaja en una posición presencial para pasar a la modalidad de teletrabajo, podrá ser revocado por la misma en cualquier momento de la relación\nEl Ministerio de Trabajo, en su calidad de autoridad de aplicación, dictará las normas referidas a la seguridad e higiene; incorporará las nuevas enfermedades laborales por esta modalidad; tendrá a cargo la fiscalización; y llevará un registro en el cual deberán estar anotadas las empresas que desarrollen esta modalidad.\nLa presente ley entrará en vigencia 90 días después de que finalice el aislamiento obligatorio. Derecho a la desconexión digital: se admitirá el envío de comunicaciones fuera de la jornada laboral en los supuestos que la actividad de la empresa se lleve a cabo en diferentes husos horarios o en aquellos casos en que resulte indispensable por alguna razón objetiva. No obstante, en todos los supuestos, el empleado no estará obligado a responder hasta el inicio de su jornada, salvo que concurran los supuestos previstos en el artículo 203 de la Ley Nº 20.744, es decir, en casos en los que el trabajador está obligado a prestar servicios en horas suplementarias por peligro o accidente ocurrido o inminente de fuerza mayor, o por exigencias excepcionales de la economía nacional o de la empresa.  No se podrán establecer incentivos condicionados al no ejercicio del derecho a la desconexión, destacando que el pago de horas extras no será considerado un incentivo en tal sentido. \nEl derecho del trabajador a retomar la prestación presencial de tareas y el cumplimiento de la obligación resultante por parte del empleador, deberá ejercerse de acuerdo con el principio de buena fe, evitando el uso abusivo de tal prerrogativa. Una vez recibida la solicitud de reversión por parte del empleado, con la sola invocación de una motivación razonable y sobreviniente, el empleador deberá cumplir con su obligación en el menor plazo que permita la situación del o de los establecimientos al momento del pedido, destacando que, en ningún supuesto, dicho plazo podrá ser superior a treinta (30) días. Los empleados que hubiesen pactado la modalidad de teletrabajo desde el inicio de la relación laboral no pueden revocar su consentimiento ni ejercer el derecho para que se les otorgue tareas presenciales, salvo lo dispuesto en los Convenios Colectivos del Trabajo o en los contratos individuales que resulten aplicables.', 'Los servicios de higiene y seguridad debencontrolar las medidas necesarias . El empleador debe proporcionar el equipamiento – hardware y software-, las herramientas de trabajo y el soporte necesario para el desempeño de las tareas, y asumir los costos de instalación, mantenimiento y reparación de las mismas, o la compensación por la utilización de herramientas propias de la persona que trabaja. Protección de la Información Laboral. El empleador deberá tomar las medidas que son necesarias  para garantizar la protección de los datos utilizados y procesados para fines profesionales, no pudiendo hacer uso de software de vigilancia que viole la intimidad de la misma. .La provisión de elementos de trabajo no se considera remuneratoria y, en consecuencia, no integra la base de cálculo de ningún rubro resultante del contrato de trabajo, ni cotizaciones sindicales o de la seguridad social, destacando que las partes podrán acordar las pautas para su determinación, en los casos en los cuales la relación laboral no se encuentre regida por un Convenio Colectivo de Trabajo. En el mismo sentido, no se considerará remuneratoria la compensación de gastos, aun sin mediar presentación de comprobantes. \nSistema de control y derecho a la intimidad. Fiscalización de los sindicatos: la participación sindical tendrá lugar mediante auditorías conjuntas, compuestas por técnicos designados por la asociación sindical y por la empresa, garantizándose la confidencialidad de los procesos y datos y limitadas a preservar los derechos establecidos a favor de las personas que trabajan bajo la modalidad de teletrabajo. La entidad sindical, dentro de su ámbito de representación, recibirá únicamente información correspondiente a la nómina de las personas que desarrollan las tareas bajo la modalidad de teletrabajo, las altas y las bajas.', 2, 'de cumplimiento obligatorio a partir del 1ero de abril de 2021', 'Prestació de servicio fuera del lugar', NULL, 4, 96, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Ministerio de Trabajo de la Provincia de Buenos Aires", "custom_1783383763840": "comenzará a regir 90 días después de que cese el ASPO", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1957);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1430);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Requiere que los establecimientos cuenten con servicios de medicina del trabajo y de higiene y seguridad, con carácter interno o externo, los que estarán bajo la responsabilidad de graduados universitarios. \nEstablece la cantidad de horas-médico semanales en función de la cantidad de empleados. Establece asimismo la cantidad de horas mensuales de servicios de higiene y seguridad en función de la cantidad de empleados y de los riesgos. Estos servicios pueden ser contratados con la ART.\nLa Resolución 905 establece las funciones que deberán desarrollar los servicios de medicina y de higiene y seguridad laboral, y crea el “Registro Digital Único de Legajos de Salud”.', 'Cumplir con las horas médico semanales exigidas por la norma, y de contar con consultorio o enfermería, la misma deberá encontrarse habilitada según las normas locales.', 2, 'Acción', 'Contrato del servicio de medicina del trabajo', NULL, 4, 97, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "A TODOS LOS EMPLEADOS.", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "Empleador."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1676);
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 628);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Artículos 1 y 2', 'Modifica artículos de la Ley 24557 y agrega nuevos preceptos, a fin de mejorar las prestaciones a trabajadores damnificados. Incorpora mecanismos preventivos. \nEstablece la estructura de los Planes de Acción a implementar por la ART en establecimientos considerados críticos por la autoridad de aplicación, en base al índice de siniestralidad y el grado de cumplimiento con la normativa de higiene y seguridad en el trabajo. La ART debe controlar el cumplimiento del Plan de Acción e informar de cualquier incumplimiento a la SRT.\nDefine enfermedades profesionales como aquellas incluidas en el listado que elabore periódicamente el Poder Ejecutivo, así como aquellas que la Comisión Médica Central determine, según el procedimiento establecido en el apartado 2 del art. 6 de la Ley 24557.', 'Requiere Plan de Acción para establecimientos con alta siniestralidad', 1, 'Informativo', 'Informativa.', 'Informativa.', 4, 98, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "A TODOS LOS EMPLEADOS.", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "Informativa."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1186);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Modifica el listado de enfermedades profesionales del artículo 6 de la Ley 24557.', 'Listado de enfermedades profesionales', 1, 'Informativo', 'Informativa.', 'Informativa.', 4, 99, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "A TODOS LOS EMPLEADOS.", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "Informativa."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1187);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Artículos 1 a 6 inclusive', 'Los trabajadores de Empresas de Servicios Eventuales deberán incluirse dentro de la nómina salarial de la Empresa Usuaria del servicio, mientras se encuentren prestando servicios para ella. La ART deberá cumplir con las prestaciones correspondientes mientras el trabajador se encuentre prestando servicios para la Empresa Usuaria. La Empresa Usuaria deberá retener de los pagos que deba efectuar a la Empresa de Servicios Eventuales, los importes correspondientes a la ART. Deberá asimismo denunciar ante la ART, inmediatamente de conocido, todo accidente de trabajo o enfermedad profesional que sufran los trabajadores de servicios eventuales que presten servicios para la Empresa Usuaria.', 'Trabajadores de servicios eventuales deben incluirse dentro de la nómina salarial de la empresa', 2, 'Acción', NULL, NULL, 4, 100, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Cada vez que se incorpore un nuevo trabajador eventual y mientras duren sus servicios.", "custom_1783383788609": "Empleados eventuales.", "custom_1783383823178": "Condiciones de trabajo y protección de la salud del trabajador.", "custom_1784900000002": "RRHH"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1336);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba los requisitos y formalidades mínimas que deben cumplir los “Planes de Mejoramiento” y las constancias de visitas a los establecimientos de acuerdo con lo normado por la Ley 24.557 de Riesgos del Trabajo y Decreto 170/1996.\nSi el Plan de Mejoramiento no cumpliera con la normativa vigente, el empleador debe proceder a su adecuación, bajo apercibimiento de sanciones. \nSe establece en qué casos no procederá un “Plan de Mejoramiento”', 'En caso de corresponder, establece los requisitos y formalidades mínimas de los Planes de Mejoramiento.', 1, 'Informativo', 'Informativa.', 'Informativa.', 4, 101, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "De requerirse un Plan de Mejoramiento", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo e infraestructura.", "custom_1784900000002": "Informativa."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece el procedimiento a seguir ante un accidente de trabajo: \na) Empleador debe gestionar traslado del trabajador al establecimiento asistencial adecuado.\nb) Empleador debe entregar el formulario de denuncia de accidente (Anexo I) al prestador y quedarse con constancia firmada en recepción\nc) Si se trata de un prestador no habilitado, el empleador deberá remitir la denuncia a la ART o a uno de sus centros autorizados\nd) ART requerirá al prestador la remisión del parte médico de ingreso y de egreso.\ne) Dentro de las 72 hs. del accidente, el prestador debe remitir al empleador el Parte Médico de Ingreso.\nSi el accidente es in itinere, no se completa el paso a) supra. El prestador debe informar al empleador y a la ART del arribo del accidentado, solicitando que complete el formulario de denuncia. El trámite se completa con los pasos d) y e) supra. \nEn caso de ampliación de información de la denuncia de accidente, empleador deberá completar Formulario de Ampliación de Denuncia.', 'Ante un accidente de trabajo, se debe seguir el procedimiento que detalla la norma.', 1, 'Informativo', 'Procedimiento de cómo actuar ante Accidentes de Trabajo', NULL, 4, 102, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Ante un accidente de trabajo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Infraestructura.", "custom_1784900000002": "RRHH/EH&S"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece el procedimiento en caso de detectarse en los exámenes preocupacionales, alguna condición o enfermedad preexistente del trabajador. \nRequiere que los exámenes preocupacionales sean realizados con una antelación no mayor a un mes, y su resultado notificado fehacientemente al trabajador mediante informe suscripto por profesional médico.\nSi se detectare alguna secuela incapacitante, y a los fines de ser considerada como enfermedad preexistente, el trabajador y el empleador deberán solicitar la realización de una revisación médica a fines de acreditar la real condición del trabajador.\nEl prestador debe enviar el Parte Médico de Egreso al empleador dentro de las 24 hs. del alta médico del trabajador.', 'Procedimiento ante detección de condiciones de salud preexistentes como resultado de un examen preocupacional.', 1, 'Informativo', 'Procedimiento de gestión de exámenes médicos preocupacionales', NULL, 4, 103, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Al momento de realizar un examen preocupacional", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "RRHH"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Crea el “Programa de Acciones para la Prevención” para el mejoramiento de las condiciones de salud y seguridad laboral, en el que participarán empleadores, trabajadores, las ART, el Estado y los y sindicatos. Los componentes básicos del Programa son la difusión, la capacitación, la asistencia técnica, la fiscalización y el control del cumplimiento de las normas.', 'Cumplir con el Programa de Acciones para la Prevención.', 2, 'Acción', 'No se pudo disponer de evidencias.', NULL, 4, 104, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "RRHH"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece el procedimiento administrativo ante sumarios por incumplimientos de las normas sobre riesgos laborales y sobre higiene y seguridad en el trabajo, iniciados por la SRT o por los organismos provinciales competentes.', 'Ante sumarios por incumplimientos, aplicar el procedimiento administrativo de la norma.', 1, 'Informativo', 'Informativa.', 'Informativa.', 4, 105, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Ante imputaciones de infracciones o sanciones.", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo e infraestructura.", "custom_1784900000002": "Informativa."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Regula el tamaño y el texto prototipo de los afiches informativos que deberán exhibirse en lugares visibles para todos los trabajadores. Estos afiches incluyen información ante accidentes de trabajo, así como sobre los derechos y obligaciones del trabajador y del empleador. Los afiches informativos deben ser provistos por la ART en forma gratuita (al menos 1 por establecimiento), y deben colocarse en lugares visibles para todos los trabajadores.', 'Solicitar los afiches informativos a la ART y colocarlos en lugares visibles', 2, 'Acción', 'Informativa.', NULL, 4, 106, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Una vez", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "Informativa."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Se habilita la implementación de afiches digitales mediante dispositivos electrónicos de reproducción de imagen, para el cumplimiento de las obligaciones generadas por la Resolución de la SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 70 de fecha 01 de octubre de 1997, y su modificatoria, siempre que estos garanticen la visibilidad, accesibilidad y actualización del contenido exigido. La Resolución 70/1996 de la Superintendencia de Riesgos del Trabajo establece la obligatoriedad de exhibir un afiche informativo en todos los lugares de trabajo de Argentina. Este cartel debe ser provisto de forma gratuita por la ART y contener datos clave, como los números de contacto en caso de emergencias o accidentes. Este afiche tiene como objetivo principal informar tanto a empleadores como a trabajadores sobre sus derechos, obligaciones elementales y los pasos a seguir bajo el sistema de la Ley de Riesgos del Trabajo. \nSe establece la obligatoriedad para las Aseguradoras de Riesgos del Trabajo (A.R.T.) de remitir el afiche digital a todos sus empleadores afiliados de manera gratuita.\nSin perjuicio de ello, y a fin de garantizar la accesibilidad, las A.R.T. deberán proveer el material en formato físico a requerimiento de aquellos empleadores que manifiesten la necesidad de contar con dicho soporte.', 'Poseer el cartel de la Res. SRT 70/1996 con información básica para el trabajador en lugar visible, que debe remitirlo la ART a sus asegurados, y dicha remisión puede ser digital', 2, NULL, NULL, NULL, 4, 107, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO - GERENCIA DE PREVENCIÓN"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1713);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece que los empleadores deberán declarar el alta de sus trabajadores a su ART con antelación al inicio de la relación laboral. Fija en 18 meses la validez de los exámenes preocupacionales.\nEl empleador debe notificar al trabajador los hallazgos y afecciones detectados en los exámenes preocupacionales, debiendo poner a disposición del trabajador los exámenes realizados.', 'Dar de alta a nuevos trabajadores ante la ART, previo al inicio de la relación laboral.', 2, 'Acción', NULL, NULL, 4, 108, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Ante la incorporación de un nuevo trabajador", "custom_1783383788609": "TODOS", "custom_1783383823178": "Contratación de personal.", "custom_1784900000002": "RRHH"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba el “Procedimiento para calificar el carácter de lugares, tareas o ambientes de trabajo como normales o insalubres”\nLa calificación se efectúa mediante Resolución administrativa del organismo laboral provincial, declarando la insalubridad o el levantamiento de una insalubridad existente, de acuerdo con los términos de la Resoluciones MTEySS Nos. 434 y 860 de 2002.', 'El organismo laboral de la CABA califica a los establecimientos como lugares, tareas o ambientes de trabajo normales o insalubres.', 1, 'Informativo', NULL, NULL, 4, 109, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "No requiere acción, aunque sí actuar en consecuencia según las indicaciones de la autoridad de aplicación.", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Obliga a empleadores a denunciar los accidentes de trabajo y enfermedades profesionales ante la ART. A requerimiento de ésta, empleador debe entregar toda la información sobre el accidente o enfermedad, a fin de que la ART determine su causa.\nLa ART establecerá medidas correctivas, que deben ser cumplidas por el empleador.', 'Al denunciar accidentes, conservar copia del formulario, con constancia de recepción por ART, al menos por 3 años.\nCumplir con las medidas correctivas indicadas por la ART.', 2, 'Acción', 'No se pudo disponer de evidencias.', NULL, 4, 110, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Ante un accidente de trabajo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "RRHH"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba especificaciones técnicas sobre ergonomía y levantamiento manual de cargas, y sobre radiaciones.', 'Especificaciones técnicas sobre ergonomía, levantamiento de cargas y radiaciones', 2, 'Acción', 'Estudio ergonómico de oficinas y monitoreo de radiaciones no ionizantes (por antenas microondas)', 'Informativa.', 4, 111, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "Informativa."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Requiere que la ART, dentro de los 90 días de inicio de vigencia del Contrato de Afiliación:\na) Evalúe en sede la verosimilitud del relevamiento de riesgos realizado por el empleador mediante Formulario de Estado de Cumplimiento de la normativa vigente (Decretos 351/79 ó 911/96, según corresponda) en la medida que manipule sustancias de las descriptas en las Planillas A, B y C del Anexo I.\nb) Evalúe las fechas de regularización de los incumplimientos informados por el empleador a través de los formularios del Anexo I, los que estarán firmados por el Responsables de Higiene y Seguridad. De corresponder, debe indicar ajustes fijando un plazo para su corrección.\nc) Fije la fecha en que se auditará la regularización de los incumplimientos y/o de las observaciones realizadas oportunamente por la ART.\nLa ART deberá visitar al empleador a fin de verificar el estado de cumplimiento de salud y seguridad en el trabajo, conforme formularios y Planillas A, B y C del Anexo I, con la siguiente frecuencia:\na) Anualmente, en establecimientos no móviles que posean 6 o más trabajadores y declaren la presencia de alguno de los agentes de las Planillas A, B o C del Anexo I, y formen parte del listado que la SRT publique anualmente respecto de empleadores cuya siniestralidad supere el índice de incidencia del estrato al que perteneces según actividad, con un mínimo de 3 accidentes por año, o 1 accidente mortal por año.\nb) Para las empresas no comprendidas en el punto anterior, las visitas se realizarán con la frecuencia indicada en el Anexo III de la Resolución (ver listado de actividades y frecuencia de visitas correspondiente). \nLa ART debe notificar al empleador el resultado de las evaluaciones y recomendarle medidas de adecuación, e informar a la SRT de ello. La SRT lo asentará en el Registro de las visitas de las ART a los establecimientos. Además, la ART debe declarar ante el Registro de Cumplimiento de Normas de Salud y Seguridad, y dentro de los 10 días corridos del vencimiento del plazo inicial de 90 días desde la celebración del Contrato de Afiliación, los datos que fueran suministrados por los empleadores al momento de suscribir la solicitud de Afiliación, respecto del nivel de cumplimiento de las normas de salud, higiene y seguridad laboral, el programa anual de prevención de riesgos laborales, las observaciones realizadas y la fecha de verificación de cumplimiento de las mismas. \nLas ART deberán notificar al empleador, con al menos 45 días de anticipación a la fecha de renovación del Contrato de Afiliación, la obligación de presentar en forma completa el Relevamiento General de Riesgos Laborales y el Plan de Regularización de los incumplimientos denunciados, antes de que opere la renovación automática del contrato, a través de los Formularios del Anexo I. La ART entregará constancia de recepción del Relevamiento de Riesgos. En caso de que el empleador no cumpla con la obligación de presentar el Relevamiento General de Riesgos Laborales y el Plan de Regularización de Incumplimientos, la ART incrementará el moto de las alícuotas de renovación contractual con más un 50%, hasta tanto se subsanen los incumplimientos. \nEl empleador no podrá cambiar de ART mientras no cumpla con su obligación de presentar en tiempo y forma el Relevamiento General de Riesgos Laborales y el Plan de Regularización. La ART deberá denunciar a la SRT los incumplimientos a estas obligaciones.', 'Lista las acciones a llevar a cabo por la ART y las condiciones de afiliación y cambio de ART.', 1, 'Informativo', NULL, NULL, 4, 112, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "No requiere acción.", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo e infraestructura.", "custom_1784900000002": "Empleador."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece que las Aseguradoras de Riesgos del Trabajo (A.R.T.) y las A.R.T. Mutuales podrán registrar las visitas que realicen a los establecimientos de los empleadores alcanzados por su cobertura, y los Empleadores Autoasegurados (E.A.) podrán registrar las visitas presenciales que realicen a sus establecimientos mediante constancias digitales de visita, conforme las previsiones del Anexo IF-2022-118830241-APN-GP#SRT que forma parte de la presente resolución.\n\nLas A.R.T., los E.A. y las A.R.T. Mutuales podrán incorporar imágenes y material audiovisual complementario en los formularios digitales detallados en el artículo precedente, de conformidad con las normas que regulan la expresión del consentimiento, el uso de la imagen, la privacidad y el secreto comercial.\nResultarán inoponibles las imágenes y videos obtenidos en contravención a las normas de aplicación, sin perjuicio de las sanciones que pudieran corresponder.\n\nLas aplicaciones informáticas que se desarrollen a fin de implementar el registro digital de visitas, deberán garantizar la seguridad e integridad de los datos consignados y mantener un adecuado mecanismo para la identificación y autenticidad de los usuarios que registren la información', 'Tener en cuenta que el registro desde ahora puede ser en formato virtual siempre que se respete la privacidad de las partes y debido consentimiento.', 2, 'Obligatoria', NULL, NULL, 4, 113, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (SRT) de la Nación.\\n\\nGerencia de Operaciones de Seguridad y Ambiente de la Administración General del Puerto de Buenos Aires.", "custom_1783383763840": "Durante todo el año", "custom_1783383788609": "Todos", "custom_1783383823178": "Riesgos laborales derivados de la actividad"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 390);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece que los EMPLEADORES AUTOASEGURADOS (E.A.) deberán registrar el Alta, Modificación y Baja de sus ESTABLECIMIENTOS activos propios y/o de terceros, mediante el “Procedimiento para que las A.R.T./E.A remitan la información de ESTABLECIMIENTOS”, creado por la Disposición Conjunta de la Gerencia de Sistemas N° 2 y de la Gerencia de Prevención N° 1 de fecha 09 de febrero de 2015, conforme los términos y condiciones determinados en el Anexo IF-2022-71083248-APN-GP#SRT que se aprueba en la presente resolución.\nAprueba el Anexo IF-2022-71083248-APN-GP#SRT “REGISTRO DE ESTABLECIMIENTOS Y RELEVAMIENTO DE RIESGOS LABORALES PARA LOS EMPLEADORES AUTOASEGURADOS” que forma parte integrante de la presente resolución.\nEstablece  la obligación a los E.A. de remitir la información por cada establecimiento, de acuerdo al procedimiento, los requisitos y plazos establecidos en el Anexo IF-2022-71083248-APN-GP#SRT.', 'tener en cuenta por autoasegurados para relevamiento de riesgos.', 2, 'De cumplimiento si son autoasegurados', NULL, NULL, 4, 114, '{"custom_1783383400370": "Higiene y Seguridad  en el Trabajo", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires", "custom_1783383763840": "contante", "custom_1783383788609": "Todos"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 409);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba el “Reglamento para la Ejecución de Trabajos con Tensión en Instalaciones Eléctricas Mayores a 1 kV” elaborado por la Asociación Electrotécnica Argentina (AEA).\nEmpleador que desarrolle trabajos con tensión debe poner a disposición de las comisiones de higiene y seguridad (según convenio colectivo de trabajo) los Planes de Capacitación en materia de trabajos con tensión para la habilitación de los trabajadores que realicen dichas tareas.', 'Se aplica para trabajos con tensión en instalaciones eléctricas mayores a 1kV.', 1, 'Informativo', 'Plan de Capacitación EH&S\nRegistros de capacitación en seguridad eléctrica', NULL, 4, 115, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Cumplir si se trabaja con tensión en instalaciones eléctricas mayores a 1 kV.", "custom_1783383788609": "Todas las instalaciones eléctricas.", "custom_1783383823178": "Riesgo eléctrico.", "custom_1784900000002": "EH&S"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Crea el “Programa para la Reducción de los Accidentes Mortales”. \nTodo empleador que registre al menos un (1) accidente mortal, quedará comprendido en el Programa, en el cual permanecerá al menos un año, y hasta que la ART informe a la SRT la adopción de medidas preventivas permanentes en el establecimiento (siempre que no ocurra un nuevo siniestro mortal). \nEn el caso de que el accidente mortal se verifique durante la ejecución de trabajos para terceros como contratista, la empresa contratante también entrará en el Programa, y ambas ART deberán investigar el accidente, indicando las medidas de disminución de riesgos mortales que sus respectivos asegurados deberán implementar. La verificación del cumplimiento de estas medidas estará a cargo de la ART de la empresa contratante.\nEn caso de accidente laboral que resulte en la muerte de un empleado, se deberá realizar –a instancias de la ART- la evaluación de riesgos en el ámbito o área del accidente, a través de especialistas en seguridad e higiene en el trabajo.\nEl empleador deberá implementar las medidas de control de riesgo que indique la ART, a fin de evitar accidentes similares. De no ser posible la eliminación de los riesgos señalados por la ART, deberán minimizarse, priorizando la prevención (anticipación) por sobre la protección.\nNotificar a los trabajadores sobre los riesgos mortales a los que están expuestos y las medidas preventivas adoptadas por la empresa para evitarlos o minimizarlos.\nEl empleador deberá:\na) Capacitar a trabajadores designados en seguimiento permanente de medidas de prevención de los riesgos detectados\nb) Hacer participar a los delegados o trabajadores designados, de las visitas de verificación de la ART.\nEl Formulario de Investigación del Accidente fatal deberá llevar la firma de al menos un trabajador designado.', 'De registrar al menos 1 accidente mortal, deberán cumplir con el Programa para la Reducción de los Accidentes Mortales.', 1, 'Informativo', NULL, NULL, 4, 116, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Sólo ante la ocurrencia de un accidente mortal.", "custom_1783383788609": "TODAS.", "custom_1783383823178": "Condiciones de trabajo."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'La Resolución 103 adopta las “Directrices sobre los Sistemas de gestión de la Seguridad y la Salud en el Trabajo” de la OIT (ILO-OSH 2001).\nLa Resolución 523 aprueba las “Directrices Nacionales para los Sistemas de gestión de la Seguridad y la Salud en el Trabajo”, en base a las “Directrices” de la OIT adoptadas mediante Resolución 103/2005. Las mismas especifican requisitos para implementar Sistemas de Gestión de la Seguridad y la Salud en el Trabajo, a fin de contribuir con la empresa a proteger a los trabajadores contra los peligros y a eliminar lesiones, enfermedades, dolencias y muertes relacionadas con la actividad laboral.\nLa Resolución 1629 aprueba el “Reglamento para el Reconocimiento de implementación de los Sistemas de Gestión de la Seguridad y la Salud en el Trabajo”\nEstas Directrices y su Reglamento son de aplicación voluntaria por parte de los empleadores, y en caso de ser adoptadas, no reemplazan a las normas en vigencia', 'Las Directrices sobre Gestión de la Seguridad y Salud en el Trabajo aprobadas por la norma son de cumplimiento VOLUNTARIO.', 1, 'Informativo', 'Sistemas de seguridad y salud en el trabajo', NULL, 4, 117, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "De aplicación voluntaria", "custom_1783383788609": "TODAS.", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "Informativa."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Crea el "Registro de Accidentes de Trabajo". Establece los procedimientos administrativos tendientes a realizar las denuncias de los accidentes de trabajo.\nSe deben observar datos mínimos que deben contener los formularios.\nLa A.R.T. elaborará y entregará material informativo a los empleadores sobre los pasos a ejecutar en caso de accidente de trabajo.\nEl material informativo será entregado al empleador en el momento de la afiliación/renovación, o durante la primera visita que se efectúe al mismo adjunto a la entrega de los instrumentos para formalizar la denuncia.\nLos empleadores deberán poner en conocimiento de los trabajadores las instrucciones pertinentes recibidas de la A.R.T. \nLos trabajadores están obligados  a informar en forma inmediata al empleador todos los accidentes que le ocurran. \nEl empleador deberá solicitar en forma inmediata las prestaciones en especie para el accidentado.\nEl trabajador accidentado recibirá del prestador médico, en forma inmediata las prestaciones en especie definidas por la normativa vigente. \nEl empleador complementará a la información ya brindada conforme lo dispuesto por la Resolución S.R.T. Nº 310/02, la información sobre la contingencia ante la A.R.T. dentro del plazo máximo de 48 horas de haber tomado conocimiento de la misma, volcando los datos de la contingencia en el Formulario de Denuncia.\nEl empleador deberá entregar al trabajador una copia de la denuncia presentada.', 'Establece los requisitos para denunciar un accidente de trabajo.', 1, 'Informativo', 'Registros de accidentes de trabajo en ART', NULL, 4, 118, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Ante un accidente de trabajo", "custom_1783383788609": "TODAS.", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "RRHH"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establécese que los empleadores quedan incluidos en el Sistema de Ventanilla Electrónica implementado por la Resolución Nº 635/08. Procedimiento', 'Empleadores incluídos en el Sistema de Ventanilla Electrónica', 1, 'Informativo', 'Informativa.', 'Informativa.', 4, 119, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "No requiere acción.", "custom_1783383788609": "TODAS.", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "Informativa."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Enumera los exámenes de salud obligatorios:\na) Preocupacionales o de ingreso,\nb) Periódicos,\nc) Previos a una transferencia de actividad,\nd) Posteriores a una ausencia prolongada, y\ne) Previos a la terminación de la relación laboral o de egreso\nCuando el trabajador se exponga a agentes de riesgo listados por Resolución SRT 658/1996, deberá someterse a exámenes periódicos según la frecuencia y contenidos mínimos indicados en el Anexo II de la Resolución, incluyendo un examen clínico anual. Los exámenes periódicos son responsabilidad de la ART.\nTrabajadores expuestos a ruidos deberán someterse a audiometría tonal a los 6 meses de inicio de la relación laboral. Empleador debe notificar a ART la nómina de trabajadores expuestos a ruidos, y ART debe notificar centro de salud donde se harán audiometrías.\nLa Resolución 301 considera “susceptibles al ruido” a trabajadores cuyas audiometrías presenten una caída del umbral auditivo igual o mayor a 15dB en la frecuencia de 4000 Hz respecto del examen preocupacional (audiometría basal). \nLos resultados de las audiometrías deberán ser notificadas por la ART al empleador dentro de los 10 días hábiles.', 'Realizar al personal los exámenes de salud obligatorios', 2, 'Acción', 'Certificados de aptitud médica de los trabajadores', NULL, 4, 120, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Periodicidad según condiciones particulares del trabajador.", "custom_1783383788609": "TODAS.", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "RRHH"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 728);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Tarifario Médico Previsional', 'Aprueba el “Tarifario Médico Previsional” -Anexo III de la Resolución de la entonces SUPERINTENDENCIA DE ADMINISTRADORAS DE FONDOS DE JUBILACIONES Y PENSIONES (S.A.F.J.P.) N° 384 de fecha 17 de mayo de 1996-, que como Anexo DI-2021-94890180-APN-GACM#SRT forma parte integrante de la presente disposición.\nEstablece que los Prestadores de Exámenes Complementarios y Profesionales Interconsultores inscriptos de conformidad con los procedimientos de las Resoluciones de la entonces S.A.F.J.P. N° 384/96 y N° 32 de fecha 08 de mayo de 1998, en la Nómina de Prestadores de Exámenes Complementarios y de Profesionales Interconsultores por Especialidad ante las Comisiones Médicas, podrán adecuar el valor de sus servicios hasta el máximo del arancel previsto en el “Tarifario Médico Previsional” aprobado por la presente.', 'Tener en cuenta', 2, NULL, NULL, NULL, 4, 121, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 426);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Requiere cumplir con las exigencias de la Norma IRAM N° 3625 de 2003 (o aquella que la modifique o sustituya), a fin de cumplir con los requisitos de seguridad por tareas ejecutadas en espacios confinados contenidos en la Ley 24.557. \nEn caso de colisión entre los valores de la Norma IRAM citada, y los valores del Anexo IV de la Resolución MTEySS N° 295 /2003, deberán respetarse los estándares más estrictos en cuanto a valores permitidos.', 'Cumplir con la Norma IRAM N° 3625 de 2003 durante trabajos en espacios confinados', 1, 'Informativo', NULL, NULL, 4, 122, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Trabajos en espacios confinados", "custom_1783383788609": "TODAS.", "custom_1783383823178": "Condiciones de trabajo e infraestrcutura.", "custom_1784900000002": "Mantenimiento e Infraestructura de su implementación. S&H de identificar los espacios confinados, capacitar al personal que ingresa. Verificar el procedimiento. e"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 712);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Requiere que las ART y los empleadores autoasegurados gestionen la concurrencia de los trabajadores damnificados ante los prestadores asistenciales, siendo responsables de los traslados, alojamiento y alimentación según pautas establecidas en los Anexos I, II y III de la Resolución. Dichos servicios podrán contratarse a través de terceros, o deberá entregarle al trabajador las sumas que cubran dichos gastos. Los Anexos II y III establecen criterios para prescribir traslados por medios especiales, lo que deberá ser consignado por profesionales en las Historias Clínicas y Registros Médicos de los pacientes. La gestión de los turnos de atención y las condiciones de espera son consideradas parte integrante del servicio de traslado.   \nEl incumplimiento de las obligaciones derivadas de la Resolución será sancionado mediante los procedimientos reglados por las Resoluciones SRT 10/1997 y 25/1997.', 'Establece el procedimiento a seguir con trabajadores damnificados, a fin de que concurran ante los prestadores asistenciales.', 1, 'Informativo', 'Informativa.', 'Informativa.', 4, 123, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Ante un accidente o enfermedad laboral", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "Informativa."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Determina que los elementos de protección personal suministrados a los trabajadores deberán contar con la certificación emitida por los Organismos de Certificaciones de Productos, según Resolución de Secretaría de Industria y Comercio N° 896/1999.\nLos empleadores deberán utilizar el formulario “Constancia de Entrega de Ropa de Trabajo y Elementos de Protección Personal” que obra como Anexo en la Resolución.', 'Establece estándares de calidad de los elementos de protección personal (EPP) y el requisito de utilizar el formulario de constancia de entrega de ropa de trabajo y EPP al personal.', 2, 'Acción', 'Registro de entrega de EPP', NULL, 4, 124, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo", "custom_1784900000002": "EH&S"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, NULL, 'Actualiza el Reglamento Técnico de Elementos de Protección Personal, con el objetivo de garantizar que los productos que llegan a los consumidores argentinos sean seguros y de alta calidad, alineados con los estándares internacionales. Los mismo se encuentra definidos en el Anexo I de la norma\nSe establece que los certificados nacionales y extranjeros de organismos de certificación acreditados son válidos para comercializar en el país, evitando así la duplicación de ensayos y procesos de control que las plantas internacionales ya verificadas. Esto aplica para elementos de prevención contra el ahogamiento por inmersión; de protección auditiva; la indumentaria de protección y equipos de protección contra caída en altura; de protección de la cabeza; respiratoria, total o parcial del rostro, protectores auditivos de diferentes niveles,  cobertores /orejeras, tapones auriculares, protección de extremidades superiores e inferiores, ocular de todos los niveles, indumentaria específica para diferentes riesgos, y de prevención contra el deslizamiento.\n\nEl procedimiento que deberán cumplir los fabricantes e importadores de los productos se encuentra en el Anexo III de la norma, como las normas nacionales de referencia en el Anexo II. Así, las exigencias establecidas en esta resolución que serán de aplicación a los productos, junto a las normas técnicas correspondientes a cada uno de ellos, se encuentran detallados en el Anexo II. Por su parte los distribuidores y los comercializadores, mayoristas y/o minoristas, de los productos detallados en el Anexo II, deben contar con una copia simple de la declaración jurada de conformidad, en formato papel o digital, para comercializar y/o distribuir los productos y ser exhibida cuando se lo requiera.\nLos productos listados en el Anexo II deberán dar cumplimiento a las normas técnicas de los organismos de normalización establecidos en el cuadro contenido en la resolución, o las que en el futuro las reemplacen. Las mismas deberán ser adecuadas para cumplir los requisitos esenciales de seguridad. En el caso de que se requiera la aplicación de más de una norma contemplada para un producto específico, deberán aplicarse todas ellas. A su vez, en el caso de que alguno de los productos listados requiera complementar la evaluación de los requisitos específicos con la norma técnica de requisitos generales -si la hubiera-, las mismas deberán complementarse.\nA partir de la medida, se eliminan trámites redundantes que obstaculizan el libre comercio. Esta norma debe tenerse en cuenta al momento de adquirir los EPP, ya que aplica directamente a los fabricantes e importadores, distribuidores y los comercializadores, mayoristas y/o minoristas, de los productos detallados en el Anexo II de la norma.', 'Esta norma debe tenerse en cuenta al momento de adquirir los EPP, ya que aplica directamente a los fabricantes e importadores, distribuidores y los comercializadores, mayoristas y/o minoristas, de los productos detallados en el Anexo II de la norma.', 2, NULL, NULL, NULL, 4, 125, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "SECRETARÍA DE INDUSTRIA Y COMERCIO DE LA NACIÓN"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1682);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba el protocolo para la medición de la iluminación en el ambiente laboral. La medición de los valores de iluminación del ambiente laboral tiene una duración de 12 meses.', 'Establece estándares para la medición de iluminación en el ambiente laboral.', 2, 'Acción', 'Informe de medición de iluminación ocupacional firmado por profesional calificado', NULL, 4, 126, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. Dirección General de Protección del Trabajo de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Anual", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo", "custom_1784900000002": "EH&S"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba el protocolo para la medición de ruidos en el ambiente laboral. La medición de los valores de ruidos del ambiente laboral tiene una duración de 12 meses.', 'Establece estándares para la medición de ruidos en el ambiente laboral.', 2, 'Acción', 'Informe de medición de ruido ocupacional firmado por profesional calificado', 'Informativa.', 4, 127, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Anual", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo", "custom_1784900000002": "EH&S"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Adopta el “Reglamento para la Ejecución de Trabajos de Tensión en Instalaciones Eléctricas con tensión menor a igual a un Kilovoltio (1 kV)” elaborado por la Asociación Electrotécnica Argentina.\nLos empleadores que desarrollen trabajos con tensión, deben poner a disposición de las comisiones de higiene y seguridad los planes de capacitación en materia de trabajos de tensión que se desarrollen para la habilitación de los trabajadores que realicen tales tareas.', 'Establece normas para trabajos en tensión en instalaciones eléctricas con tensión menor o igual a 1 kV.', 2, 'Acción', 'Registros de capacitación en seguridad eléctrica', NULL, 4, 128, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Cumplir si se trabaja con tensión en instalaciones eléctricas menores o iguales a 1 kV.", "custom_1783383788609": "Infraestructura eléctrica.", "custom_1783383823178": "Riesgo eléctrico.", "custom_1784900000002": "Infraestructura."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba el “Protocolo de Ergonomía” (Anexo I) como herramienta básica para la prevención de trastornos músculo-esqueléticos, hernias inguinales directas, mixtas y crurales, hernia discal lumbo-sacra con o sin compromiso radicular que afecte a un solo segmento columnario y várices primitivas bilaterales. \nAprueba asimismo el “Diagrama de Flujo” (Anexo II) que indica la secuencia de gestión necesaria para dar cumplimiento al Protocolo de Ergonomía. \nBajo el Anexo III, incorpora el instructivo con información necesaria para completar las planillas del Protocolo de Ergonomía.\nLa implementación de este protocolo es obligatoria para todos los empleadores, excepto para quien cuente con protocolos de gestión de la ergonomía de similares características. Se puede solicitar asesoramiento a la ART en esta materia.', 'Es obligatorio cumplir con el Protocolo de Ergonomía aprobado por la norma', 1, 'Informativo', 'Informe de protocolo ergonómico', NULL, 4, 129, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "TODOS", "custom_1783383823178": "Condiciones de trabajo.", "custom_1784900000002": "EH&S"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Sustituye el “Programa de Rehabilitación para Empresas con Establecimientos que registren Alta Siniestralidad” por el nuevo “Programa de Empleadores con Siniestralidad Elevada” (PESE).\nAprueba el “Desarrollo del PESE” (Anexo I), el “Informe General del Empleador” –IGE- (Anexo II) y el “Plan de Reducción de Siniestralidad” –PRS- (Anexo III).\nEn caso de ser notificado a través de la ART, de la inclusión de la empresa en el PESE, se procederá del siguiente modo:\na) El empleador debe completar el Informe General del Empleador (IGE). \nb) Cualquier alta, baja o modificación de lo declarado implicará la presentación de un nuevo IGE.\nc) La ART confeccionará un Plan de Reducción de Siniestralidad (PRS).\nd) Se confeccionará un cronograma de visitas. LA ART deberá realizar al menos 8 visitas durante el período bianual de ejecución del PRS.\ne) Todo incumplimiento del PRS será denunciado por la ART a la SRT.', 'Si la empresa es includa por la ART en el Programa de Empleadores con Siniestralidad Elevada (PESE), deberá cumplirse con lo requerido por la norma', 1, 'Informativo', NULL, NULL, 4, 130, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Según indicaciones de la ART", "custom_1783383788609": "No aplica."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece el “Programa de Prevención para Empleadores PyMES”, el cual establecerá acciones preventivas de los riesgos derivados del trabajo para empleadores con un promedio anual de entre 11 y 49 trabajadores.  \nAprueba asimismo el “Desarrollo del PESE para PyMES”, la “Nómina de Actividades Incluidas en PESE-PyMES”, el “Informe General del Empleador -IGE-”, y el “Plan de Reducción de Siniestralidad PyME -PRS-PyME-”', 'Aprueba programas de prevención para PyMES de entre 11 y 49 trabajadores.', 2, 'Acción', NULL, NULL, 4, 131, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Continuo", "custom_1783383788609": "No aplica."}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Se sustituye el artículo 7°, inciso e) de la Resolución de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) Nº 216 de fecha 24 de abril de 2003 -modificado por la Resolución S.R.T. Nº 1.300 de fecha 04 de noviembre de 2004-, por el siguiente texto:\n“e) Colocación: Se promoverá la reinserción del trabajador siniestrado al puesto de trabajo que ocupaba en el mismo establecimiento; de no ser posible, se evaluará a través de las habilidades del damnificado la posibilidad de reinserción laboral en otro puesto de trabajo. El Responsable de Recalificación de la Aseguradora de Riesgos del Trabajo o Empleador Autoasegurado elevará al empleador o al responsable de recursos humanos de la empresa, en su caso, un informe donde se especificarán los resultados del análisis ocupacional y de puestos de trabajo para los que estaría calificado según lo indicado en el inciso c). La Aseguradora de Riesgos del Trabajo o Empleador Autoasegurado solicitará a la empresa o, en su caso, al responsable de recursos humanos de la misma, que informe dentro de un plazo no superior a los QUINCE (15) días hábiles, si dará curso a la reubicación laboral y, de no ser posible dicha reubicación, indicará los motivos que imposibilitan la misma. Tratándose de este último supuesto, el damnificado será capacitado en un nuevo oficio debiendo recibir las herramientas adecuadas para poner en práctica su nueva instrucción; de verificarse que el trabajador conozca un oficio previo y conserve las capacidades funcionales para ejercerlo, se lo proveerá de las herramientas suficientes para que pueda desempeñarlo. En todo caso la A.R.T. o el Empleador Autoasegurado estará obligado a cubrir el valor de las herramientas hasta la suma equivalente en PESOS de OCHO (8) veces el valor del Haber Mínimo Garantizado (H.M.G.) que periódicamente determine la ADMINISTRACIÓN NACIONAL DE LA SEGURIDAD SOCIAL (A.N.S.E.S.).”\nSe sustituye el artículo 8º de la Resolución S.R.T. Nº 1.195 de fecha 25 de octubre de 2004, por el\nsiguiente texto:\nEn aquellos casos en que la aseguradora o el empleador autoasegurado no se hubieren hecho cargo de los trámites y costos del servicio funerario y el gasto hubiere sido cubierto por algún sistema que implique el pago adelantado de sumas para la previsión de esta eventualidad, por parte del fallecido o el grupo familiar, la aseguradora o el empleador autoasegurado procederán a poner a disposición de los derechohabientes, una suma en PESOS equivalente a SEIS (6) veces el valor del Haber Mínimo Garantizado (H.M.G.) que periódicamente determine la ADMINISTRACIÓN NACIONAL DE LA SEGURIDAD SOCIAL (A.N.S.E.S.). Para el caso en que algún familiar, el empleador u otro particular hubiesen hecho frente a los costos de la prestación, la aseguradora o empleador autoasegurado deberá abonar al particular la totalidad de la suma gastada. La aseguradora o empleador autoasegurado, sin previo reclamo del interesado, deberá gestionar estos pagos en forma obligatoria y abonarlo dentro de los QUINCE (15) días de haber recibido los comprobantes correspondientes.”', 'Procedimientos de reinserción del trabajador siniestrado al puesto de trabajo que ocupaba en el mismo establecimiento y para  servicios funerarios en los que no se cumplieron con las obligaciones', 1, 'Informativo', NULL, NULL, 4, 132, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Si debieran reinsertar algún empleado por un accidente laboral o en caso de muerte de algún empleado", "custom_1783383788609": "TODOS", "custom_1783383823178": "Enfermedad profesional."}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1696);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Se aprueban el “RÉGIMEN DE ACCIONES DE CONTROL DEL CUMPLIMIENTO DE LAS OBLIGACIONES EMANADAS DE LAS NORMAS DEL SISTEMA DE RIESGOS DEL TRABAJO”, el “RÉGIMEN DE SANCIONES POR INFRACCIONES A LAS NORMAS DEL SISTEMA DE RIESGOS DEL TRABAJO” (el valor de las multas se fija en MOPRES, y serán convertidas a pesos teniendo en cuenta la equivalencia actualizada del MOPRE que publica la S.R.T. a tenor de lo dispuesto en el Decreto N° 404 de fecha 05 de junio de 2019), el “SISTEMA DE CALIFICACIÓN DE LAS INFRACCIONES A LAS NORMAS DEL SISTEMA DE RIESGOS DEL TRABAJO” y el formulario de “DECLARACIÓN JURADA PAGO VOLUNTARIO” (si se opta por el mismo tendrán una reducción del 50% de la multa.', 'Régimen sancionatorio', 1, 'Informativo', NULL, NULL, 4, 133, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "Superintendencia de Riesgos de Trabajo (SRT) de la Nación. \\n\\nDirección General de Protección del Trabajo (DGPT) del Gobierno de la Ciudad Autónoma de Buenos Aires.", "custom_1783383763840": "Si fueren infraccionados", "custom_1783383788609": "TODOS"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 1697);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Se aprueba el “Procedimiento para la Actuación de la Inspección Laboral Nacional ante la presencia de adolescentes de 16 y 17 años trabajando”.\nSe aprueba el Instructivo para la Confección del Acta de Constatación del Trabajo Adolescente.\nEn todas las largas y cortas. En largas en solapa higiene y seguridad , y en las cortas luego de Resolución 48/2019de la SRT. En obligaciones: Tener en cuenta en lugares donde se encuentren adolescentes de 16 y 17 años. Color Blanco', 'Tener en cuenta en lugares donde se encuentren adolescentes de 16 y 17 años', 1, 'Informativo', NULL, NULL, 4, 134, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "SECRETARÍA DE TRABAJO", "custom_1783383763840": "Si fueren inspeccionados", "custom_1783383788609": "TODOS"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 524);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo', 'Se sustituye el artículo 12 de la Ley N° 24.557 y sus modificaciones, por el siguiente:\n“ARTÍCULO 12.- Ingreso Base. Establécese, respecto del cálculo del monto de las indemnizaciones por incapacidad laboral definitiva o muerte del trabajador, la aplicación del siguiente criterio: \n1. A los fines del cálculo del valor del ingreso base se considerará el promedio mensual de todos los salarios devengados -de conformidad con lo establecido por el artículo 1° del Convenio N° 95 de la OIT- por el trabajador durante el año anterior a la primera manifestación invalidante, o en el tiempo de prestación de servicio si fuera menor. Los salarios mensuales tomados a fin de establecer el promedio se actualizarán mes a mes aplicándose la variación del índice Remuneraciones Imponibles Promedio de los Trabajadores Estables (RIPTE), elaborado y difundido por el MINISTERIO DE SALUD Y DESARROLLO SOCIAL.\n2. Desde la fecha de la primera manifestación invalidante y hasta la fecha en que deba realizarse la puesta a disposición de la indemnización por determinación de la incapacidad laboral definitiva, deceso del trabajador u homologación, el monto del ingreso base devengará un interés equivalente a la tasa de variación de las Remuneraciones Imponibles Promedio de los Trabajadores Estables (RIPTE) en el período considerado.\n3. En caso de que las Aseguradoras de Riesgos del Trabajo no pongan a disposición el pago de la indemnización dentro del plazo debido, se aplicará un interés equivalente al promedio de la tasa activa cartera general nominal anual vencida a TREINTA (30) días del BANCO DE LA NACIÓN ARGENTINA, hasta la efectiva cancelación, acumulándose los intereses al capital en forma semestral, según lo establecido en el artículo 770 del Código Civil y Comercial de la Nación.”', 'Tener en cuenta en caso de muerte o incapacidad laboral definitiva.', 2, NULL, NULL, NULL, 4, 135, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "PODER EJECUTIVO NACIONAL"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todo', 'Sustituye el ANEXO I del Decreto Nº 659 del 24 de junio de 1996 y su modificatorio por el ANEXO “TABLA DE EVALUACIÓN DE INCAPACIDADES LABORALES” (IF-2025-19864352-APN-SRT#MCH) que forma parte integrante de la presente medida, con vigencia conforme a lo previsto en el artículo 3º del presente decreto.', 'Tener en cuenta la nueva tabla.', 2, NULL, NULL, NULL, 4, 136, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "PODER EJECUTIVO NACIONAL"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 282);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Se aprueba la implementación de la credencial de cobertura en formato digital, la cual coexistirá con la credencial física establecida en la Resolución de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 310 de fecha 10 de septiembre de 2002, y cuyo diseño la replicará, resultando ambas autosuficientes y válidas.', 'Tener en cuenta', 1, 'Informativo', NULL, 'credencial', 4, 137, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO", "custom_1783383788609": "Informativo"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 523);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Se crea en el ámbito de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) el Sistema de Vigilancia y Control de Sustancias y Agentes Cancerígenos, en adelante S.V.C.C..\nSe aprueba el “Listado de Sustancias y Agentes Cancerígenos” como Anexo I; el “Procedimiento para informar la presencia de Sustancias y Agentes Cancerígenos” como Anexo II; el “Listado de Códigos de Agentes de Riesgo” como Anexo III.\nSe establece la obligatoriedad de la inscripción en el S.V.C.C. de todos los empleadores que en sus establecimientos produzcan, importen, utilicen, obtengan en procesos intermedios, vendan y/o cedan a título gratuito las sustancias o agentes que se enumeran en el Anexo I IF-2019-87690501-APN-GP#SRT de la presente, así como todos aquellos que en función de sus procesos productivos, actividades económicas o con motivo de circunstancias medioambientales, estén alcanzados por las previsiones del Anexo II.\nEn largas solapa higiene y seguridad y Cortas en el lugar donde estaba la 844/17. Obligaciones: si se posee alguna de las sustancias alcanzadas por la norma inscribirse en el Registro de Agentes Cancerígenos.', 'Revisar nuevos listados e inscribirse', 2, '31 de junio comiemza a regir', NULL, NULL, 4, 138, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO", "custom_1783383788609": "Informativo"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 525);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Se aprueban los métodos y estructuras de datos que deberán emplear las Aseguradoras de Riesgos del Trabajo (A.R.T) y los Empleadores Autoasegurados (E.A.) para operar el Sistema de Vigilancia y Control de Sustancias y Agentes Cancerígenos (S.V.C.C.).\nSe aprueba el “Procedimiento para que las Aseguradoras de Riesgos del Trabajo (A.R.T) y los Empleadores Autoasegurados (E.A.) remitan la información de Portada, de Inicio de Presentación y de Nóminas” como Anexos I, II y III respectivamente.\nSe aprueba “Esquema para operar en el Sistema de Vigilancia y Control de Sustancias y Agentes Cancerígenos (S.V.C.C.)” como Anexo IV.\nSe aprueba el “Procedimiento para que las Aseguradoras de Riesgos del Trabajo (A.R.T) y los Empleadores Autoasegurados (E.A.) remitan la información de Sustancias y Agentes Cancerígenos” como Anexo V.', 'Revisar nuevos listados e inscribirse. Si se posee alguna de las sustancias alcanzadas por la norma inscribirse en el Registro de Agentes Cancerígenos a través de ART quien a través de esta resolución enviará la información a la SRT. Controlar si se posee alguna de las sustancias o generadores listados en la Res. 81/19 y denunciarla en conjunto con la ART siguiendo los procedimientos y brindando los datos contenidos en estas normas, ya que las ART los fiscalizarán con esta disposición a los fines de informar a la SRT', 2, '31 de junio comiemza a regir', NULL, NULL, 4, 139, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO", "custom_1783383788609": "Informativo"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 501);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba la implementación de la MESA DE ENTRADAS VIRTUAL como medio de interacción con la comunidad en general en el ámbito de la SUPERINTEDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) mediante la plataforma “e-Servicios S.R.T.”, accediendo a través de “Clave Fiscal” conforme lo previsto por la Resolución General de la ADMINISTRACIÓN FEDERAL DE INGRESOS PÚBLICOS (A.F.I.P.) No 3.713 de fecha 21 de enero de 2015, o por otros medios de validación que se implementen.\nLa MESA DE ENTRADAS VIRTUAL implementada constituye un medio complementario de los canales de tramitación disponibles en el ámbito de la S.R.T.. No reemplaza otros esquemas de tramitación vigentes, así como tampoco exime del cumplimiento de obligaciones que resulten exigibles a través de otros medios electrónicos habilitados por la S.R.T.', 'Procedimental crea la Mesa de Entradas virtual', 2, NULL, NULL, NULL, 4, 140, '{"custom_1783383400370": "Salud ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO", "custom_1783383788609": "Informativo"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 482);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece la adopción las recomendaciones formuladas por el COMITÉ DE EVALUACIÓN Y MONITOREO DEL PROGRAMA DE ASISTENCIA DE EMERGENCIA AL TRABAJO Y LA PRODUCCIÓN, en el Acta No 16.', 'Indicativa/nformativa', 2, NULL, NULL, NULL, 4, 141, '{"custom_1783383400370": "Salud Ocupacional", "custom_1783383445340": "COMITÉ DE EVALUACIÓN Y MONITOREO DEL PROGRAMA DE ASISTENCIA DE EMERGENCIA AL TRABAJO Y LA PRODUCCIÓN", "custom_1783383788609": "Informativo"}');
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos', 'Modifica el apartado “DICTAMEN – Firma del dictamen” del punto 20 del Anexo I de la Resolución de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 179 de fecha 21 de enero de 2015, el que quedará redactado conforme el siguiente texto:\n“20. DICTAMEN Las Comisiones Médicas se expedirán para resolver los planteos de las partes a través de dictámenes.\nFirma del dictamen \nDichos dictámenes deberán ser suscriptos, en el ámbito de las Comisiones Médicas Jurisdiccionales, por al menos un (1) médico titular o co-titular”.', 'Forma de emitir dictámenes por parte de las comisiones médicas.', 2, 'Obligatoria para las Comisiones', 'Dictamen de la Comisón', NULL, 4, 142, '{"custom_1783383400370": "Seguridad Ocupacional", "custom_1783383445340": "MINISTERIO DE SALUD Y SUPERINTENDENCIA DE RIESGOS DEL TRABAJO", "custom_1783383763840": "Constante", "custom_1783383788609": "Infortiva", "custom_1783383823178": "Porcedimiental"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 341);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba el “LISTADO DE PATOLOGÍAS Y ESTUDIOS PARA EXCLUSIVO ANÁLISIS DOCUMENTAL”. Los trámites de revisión de la incapacidad caratulados en virtud de las disposiciones del artículo 50 de la Ley N° 24.241, llevados adelante por padecimiento de patologías previstas en el listado aprobado en el artículo 1° de la presente resolución, los exámenes que se prevén realizar antes de cumplido el 3er año desde la emisión del dictamen transitorio y las prórrogas generadas en orden a las disposiciones del propio artículo 50, la Comisión Médica Jurisdiccional podrá proceder a la evaluación documental de los antecedentes obrantes en las actuaciones y emitir el Dictamen Médico correspondiente.', 'Tener en cuenta el listado de patologías y estudios por los que sólos e realiza análisis documental', 2, 'obligatoria', NULL, NULL, 4, 143, '{"custom_1783383400370": "Seguridad Ocupacional", "custom_1783383445340": "MINISTERIO DE SALUD Y SUPERINTENDENCIA DE RIESGOS DEL TRABAJO", "custom_1783383763840": "Constante", "custom_1783383788609": "Informava", "custom_1783383823178": "Procedimental"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 381);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba el “Tarifario Médico Previsional”. los Prestadores de Exámenes Complementarios y Profesionales Interconsultores inscriptos de conformidad con los procedimientos de las Resoluciones de la entonces S.A.F.J.P. N° 384/96 y N° 32 de fecha 8 de mayo de 1998, en la Nómina de prestadores de Exámenes Complementarios y de Profesionales Interconsultores por Especialidad ante las Comisiones Médicas, podrán adecuar el valor de sus servicios hasta el máximo del arancel previsto en el “Tarifario Médico Previsional” aprobado por la presente.', 'Tener en cuanta el tarifario médico', 2, 'obligatoria', NULL, NULL, 4, 144, '{"custom_1783383400370": "Seguridad Ocupacional", "custom_1783383445340": "MINISTERIO DE SALUD Y SUPERINTENDENCIA DE RIESGOS DEL TRABAJO", "custom_1783383763840": "Constante", "custom_1783383788609": "Informava", "custom_1783383823178": "Procedimental"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 375);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba el “PROCEDIMIENTO A SEGUIR EN LOS TRÁMITES PREVISIONALES RECURRIDOS ANTE LA COMISIÓN MÉDICA CENTRAL', 'Tener en cuenta para cualquier denuncia o apleción ante las comisiones médicas', 2, 'obligatoria', NULL, NULL, 4, 145, '{"custom_1783383400370": "Seguridad Ocupacional", "custom_1783383445340": "MINISTERIO DE SALUD Y SUPERINTENDENCIA DE RIESGOS DEL TRABAJO", "custom_1783383763840": "Constante", "custom_1783383788609": "Informava", "custom_1783383823178": "Procedimental"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 396);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Aprueba el “PROCEDIMIENTO ANTE LA COMISIÓN MÉDICA CENTRAL EN TRÁMITES\nREGULADOS POR LA LEY N° 24.557, SUS MODIFICATORIAS Y COMPLEMENTARIAS”.\nLas pautas procedimentales contenidas en el Anexo IF-2023-08248238-APN-GACM#SRT serán de aplicación exclusiva para la intervención de la Comisión Médica Central en los trámites laborales, con independencia de tratarse de actuaciones originadas en Comisión Médicas Jurisdiccionales en provincias adheridas o no a la Ley N° 27.348', 'Tener en cuenta el procedimiento para reclamos ante Comisiones Médicas', 2, 'obligatoria', NULL, NULL, 4, 146, '{"custom_1783383400370": "Seguridad Ocupacional", "custom_1783383445340": "MINISTERIO DE SALUD Y SUPERINTENDENCIA DE RIESGOS DEL TRABAJO", "custom_1783383763840": "Constante", "custom_1783383788609": "Informava", "custom_1783383823178": "Procedimental"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 380);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Autoriza a los médicos que integran la Comisión Médica Central para que, de manera transitoria y excepcional, intervengan en el análisis de los expedientes y rúbrica de los dictámenes médicos que se encuentren en trámite en las Comisiones Médicas Jurisdiccionales.\nDispone que los profesionales deberán expresar su conformidad previa a ejercer las funciones autorizadas por el artículo 1° de la presente resolución, debiendo abstenerse de intervenir y dictaminar en los casos que se apelen ante la Comisión Médica Central cuando hayan participado en los expedientes de la instancia anterior.', 'Tener en cuenta la posibilidad de intervención en sumarios de la Comisión Médica Central.', 2, 'Obligatoria', NULL, NULL, 4, 147, '{"custom_1783383400370": "Seguridad Ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO", "custom_1783383788609": "Informativo"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 276);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Se establece que la suspensión de plazos prevista en el punto 1.6. del Anexo de la Resolución de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 46 de fecha 28 de septiembre de 2023, no podrá exceder el plazo de NOVENTA (90) días hábiles administrativos.\nEn aquellos supuestos en que el impulso del procedimiento dependa exclusivamente del afiliado, el plazo máximo de suspensión se reducirá a TREINTA (30) días hábiles administrativos.\nAmbos plazos se computarán a partir de la notificación fehaciente al beneficiario de la causa que motivó la suspensión.\nVencido el plazo aplicable sin que el interesado hubiere subsanado las causas que le sean imputables, la Comisión Médica Jurisdiccional deberá, como principio general, emitir el dictamen correspondiente en base a los elementos obrantes en el expediente. Excepcionalmente, cuando se trate de trámites caratulados como Reexamen antes del 3° año, artículo 50 Ley N° 24.241 o Prórroga del artículo 50 Ley 24.241, y los antecedentes existentes resulten insuficientes para ratificar el beneficio, la Comisión Médica Jurisdiccional dispondrá, mediante pronunciamiento fundado, la caducidad y archivo de las actuaciones.\nLo dispuesto en los párrafos precedentes no será aplicable en caso de inasistencia injustificada del solicitante a la audiencia médica, supuesto que se regirá por lo establecido en el punto 1.3. del Anexo de la Resolución S.R.T. N° 46/23, correspondiendo declarar la caducidad y el archivo de las actuaciones sin más trámite.\nEl pronunciamiento que se dicte -sea el dictamen o la declaración de caducidad- será notificado al interesado y comunicado a la ADMINISTRACIÓN NACIONAL DE LA SEGURIDAD SOCIAL (ANSES) o al Organismo que en el futuro lo reemplace. En caso de archivo, el interesado deberá instar una nueva solicitud de trámite ante ANSES.', 'Tener en cuenta el procedimiento y plazos para resolver que poseen las comisiones médicas.', 2, NULL, NULL, NULL, 4, 148, '{"custom_1783383400370": "Seguridad Ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO- GERENCIA DE ADMINISTRACIÓN DE COMISIONES MÉDICAS", "custom_1783383788609": "Informativo"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 273);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Sustituye el artículo 1° de la Resolución de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 886 de fecha 22 de septiembre de 2017, el que quedará redactado de la siguiente forma: “ARTÍCULO 1°.- Apruébase el “PROTOCOLO DE ESTUDIOS MÍNIMOS PARA LA VALORACIÓN DEL DAÑO CORPORAL Y PARA LA DETERMINACIÓN DE LA INCAPACIDAD”, que como Anexo I IF-2021-09194454-APN-GACM#SRT forma parte integrante de la presente resolución.”.', 'Indicativa para ART/Comisiones Médicas', 2, 'Obligatoria', NULL, NULL, 4, 149, '{"custom_1783383400370": "Salud Ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO  (09/02/2021)", "custom_1783383788609": "Informativo"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 452);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Se aprueba el “PROTOCOLO DE ESTUDIOS MÍNIMOS PARA LA VALORACIÓN DEL DAÑO CORPORAL Y PARA LA DETERMINACIÓN DE LA INCAPACIDAD”, que como Anexo I IF-2026-10128719-APN-SRT#MCH forma parte integrante de la presente resolución, para todos aquellos casos donde deba determinarse el grado de incapacidad resultante de una contingencia laboral, conforme el Decreto N° 549 de fecha 05 de agosto de 2025, que aprobó la actualización de la Tabla de Evaluación de Incapacidades Laborales prevista en el Anexo I del Decreto N° 659 de fecha 24 de junio de 1996 y sus modificatorios.\nSe aprueba la “PRESENTACIÓN Y CONTENIDO DE INFORMES MÉDICOS E INTERCONSULTAS ANTE COMISIONES MÉDICAS” que como Anexo II IF-2026-10128838-APN-SRT#MCH, forma parte de la presente resolución.', 'Tener en cuenta para realizar la valoración del daño corporal y determinación de incapacidades.', 2, NULL, NULL, NULL, 4, 150, '{"custom_1783383400370": "Salud Ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 268);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Se aprueba el “PROTOCOLO DE PRESTACIONES EN SALUD MENTAL”, que como Anexo I IF-2026-10137691-APN-SRT#MCH forma parte de la presente resolución, de observancia obligatoria para las ASEGURADORAS DE RIESGOS DEL TRABAJO (A.R.T.) y los EMPLEADORES AUTOASEGURADOS (E.A.) en el marco del otorgamiento de las prestaciones en especie previstas en el artículo 20, apartado 1 de la Ley N° 24.557 y demás normas complementarias.\nSe aprueban los “INFORMES Y FORMULARIOS DE TRATAMIENTO DE SALUD MENTAL”, que como Anexo II IF-2026-10137748-APN-SRT#MCH forma parte de la presente resolución.', 'Tener en cuenta para realizar las prestaciones en salud mental.', 2, NULL, NULL, NULL, 4, 151, '{"custom_1783383400370": "Salud Ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 267);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Incorpora a los datos mínimos que deben contener los modelos de Formularios A “Constancia de Alta Médica” y B “Constancia de Fin de Tratamiento”, incluidos en el Anexo aprobado mediante el artículo 12 de la Resolución de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 1.838 de fecha 01 de agosto de 2014, los siguientes ítems: “El trabajador ameritó tratamiento psicológico y/o psiquiátrico (SI/NO)” y “El trabajador ameritó estimación de secuelas incapacitantes, de conformidad con lo establecido en el punto 13 del Anexo I y en el punto I del Anexo II de la Resolución S.R.T. N° 886/17, modificado por la Resolución S.R.T. N° 3/21 (SI/NO)”.', 'Tener presente nuevos formularios.', 2, NULL, NULL, NULL, 4, 152, '{"custom_1783383400370": "Salud Ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO", "custom_1783383788609": "Informativo"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 289);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Se sustituye el texto del punto 19 del Anexo I de la Resolución de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 179 de fecha 21 de enero de 2015, por el siguiente:\n“19. PRUEBA\nLas partes deberán ofrecer, en su primera presentación, toda la prueba de la que intenten valerse acompañando en esa oportunidad la documental pertinente. Cuando la parte trabajadora invocare haber recibido tratamiento médico a través de su Obra Social o de prestadores públicos o particulares, deberá acompañar la historia clínica correspondiente.\nNo se admitirá prueba alguna que no haya sido ofrecida en dicha oportunidad, salvo que se trate de hechos nuevos o de documentos que, por su naturaleza, no hubieran podido ser conocidos o habidos por la parte al momento de su presentación, circunstancia que deberá ser debidamente acreditada. [...]”\nSe sustituyen los artículos 6° y 7° de la Resolución S.R.T. N° 298 de fecha 23 de febrero de 2017, por los siguientes:\n“ARTÍCULO 6°.- Intervención médica.\nRecibida la solicitud de intervención y cumplidos los requisitos de inicio dispuestos en los artículos precedentes, el profesional médico interviniente se expedirá sobre la prueba médica presentada y solicitada por las partes. En caso de corresponder, podrá ordenar la realización de examen físico o de estudios complementarios.\nPara el caso de existir planteos o producción de prueba de tipo jurídico, dispondrá la intervención del Secretario Técnico Letrado (S.T.L.).”.\n“ARTÍCULO 7°.- Prueba.\nLas partes deberán ofrecer, en su primera presentación, toda la prueba de la que procuren valerse, acompañando en esa oportunidad la documental pertinente. De dicha presentación y de la prueba documental ofrecida se dará traslado a la contraparte.\nCuando la parte trabajadora invocare haber recibido tratamiento médico a través de su Obra Social o de prestadores públicos o particulares, deberá acompañar la historia clínica correspondiente.\nNo se admitirá prueba alguna que no haya sido ofrecida en dicha oportunidad, salvo que se trate de hechos nuevos o de aquellos documentos que, por su naturaleza, no hubieran podido ser conocidos o habidos por la parte al momento de su presentación, circunstancia que deberá ser debidamente acreditada. [...]”\nSe sustituye el texto del punto 2 del artículo 3° de la Resolución S.R.T. N° 899 de fecha 08 de noviembre de 2017, por el siguiente:\n“2.- PROFESIONAL MÉDICO.\nSus funciones son:\na. Analizar y valorar la prueba médica solicitada y presentada por las partes.\nb. Efectuar el examen físico, en caso de corresponder.\nc. Requerir la realización de estudios médicos complementarios y/o interconsultas con especialistas, cuando resultare necesario para dictaminar.\nd. Requerir la asistencia de servicios profesionales o de organismos técnicos, en los casos que se susciten cuestiones ajenas a su especialidad.\ne. Proveer los informes técnicos que sustenten la intervención médica.\nf. Emitir el dictamen médico o el Informe de Valoración de Daño (I.V.D.), según corresponda, expresando en dicha oportunidad los fundamentos médicos que motivaron su conclusión.\ng. Expedirse sobre las cuestiones atinentes al dictamen médico planteadas por las partes en las solicitudes de rectificaciones, revocaciones, o aclaratorias.\nh. Dar intervención, en el marco de las funciones establecidas en el Decreto N° 1.475/15 y conforme a lo previsto en los artículos 6° y 7° de la Resolución S.R.T. N° 298/17, al Secretario Técnico Letrado cuando se susciten planteos de orden legal, quedando la cuestión sujeta a lo que éste resuelva en el ámbito de su competencia.”.\nSe aprueban los formularios de datos mínimos requeridos para el inicio de trámites ante las Comisiones Médicas Jurisdiccionales, los cuales, como Anexo I IF-2026-09572121-APN-SRT#MCH, Anexo II IF-2026-09572332-APN-SRT#MCH, Anexo III IF-2026-09572484-APN-SRT#MCH y Anexo IV IF-2026-09572607-APN-SRT#MCH forman parte integrante de la presente resolución.\nDichos formularios tendrán carácter obligatorio para la tramitación de los procedimientos previstos en las Resoluciones S.R.T. N° 179/15 y N° 298/17.\nSe derogan los artículos 17, 18, 19 y 20 de la Resolución S.R.T. N° 179/15, conforme los motivos\nexpuestos en los considerandos de la presente resolución.', 'Tener en cuenta como meritar la prueba médica en el procedimiento de determinación de accidentes y enfermedades de trabajo, como así también las funciones de los profesionales médicos.', 2, NULL, NULL, NULL, 4, 153, '{"custom_1783383400370": "Salud Ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 269);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Modifica los datos mínimos que deben contener los modelos de Formularios A “Constancia de Alta Médica” y B “Constancia de Fin de Tratamiento”, incluidos en el Anexo aprobado mediante el artículo 12 de la Resolución de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 1.838 de fecha 01 de agosto de 2014, texto incorporado por el artículo 1º de la Resolución de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) Nº 27 de fecha 09 de junio de 2025, por el siguiente: “Incorpórase a los datos mínimos que deben contener los modelos de Formularios A “Constancia de Alta Médica” y B “Constancia de Fin de Tratamiento”, incluidos en el Anexo aprobado mediante el artículo 12 de la Resolución de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 1.838 de fecha 1 de agosto de 2014, los siguientes ítems: “El trabajador ameritó tratamiento psicológico y/o psiquiátrico, de conformidad con lo establecido por la Resolución S.R.T. N° 8 de fecha 28 de enero de 2026 o la que en el futuro la reemplace (SI/NO)” y “El trabajador ameritó estimación de secuelas incapacitantes, de conformidad con lo establecido por la Resolución S.R.T. N° 7 de fecha 28 de enero de 2026 o la que en el futuro la reemplace (SI/NO)”.', 'Tener en cuenta los requisitos a contener en los Formularios A “Constancia de Alta Médica” y B “Constancia de Fin de Tratamiento”, “Alta médica”.', 2, NULL, NULL, NULL, 4, 154, '{"custom_1783383400370": "Salud Ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 592);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece que, cesada la situación de Incapacidad Laboral Temporaria (I.L.T.), y ante la existencia de secuelas incapacitantes resultantes de una contingencia, en todos los casos las ASEGURADORAS DE RIESGOS DEL TRABAJO (A.R.T.) y los EMPLEADORES AUTOASEGURADOS (E.A.) deberán proceder a citar al/la trabajador/a damnificado/a, requiriendo la constitución del patrocinio letrado correspondiente, con el fin de valorar el grado correspondiente de incapacidad y formular una propuesta de acuerdo sobre la Incapacidad Laboral Permanente Parcial (I.L.P.P.) y las respectivas prestaciones dinerarias previstas en la Ley sobre Riesgos del Trabajo, ello en los términos del artículo 1° y 3° de la Ley N° 27.348 y del Título I, Capítulo II, Punto II de la Resolución de la SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 298 de fecha 23 de febrero de 2017', 'Indicativa para ART/Comisiones Médicas', 2, 'Obligatoria', NULL, NULL, 4, 155, '{"custom_1783383400370": "Salud Ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO  (09/02/2021)", "custom_1783383788609": "Informativo"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 444);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Deroga el CAPÍTULO II del TÍTULO I de la Resolución de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 20 de fecha 14 de abril de 2021 (que instituyó la posibilidad que, ante el CESE DE LA INCAPACIDAD LABORAL TEMPORARIA SIN SECUELAS INCAPACITANTES RESULTANTES DE LA CONTINGENCIA, las partes pudieran arribar a un acuerdo por una compensación económica en el Servicio de Homologación dependiente de la Gerencia de Administración de Comisiones Médicas (G.A.C.M.).\nDeroga  la Disposición de la Gerencia de Administración de Comisiones Médicas (G.A.C.M.) N° 6 de fecha 7 de diciembre de 2021 (que instrumentó las medidas necesarias para llevar adelante el procedimiento instado en el CAPÍTULO II del TÍTULO I de la Resolución S.R.T. N° 20/21.)', 'Tener en cuenta que deberán tener en cuenta el procedimiento completo', 2, 'Obligatoria', NULL, NULL, 4, 156, '{"custom_1783383400370": "Salud Ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO", "custom_1783383788609": "Informativo"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 403);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Establece que las Aseguradoras de Riesgos del Trabajo (ART)/Empleadores Autoasegurados (EA)/Empleadores No Asegurados (ENA) en las jurisdicciones adheridas a la Ley N° 27.348 Complementaria de la Ley sobre Riesgos del Trabajo, podrán iniciar, dentro del mismo plazo previsto en el artículo 19 de la Resolución de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 298 de fecha 23 de febrero de 2017, el procedimiento de homologación de un acuerdo de compensación económica para los casos en los que se hubiere dispuesto el alta médica sin secuelas, sin que ello implique modificación de esa determinación ni reconocimiento de derecho alguno de prestaciones dinerarias en concepto de Incapacidad Laboral Permanente (I.L.P.), contempladas en la Ley N° 24.557 y sus modificatorias. Para estos supuestos se seguirá el procedimiento establecido en el Apartado II -Procedimiento para la Homologación de la Propuesta de Convenio por Incapacidades Definitivas y Fallecimiento- del Capítulo II -del Procedimiento ante el Servicio de Homologación en el Ámbito de las Comisiones Médicas Jurisdiccionales- del Título I de la mencionada Resolución, en lo que resulte aplicable.', 'Tener en cuenta en procedimiento de homologación de un acuerdo de compensación económica para los casos en los que se hubiere dispuesto el alta médica sin secuelas.', 2, 'Obligatoria', NULL, NULL, 4, 157, '{"custom_1783383400370": "Salud Ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO", "custom_1783383788609": "Informativo"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 304);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, NULL, 'Establece la entrada en vigencia de la Resolución de la SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 20 de fecha 14 de abril de 2021 (mediante la cual se instruyeron medidas tendientes a la simplificación de las actuaciones administrativas en el ámbito de dichas Comisiones ante el contexto de pandemia imperante), a partir del día 1° de septiembre de 2021.\nDetermina que las ASEGURADORAS DE RIESGOS DEL TRABAJO (A.R.T.) y los EMPLEADORES AUTOASEGURADOS (E.A.) deberán proceder a notificar en forma fehaciente a las trabajadoras damnificadas o a los trabajadores damnificados sobre la existencia de secuelas incapacitantes y requerir la constitución del patrocinio letrado obligatorio, utilizando para ello el modelo de “NOTIFICACIÓN DE LA INCAPACIDAD LABORAL PERMANENTE (I.L.P.)” que como Anexo I de esta Disposición.', 'Tener en cuenta el procedimiento de notificación de incapacidades permanentes.', 2, NULL, NULL, NULL, 4, 158, '{"custom_1783383400370": "Salud Ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 432);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', '(21/10/2020)\nEstablece que en el marco de lo dispuesto por la Resolución S.R.T. N° 56 de fecha 24 de junio de 2020, las COMISIONES MÉDICAS JURISDICCIONALES (C.M.J.) y sus Delegaciones, como así también la COMISIÓN MÉDICA CENTRAL (C.M.C.), prestarán integralmente los servicios que le competen y brindarán atención al público de manera presencial, exclusivamente a aquellas personas que cuenten con turno previamente asignado, conforme la modalidad que corresponda. No se permitirá el ingreso a los establecimientos a personas que no acrediten relación e interés directo con el trámite a realizar.\nLos turnos serán determinados, conforme la agenda disponible en función de los recursos existentes en la sede administrativa, de acuerdo con la evolución epidemiológica. Esto, hasta tanto perdure la emergencia sanitaria prevista por la Ley N° 27.541 y que se ampliara en UN (1) año en virtud del Decreto de Necesidad y Urgencia (D.N.U.) N° 260 de fecha 12 de marzo de 2020 o el que en el futuro lo reemplace.', 'Cumplir con el procedimiento', 2, 'Obligatoria', 'Dictamen de la Comisón', NULL, 4, 159, '{"custom_1783383400370": "Salud Ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO", "custom_1783383763840": "En principio mientras dure el ASPO", "custom_1783383788609": "determinación de enfermedades", "custom_1783383823178": "disputa para determinar enfermedades profesionales", "custom_1784900000002": "Servicio médico"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 470);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Autoriza, de manera transitoria y excepcional, a los Secretarios Técnicos Letrados de las Comisiones Médicas Jurisdiccionales detallados en el Anexo IF-2021-18718277-APN-GACM#SRT, que forma parte integrante de la presente resolución, a intervenir provisoriamente en el análisis jurídico y en la rúbrica de los dictámenes jurídicos previstos en el artículo 6° de la Resolución de esta SUPERINTENDENCIA DE RIESGOS DEL TRABAJO (S.R.T.) N° 38 de fecha 28 de abril de 2020, a excepción de los trámites por fallecimiento.', 'Lo cumplen las Comisiones Médicas', 2, 'Obligatoria', 'Dictamen de la Comisón', NULL, 4, 160, '{"custom_1783383400370": "Salud Ocupacional", "custom_1783383445340": "SUPERINTENDENCIA DE RIESGOS DEL TRABAJO", "custom_1783383763840": "En principio mientras dure el ASPO", "custom_1783383788609": "determinación de enfermedades", "custom_1783383823178": "disputa para determinar enfermedades profesionales", "custom_1784900000002": "Servicio médico"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 448);
INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, 'Todos los artículos', 'Prorroga hasta el 31 de mayo de 2021 la prohibición de efectuar despidos sin justa causa y por las causales de falta o disminución de trabajo y fuerza mayor. Prorroga a su vez hasta el 31 de mayo de 2021 la prohibición de efectuar suspensiones por las causales de fuerza mayor o falta o disminución de trabajo.\nQuedan exceptuadas de esta prohibición y de los límites temporales previstos por los artículos 220, 221 y 222 de la Ley de Contrato de Trabajo las suspensiones efectuadas en los términos del artículo 223 bis de la Ley de Contrato de Trabajo (t.o. 1976) y sus modificatorias, como consecuencia de la emergencia sanitaria.\nLos despidos y las suspensiones que se dispongan en violación de lo dispuesto en el artículo 2° y en el primer párrafo del artículo 3º del presente decreto no producirán efecto alguno, manteniéndose vigentes las relaciones laborales existentes y sus condiciones actuales.Se amplía, hasta el 30 de junio de 2022, la emergencia pública en materia ocupacional declarada por el Decreto de Necesidad y Urgencia Nº 34/19 y ampliada por sus similares Nros. 528/20, 961/20 y 39/21.\n \nEn dicho marco, el Gobierno establece la reducción progresiva de la duplicación de indemnizaciones por despido. A partir del 1 de enero de 2022, el trabajador despedido sin causa tendrá derecho a percibir un incremento del 75% de las indemnizaciones por despido, que se irá reduciendo hasta su eliminación a partir del 01/07/22. La norma mantiene el tope de $500.000 para el incremento, como así también se mantiene el universo de empleados alcanzados (aquellos contratados antes del 13 de diciembre de 2019).', 'Tener en cuenta las indemnizaciones a ser abonadas por despidos hasta el 01/07/22.', 2, 'Obligatoria', NULL, NULL, 4, 161, '{"custom_1783383400370": "Salud Ocupacional", "custom_1783383445340": "PEN-EMERGENCIA PÚBLICA", "custom_1783383763840": "En principio mientras dure el ASPO", "custom_1783383823178": "Pago de dobe indemnización"}');
INSERT INTO `item_matriz_norma` (`id_item_matriz`,`id_norma`) VALUES (@i, 478);
