INSERT INTO `item_matriz` (`id_matriz`,`articulos_aplicables`,`resumen_legal`,`interpretacion_aplicacion`,`id_tipo_modalidad`,`obs_modalidad`,`evidencia_cumplimiento`,`verificacion_cumplimiento`,`id_estado_cumplimiento`,`orden`,`datos_dinamicos`) VALUES
(@m, '4.2.2.1', 'Los siguientes elementos deben estar documentados como parte del análisis del manejo de riesgos:\n1. Seguridad Humana\n2. Continuidad del servicio\n3. Tamaño y valor de la instalación\n4. Planes de restauración\n5. Disponibilidad de infraestructuras de telecomunicaciones de reposición que sean fáciles de montar\n6. Tiempo de respuesta ante una alarma\n7. Capacidades de los bomberos locales\n8. Infraestructura redundante de telecomunicaciones', 'El análisis de riesgos de incendio de las instalaciones de Cirion debe contener estos componentes', 2, 'Acción', 'Estudio de carga de fuego', NULL, 4, 0, '{"custom_1783383400370": "Seguridad contra incendios", "custom_1783383445340": "NFPA", "custom_1783383763840": "Actualizarse una vez al año como mínimo", "custom_1783383788609": "Salas Técnicas", "custom_1783383823178": "Análisis de riesgos", "custom_1784900000002": "EH&S"}');
